/** Construit le contexte standard email à partir d'un ref logement. */
function _buildEmailCtxFromRef(ref, extraCtx) {
  const log = (DB.logements||[]).find(l => l && !l._deleted && l.ref === ref) || { ref };
  const bail = (DB.baux && DB.baux[ref]) || {};
  const ent = (DB.entites||[]).find(e => e.nom === (log.entity || bail.entity)) || {};
  const locataire = (Array.isArray(bail.locataires) && bail.locataires[0]) ||
                    { nom: log.locataire || '', email: log.mail || '' };
  const baseCtx = {
    logement: log,
    bail: { ...bail, adrBien: bail.adrBien || log.adr || '' },
    entite: ent,
    locataire,
    garant: bail.garant ? { nom: bail.garant } : null,
    // R-0 : le loyer EN VIGUEUR aujourd'hui (même règle que la fiche du bien, `loyerDuLotA` du moteur) —
    // un e-mail parti après une révision IRL n'annonce plus l'ancien loyer du bail. Un envoi qui porte sur
    // une date (période réclamée, quittance) fournit son propre `montant` via extraCtx, qui l'emporte
    // (mise en demeure : montant saisi). Aucun acte signé ni document déjà généré n'est relu ici.
    montant: (function(){ const m = _loyerEnVigueurLot(ref, bail, log); return m == null ? '‹montant›' : m; })(),
    periode: '', // À compléter par extraCtx selon le type
    // Date en clair : ces modèles l'impriment en toutes lettres (« Fait à …, le … »).
    dateLettre: fd(td()),
    // TROISIÈME chemin de composition de la mise en demeure, après la modale d'actes et
    // l'escalade quittance. Il avait été oublié : le modèle ne portant plus `{{rappel1Date}}`,
    // l'acte s'ouvrait sur « (inconnu) votre loyer… ». Même lecture unique de l'historique.
    phraseRelances: (typeof window.phraseRelances === 'function')
      ? window.phraseRelances(typeof _relancesEnvoyees === 'function' ? _relancesEnvoyees(ref) : [])
      : 'Nous constatons que'
  };
  return { ...baseCtx, ...(extraCtx || {}) };
}

// ─── v15.79 EMAIL-ONGLET-PERMANENT (Sprint 19B) — Page Communications #p-emails ─
// Module pur testable miroir : js/core/emails-page.js (24 tests Vitest).
// Helpers inlinés pattern shadow (duplication couverte par les tests).

function _emailsSortDesc(emails) {
  if (!Array.isArray(emails)) return [];
  return emails.slice().sort((a, b) => String((b && b.sentAt) || '').localeCompare(String((a && a.sentAt) || '')));
}
function _emailsFormatMonthLabel(yyyymm) {
  const m = String(yyyymm || '').match(/^(\d{4})-(\d{2})$/);
  if (!m) return String(yyyymm || '');
  const months = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
  const idx = parseInt(m[2], 10) - 1;
  return (months[idx] || m[2]) + ' ' + m[1];
}
function _emailsGroupByMonth(emails) {
  if (!Array.isArray(emails)) return [];
  const buckets = new Map();
  for (const e of emails) {
    if (!e || !e.sentAt) continue;
    const key = String(e.sentAt).slice(0, 7);
    if (!/^\d{4}-\d{2}$/.test(key)) continue;
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(e);
  }
  const keys = Array.from(buckets.keys()).sort().reverse();
  return keys.map(k => ({ key: k, label: _emailsFormatMonthLabel(k), emails: _emailsSortDesc(buckets.get(k)) }));
}
function _emailsCountByType(emails) {
  const out = {};
  if (!Array.isArray(emails)) return out;
  for (const e of emails) { if (!e || !e.type) continue; out[e.type] = (out[e.type] || 0) + 1; }
  return out;
}
function _emailsDashboardStats(emails) {
  const empty = { total: 0, last30: 0, last90: 0, byMonth: [], topTypes: [] };
  if (!Array.isArray(emails) || !emails.length) return empty;
  const now = Date.now();
  let last30 = 0, last90 = 0;
  for (const e of emails) {
    if (!e || !e.sentAt) continue;
    const t = new Date(e.sentAt).getTime();
    if (!isFinite(t)) continue;
    const diffDays = (now - t) / 86400000;
    if (diffDays <= 30) last30++;
    if (diffDays <= 90) last90++;
  }
  const counts = _emailsCountByType(emails);
  const topTypes = Object.entries(counts).sort((a,b) => b[1]-a[1]).slice(0, 5).map(([type, n]) => ({ type, n }));
  return { total: emails.length, last30, last90, byMonth: _emailsGroupByMonth(emails).slice(0, 6), topTypes };
}

/** Récupère tous les emails envoyés depuis DB.emailsSent (no-throw safe). */
function _emailsListAll() {
  try {
    if (typeof DB !== 'undefined' && Array.isArray(DB.emailsSent)) return DB.emailsSent;
  } catch (e) {}
  return [];
}

/** Récupère le label/icon d'un type d'email depuis EMAIL_HUB_CATALOG. */
function _emailsTypeMeta(type) {
  const item = EMAIL_HUB_CATALOG.find(x => x.type === type);
  return item || { icon: '✉', label: type, phase: '—' };
}

/** Switch entre les 3 sous-tabs (dashboard / historique / modeles) + re-render. */
function _emailsSetTab(tab) {
  document.querySelectorAll('#p-emails .em-tab-btn').forEach(b => b.classList.toggle('act', b.dataset.emTab === tab));
  document.querySelectorAll('#p-emails .em-tab-pane').forEach(p => p.classList.toggle('act', p.id === 'em-pane-' + tab));
  rEmailsPage(tab);
}

/** Render principal de la page Communications. Tab actif lu depuis le DOM si non fourni. */
function rEmailsPage(tab) {
  const all = _emailsListAll();
  if (!tab) {
    const cur = document.querySelector('#p-emails .em-tab-btn.act');
    tab = (cur && cur.dataset.emTab) || 'dashboard';
  }

  if (tab === 'dashboard') {
    const pane = el('em-pane-dashboard'); if (!pane) return;
    const stats = _emailsDashboardStats(all);
    if (!stats.total) {
      pane.innerHTML = `<div class="em-empty">${_uiIcon('mail')} Aucun email envoyé pour le moment.<br><span class="mu sm">L'historique se construira au fil de l'usage (clic sur 📧 dans les fiches bail / quittance / IRL).</span></div>`;
      return;
    }
    const topRows = stats.topTypes.map(t => {
      const meta = _emailsTypeMeta(t.type);
      return `<div class="em-row"><span class="ic">${meta.icon}</span><div class="info"><div class="lbl">${escHtml(meta.label)}</div><div class="meta">${escHtml(meta.phase)}</div></div><div class="when"><b>${t.n}</b> envois</div></div>`;
    }).join('');
    const monthRows = stats.byMonth.map(m => `<div class="em-row"><span class="ic">${_uiIcon('calendar')}</span><div class="info"><div class="lbl">${escHtml(m.label)}</div></div><div class="when"><b>${m.emails.length}</b> envois</div></div>`).join('');
    pane.innerHTML = `
      <div class="em-stats">
        <div class="em-stat"><div class="v">${stats.total}</div><div class="l">emails envoyés (total)</div></div>
        <div class="em-stat"><div class="v">${stats.last30}</div><div class="l">30 derniers jours</div></div>
        <div class="em-stat"><div class="v">${stats.last90}</div><div class="l">90 derniers jours</div></div>
      </div>
      <h4 style="margin:14px 0 8px;font-size:12px;color:var(--mu,#888);text-transform:uppercase;letter-spacing:0.06em">Top types d'emails</h4>
      ${topRows || '<div class="mu">—</div>'}
      <h4 style="margin:18px 0 8px;font-size:12px;color:var(--mu,#888);text-transform:uppercase;letter-spacing:0.06em">Activité par mois (6 derniers)</h4>
      ${monthRows || '<div class="mu">—</div>'}`;
  } else if (tab === 'historique') {
    const pane = el('em-pane-historique'); if (!pane) return;
    if (!all.length) {
      pane.innerHTML = `<div class="em-empty">${_uiIcon('mail')} Aucun email dans l'historique.</div>`;
      return;
    }
    const groups = _emailsGroupByMonth(all);
    const html = groups.map(g => {
      const rows = g.emails.map(e => {
        const meta = _emailsTypeMeta(e.type);
        const when = e.sentAt ? new Date(e.sentAt).toLocaleString('fr-FR', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }) : '—';
        const target = e.entityId ? `${escHtml(e.entityType || '')} · <b>${escHtml(e.entityId)}</b>` : '—';
        return `<div class="em-row"><span class="ic">${meta.icon}</span><div class="info"><div class="lbl">${escHtml(meta.label)}</div><div class="meta">→ ${escHtml(e.to || '—')} · ${target}</div></div><div class="when">${escHtml(when)}</div></div>`;
      }).join('');
      return `<div class="em-month-group"><div class="em-month-head">${escHtml(g.label)}<span class="ct">${g.emails.length} envoi${g.emails.length>1?'s':''}</span></div>${rows}</div>`;
    }).join('');
    pane.innerHTML = html;
  } else if (tab === 'modeles') {
    const pane = el('em-pane-modeles'); if (!pane) return;
    const byPhase = {};
    EMAIL_HUB_CATALOG.forEach(item => { if (!byPhase[item.phase]) byPhase[item.phase] = []; byPhase[item.phase].push(item); });
    let html = `<div class="mu sm" style="margin-bottom:14px;font-size:12px;line-height:1.55">${EMAIL_HUB_CATALOG.length} modèles d'emails disponibles, déclenchables depuis les fiches bail / quittance / IRL / EDL via le bouton <b>📧</b>. Brouillons pré-remplis automatiquement.</div>`;
    for (const phase of ['1. Signature','2. Entrée','3. Vie du bail','4. Fin de bail','5. Sortie']) {
      const items = byPhase[phase] || [];
      if (!items.length) continue;
      html += `<h4 style="margin:14px 0 6px;font-size:12px;color:var(--acc,#3b7ef6);font-weight:700">${escHtml(phase)}</h4>`;
      html += `<div class="em-templates-grid">`;
      for (const item of items) {
        // BAUX-ECHUS — un modèle réservé à certains types de bail le dit (ex. renouvellement : nu, meublé).
        const _TB = { nu: 'nu', meuble: 'meublé', etudiant: 'étudiant', mobilite: 'mobilité', garage: 'garage', autre: 'autre' };
        const _tbTxt = Array.isArray(item.typesBail) ? ' · baux ' + item.typesBail.map(t => _TB[t] || t).join(', ') : '';
        html += `<div class="em-tpl"><div class="ic">${item.icon}</div><div class="lbl">${escHtml(item.label)}</div><div class="phase">${escHtml(item.phase + _tbTxt)}</div></div>`;
      }
      html += `</div>`;
    }
    pane.innerHTML = html;
  }
}
