// GESTION DG & IMPAYÉS v15.12 Sprint 12 V1.1 — Shadow inline helpers purs
// Module js/core/gestion-dg-impayes.js exposés à window via main.js.
// ════════════════════════════════════════════════════════════════════════════

const DG_STATUS = {
  MANQUANT:'manquant', PARTIEL:'partiel', COMPLET:'complet',
  A_RESTITUER:'a_restituer', RESTITUE:'restitue', EN_RETARD:'en_retard',
  DEPASSEMENT_POSSIBLE:'depassement_possible'   // conformité de l'EDL de sortie inconnue, entre 1 et 2 mois (art. 22)
};
const PROCEDURE_ETAT = {
  AUCUNE:'aucune', MISE_EN_DEMEURE:'mise_en_demeure',
  COMMANDEMENT_PAYER:'commandement_payer', ASSIGNATION:'assignation',
  JUGEMENT:'jugement', CLOTUREE:'cloturee'
};

// Copies du chemin file:// (le module js/core/gestion-dg-impayes.js les remplace au chargement) : le délai de
// restitution y est lu dans LA MÊME règle — window.DgDelai, mirror de js/core/dg-delai.js — avec l'EDL de sortie
// de CE bail (_edlSortieDuBail). Aucune arithmétique de délai ici.
// DÉPÔT VERSÉ — copie file:// de _dgVerseMontant / _dgVerseCoche (js/core/gestion-dg-impayes.js, définition UNIQUE, R-0) :
// le module les remplace au chargement (js/main.js). Égalité verrouillée par __tests__/helpers/bail-dg-verse.test.js.
function _dgVerseMontant(bail, dgRepli) {
  if (!bail || bail.dgVerse === false) return 0;
  return Number(bail.dgPaid) || Number(bail.dg) || Number(dgRepli) || 0;
}
function _dgVerseCoche(bail) {
  return !!bail && bail.dgVerse !== false;
}
function _dgStatut(bail, dateRef) {
  if (!bail) return { statut: DG_STATUS.MANQUANT, dgDu: 0, dgPaid: 0, soldeRestant: 0 };
  const dgDu = Number(bail.dg) || 0;
  const dgPaid = _dgVerseMontant(bail);   // définition unique du dépôt versé (case B4 comprise)
  const soldeRestant = dgDu - dgPaid;
  if (bail.dgRestitueAt) return { statut: DG_STATUS.RESTITUE, dgDu, dgPaid, soldeRestant: 0 };
  if (dgDu > 0 && dgPaid <= 0) return { statut: DG_STATUS.MANQUANT, dgDu, dgPaid, soldeRestant };   // non versé : rien à restituer
  const D = (typeof window !== 'undefined') ? window.DgDelai : null;
  if (bail.cloture && D) {
    const ech = D.echeancesRestitution(bail, _edlSortieDuBail(bail));
    const ref = (typeof dateRef === 'string' && dateRef) ? dateRef.slice(0, 10) : (dateRef instanceof Date ? _isoLocal(dateRef) : _todayIsoLocal());
    const et = D.etatDelai(ech, ref);
    if (ech && et) {
      const info = { dgDu, dgPaid, soldeRestant, delaiMois: ech.delaiMois, limite: ech.limite, limiteSiConforme: ech.limiteSiConforme, limiteSinon: ech.limiteSinon, conforme: ech.conforme, remise: ech.remise, joursSiConforme: et.joursSiConforme };
      if (et.etat === 'en_retard') return { statut: DG_STATUS.EN_RETARD, ...info, joursRetard: et.joursRetard };
      if (et.etat === 'depassement_possible') return { statut: DG_STATUS.DEPASSEMENT_POSSIBLE, ...info, joursRestants: et.jours };
      return { statut: DG_STATUS.A_RESTITUER, ...info, joursRestants: et.jours };
    }
  }
  if (dgPaid <= 0 && dgDu > 0) return { statut: DG_STATUS.MANQUANT, dgDu, dgPaid, soldeRestant };
  if (dgPaid < dgDu) return { statut: DG_STATUS.PARTIEL, dgDu, dgPaid, soldeRestant };
  return { statut: DG_STATUS.COMPLET, dgDu, dgPaid, soldeRestant: 0 };
}

// Le statut du dépôt d'un bail CIBLE de restitution (fenêtre de restitution, frise) : un bail parti (départ déclaré) ou
// archivé par une relocation n'est pas « clôturé » au sens de _dgStatut, mais son dépôt est À RESTITUER depuis sa fin
// d'occupation (_bailFinOccupation) — même règle de délai que pour un bail clôturé (vérification finale 06/10).
function _dgStatutDuBail(bail) {
  const fin = bail && (bail.finEffective || _bailFinOccupation(bail, false));
  if (!bail || bail.dgRestitueAt || bail.cloture || !fin) return _dgStatut(bail);
  return _dgStatut(Object.assign({}, bail, { cloture: true, finEffective: String(fin).slice(0, 10) }));
}

// Délai APPLICABLE : 1 mois si l'EDL de sortie de CE bail est conforme, 2 mois sinon ou s'il n'existe pas encore.
// Les retenues n'en décident plus (une retenue pour loyer impayé ne rend pas l'état des lieux non conforme).
function _calculerDelaiRestitution(bail) {
  if (!bail) return 2;
  const D = (typeof window !== 'undefined') ? window.DgDelai : null;
  return (D && D.conformiteEdlSortie(_edlSortieDuBail(bail)) === true) ? 1 : 2;
}

function _calculerLoyerImpayeCumule(bail, mouvements, dateRef) {
  if (!bail || !bail.debut) return 0;
  const debut = new Date(bail.debut + 'T00:00:00');
  const today = dateRef instanceof Date ? dateRef : new Date(String(dateRef||td()) + 'T00:00:00');
  const fin = bail.finEffective ? new Date(bail.finEffective + 'T23:59:59') :
              bail.fin ? new Date(bail.fin + 'T23:59:59') : today;
  if (Number.isNaN(debut.getTime())) return 0;
  const nbMois = Math.max(0, (fin.getFullYear()-debut.getFullYear())*12 + (fin.getMonth()-debut.getMonth()) + 1);
  const loyerMensuel = (Number(bail.hc)||0) + (Number(bail.ch)||0);
  const attendu = nbMois * loyerMensuel;
  const ref = bail.ref;
  const encaisse = (mouvements||[]).filter(m => m && !m._deleted && m.qui === ref && (m.cr||0) > 0)
    .reduce((s,m) => s + (Number(m.cr)||0), 0);
  return Math.max(0, attendu - encaisse);
}

function _calculerSoldeDG(bail, mouvements) {
  if (!bail) return { dgPaid: 0, retenuesDG: 0, loyerImpaye: 0, soldeRestitue: 0 };
  const dgPaid = _dgVerseMontant(bail);
  const retenuesDG = Number(bail.dgRetenu) || 0;
  const loyerImpaye = _calculerLoyerImpayeCumule(bail, mouvements);
  const soldeRestitue = Math.max(0, dgPaid - retenuesDG - loyerImpaye);
  return { dgPaid, retenuesDG, loyerImpaye, soldeRestitue };
}
// NB : cette copie est DEAD CODE — la version qui fait autorité au runtime est
// js/core/gestion-dg-impayes.js (exportée + assignée à window par js/main.js). Le fix « loyer seul »
// (modèle Didier, anti double-compte) est appliqué dans le module, pas ici.

function _planApurementStatut(plan, dateRef) {
  if (!plan || !Array.isArray(plan.echeances) || !plan.echeances.length) {
    return { statut: 'aucun', montantPaye: 0, montantDu: 0, prochaineEcheance: null, retardJours: 0 };
  }
  const today = dateRef instanceof Date ? dateRef : new Date(String(dateRef||td()) + 'T00:00:00');
  let montantPaye = 0, montantDu = 0, prochaineEcheance = null, retardJours = 0;
  for (const ech of plan.echeances) {
    if (!ech) continue;
    montantDu += Number(ech.montant) || 0;
    if (ech.paye) montantPaye += Number(ech.montant) || 0;
    else if (!prochaineEcheance) {
      prochaineEcheance = ech.date;
      const dEch = new Date(ech.date + 'T23:59:59');
      if (!Number.isNaN(dEch.getTime())) {
        const j = Math.floor((today.getTime() - dEch.getTime()) / 86400000);
        if (j > 0) retardJours = j;
      }
    }
  }
  if (montantPaye >= montantDu && montantDu > 0) return { statut: 'termine', montantPaye, montantDu, prochaineEcheance: null, retardJours: 0 };
  if (retardJours > 0) return { statut: 'retard', montantPaye, montantDu, prochaineEcheance, retardJours };
  return { statut: 'a_jour', montantPaye, montantDu, prochaineEcheance, retardJours: 0 };
}

function _procedureJudiciaireEtat(procedure, dateRef) {
  if (!procedure) return { etat: PROCEDURE_ETAT.AUCUNE };
  const today = dateRef instanceof Date ? dateRef : new Date(String(dateRef||td()) + 'T00:00:00');
  let etat = PROCEDURE_ETAT.AUCUNE, derniereDate = null;
  if (procedure.miseEnDemeureDate)    { etat = PROCEDURE_ETAT.MISE_EN_DEMEURE;     derniereDate = procedure.miseEnDemeureDate; }
  if (procedure.commandementDate)     { etat = PROCEDURE_ETAT.COMMANDEMENT_PAYER;  derniereDate = procedure.commandementDate; }
  if (procedure.assignationDate)      { etat = PROCEDURE_ETAT.ASSIGNATION;         derniereDate = procedure.assignationDate; }
  if (procedure.jugementDate)         { etat = PROCEDURE_ETAT.JUGEMENT;            derniereDate = procedure.jugementDate; }
  if (procedure.clotureDate)          { etat = PROCEDURE_ETAT.CLOTUREE;            derniereDate = procedure.clotureDate; }
  const out = { etat };
  if (derniereDate) {
    const dD = new Date(derniereDate + 'T00:00:00');
    if (!Number.isNaN(dD.getTime())) out.nbJoursDernEtape = Math.floor((today.getTime() - dD.getTime()) / 86400000);
  }
  return out;
}

// ════════════════════════════════════════════════════════════════════════════
// Mois de quittance en toutes lettres (« janvier 2026 ») → Date du 1er du mois.
// Lu par _dernierMoisQuittanceYm et _hlNbQuittances.
// ════════════════════════════════════════════════════════════════════════════

const _QA_MOIS_FR = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];

function _qaMoisToDate(moisStr) {
  if (!moisStr) return null;
  const s = String(moisStr).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  for (let i = 0; i < _QA_MOIS_FR.length; i++) {
    const moisNorm = _QA_MOIS_FR[i].normalize('NFD').replace(/[̀-ͯ]/g,'');
    if (s.includes(moisNorm)) {
      const m = s.match(/(\d{4})/);
      if (m) return new Date(`${m[1]}-${String(i+1).padStart(2,'0')}-01T00:00:00`);
    }
  }
  const iso = s.match(/^(\d{4})-(\d{2})/);
  if (iso) return new Date(`${iso[1]}-${iso[2]}-01T00:00:00`);
  return null;
}

/**
 * LES RELANCES QU'ON PEUT MONTRER, pour ce lot, dans l'ordre chronologique.
 *
 * Unique lecture de l'historique : les TROIS chemins qui composent une mise en demeure — modale
 * d'actes, escalade quittance, Hub Communications — produisent le même acte et doivent donc
 * partir des mêmes faits. Avant, l'un décrétait deux relances (« (relance 1) », « (relance 2) »),
 * un autre les demandait à l'utilisateur, le troisième lisait l'historique.
 *
 * ⚠️ LE STATUT COMPTE AUTANT QUE LE TYPE. `_logEmailSent` trace quatre issues très différentes :
 * `sent` (envoi prouvé par l'API, avec identifiant), `mailto` (le client mail s'est ouvert),
 * `shared` (partage système déclenché) et `copied` (le texte a été mis dans le presse-papier).
 * **`copied` n'est pas un envoi** : relire un rappel en le copiant créait une trace, et la mise
 * en demeure affirmait ensuite « Malgré notre relance du … » pour un courrier jamais parti.
 * On retient donc les trois issues où l'utilisateur a réellement lancé l'envoi, jamais la copie.
 *
 * ⚠️ UNE RELANCE, UNE DATE. Copier puis ouvrir le client mail sur le MÊME rappel produisait deux
 * traces le même jour — et un acte qui annonçait « nos relances des 05/06/2026 et 05/06/2026 ».
 * On ne garde donc qu'une date par rappel, la plus récente : c'est celle qui précède l'acte.
 */
function _relancesEnvoyees(ref){
  var ENVOI={ sent:1, mailto:1, shared:1 };   // `copied` exclu : voir ci-dessus
  var parType={};
  (DB.emailsSent||[]).forEach(function(e){
    if(!e || e.entityType!=='logement' || e.entityId!==ref) return;
    if(!/^rappel-impaye-[12]$/.test(e.type||'')) return;
    if(!ENVOI[e.status]) return;
    var d=String(e.sentAt||'').slice(0,10);
    if(!d) return;
    if(!parType[e.type] || d>parType[e.type]) parType[e.type]=d;
  });
  return Object.keys(parType).map(function(k){ return parType[k]; })
    .sort()
    .map(function(d){ return (typeof fd==='function') ? fd(d) : d; });
}

/** v15.10 Phase B3 — Lance un email d'escalade quittance impayée. */
function _quittanceActionEmail(ref, mois, emailType, ev) {
  if (ev) { try { ev.preventDefault(); ev.stopPropagation(); } catch(e){} }
  if (typeof window._openEmailModal !== 'function') {
    showToast('Module email non chargé — vérifier http-server', 'err', 5000);
    return;
  }
  const log = (DB.logements||[]).find(l => l.ref === ref);
  if (!log) { showToast('Logement introuvable','err'); return; }
  const bail = DB.baux && DB.baux[ref];
  const q = (DB.quittances||[]).find(x => x.logement === ref && x.mois === mois);
  if (!q) { showToast('Quittance introuvable','err'); return; }
  const ent = (DB.entites||[]).find(e => e.nom === (log.entity || q.entity));
  const locataire = (bail?.locataires && bail.locataires[0]) || { nom: q.locataire || log.locataire || '', email: log.mail || '' };
  const montant = (Number(q.hc)||0) + (Number(q.ch)||0);
  const ctx = {
    locataire, bail: bail || { adrBien: log.adr||'', hc: q.hc, ch: q.ch, dg: 0 },
    logement: log, entite: ent || {}, quittance: { ...q, total: montant },
    periode: mois, montant: montant, dateLettre: fd(td()),
    // Les relances réellement envoyées, via la MÊME lecture que la modale d'actes.
    phraseRelances: (typeof window.phraseRelances==='function')
      ? window.phraseRelances(emailType === 'rappel-impaye-3' ? _relancesEnvoyees(ref) : [])
      : 'Nous constatons que'
  };
  window._openEmailModal(emailType, ctx, { entityType: 'logement', entityId: ref });
  // Pour mise en demeure (rappel-impaye-3), marquer la quittance après envoi (handled côté EmailModal logEmailSent)
}

function envoyerQuittanceParEmail(id) {
  const q = DB.quittances.find(x => x.id === id);
  if (!q) { showToast('Quittance introuvable', 'err'); return; }
  if (typeof window._openEmailModal !== 'function') {
    showToast('Module email non chargé — vérifier http-server (npx serve)', 'err', 6000);
    return;
  }
  const log = DB.logements.find(l => l.ref === q.logement);
  const bail = DB.baux[q.logement];
  const ent = DB.entites.find(e => e.nom === (q.entity || log?.entity));
  const locataire = (bail?.locataires && bail.locataires[0]) || {
    nom: q.locataire || log?.locataire || '',
    email: log?.mail || ''
  };
  const ctx = {
    locataire,
    bail: bail || { adrBien: log?.adr || '', hc: q.hc, ch: q.ch },
    logement: log || { ref: q.logement },
    entite: ent || {},
    quittance: { ...q, total: (q.hc || 0) + (q.ch || 0) }
  };
  _docShareOpen('quittance', ctx, { entityType: 'quittance', entityId: id });
}

// ════════════════════════════════════════════════════════════════════════════
// CDC-QUITTANCES-IRL étape 2 — LA FABRIQUE UNIQUE DE QUITTANCE.
//
// C4 : jusqu'ici les 3 chemins de création lisaient `bail.hc/ch`, c'est-à-dire le loyer
// D'AUJOURD'HUI — une quittance de juin 2026 portait le tarif post-révision. Ici le montant
// vient du BARÈME DU MOIS (`_duMoisLot(ref, ym)`, périodes datées) : une quittance de juin
// porte le loyer de juin, quoi qu'il soit arrivé depuis (I5).
//
// D6/I4 : un mois non soldé ne produit JAMAIS de quittance — le garde-fou est
// `peutQuittancer` (js/core/loyers-mois.js), pas une règle réécrite ici.
// D8/I7 : un appel = UN mois = UN document. Jamais de document « juin à août ».
// I13 : cette fonction n'est appelée que depuis un geste explicite (aucun boot, aucun save).
//
// `datePaiement` n'est plus écrit à la création (C1 : l'ancien « ⚡ Générer ce mois » y mettait « aujourd'hui »,
// ce qui faisait mentir le document) — la date affichée est résolue au rendu.
//
// @returns {{ok:boolean, quittance?:object, existante?:boolean, motif?:string}}
//          N'ÉCRIT PAS en base au-delà du push : l'appelant fait saveDB() (permet d'émettre
//          N mois en une seule écriture).
function _creerQuittance(ref, ym, opts) {
  opts = opts || {};
  if (!/^\d{4}-\d{2}$/.test(String(ym || ''))) return { ok: false, motif: 'mois invalide' };
  const mois = (typeof window !== 'undefined' && typeof window.ymToMoisFr === 'function')
    ? window.ymToMoisFr(ym) : String(ym);
  if (!mois) return { ok: false, motif: 'mois invalide' };
  if (!DB.quittances) DB.quittances = [];
  const deja = DB.quittances.find(q => q && !q._deleted && q.logement === ref && q.mois === mois);
  if (deja) return { ok: true, quittance: deja, existante: true };   // jamais de doublon, jamais de recalcul

  if (opts.verifierSolde !== false) {
    const g = (typeof window !== 'undefined' && typeof window.peutQuittancer === 'function')
      ? window.peutQuittancer(_loyerEtatLot(ref), ym)
      : { ok: false, motif: 'module Loyers indisponible' };
    if (!g.ok) return { ok: false, motif: g.motif };
  }

  const log = (DB.logements || []).find(l => l.ref === ref);
  const bail = _findBailByRefTolerant(ref);
  const du = _duMoisLot(ref, ym);
  // FINANCES-SUIVI-V2 : la remise du mois (manque accepté, écart d'arrondi abandonné), lue au moteur et FIGÉE ici.
  const _e = _loyerEtatLot(ref), _m = _e && _e.byYm && _e.byYm[ym];
  const _rem = _m && _m.remise > 0.005 ? Math.round(_m.remise * 100) / 100 : 0;
  // Un mois ENTIÈREMENT remis (rien reçu) ne se quittance pas : une quittance atteste une somme reçue.
  if (_rem > 0 && Math.round(((Number(du.hc) || 0) + (Number(du.ch) || 0) - _rem) * 100) / 100 <= 0.005)
    return { ok: false, motif: 'mois soldé par une remise : aucune somme reçue à quittancer' };
  const q = {
    id: nid(), logement: ref,
    locataire: ((bail && bail.locataires) || []).map(l => l && l.nom).filter(Boolean).join(', ')
      || (bail && bail.nom) || (log && log.locataire) || '',
    mois, hc: du.hc || 0, ch: du.ch || 0,
    entity: (bail && bail.entity) || (log && log.entity) || '',
    date: td()
  };
  if (_rem > 0) { q.remise = _rem; if (_m.remiseMotifs && _m.remiseMotifs.length) q.remiseMotif = _m.remiseMotifs.join(' ; ').slice(0, 200); }
  _stamp(q);
  if (typeof _auditLog === 'function') _auditLog('create', 'quittance', q.id, q.logement + '/' + q.mois);
  DB.quittances.push(q);
  return { ok: true, quittance: q, existante: false };
}

/**
 * v15.91 EM-2d — Build pur du HTML+CSS de la quittance (extrait depuis previewQuit).
 * Permet la réutilisation pour la PJ PDF auto email (cf js/core/email-pdf-attachment.js).
 *
 * @param {object} q   - Entrée DB.quittances (hc, ch, mois, logement, locataire, datePaiement, date, entity)
 * @param {object} log - Entrée DB.logements
 * @param {object} ent - Entrée DB.entites
 * @param {object} bail - Entrée DB.baux[ref]
 * @param {object} [opts] - { totalRecu?: number, infoPaiement?: {date, dates, nb} } — surcharge
 *        explicite (reçu partiel, tests) ; sinon la date vient de la cascade unique (I-DATE).
 * @returns {{html:string, css:string, title:string, status:'complet'|'partiel'}}
 */
// AUDIT M3 — mise en page propre a la FENETRE d'impression/partage de la quittance.
// Volontairement SEPAREE de `built.css` : ce dernier est injecte dans la page de l'app par
// _rasterizeHtmlToPdfBlob, ou une regle `body`/`@page` nue repeindrait l'application.
const QUIT_PRINT_CSS = '@page{size:A4;margin:1.8cm 2cm}body{margin:0;background:#fff}';
function _buildQuittanceHtml(q, log, ent, bail, opts) {
  q = q || {}; log = log || {}; ent = ent || {}; bail = bail || {}; opts = opts || {};

  // Extraire la ville du siège : "15 rue du château 67190 MUTZIG" → "MUTZIG"
  const siegeStr = ent.siege || '';
  const villeMatch = siegeStr.match(/\d{5}\s+(.+)/);
  const ville = villeMatch ? villeMatch[1].split(',')[0].trim() : siegeStr;
  const villeTitre = ville ? ville.charAt(0).toUpperCase()+ville.slice(1).toLowerCase() : '';

  // RCS
  const siren = ent.siren ? ent.siren+' RCS '+(ent.rcs||siegeStr.replace(/.*\d{5}\s+/,'').split(' ')[0]||'') : '';

  // Période : "avril 2026" → 01/04/2026 au 30/04/2026
  const moisParts = (q.mois||'').toLowerCase().split(' ');
  const moisIdx = MOIS_FR.indexOf(moisParts[0]);
  const anneeQ = parseInt(moisParts[1])||new Date().getFullYear();
  const dateDebut = moisIdx>=0 ? new Date(anneeQ, moisIdx, 1) : null;
  const dateFin   = moisIdx>=0 ? new Date(anneeQ, moisIdx+1, 0) : null;
  const periodeStr = dateDebut && dateFin
    ? 'du '+dateDebut.toLocaleDateString('fr-FR')+' au '+dateFin.toLocaleDateString('fr-FR')
    : q.mois||'–';

  // CDC-QUITTANCES-IRL étape 2 (I6) — le MONTANT REÇU imputé à ce mois vient de la cascade
  // unique (`_loyerPayeDuMois` → `_loyerArrearsPass`). Le document ne refait plus son propre
  // rattachement « mouvements datés de ce mois calendaire » : c'était le 7ᵉ moteur (C3), et
  // il déclarait « non payé » un loyer d'août réglé le 2 septembre.
  const prefixMois = moisIdx>=0
    ? anneeQ+'-'+(moisIdx+1).toString().padStart(2,'0')
    : null;
  const totalRecu = (opts.totalRecu != null)
    ? (Number(opts.totalRecu) || 0)
    : ((prefixMois && typeof _loyerPayeDuMois === 'function') ? _loyerPayeDuMois(q.logement, prefixMois) : 0);
  // I-DATE (CDC-LOYERS-DESIGN V5, surfaces 1 et 2 du §4) — LA date « reçu le ».
  //
  // AVANT : le dernier encaissement de loyer DU LOT antérieur à l'émission, avec deux replis
  // (champ legacy `datePaiement`, puis la DATE D'ÉMISSION). Trois façons d'être faux : un
  // rattrapage de cinq mois donnait la même date aux cinq quittances sans que ce soit dit,
  // un lot qui paie deux loyers voyait la quittance de mai dater du versement de juin, et
  // à défaut de tout, la quittance certifiait un paiement le jour où on l'imprimait.
  //
  // MAINTENANT : la date du (ou des) versement(s) que la cascade unique a IMPUTÉ(S) À CE MOIS
  // (lot 0 du chantier). Aucun rattachement daté ⇒ la phrase se dit SANS date. On n'invente
  // rien : l'article 21 de la loi du 6 juillet 1989 fait de ce document un reçu, la date qu'il
  // porte engage le bailleur.
  const _infoPay = (opts.infoPaiement != null) ? opts.infoPaiement
    : ((prefixMois && typeof _loyerEtatLot === 'function' && typeof window !== 'undefined'
        && typeof window.datePaiementMois === 'function')
        ? window.datePaiementMois(_loyerEtatLot(q.logement), prefixMois)
        : { date: null, dates: [], nb: 0 });

  // QUITTANCE FIGÉE (décision user 16/07) : la quittance est un DOCUMENT — elle affiche le montant
  // qu'elle porte (q.hc/q.ch stockés à l'émission), point. AUCUN recalcul à l'affichage : ré-imprimer
  // ≠ re-calculer, donc une révision IRL postérieure ne change jamais une quittance déjà émise.
  // (Le prorata entrée/sortie mi-mois est désormais figé à la CRÉATION, plus corrigé ici.)
  // Repli (quittance legacy sans montant) : le BARÈME DU MOIS, jamais le bail courant (C4/I5).
  // CHAMP PAR CHAMP : une quittance qui ne porte que ses charges garde ses charges et
  // récupère son loyer au barème (même politique de repli symétrique que `duMois`).
  if ((q.hc == null || q.ch == null) && prefixMois && typeof _duMoisLot === 'function') {
    const _d = _duMoisLot(q.logement, prefixMois);
    q = Object.assign({}, q, {
      hc: q.hc == null ? (_d.hc || 0) : q.hc,
      ch: q.ch == null ? (_d.ch || 0) : q.ch
    });
  }
  const total = (q.hc||0)+(q.ch||0);
  // FINANCES-SUIVI-V2 (décision Didier Q1, 06/10) — mois soldé par un MANQUE ACCEPTÉ (ou un écart d'arrondi abandonné) :
  // la quittance est émise pour le montant REÇU, avec la mention de la remise (figée à l'émission : q.remise / q.remiseMotif).
  const _remise = Math.round((Number(q.remise) || 0) * 100) / 100;
  const totalPaye = Math.max(0, Math.round((total - _remise) * 100) / 100);

  // AUDIT I-3/S-2 — ce bloc vit APRÈS `total`, donc après le repli legacy champ par champ.
  // Le lire avant obligeait à recalculer un dû à part (`_duDoc`), qui n'était pas symétrique :
  // une quittance mixte (hc stocké, ch nul) donnait un total faux, donc un reçu partiel privé
  // de sa mention de versements. Une seule lecture, une seule source, un seul `_forceeV7`.
  //
  // AUDIT C3 — le document sait ce qu'il EST, et la règle de date en dépend :
  //  · QUITTANCE (terme payé en entier) → une date SEULEMENT si le mois est soldé. Sur un mois
  //    partiellement payé (garde-fou V7), la liste des versements ne prouve rien : le document
  //    sortait « reçu le 14/06 la somme de 800 € » alors que 300 € seulement étaient arrivés,
  //    et le bandeau affiché juste au-dessus promettait l'inverse. Sur un document que
  //    l'article 21 rend opposable au bailleur, c'était pire qu'avant le chantier.
  //  · REÇU DE PAIEMENT PARTIEL → la liste des versements FAIT foi : c'est exactement ce que
  //    le document reconnaît avoir reçu.
  const _forceeV7 = (opts.forceeV7 != null)
    ? !!opts.forceeV7
    : !!(prefixMois && typeof _qeMeta === 'function' && _qeMeta(q.logement, prefixMois));
  const _docPartiel = (opts.partiel != null)
    ? !!opts.partiel
    : (!_forceeV7 && totalRecu > 0 && totalRecu < totalPaye - 0.01);
  const _mention = (typeof window !== 'undefined' && typeof window.mentionDateRecu === 'function')
    ? window.mentionDateRecu(_infoPay, fd, { partiel: _docPartiel })
    : { avecDate: false, mention: '', dateAffichee: null };
  // La phrase d'acte, avec ou sans date — jamais « reçu le — », jamais une date inventée.
  const recuLe = `déclare avoir reçu${_mention.mention} du locataire`;
  const isProrata = false;
  const joursOcc = null;
  const joursMois = null;
  const totalLettres = numToWords(totalPaye);
  const totalRecuLettres = numToWords(totalRecu);
  const adrBien = bail.adrBien||log.adr||'–';

  // Locataires depuis bail (avec DDN et lieu de naissance) ou fallback string
  // DOCS-UNIFIES — MÊMES clauses qu'avant, autre disposition (gabarit B) : le nom prend la
  // ligne d'identité du bloc, le reste de la phrase suit. Aucun mot n'est retiré ni ajouté.
  const locsData = bail.locataires||(bail.nom?[{nom:bail.nom,ddn:bail.ddn,lieuNaiss:bail.lieuNaiss}]:null);
  let locsHtml = '';
  if(locsData && locsData.length) {
    locsHtml = locsData.map(l=>{
      const civ = l.civilite ? l.civilite+' ' : '';
      let suite = '';
      if(l.ddn) suite += `né${l.civilite==='Mme'?'e':''} le ${fd(l.ddn)}`;
      if(l.lieuNaiss) suite += ` à ${escHtml(l.lieuNaiss)}`;
      suite += `${suite?', ':''}demeurant ${escHtml(adrBien)}`;
      return `<span class="pro-qui">${civ}${escHtml(l.nom||'–')}</span><p>${suite}&nbsp;;</p>`;
    }).join('');
  } else {
    locsHtml = `<span class="pro-qui">${escHtml(q.locataire||'–')}</span><p>demeurant ${escHtml(adrBien)}&nbsp;;</p>`;
  }

  const gerant = ent.gerant||'–';
  const typeEnt = ent.type||'';
  const dateEmission = fd(q.date||td());

  // V7 (CDC-LOYERS-DESIGN) — UNE QUITTANCE FORCÉE EST UNE QUITTANCE.
  //
  // Défaut trouvé à la re-vérification : l'utilisateur cochait « je sais que ce document vaut
  // reçu », cliquait « Éditer la quittance », l'app enregistrait bien un état « quittancé »… et
  // le document qui sortait était un « Reçu de paiement partiel », parce que `totalRecu < total`.
  // L'état disait quittancé, le papier disait reçu : V7 n'était pas honorée, et le geste que
  // Didier a explicitement demandé (« tu arrêtes de bloquer les quittances ») ne produisait pas
  // ce qu'il promet. Quand la trace du geste forcé existe, le document est une QUITTANCE
  // pleine — et, le mois n'étant pas soldé, elle sort SANS ligne « payé le » (exactement ce que
  // le bandeau annonce). L'étiquette « sans paiement constaté » reste, elle, DANS L'APP (V9).
  // D27 (retour Didier 01/09) — « Document non émissible » N'EXISTE PLUS. Le CDC §3 le retirait
  // (index.html:27114) ; ça n'avait pas été fait, et une quittance sur un mois sans paiement
  // retombait dans cette impasse. Deux documents seulement, désormais :
  //   · PAIEMENT PARTIEL (0 < reçu < dû, hors geste forcé) → reçu de paiement partiel (art. 21) ;
  //   · SINON (soldé, AUCUN paiement, ou geste forcé) → QUITTANCE. Sans encaissement imputé, elle
  //     sort simplement SANS ligne « payé le » (la mention gère déjà l'absence de date).
  // Un mois sans paiement s'édite et se réédite LIBREMENT — jamais d'impasse, jamais de blocage.
  const estPartiel   = totalRecu > 0 && totalRecu < totalPaye - 0.01 && !_forceeV7;   // = _docPartiel
  const status = estPartiel ? 'partiel' : 'complet';

  const _resteBailleur = `${typeEnt?', '+escHtml(typeEnt):''}${siegeStr?', dont le siège social est situé '+escHtml(siegeStr):''}${siren?',<br>immatriculée au registre du commerce et des sociétés sous le numéro d\'identification '+escHtml(siren):''}${gerant?',<br>représentée par '+escHtml(gerant)+' en sa qualité de Gérant, dument habilité':''}${siegeStr||siren||gerant?' ;':''}`.replace(/^,\s*/, '');
  // DOCS-UNIFIES — les deux parties côte à côte (gabarit B). Mêmes clauses, même ordre,
  // mêmes mentions « Bailleur »/« Locataire » : seule la disposition change.
  const enteteHtml = _dt('docParties', [
    { label: '1. Le(s) Bailleur(s)',
      qui: escHtml(ent.nom||q.entity||'–'),
      corps: `${_resteBailleur?'<p>'+_resteBailleur+'</p>':''}<p>Désigné(s) ci-après, le &laquo;&nbsp;<b>Bailleur</b>&nbsp;&raquo;&nbsp;;<br>Et, d'autre part,</p>` },
    { label: '2. Le(s) Locataire(s)',
      corps: `${locsHtml}<p>désigné(s) ci-après le &laquo;&nbsp;<b>Locataire</b>&nbsp;&raquo;.</p>` }
  ]);

  // DOCS-UNIFIES — le CSS Times/souligné cède la place au gabarit unique (variante B).
  // `.alerte` reste : c'est un bandeau d'écran (no-print), pas une pièce du document.
  // AUDIT M3 — PAS de règle `body` ni `@page` ici : ce CSS est injecté tel quel DANS la page
  // de l'app par _rasterizeHtmlToPdfBlob (PJ email), où une règle nue repeindrait
  // l'application. Tout est scopé sous .pro-doc ; la fenêtre d'impression pose sa propre
  // mise en page (cf. QUIT_PRINT_CSS).
  const css = `
.pro-doc{max-width:700px;margin:0 auto}
.pro-doc .alerte{border-radius:2.5mm;padding:3mm 4mm;margin:0 0 6mm;text-align:center}
@media print{.pro-doc .no-print{display:none}}
${_docCss()}`;

  let html = '', titreDoc = '', ctxDoc = '';
  if(estPartiel) {
    const solde = total - totalRecu;
    titreDoc = 'Reçu de paiement partiel';
    ctxDoc = `Période de location ${periodeStr}`;
    html = `
<div class="alerte no-print" style="background:#fff3cd;border:.5mm solid #f0a500;color:#7a4f00;font-size:11pt;font-weight:bold">
  ⚠️ PAIEMENT PARTIEL — REÇU UNIQUEMENT (pas une quittance)<br>
  <span style="font-size:9.5pt;font-weight:normal">Reçu : <b>${fmt(totalRecu)}</b> sur <b>${fmt(total)}</b> dû — Solde restant : <b style="color:#dc3545">${fmt(solde)}</b></span>
</div>
${enteteHtml}
${_dt('docActe', `Je, soussigné(e) le Bailleur du logement sis <b>${escHtml(adrBien)}</b>, ${recuLe}, la somme partielle de <b>${fmt(totalRecu)}</b> – <em>${escHtml(totalRecuLettres)}</em> se décomposant comme suit&nbsp;:`)}
${_dt('docLignes', [
  { lab:'Loyer (partiel)', val: fmt(totalRecu > (q.ch||0) ? totalRecu-(q.ch||0) : totalRecu) },
  totalRecu>(q.hc||0) ? { lab:'Charges (partiel)', val: fmt(totalRecu-(q.hc||0)) } : null,
  { lab:'Somme reçue', val: fmt(totalRecu), tot:true }
])}
<p>Cette somme correspond à un <b>paiement partiel</b> du terme de <b>${periodeStr}</b>.<br>
Solde restant dû&nbsp;: <b>${fmt(solde)}</b>.</p>
${_dt('docEncart', `<b>Ce reçu ne vaut pas quittance.</b> Il ne libère pas le locataire de son obligation de payer le solde restant dû de ${fmt(solde)}. Le bailleur se réserve le droit de réclamer le paiement intégral du terme.`)}
${_dt('docLieu', `Fait à ${escHtml(villeTitre||'–')},<br>Le ${dateEmission}`)}
${_dt('docSignzone', [{ sig: _docSigOnly(ent), label: 'Le(s) Bailleur(s)' }])}`;
  } else {
    // v15.94 BUG-QUITTANCE-PRORATA — Si prorata détecté, afficher loyer prorata + détail jours
    // pour transparence juridique (Cass. 3e civ. : indiquer base de calcul du prorata).
    const prorataHC = isProrata && total > 0 ? Math.round((q.hc||0) * total / ((q.hc||0)+(q.ch||0)) * 100) / 100 : (q.hc||0);
    const prorataCH = isProrata ? (total - prorataHC) : (q.ch||0);
    const prorataLineHC = isProrata && joursOcc && joursMois
      ? { lab: `Loyer (prorata ${joursOcc}/${joursMois} j)`, val: fmt(prorataHC) }
      : { lab: 'Loyer', val: fmt(q.hc) };
    const prorataLineCH = isProrata && joursOcc && joursMois
      ? { lab: `Charges (prorata ${joursOcc}/${joursMois} j)`, val: fmt(prorataCH) }
      : { lab: 'Charges', val: fmt(q.ch) };
    const prorataMention = isProrata && joursOcc && joursMois
      ? _dt('docMention', `Loyer calculé au prorata de ${joursOcc} jours d'occupation sur ${joursMois} jours du mois (entrée ou sortie intra-mois — loi du 6 juillet 1989).`)
      : '';
    titreDoc = 'Quittance de loyer';
    ctxDoc = `Période de location ${periodeStr}`;
    html = `
${enteteHtml}
${_dt('docActe', `Je, soussigné(e) le Bailleur du logement sis <b>${escHtml(adrBien)}</b>, ${recuLe}, la somme de <b>${fmt(totalPaye)}</b> – <em>${escHtml(totalLettres)}</em> se décomposant comme suit&nbsp;:`)}
${_dt('docLignes', [prorataLineHC, prorataLineCH, _remise > 0.005 ? { lab: 'Remise accordée', val: '− ' + fmt(_remise) } : null, { lab:'Total des sommes payées', val: fmt(totalPaye), tot:true }].filter(Boolean))}
${_remise > 0.005 ? _dt('docMention', 'Remise accordée : ' + fmt(_remise) + (q.remiseMotif ? ' (' + escHtml(q.remiseMotif) + ')' : '') + '. Le loyer et les charges du bail sont inchangés.') : ''}
${prorataMention}
<p>Cette somme correspond au règlement du loyer et des charges pour la période de location <b>${periodeStr}</b>. J'en donne quittance sous réserve du bon encaissement de cette somme.</p>
${_dt('docMention', 'Cette quittance annule tous les reçus qui auraient pu être établis précédemment en cas de paiement partiel du montant du présent terme. Elle est à conserver par le locataire.')}
${_dt('docLieu', `Fait à ${escHtml(villeTitre||'–')},<br>Le ${dateEmission}`)}
${_dt('docSignzone', [{ sig: _docSigOnly(ent), label: 'Le(s) Bailleur(s)' }])}`;
  }

  const title = (estPartiel?'Reçu partiel':'Quittance') + ' — ' + escHtml(q.logement||'') + ' — ' + escHtml(q.mois||'');
  // DOCS-UNIFIES — un seul assemblage : bandeau + titre + corps + pied (gabarit B).
  // La feuille de style part dans `css` (la quittance a son propre <head>), pas dans le corps.
  const htmlPage = _docPage(ent, {
    titre: titreDoc, ctx: ctxDoc, corps: html,
    ref: escHtml(q.logement||''), date: `Émis le ${dateEmission}`, withStyle: false
  });
  return { html: htmlPage, css, title, status };
}
// Expose pour email-pdf-attachment.js (PJ PDF auto réutilise le rendu officiel)
if (typeof window !== 'undefined') window._buildQuittanceHtml = _buildQuittanceHtml;

function previewQuit(id) {
  const q = DB.quittances.find(x=>x.id===id); if(!q) return;
  const log = DB.logements.find(l=>l.ref===q.logement);
  const ent = DB.entites.find(e=>e.nom===(q.entity||log?.entity));
  const bail = DB.baux[q.logement];

  const built = _buildQuittanceHtml(q, log, ent, bail);

  // v15.104 — Affiche dans une MODALE POPUP avec IFRAME isolé.
  // L'iframe évite la pollution du CSS global Times NR (body/h1/h2) sur la page.
  const iframe = el('ov-quit-preview-iframe');
  if (!iframe) { showToast('Modale aperçu introuvable','err'); return; }
  // Stocke l'id sur l'iframe pour boutons footer
  iframe._quitId = id;
  iframe._docBuilt = built;
  const _h = document.querySelector('#ov-quit-preview .m-head h3');
  if (_h) _h.textContent = '📄 Aperçu quittance';
  // D27 (retour Didier) — le bouton unique porte un libellé FIXE « 📤 Partager » (partout pareil,
  // tablette ≠ PC). Le GESTE, lui, reste adaptatif via `_shareQuittanceWithPdf` / `_pdfSortie`
  // (partage natif sur téléphone, boîte « Enregistrer sous » / téléchargement sur PC).
  _qpMajBoutonAction();
  // Ouvre la modale puis injecte le HTML+CSS dans l'iframe via srcdoc
  // (sandbox allow-same-origin pour que le parent puisse encore lire _quitId)
  openM('ov-quit-preview');
  const docHtml = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>${built.title}</title><style>${QUIT_PRINT_CSS}${built.css}</style></head><body>${built.html}</body></html>`;
  iframe.srcdoc = docHtml;
}

/**
 * v15.98 EM-2e — Partage d'une quittance AVEC le PDF en PJ (Web Share API files level 2).
 * Utilisé par le bouton "🔗 Partager" de la popup preview. Reçoit l'id quittance :
 *  1. Génère le PDF via window._emailGenPdfAttachment (réutilise pipeline EM-2b/d)
 *  2. Convertit base64 → File
 *  3. navigator.share({ files, title, text }) si supporté (mobile principalement)
 *  4. Fallback : download direct du PDF + copie texte clipboard
 *
 * NB : exposé sur window pour être appelable depuis la popup via window.opener.
 */
window._shareQuittanceWithPdf = async function(id) {
  const q = DB.quittances.find(x => x.id === id);
  if (!q) { showToast('Quittance introuvable', 'err'); return; }
  const log = DB.logements.find(l => l.ref === q.logement);
  const bail = DB.baux[q.logement];
  const ent = DB.entites.find(e => e.nom === (q.entity || log?.entity));
  const locataire = (bail?.locataires && bail.locataires[0]) || {
    nom: q.locataire || log?.locataire || '', email: log?.mail || ''
  };
  const total = (q.hc||0) + (q.ch||0);
  const adrBien = bail?.adrBien || log?.adr || '';
  const subject = `Quittance de loyer ${q.mois}${adrBien ? ' — ' + adrBien : ''}`;
  const body = `Quittance de loyer pour la période ${q.mois}.\n\nDétail :\n- Loyer hors charges : ${q.hc||0} €\n- Provisions sur charges : ${q.ch||0} €\n- Total perçu : ${total} €\n\nLa quittance officielle est jointe en PDF.\n\nCordialement,\n${ent?.gerant || ''}${ent?.nom ? '\n' + ent.nom : ''}`;

  // D27 — même sortie que l'EDL : boîte « Enregistrer sous » sur PC, feuille de partage sur
  // téléphone. Une seule fonction (`_pdfSortie`) — le `<a download>` recopié ici a disparu.
  if (typeof window._emailGenPdfAttachment !== 'function') {
    showToast('Module PDF non chargé (rafraîchir la page)', 'err', 5000);
    return;
  }
  const ctx = {
    locataire,
    bail: bail || { adrBien: log?.adr || '', hc: q.hc, ch: q.ch },
    logement: log || { ref: q.logement },
    entite: ent || {},
    quittance: { ...q, total }
  };
  await _pdfSortie({
    fileName: `Quittance_${_edlSanitize(q.logement || '')}_${_edlSanitize(q.mois || '')}.pdf`,
    desc: 'PDF (quittance de loyer)',
    genererAvant: true,   // AUDIT #2 — non émissible = règle métier : rien ne doit atterrir sur le disque
    titre: subject,
    texte: body,
    genererBlob: async () => {
      const r = await window._emailGenPdfAttachment('quittance', ctx);
      if (!r || r.error) throw new Error(r && r.message ? r.message : 'PDF indisponible');
      const bin = atob(r.base64);
      const bytes = new Uint8Array(bin.length);
      for (let k = 0; k < bin.length; k++) bytes[k] = bin.charCodeAt(k);
      return new Blob([bytes], { type: 'application/pdf' });
    }
  });
};
// v15.98 EM-2e — alias rétrocompat (l'ancien bouton v15.97 appelait _shareQuittanceTextOnly)
window._shareQuittanceTextOnly = window._shareQuittanceWithPdf;

/**
 * D27 — LE BOUTON UNIQUE du pied de l'aperçu. Même règle que l'EDL (cf. `_edlPrefersShare` / `downloadEDLPdfNative`) :
 * `_edlPrefersShare()` dit si l'appareil sait partager ; `_shareQuittanceWithPdf` fait déjà
 * les deux (partage natif avec le PDF, sinon téléchargement). Seul le libellé change.
 */
function _qpMajBoutonAction() {
  const b = el('qp-action'); if (!b) return;
  // D27 (retour Didier) — libellé SELON L'APPAREIL, via _edlPrefersShare() : appareil TACTILE
  // (téléphone, tablette, iPad) → feuille de partage native → « 📤 Partager » ; PC (pas de partage
  // natif) → « ⬇️ Télécharger le PDF ». Le geste (_pdfSortie) fait les deux ; seul le mot suit
  // l'appareil. (« Partager » sur PC n'avait pas de sens — le PC enregistre, il ne partage pas.)
  const share = (typeof _edlPrefersShare === 'function') ? _edlPrefersShare() : false;
  b.textContent = share ? '📤 Partager' : '⬇️ Télécharger le PDF';
  b.title = share ? 'Partager la quittance au locataire' : 'Enregistrer le PDF sur cet ordinateur';
}
/**
 * D27 — LE geste du bouton unique. Même sortie pour tout le monde (`_pdfSortie`, partagée avec
 * l'EDL) : seul le GÉNÉRATEUR du PDF change. Un document non persisté (reçu partiel, courrier de
 * relance, quittance libre) n'a pas d'id, mais il a son HTML : le même moteur natif que les
 * autres documents (`_docHtmlToNativeBlob`, D26) le transforme en PDF.
 */
async function _qpAction() {
  const ifr = el('ov-quit-preview-iframe') || {};
  if (ifr._quitId) return window._shareQuittancePreviewModal && window._shareQuittancePreviewModal();
  const built = ifr._docBuilt;
  if (!built) { showToast('Aucun document ouvert', 'err'); return; }
  const titre = ifr._docTitre || 'Document';
  if (typeof window._docHtmlToNativeBlob !== 'function') {
    showToast('Module PDF non chargé (rafraîchir la page)', 'err', 5000); return;
  }
  await _pdfSortie({
    fileName: _edlSanitize(titre) + '.pdf',
    desc: 'PDF (' + titre.toLowerCase() + ')',
    genererAvant: true,
    titre,
    genererBlob: () => window._docHtmlToNativeBlob(built.html, ifr._docEnt || {})
  });
}
// v15.104 — Wrappers footer modale aperçu quittance (#ov-quit-preview)
// Lisent l'id stocké sur ov-quit-preview-iframe + délèguent aux fonctions existantes.
window._shareQuittancePreviewModal = function() {
  const id = el('ov-quit-preview-iframe')?._quitId;
  if (!id) { showToast('Aucune quittance ouverte', 'err'); return; }
  window._shareQuittanceWithPdf(id);
};


function delQuit(id) {
  if(!confirm2('Supprimer ?')) return;
  // UNDO-OP v14.23
  _undoOp(`Suppression d'une quittance`, () => {
    // v14.30 BUG-DRIVE-RESURRECTION : tombstone (cf delMv)
    const idx = DB.quittances.findIndex(q=>q.id===id);
    if (idx >= 0) {
      const old = DB.quittances[idx];
      // v15.03 AUDIT-FIX : trace delete (RGPD : quittance = lien locataire)
      if (typeof _auditLog === 'function') _auditLog('delete', 'quittance', id, (old.logement||'')+'/'+(old.mois||''));
      // AUDIT I-2 — la trace du geste forcé meurt avec la quittance, dans la MÊME opération
      // (donc annulable d'un bloc). Sans ça, après suppression le bandeau disait « ce mois
      // n'est pas soldé » pendant que l'aperçu sortait une quittance pleine.
      if (typeof _qeDelMeta === 'function' && typeof window.moisFrToYm === 'function') {
        const _ymSupp = window.moisFrToYm(old.mois);
        if (_ymSupp) _qeDelMeta(old.logement, _ymSupp);
      }
      DB.quittances[idx] = {
        id: old.id, _deleted: true,
        _deletedAt: new Date().toISOString(),
        _modifiedAt: new Date().toISOString(),
        entity: old.entity || '',     // pour _buildEntityPayload (q.entity===nom)
        logement: old.logement || ''  // pour _buildEntityPayload (refs.has(q.logement))
      };
    }
    saveDB();
    if (typeof rLoyers === 'function') rLoyers();
    _refreshAfterMutation(); // v14.28 REFRESH-LIVE
  });
  _undoToast('Quittance supprimée');
}


// ============================================================================
// ONGLET LOYERS (CDC-QUITTANCES-IRL D1/D3/D5/D9/D10/D11)
//
// Cet écran ne DÉTIENT aucune donnée : il lit le verdict du mois (`_loyerEtatLot`,
// qui consomme la cascade unique) et la case du bail. Il ne calcule ni dû, ni payé,
// ni imputation. Trois blocs, repliés à une ligne quand ils sont vides.
// ============================================================================

/** Les lots à considérer : vivants, dans l'entité active, avec un bail (occupés). */
function _lyLots() {
  const alive = (typeof _isAlive === 'function') ? _isAlive : (x => x && !x._deleted);
  const _nr = (x) => String(x == null ? '' : x).trim().toLowerCase();
  // Un bail ARCHIVÉ compte encore : une dette ne s'éteint pas au départ du locataire, et
  // c'est justement là qu'on a besoin du courrier de relance (D9 : « jusqu'au solde »).
  // Les lots soldés retombent naturellement hors des trois blocs.
  const aEuUnBail = (ref) => !!_findBailByRefTolerant(ref)
    || (DB.baux_historique || []).some(b => b && !b._deleted && _nr(b.ref) === _nr(ref));
  return (DB.logements || []).filter(alive)
    .filter(l => (typeof _logInEnt !== 'function') || _logInEnt(l))
    .filter(l => aEuUnBail(l.ref));
}

/** Les 'YYYY-MM' déjà quittancés d'un lot. */
function _lyDejaYm(ref) {
  const alive = (typeof _isAlive === 'function') ? _isAlive : (x => x && !x._deleted);
  return (DB.quittances || []).filter(q => alive(q) && q.logement === ref)
    .map(q => window.moisFrToYm(q.mois)).filter(Boolean);
}

/** L'état complet d'un lot pour l'écran : verdict + case du bail + retard. */
function _lyEtatLot(l) {
  const bail = _findBailByRefTolerant(l.ref);
  const etat = _loyerEtatLot(l.ref, { visibles: true });   // FINANCES-SUIVI-V2 : même chiffre que Finances (baux visibles)
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  const tol = (typeof window._loyerToleranceActive === 'function') ? window._loyerToleranceActive(today) : false;
  return {
    log: l, ref: l.ref, bail,
    demande: !!(bail && bail.quittanceDemandee),
    etat,
    aQuittancer: etat ? window.moisAQuittancer(etat, _lyDejaYm(l.ref)) : [],
    retard: etat ? window.retardLot(etat, { toleranceActive: tol }) : { enRetard: false }
  };
}

/* ══ ÉTAT D'INTERFACE (V1) ══════════════════════════════════════════════════
   L'écran est un tableau de bord : trois tuiles en toutes lettres, UNE SEULE liste
   dessous — celle de la tuile cliquée, les impayés par défaut. Motif de Didier :
   « on mélange des quittances (document obligatoire) avec des loyers non payés —
   2 niveaux de priorités ».
   Rien de tout cela n'est une donnée : c'est de l'état d'écran, volatil, jamais en base. */
// KPI (CDC-KPI §4, révision 27/08 — mockup loyers-v4) : les trois familles sont des BLOCS EMPILÉS
// VISIBLES, dans l'ordre du cash — Impayés, Révisions (à préparer + en retard fusionnées),
// Quittances. Plus de sélecteur à tuiles ni de bascule « Tous les loyers » (elle doublonnait le
// Suivi, retirée). Plus de sélecteur à tuiles : `_lyUI` ne garde que suivi/frise/blocs/tousOpen.
var _lyUI = { suivi: null, frise: null, blocs: {}, tousOpen: false };
function _lyOuvrirSuivi(k) { _lyUI.suivi = (_lyUI.suivi === k) ? null : k; rLoyers(); }
function _lyOuvrirMois(ym) { _lyUI.frise = (_lyUI.frise === ym) ? null : ym; rLoyers(); }
/** Replier/déplier un bloc — dans le DOM, sans re-render : la liste ne clignote pas. */
function _lyToggleBlk(id) {
  const d = el(id); if (!d) return;
  const off = d.classList.toggle('closed');
  _lyUI.blocs[id] = !off;
}
/** Déplier/replier « Tous les loyers » — re-render (contenu lourd : rendu à l'ouverture seulement). */
function _lyToggleTous() { _lyUI.tousOpen = !_lyUI.tousOpen; if (typeof rLoyers === 'function') rLoyers(); }

/** Les trois familles-blocs de l'écran — libellés figés par V14 (jamais d'icône sans mot). */
// v15.63x REFONTE-PC Loyers — emoji d'en-tête → noms de line-icons (_uiIcon), rendus en 28822.
const _LY_FAM = {
  quit:      { ico: 'receipt', t: 'Quittances demandées', hint: 'Mois soldé — la quittance peut être remise' },
  retard:    { ico: 'warn',    t: 'Impayés',              hint: 'Loyer ou charges non réglés — aucun document n\'est émis' },
  prep:      { ico: 'chart',   t: 'Révisions', hint: 'À préparer ou en retard — dans les deux cas, une lettre à faire' }
};

function rLoyers() {
  const host = el('ly-blocs'); if (!host) return;
  // IRL-REVISION R9 — une révision programmée dont la date d'effet arrive pendant que l'app reste
  // ouverte s'applique ici aussi, pas seulement au démarrage. Idempotent (n'écrit que s'il y a
  // quelque chose à appliquer). Hors ligne : rien (même garde que _bootDataJobs, invariant 19a).
  // Audit M10 — ni en lecture seule : un rendu n'écrit pas là où l'utilisateur ne peut pas écrire.
  try { if (!(typeof window !== 'undefined' && window.__immoHorsLigne) && !(typeof _appReadOnly !== 'undefined' && _appReadOnly) && typeof _applyPendingIRLRevisions === 'function') _applyPendingIRLRevisions(); } catch (e) { console.warn('[IRL pending apply]', e); }
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  const ymCourant = today.slice(0, 7);
  const moisCourant = window.ymToMoisFr ? window.ymToMoisFr(ymCourant) : ymCourant;

  if (typeof window.moisAQuittancer !== 'function') {
    host.innerHTML = `<div class="ly2 cft"><div class="ly2-blk t-info"><div class="ly2-empty"><b>Module Loyers non chargé</b>
      Ouvrir l'application via http (les modules ES ne se chargent pas en file://).</div></div></div>`;
    return;
  }

  const lots = _lyLots();
  if (!lots.length) {
    host.innerHTML = `<div class="ly2 cft"><div class="ly2-blk t-info"><div class="ly2-empty"><b>Aucun bail en cours</b>
      Les loyers apparaîtront ici dès qu'un logement sera loué.
      <div style="margin-top:10px"><button class="btn bp" onclick="go('baux')">Créer un bail</button></div></div></div></div>`;
    return;
  }

  const etats = lots.map(_lyEtatLot);
  const demandes = etats.filter(e => e.demande && e.aQuittancer.length);
  const retards  = etats.filter(e => e.retard.enRetard);
  const rev      = _lyRevisionsTriees(etats);
  const nbRev    = rev.aPreparer.length + rev.enRetard.length;
  const loues    = etats.filter(e => e.bail).length;

  // ── 1. La ligne de commande : titre, contexte, bouton. Une seule ligne. ──
  let html = `<div class="ly2-cmd">
    <div class="ttl">Loyers<em>${escHtml(moisCourant)} · ${loues} lot${loues > 1 ? 's' : ''} loué${loues > 1 ? 's' : ''} sur ${lots.length} suivi${lots.length > 1 ? 's' : ''}</em></div>
    <div class="sp"></div>
    <button class="btn bp" onclick="_openFaireQuittance()">＋ Faire une quittance</button></div>`;

  // ── 2. Les trois familles en BLOCS EMPILÉS VISIBLES (CDC-KPI §4, révision 27/08 — mockup
  //    loyers-v4). Ordre du cash : Impayés d'abord, puis Révisions (« à préparer » + « en retard »
  //    FUSIONNÉES : dans les deux cas une lettre à faire), puis Quittances. Un bloc vide reste
  //    replié à sa seule ligne d'en-tête (le silence est l'information). Réutilise _lyBloc + les
  //    lignes existantes + le groupement gouttière — rien n'est recréé. Remplace le sélecteur à
  //    tuiles (ex-D25) et la bascule « Tous les loyers » (elle doublonnait le Suivi).
  html += _lyBloc('retard', retards.length, retards.map(_lyLigneRetard),
    'Tous les loyers et toutes les charges sont à jour.');
  const revItems = rev.aPreparer.map(x => _lyLigneRev(x, false))
    .concat(rev.enRetard.map(x => _lyLigneRev(x, true)))
    .concat(rev.programmees.map(_lyLigneRevProg));
  const nProg = rev.programmees.length;
  html += _lyBloc('prep', nbRev, revItems,
    'Aucune révision à préparer ni en retard.', false,
    nProg ? `${nProg} révision${nProg > 1 ? 's' : ''} programmée${nProg > 1 ? 's' : ''} — rien à faire` : '');
  html += _lyBloc('quit', demandes.length, demandes.map(_lyLigneQuittance),
    'Personne n\'attend de quittance ce mois-ci.');

  // ── 4. La frise IRL : toujours affichée, jamais repliée (V3/V4) ──
  html += _lyFriseRuban(etats);

  // ── 4bis. DPE à compléter (D23/D25) — juste SOUS les révisions : il parle du bloc du dessus.
  // Informe (compte les lots sans DPE), ne retient rien ; saisie rapide écrite sur le bien.
  html += _lyDpeBlock(etats);

  // ── 4ter. Dépliant « Tous les loyers » : la vue d'ensemble inline (frise 12 mois par lot,
  //    groupée par immeuble/bailleur), repliée par défaut. Réutilise _lyTousLoyersHtml — LE MÊME
  //    constructeur que la modale Suivi — avec l'option `grouped` (via _lyGrouper). Contenu lourd :
  //    rendu à l'ouverture seulement. CDC-KPI §4, mockup loyers-v4 (solution B validée 27/08).
  {
    const _tousEnt = (typeof _finActiveEnt === 'function') ? _finActiveEnt() : '';
    const _tousOpen = !!_lyUI.tousOpen;
    html += '<div class="ly2-blk t-info' + (_tousOpen ? '' : ' closed') + '" id="ly-tous">'
      + '<div class="ly2-blk-h" onclick="_lyToggleTous()" style="cursor:pointer"><span class="chev">▾</span>'
      + '<span class="t">' + _uiIcon('list') + ' Tous les loyers</span>'
      + '<span class="hint">' + loues + ' bail' + (loues > 1 ? 'ux' : '') + ' · frise 12 mois, groupés par immeuble</span></div>'
      + (_tousOpen ? '<div class="ly2-body" style="padding:12px 14px">'
          + _lyTousLoyersHtml(new Date().getFullYear(), _tousEnt, { inline: true, grouped: true }).html + '</div>' : '')
      + '</div>';
  }

  // ── 5. La bande « Suivi » : ce qui ne demande AUCUN geste, chiffré, à un clic ──
  const nQuitMois = _lyQuittancesDuMois(ymCourant).count;
  const pastille = (k, lbl, n) =>
    `<button class="ly2-s${_lyUI.suivi === k ? ' open' : ''}" onclick="_lyOuvrirSuivi('${k}')">${lbl}${n !== '' ? ` <b>${n}</b>` : ''}</button>`;
  html += '<div class="ly2-suivi"><span class="lg">Suivi</span>'
    + pastille('perdue', _uiIcon('pause') + ' IRL non appliquées', rev.perdues.length)
    + pastille('muet', _uiIcon('lock') + ' Non révisables', rev.muets.length)
    + pastille('quit-mois', _uiIcon('receipt') + ' Quittances éditées ce mois', nQuitMois)
    + '</div>';
  if (_lyUI.suivi) html += _lyPanneauSuivi(_lyUI.suivi, rev, ymCourant, moisCourant);

  host.innerHTML = `<div class="ly2 cft">${html}</div>`;
}

// CDC-QUITTANCES-IRL D22 / I15 — LE COMPTEUR de l'entrée de menu « Loyers ». Il vaut EXACTEMENT
// le nombre de LIGNES ACTIONNABLES de l'écran : quittances demandées prêtes à éditer + lots pas à
// jour + révisions à préparer. Ni les « non révisables » (gelé/bail<1an/indice) ni les « perdues »
// (D15) n'y entrent — rien à y faire, rien à compter. Écran vide → 0 → pas de pastille (I15).
// Réutilise LES MÊMES calculs que rLoyers (jamais une 2ᵉ source qui divergerait).
function _lyBadgeCount() {
  try {
    if (typeof window.moisAQuittancer !== 'function' || typeof _lyLots !== 'function' || typeof window.loyersBadgeCount !== 'function') return 0;
    const lots = _lyLots();
    if (!lots.length) return 0;
    const etats = lots.map(_lyEtatLot);
    // I15 encodé dans le module pur js/core/loyers-badge.js (testé) : l'écran fournit les mêmes
    // états + révisions triées qu'il affiche, le module fait la somme des lignes actionnables.
    return window.loyersBadgeCount(etats, _lyRevisionsTriees(etats));
  } catch (e) { return 0; }
}
// Détail des trois nombres, pour l'info-bulle de la pastille (D22) — même source que le compteur.
function _lyBadgeTip(n) {
  try {
    if (typeof window.moisAQuittancer !== 'function' || typeof _lyLots !== 'function' || typeof window.loyersBadgeBreakdown !== 'function') return '';
    const lots = _lyLots(); if (!lots.length) return '';
    const etats = lots.map(_lyEtatLot);
    const b = window.loyersBadgeBreakdown(etats, _lyRevisionsTriees(etats));
    return `Loyers — ${n} à traiter : ${b.revisions} révision${b.revisions > 1 ? 's' : ''} à préparer · ${b.quittances} quittance${b.quittances > 1 ? 's' : ''} demandée${b.quittances > 1 ? 's' : ''} · ${b.pasAJour} lot${b.pasAJour > 1 ? 's' : ''} pas à jour`;
  } catch (e) { return ''; }
}

// CDC-QUITTANCES-IRL D23 — LE BLOC « 🏷 DPE à compléter », juste sous les révisions. Il INFORME
// (compte les lots dont le DPE est absent ou périmé) et ne retient RIEN : la révision reste
// proposable (D23). Saisie rapide en un clic (classe A→G + date), écrite sur le BIEN
// (log.diagnostics.dpe, la source de vérité depuis v15.233) et nulle part ailleurs (I17). Un lot
// « non concerné » (garage/cave/parking) ne réapparaît jamais. Un DPE > 10 ans = manquant.
function _lyDpeBlock(etats) {
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  const gate = (window.IrlDpeGate && typeof window.IrlDpeGate.irlDpeGate === 'function') ? window.IrlDpeGate.irlDpeGate : null;
  const aCompleter = [];
  for (const e of etats) {
    if (!e.bail) continue;                                   // lots loués (même périmètre que les révisions)
    const d = (typeof _diagGet === 'function') ? _diagGet(e.log, 'dpe') : null;
    if (d && d.na) continue;                                 // « non concerné » : jamais réclamé (I17)
    const cls = (d && d.classe) || '';
    const dat = (d && d.date) || '';
    const g = gate ? gate({ dpe: cls, dpeDate: dat, todayISO: today }) : { dpeManquant: !cls, dpeExpire: false };
    if (g.dpeManquant) aCompleter.push({ e, expire: !!g.dpeExpire });
  }
  const n = aCompleter.length;
  if (!n) {
    return `<div class="ly2-blk t-info"><div class="ly2-h"><span class="t">${_uiIcon('tag')} DPE à compléter</span>`
      + `<span class="c">tous les DPE des lots loués sont renseignés</span></div></div>`;
  }
  const rows = aCompleter.map(({ e, expire }) => {
    const ref = _lyQ(e.ref);
    const classes = ['A', 'B', 'C', 'D', 'E', 'F', 'G'].map(c =>
      `<button type="button" class="ly-dpe-c${(c === 'F' || c === 'G') ? ' fg' : ''}" onclick="_lyDpeRapide('${ref}','${c}',this)" `
      + `title="${(c === 'F' || c === 'G') ? 'Classe ' + c + ' — loyer gelé (loi Climat art. 23)' : 'Classe ' + c}">${c}</button>`).join('');
    return `<div class="ly-dpe-ln"><span class="who"><b>${escHtml(_logLabel(e.ref))}</b> <span class="mu" style="display:inline">${escHtml((e.log && e.log.adr) || '')}</span>`
      + `${expire ? ' <span class="mu" style="display:inline">· DPE > 10 ans</span>' : ''}</span>`
      + `<span class="pick"><input type="date" class="ly-dpe-d" title="Date de réalisation du DPE" />${classes}`
      + `<button type="button" class="btn bs bb" onclick="_lyDpeNonConcerne('${ref}')" title="Garage, cave, parking — pas de DPE exigible par nature">non concerné</button></span></div>`;
  }).join('');
  return `<div class="ly2-blk t-info"><div class="ly2-h"><span class="t">${_uiIcon('tag')} DPE à compléter</span>`
    + `<span class="c">${n} lot${n > 1 ? 's' : ''} sans DPE en base — la révision reste possible, mais un F ou G ne se révise pas</span></div>`
    + `<div class="ly-dpe-body">${rows}</div></div>`;
}
// I17 — écrit la classe + la date sur le BIEN (log.diagnostics.dpe), source de vérité. La date
// est OBLIGATOIRE (un DPE sans date de réalisation ne prouve pas sa validité).
function _lyDpeRapide(ref, classe, btn) {
  const log = DB.logements.find(l => l.ref === ref); if (!log) return;
  const row = (btn && btn.closest) ? btn.closest('.ly-dpe-ln') : null;
  const di = row ? row.querySelector('.ly-dpe-d') : null;
  const date = (di && di.value) || '';
  if (!date) { try { showToast('Saisir d\'abord la date de réalisation du DPE', 'warn', 3000); } catch (e) {} if (di) di.focus(); return; }
  if (!log.diagnostics) log.diagnostics = {};
  const cur = (log.diagnostics.dpe && typeof log.diagnostics.dpe === 'object') ? log.diagnostics.dpe : {};
  log.diagnostics.dpe = Object.assign({}, cur, { classe: classe, date: date, na: false });
  if (typeof _stamp === 'function') _stamp(log);
  saveDB();
  try { showToast('DPE ' + classe + ' enregistré sur ' + _logLabel(ref) + ((classe === 'F' || classe === 'G') ? ' — loyer gelé' : ''), 'ok', 3000); } catch (e) {}
  try { rLoyers(); } catch (e) {}
  try { _renderInboxSurfaces(); } catch (e) {}
}
// I17 — « non concerné » : marque le DPE na sur le bien ; le lot ne réapparaît jamais dans le rappel.
function _lyDpeNonConcerne(ref) {
  const log = DB.logements.find(l => l.ref === ref); if (!log) return;
  if (!log.diagnostics) log.diagnostics = {};
  const cur = (log.diagnostics.dpe && typeof log.diagnostics.dpe === 'object') ? log.diagnostics.dpe : {};
  log.diagnostics.dpe = Object.assign({}, cur, { na: true });
  if (typeof _stamp === 'function') _stamp(log);
  saveDB();
  try { showToast(_logLabel(ref) + ' — DPE marqué « non concerné »', 'ok', 2500); } catch (e) {}
  try { rLoyers(); } catch (e) {}
  try { _renderInboxSurfaces(); } catch (e) {}
}

/**
 * Échappe une valeur destinée à une CHAÎNE JS placée DANS UN ATTRIBUT HTML
 * (`onclick="f('…')"`). Les deux échappements sont nécessaires et dans cet ordre :
 *   1. chaîne JS  — `\` et `'`, sinon une apostrophe ferme l'argument ;
 *   2. attribut HTML — `"` `<` `&`, sinon un guillemet sort de l'attribut.
 * Un seul des deux ne suffit pas : `escHtml` seul produit `&#39;`, que le parseur HTML
 * redécode en `'` AVANT la compilation du JS — donc rétablit l'évasion qu'il devait fermer.
 * Aujourd'hui mono-locataire, ce serait du self-XSS ; avec le partage SCI, la référence
 * saisie par un membre est rendue dans le DOM des autres.
 */
function _lyQ(s2) {
  return escHtml(String(s2 == null ? '' : s2).replace(/\\/g, '\\\\').replace(/'/g, "\\'"));
}
/* Valeur passée telle quelle (nombre ou chaîne, type conservé) en argument d'un gestionnaire on…="…" :
   littéral JSON (guillemets doubles), puis échappé pour l'attribut — le parseur HTML le redécode avant le JS. */
function _jsArgAttr(v) {
  return escHtml(JSON.stringify(v == null ? null : v));
}

/**
 * V15 — LA ligne : quatre colonnes, UNE ligne de texte, 40 px en densité Confort.
 * Elle ne répète JAMAIS ce que dit l'en-tête de son bloc (« juillet 2026 », pas
 * « juillet 2026 soldé, non quittancé ») ; le détail du calcul vit dans la fenêtre
 * de validation, pas dans la liste.
 * @param {{log:object, ref:string, loc:string, demande:boolean,
 *          contexte:string, montant:string, actions:string}} o
 */
function _lyRow(o) {
  return `<div class="ly2-r">
    <div class="c1"><b>${escHtml(_logLabel(o.ref))}</b><span>${escHtml(o.loc || '—')}</span>${o.demande ? '<span class="ly2-ask" title="Le locataire demande une quittance chaque mois"></span>' : ''}</div>
    <div class="c2">${o.contexte || ''}</div>
    <div class="c3">${o.montant || ''}</div>
    <div class="c4">${o.actions || ''}</div>
  </div>`;
}

/**
 * Un bloc de famille. Vide : il reste, replié à sa seule ligne d'en-tête, avec son
 * compteur à 0 et la mention « rien ce mois-ci » — l'utilisateur voit que la question
 * a été posée et qu'il n'y a rien, il ne se demande pas où c'est passé.
 * @param {string} fam clé de _LY_FAM
 * @param {number} n
 * @param {Array<{log:object, html:string}>} items
 * @param {string} vide phrase de l'état vide
 * @param {boolean} [replie] ouvrir replié (révisions en retard : présentes, pas au premier plan)
 */
function _lyBloc(fam, n, items, vide, replie, hintSeul) {
  const f = _LY_FAM[fam];
  const id = 'ly-blk-' + fam;
  const memo = _lyUI.blocs[id];
  // IRL-REVISION R5 — un bloc peut porter des lignes NON comptées (révisions programmées) :
  // le compteur reste celui des gestes à faire, mais les lignes restent consultables.
  const nLignes = (items || []).filter(Boolean).length;
  const closed = !nLignes || (memo === undefined ? !!replie : !memo);
  return `<div class="ly2-blk t-${fam}${closed ? ' closed' : ''}" id="${id}">
    <div class="ly2-blk-h" onclick="_lyToggleBlk('${id}')"><span class="chev">▾</span>
      <span class="t">${_uiIcon(f.ico,15)} ${f.t}</span><span class="n">${n}</span>
      ${n ? `<span class="hint">${f.hint}</span>`
        : (nLignes && hintSeul ? `<span class="hint">${escHtml(hintSeul)}</span>` : `<span class="vide">${escHtml(vide || 'rien ce mois-ci')}</span>`)}</div>
    ${nLignes ? `<div class="ly2-body">${_lyGrouper(items)}</div>` : ''}
  </div>`;
}

/**
 * V2 — LE GROUPEMENT BAILLEUR > IMMEUBLE EST UNE COLONNE, PAS DES LIGNES.
 *
 * L'écran livré en v15.537 dépensait 45 lignes d'en-tête pour 32 lignes de données,
 * parce que `_lyBloc` rappelait les mêmes 4 bailleurs et les mêmes 6 immeubles DANS
 * CHAQUE bloc. Ici le contexte vit dans une gouttière à gauche des lignes : zéro ligne
 * consommée. À 390 px la gouttière redevient UNE ligne fusionnée « bailleur · immeuble ».
 *
 * Le groupage lui-même n'est pas réinventé : il vient de js/core/group-by-imm.js
 * (`_grouperLotsParBailleurEtImmeuble`). Les lots sans immeuble et sans bailleur restent
 * VISIBLES, dans un groupe nommé.
 *
 * @param {Array<{log:object, html:string}>} items
 */
function _lyGrouper(items) {
  const list = (items || []).filter(Boolean);
  if (!list.length) return '';
  const G = (typeof window !== 'undefined') ? window.GroupByImm : null;
  if (!G || typeof G._grouperLotsParBailleurEtImmeuble !== 'function') {
    return list.map(x => x.html).join('');   // module absent : jamais d'écran vide
  }
  const parBailleur = !(typeof _entActif === 'function' && _entActif());
  const parRef = new Map(list.map(x => [x.log && x.log.ref, x.html]));
  const groupes = G._grouperLotsParBailleurEtImmeuble(list.map(x => x.log), { parBailleur });
  let out = '', alt = false;
  for (const gb of groupes) {
    let premier = true;
    for (const gi of gb.immeubles) {
      const bail = premier
        ? (gb.isUnassigned ? '<b class="orph">Sans bailleur</b>' : `<b>${escHtml(gb.entite || '')}</b>`)
        : '';
      const imm = gi.isUnassigned ? '<span class="orph">Sans immeuble</span>' : `<span>${escHtml(gi.imm || '')}</span>`;
      const lignes = gi.logements.map(l => parRef.get(l && l.ref) || '').join('');
      out += `<div class="ly2-run${premier ? ' newb' : ''}${alt ? ' alt' : ''}">
        <div class="ly2-gut">${parBailleur ? bail : ''}${imm}</div>
        <div class="ly2-rows">${lignes}</div></div>`;
      premier = false;
    }
    alt = !alt;
  }
  return out;
}

/* ── Les lignes des trois familles ────────────────────────────────────────── */

/** D3/D8 — un lot dont la case « quittance demandée » est cochée et qui a des mois soldés. */
function _lyLigneQuittance(e) {
  const n = e.aQuittancer.length;
  const mois = e.aQuittancer.map(y => window.ymToMoisFr(y));
  const du = e.aQuittancer.reduce((s2, ym) => s2 + ((e.etat.byYm[ym] || {}).du || 0), 0);
  const contexte = n === 1 ? escHtml(mois[0])
    : `${n} mois · ${escHtml(mois[0])} → ${escHtml(mois[n - 1])}`;
  return { log: e.log, html: _lyRow({
    ref: e.ref, loc: e.log.locataire, demande: true, contexte,
    montant: `<b>${fmt(du)}</b>`,
    actions: `<button class="btn bp bb" onclick="_lyEditerQuittances('${_lyQ(e.ref)}')">${n === 1 ? 'Quittance' : 'Éditer les ' + n}</button>
      <button class="btn bs bb" onclick="_openFaireQuittance('${_lyQ(e.ref)}')" title="Détail mois par mois">⋯</button>`
  }) };
}

/** D9/D10 — UNE ligne par lot, quel que soit le nombre de mois, loyer ET charges. */
/** R0-C C1 — « Encaissement du JJ/MM (montant) antérieur à la date d'achat : à vérifier avant de relancer ».
 *  Rend '' s'il n'y a rien à signaler. */
function _lyAVerifierTexte(etat) {
  const av = (etat && etat.aVerifier) || [];
  if (!av.length) return '';
  const jm = (iso) => String(iso).slice(8, 10) + '/' + String(iso).slice(5, 7);
  const liste = av.map(a => 'du ' + jm(a.date) + ' (' + fmt(a.montant) + ')').join(', ');
  return (av.length > 1 ? 'Encaissements ' : 'Encaissement ') + liste + (av.length > 1 ? ' antérieurs' : ' antérieur')
    + ' à la date d\'achat : à vérifier avant de relancer.';
}
function _lyLigneRetard(e) {
  const r = e.retard;
  const depuis = r.depuisYm ? window.ymToMoisFr(r.depuisYm) : '';
  const quoi = r.chargesSeules ? 'charges non réglées'
    : (r.loyerSeul ? 'loyer non réglé' : 'loyer <b>et</b> charges');
  const contexte = r.nbMois > 1
    ? `depuis ${escHtml(depuis)} · ${quoi}`
    : `${escHtml(depuis)} · ${quoi}`;
  const pastille = r.chargesSeules
    ? '<span class="ly2-p wa">charges</span>'
    : `<span class="ly2-p er">${r.nbMois} mois</span>`;
  const partiel = e.etat.list.filter(m => m.partiel);
  const btnRecu = partiel.length
    ? `<button class="btn bs bb" onclick="_lyRecuPartiel('${_lyQ(e.ref)}','${partiel[partiel.length - 1].ym}')" title="Art. 21 : en cas de paiement partiel, le bailleur délivre un reçu">Reçu partiel</button>`
    : '';
  return { log: e.log, html: _lyRow({
    ref: e.ref, loc: e.log.locataire, demande: !!e.demande, contexte,
    montant: `<b>${fmt(r.reste)}</b> ${pastille}`,
    actions: `<button class="btn bp bb" onclick="_lyRelance('${_lyQ(e.ref)}')">Relance</button>${btnRecu}
      <button class="btn bs bb" onclick="_impayesOuvrirSur('${_lyQ(e.ref)}')" title="Détail mois par mois">⋯</button>`
  }) + (() => { const t = _lyAVerifierTexte(e.etat); return t ? `<div class="ly2-av" role="note">${_uiIcon('warn', 14)}<span>${escHtml(t)}</span></div>` : ''; })() };
}

/**
 * V15 — la ligne de révision ALLÉGÉE : la date d'effet et le pourcentage, rien de plus.
 * La date de bail et les deux indices vivent dans la fenêtre de validation (`applyIRL`),
 * pas dans la liste — c'est là qu'on en a besoin pour décider.
 */
/**
 * Maquette 5 validée (option C, 25/09) — la révision de l'année écoulée n'est pas faite ET on est
 * dans le mois de rappel de la suivante : deux hausses tomberaient en quelques jours (« une seule
 * fois par an »). On montre l'enjeu chiffré et on fait CHOISIR ; rien n'est bloqué.
 *  1 · Faire les deux : l'ancienne à la demande (aujourd'hui), la nouvelle à sa date.
 *  2 · Renoncer à l'ancienne (skipIRL, art. 17-1) et préparer la nouvelle.
 */
function _lyLigneDecision({ e, rev }) {
  const C = (typeof window !== 'undefined') ? window.IrlCalendrier : null;
  const eff2 = rev.conflitSuivant.effetIso;
  const T = rev.T;
  const n2 = (C && typeof C.anneeIndice === 'function') ? C.anneeIndice(T, eff2) : null;
  const v2 = n2 != null ? irlVal(T, n2) : null, v21 = n2 != null ? irlVal(T, n2 - 1) : null;
  const r2 = (v2 && v21) ? v2 / v21 : null;
  const an1 = String(rev.effetPrevuIso || '').slice(0, 4), an2 = String(eff2).slice(0, 4);
  const today = _todayIsoLocal();
  // I3 (passe 4) — la date RÉELLE : « aujourd'hui », sauf mois déjà quittancé (report au mois libre).
  const effet1 = (typeof window._baremeClampDateEffet === 'function')
    ? window._baremeClampDateEffet(today, { libre: true, annivMoisPremierIso: rev.effetPrevuIso, dernierMoisQuittanceYm: _dernierMoisQuittanceYm(e.ref) || undefined }).effetIso
    : today;
  const combine = effet1 >= eff2;
  const h1 = rev.nouveauHC;
  const h12 = r2 ? Math.round(h1 * r2 * 100) / 100 : null;
  const _base = (rev.ancienHC != null) ? rev.ancienHC : e.log.hc;   // O6 : base du barème, comme h1
  const h2 = r2 ? Math.round(_base * r2 * 100) / 100 : null;
  const perte = (h12 != null && h2 != null) ? Math.round((h12 - h2) * 100) / 100 : null;
  const i2 = r2 ? '' : ` (indice T${T} ${n2 != null ? n2 : ''} pas encore publié : montant connu à sa parution)`;
  const R = _lyQ(e.ref);
  const html = `<div class="ly2-r" style="background:var(--warn-soft)">
    <div class="c1"><b>${escHtml(_logLabel(e.ref))}</b><span>${escHtml(e.log.locataire || '—')}</span></div>
    <div class="c2"><span class="ly2-p wa">à décider</span> Révision <b>de ${fd(rev.effetPrevuIso)}</b> jamais faite · celle du <b>${fd(eff2)}</b> arrive</div>
    <div class="c3"><span class="ly2-p nu">${fmt(_base).replace(' €', '')}</span> → <b>${fmt(h1)}</b></div>
    <div class="c4"><button class="btn bs bb" onclick="_lyMenuRev(event,'${R}')" title="Plus d'actions" aria-label="Plus d'actions">⋯</button></div></div>
    <div class="ly2-dec" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px;padding:10px 12px;background:var(--sur2);border-top:1px solid var(--bor)">
      <div style="background:var(--sur);border:1px solid var(--bor);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:6px">
        <div><b>1 · Faire les deux</b> <span class="ly2-p nu">aucune variation perdue</span></div>
        <div class="mu" style="font-size:12px;line-height:1.5">${an1} : <b>${fmt(_base)} → ${fmt(h1)}</b>, ${effet1 > today ? `effet au <b>${fd(effet1)}</b> (mois déjà quittancé : 1<sup>er</sup> mois libre)` : `effet à la demande (<b>${fd(effet1)}</b>)`}<br>${an2} : ${h12 != null ? `<b>${fmt(h1)} → ${fmt(h12)}</b>` : '—'}, effet au <b>${fd(eff2)}</b>${i2}</div>
        <div style="font-size:11.5px;color:var(--warn);background:var(--warn-soft);border-radius:6px;padding:6px 8px">${combine ? `La révision ${an1} prend effet au ${fd(effet1)} ; la révision ${an2} se valide ensuite, à part : effet à sa propre demande, jamais avant.` : '⚠ Deux hausses à quelques jours d’écart : la loi dit « une fois par an » — le locataire peut contester.'}</div>
        <button class="btn bp bb" style="align-self:flex-start" onclick="applyIRL('${R}',${h1},{effetIso:'${effet1}'})">Faire la révision ${an1} maintenant</button></div>
      <div style="background:var(--sur);border:1px solid var(--bor);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:6px">
        <div><b>2 · Ne faire que celle du ${fd(eff2)}</b> <span class="ly2-p nu">simple, incontestable</span></div>
        <div class="mu" style="font-size:12px;line-height:1.5">${an2} : ${h2 != null ? `<b>${fmt(_base)} → ${fmt(h2)}</b>` : '—'}, effet au <b>${fd(eff2)}</b>${i2}<br>${an1} : <b>renoncée</b> (art. 17-1)</div>
        <div style="font-size:11.5px;color:var(--warn);background:var(--warn-soft);border-radius:6px;padding:6px 8px">${perte != null ? `≈ <b>${fmt(perte)}/mois</b> de moins pour toujours (la variation de ${an1} n'est jamais appliquée).` : `La variation de ${an1} n'est jamais appliquée.`}</div>
        <button class="btn bs bb" style="align-self:flex-start" onclick="_lyRenoncerPuisPreparer('${R}')">Renoncer à ${an1}, préparer ${an2}</button></div>
    </div>`;
  return { log: e.log, html };
}

/** Option C, choix 2 : renoncer au cycle écoulé (geste existant skipIRL, confirmé), puis préparer le suivant. */
function _lyRenoncerPuisPreparer(ref) {
  const log = (DB.logements || []).find(l => l.ref === ref);
  if (!log) return;
  const avant = (DB.irlHistorique || []).length;
  skipIRL(ref);
  if ((DB.irlHistorique || []).length === avant) return;          // renonciation annulée
  const r = computeIRLRevision(log);
  if (r && r.isApplicable && r.nouveauHC) applyIRL(ref, r.nouveauHC);
  else showToast(`Révision renoncée. Rien d'autre à préparer pour l'instant${r && r.message ? ' : ' + r.message : '.'}`, 'info', 7000);
}

function _lyLigneRev({ e, rev }, tard) {
  if (tard && rev.conflitSuivant) return _lyLigneDecision({ e, rev });
  const pct = ((rev.variation || 0) * 100).toFixed(2).replace('.', ',');
  const effet = rev.effetPrevuIso ? fd(rev.effetPrevuIso) : '–';
  // Bloc « Révisions » fusionné (KPI §4) : la ligne EN RETARD porte une pastille rouge visible —
  // le regroupement par immeuble (_lyGrouper) entremêle « à préparer » et « en retard », c'est le
  // seul repère qui distingue le périssable (prescription 1 an) du courant.
  const contexte = (rev.moinsDunAn ? '<span class="ly2-p wa" title="Date de révision convenue moins d\'un an après le début du bail — avertissement à la validation">bail &lt; 1 an</span> ' : '')
    + (tard
    ? `<span class="ly2-p er">en retard</span> prévu au <b>${effet}</b>, jamais appliqué · ${rev.variation >= 0 ? '+' : ''}${pct} %`
    : `effet au <b>${effet}</b> · ${rev.variation >= 0 ? '+' : ''}${pct} %`);
  return { log: e.log, html: _lyRow({
    ref: e.ref, loc: e.log.locataire, demande: !!e.demande, contexte,
    montant: `<span class="ly2-p nu">${fmt(rev.ancienHC != null ? rev.ancienHC : e.log.hc).replace(' €', '')}</span> → <b>${fmt(rev.nouveauHC)}</b>`,
    actions: `<button class="btn bp bb" onclick="applyIRL('${_lyQ(e.ref)}',${rev.nouveauHC})">Réviser</button>
      <button class="btn bs bb" onclick="_lyMenuRev(event,'${_lyQ(e.ref)}')" title="Plus d'actions : lettre, renoncer" aria-label="Plus d'actions">⋯</button>`
  }) };
}

/**
 * IRL-REVISION R5 — la ligne d'une révision PROGRAMMÉE (validée, effet à venir) : elle quitte
 * « à préparer / en retard » mais reste visible jusqu'à sa date d'effet, avec sa lettre.
 * Les montants sont ceux de l'entrée VALIDÉE, pas un recalcul.
 */
function _lyLigneRevProg({ e, rev }) {
  const p = rev.programmee || {};
  const h = (window.IrlRevision && typeof window.IrlRevision.entreeValideeDuCycle === 'function')
    ? window.IrlRevision.entreeValideeDuCycle(DB.irlHistorique || [], e.ref, p.cycleIso, e.bail && e.bail.debut) : null;
  const ancien = h ? Number(h.ancienHC) : e.log.hc;
  const nouveau = h ? Number(h.nouveauHC) : rev.nouveauHC;
  return { log: e.log, html: _lyRow({
    ref: e.ref, loc: e.log.locataire, demande: !!e.demande,
    // La DATE vit dans la pastille : la colonne de contexte se tronque en tablette, la pastille non.
    contexte: `<span class="ly2-p ok" title="Le loyer actuel reste dû jusqu'à cette date">programmée au ${p.effetIso ? fd(p.effetIso) : '–'}</span> <span class="mu">loyer actuel dû jusque-là</span>`,
    montant: `<span class="ly2-p nu">${fmt(ancien).replace(' €', '')}</span> → <b>${fmt(nouveau)}</b>`,
    actions: `<button class="btn bs bb" onclick="previewIRLLetter('${_lyQ(e.ref)}')" title="La lettre de révision à envoyer au locataire">${_uiIcon('mail')} Lettre</button>
      <button class="btn bs bb" onclick="_lyMenuRev(event,'${_lyQ(e.ref)}')" title="Plus d'actions : lettre, date d'effet, annuler" aria-label="Plus d'actions">⋯</button>`
  }) };
}

/**
 * IRL-REVISION R7 — le menu « ⋯ » d'une ligne de révision. Avant : un clic = « Renoncer »
 * directement (skipIRL), rien d'autre. Réutilise le menu contextuel commun (_openMenuPopover).
 */
function _lyMenuRev(evt, ref) {
  const log = (DB.logements || []).find(l => l.ref === ref);
  if (!log) return;
  const rev = computeIRLRevision(log);
  if (!rev) return;
  const R = _lyQ(ref);
  const items = [];
  if (rev.programmee) {
    items.push(`<button class="bmp-item" role="menuitem" onclick="_closeBienMenus();previewIRLLetter('${R}')">${_uiIcon('mail')} Voir la lettre</button>`);
    items.push(`<button class="bmp-item" role="menuitem" onclick="_closeBienMenus();openLogFiche('${R}');setLogFicheTab('bail')">${_uiIcon('edit')} Corriger la date d'effet</button>`);
    items.push('<div class="bmp-divider" role="separator"></div>');
    items.push(`<button class="bmp-item bmp-danger" role="menuitem" onclick="_closeBienMenus();_irlAnnulerProgrammee('${R}')">${_uiIcon('close')} Annuler la révision programmée</button>`);
  } else {
    items.push(`<button class="bmp-item" role="menuitem" onclick="_closeBienMenus();previewIRLLetter('${R}')">${_uiIcon('eye')} Aperçu de la lettre</button>`);
    if (rev.isApplicable) {
      items.push(`<button class="bmp-item" role="menuitem" onclick="_closeBienMenus();applyIRL('${R}',${rev.nouveauHC})">${_uiIcon('chart')} Réviser le loyer</button>`);
      items.push('<div class="bmp-divider" role="separator"></div>');
      items.push(`<button class="bmp-item bmp-danger" role="menuitem" onclick="_closeBienMenus();skipIRL('${R}')">${_uiIcon('close')} Renoncer à cette révision</button>`);
    }
  }
  _openMenuPopover(evt, items.join(''));
}

/**
 * IRL-REVISION R7 — annuler une révision PROGRAMMÉE (effet pas encore atteint). Logique pure
 * testée : js/core/irl-revision.js (annulerRevisionProgrammee). L'entrée part en tombstone
 * (propagation cloud), le loyer d'avant reprend à la même date au barème, une trace est posée
 * dans l'historique du bail. Le cycle redevient « à faire » (délai d'un an, art. 17-1).
 */
function _irlAnnulerProgrammee(ref) {
  const IR = (typeof window !== 'undefined') ? window.IrlRevision : null;
  if (!IR || typeof IR.annulerRevisionProgrammee !== 'function') { showToast('Module indisponible (rafraîchir la page)', 'err'); return; }
  const log = (DB.logements || []).find(l => l.ref === ref);
  if (!log) return;
  const r = IR.annulerRevisionProgrammee({
    irlHistorique: DB.irlHistorique || [], bareme: DB.loyerBareme || [], ref, todayIso: _todayIsoLocal()
  });
  if (!r.ok) { showToast(r.erreur, 'err', 7000); return; }
  const e = r.entree;
  if (!confirm2(`Annuler la révision programmée de ${_logLabelRef(ref)} ?\n\n${fmt(e.ancienHC)} → ${fmt(e.nouveauHC)} au ${fd(e.dateEffet)} : le loyer reste à ${fmt(e.ancienHC)}.\n\nSi la lettre a déjà été envoyée, prévenir le locataire de l'annulation.\nLa révision de ce cycle redevient à faire (délai d'un an, art. 17-1).`)) return;
  DB.irlHistorique = r.irlHistorique;
  DB.loyerBareme = r.bareme;
  // La trace d'un forçage (gel/DPE/cycle éteint) posée pour CE cycle tombe avec lui.
  const t = _irlForcage(ref);
  if (t && String(t.cycle || '').slice(0, 10) === String(e.dateRevision || '').slice(0, 10) && DB.params && DB.params.irlForcee) {
    delete DB.params.irlForcee[String(ref)];
  }
  delete log.irlLettreEnvoyee; delete log.irlLettreEnvoyeeDate; delete log.irlLettreEnvoyeePour;
  _stamp(log);
  if (!DB.bailEvents) DB.bailEvents = [];
  DB.bailEvents.push(_stamp({ ref, bailDebut: (DB.baux[ref] && DB.baux[ref].debut) || '',
    date: _todayIsoLocal(), type: 'correction', motif: 'Révision IRL programmée annulée',
    avant: Number(e.nouveauHC), apres: Number(e.ancienHC), dateEffet: e.dateEffet,
    detail: `Révision IRL ${fmt(e.ancienHC)} → ${fmt(e.nouveauHC)} au ${fd(e.dateEffet)} annulée avant son effet` }));
  if (typeof _auditLog === 'function') _auditLog('irl-annulee', 'bail', ref, ref);
  saveDB(); refreshAllIRL(); _rPeriodPage();
  try { if (typeof rLogFiche === 'function' && currentPage === 'log-fiche') rLogFiche(); } catch (err) {}
  showToast(`Révision annulée pour ${_logLabel(ref)} — loyer maintenu à ${fmt(e.ancienHC)}`, 'ok', 5000);
}

/** Les quittances émises ce mois-ci — l'ÉTAT du mois courant (V13, point 1). */
function _lyQuittancesDuMois(ymCourant) {
  const alive = (typeof _isAlive === 'function') ? _isAlive : (x => x && !x._deleted);
  const refsEnt = (typeof _logInEnt === 'function')
    ? new Set((DB.logements || []).filter(alive).filter(_logInEnt).map(l => l.ref)) : null;
  const qs = (DB.quittances || []).filter(q => alive(q) && String(q.date || '').startsWith(ymCourant))
    .filter(q => !refsEnt || refsEnt.has(q.logement))
    .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
  if (!qs.length) return { count: 0, resume: 'aucune', html: '' };
  return {
    count: qs.length,
    resume: qs.slice(0, 3).map(q => `${_logLabel(q.logement)} ${q.mois}`).join(', '),
    html: qs.map(q => `<div class="ln"><span class="who"><b>${escHtml(_logLabel(q.logement))}</b> <span class="mu" style="display:inline">${escHtml(q.locataire || '—')}</span></span>
      <span class="mu">${escHtml(q.mois || '')} · éditée le ${fd(q.date)}</span>
      <span class="am"><b>${fmt((q.hc || 0) + (q.ch || 0))}</b></span>
      <span class="ac"><button class="btn bs bb" onclick="_ouvrirQuittanceSurMois('${_lyQ(q.logement)}','${_lyQ(window.moisFrToYm(q.mois) || '')}')" title="Rééditer : l'éditeur s'ouvre sur ce mois, le document se regénère">↺ Rééditer</button>
        <button class="btn bs bb" onclick="previewQuit(${q.id})" title="Aperçu">${_uiIcon('eye')}</button>
        <button class="btn bs bb" onclick="envoyerQuittanceParEmail(${q.id})" title="Télécharger le PDF">${_uiIcon('download')}</button>
        <button class="btn br bb" onclick="delQuit(${q.id})" title="Supprimer">${_uiIcon('trash')}</button></span></div>`).join('')
  };
}

// ── Révisions IRL (D13/D15/D16/D17) ────────────────────────────────────────
// Le CALENDRIER est tranché par js/core/irl-calendrier.js via `computeIRLRevision` (qui le
// consomme). Ici : de l'affichage, et le tri en quatre blocs — à préparer / en retard /
// IRL non appliquées / non révisables. Rien n'est recalculé.

/** Toutes les révisions du parc, avec leur état de calendrier. */
function _lyRevisions(etats) {
  if (typeof computeIRLRevision !== 'function') return [];
  const out = [];
  for (const e of etats) {
    let rev = null;
    try { rev = computeIRLRevision(e.log); } catch (err) { rev = null; }
    // Audit I4 — une révision validée « quand même » (gel F/G, garde-fou confirmé) est PROGRAMMÉE :
    // la lecture honnête la montrerait « gelée », sans ligne, donc sans lettre ni annulation.
    // On ne relit en mode forcé QUE ce cas (trace de forçage du cycle + état programmé).
    try {
      if (rev && rev.muet && typeof _irlModeLecture === 'function') {
        const m = _irlModeLecture(e.log);
        if (m.force) { const rf = computeIRLRevision(e.log, m); if (rf && rf.etat === 'programmee') rev = rf; }
      }
    } catch (err) {}
    if (rev) out.push({ e, rev });
  }
  return out;
}

/**
 * Le tri des révisions en quatre familles, une seule fois par rendu (D13/D15/D17).
 * Rien n'est recalculé ici : `computeIRLRevision` — qui consomme js/core/irl-calendrier.js —
 * a déjà tranché ; on range.
 */
function _lyRevisionsTriees(etats) {
  const toutes = _lyRevisions(etats);
  return {
    toutes,
    aPreparer: toutes.filter(({ rev }) => rev.etat === 'a-preparer'),
    enRetard:  toutes.filter(({ rev }) => rev.etat === 'en-retard'),
    // IRL-REVISION R5 — validées, effet à venir : listées (« programmée au JJ/MM »), pas comptées.
    programmees: toutes.filter(({ rev }) => rev.etat === 'programmee'),
    // D15 — les cycles éteints par le délai d'un an (art. 17-1). V14 : « IRL non appliquées ».
    perdues:   toutes.filter(({ rev }) => rev.perdue),
    // D17 — visibles, hors du compteur, aucun geste demandé pour l'instant (V20/V21 au lot 7).
    muets:     toutes.filter(({ rev }) => rev.muet)
  };
}

/** Le manque à gagner d'un cycle éteint, calculé sur les indices DE CE CYCLE (jamais ceux
 *  du cycle en cours : autre année, autre ratio — ce serait un chiffre faux sous un
 *  libellé factuel). Retourne null si l'indice de l'époque n'est pas connu. */
function _lyGainCyclePerdu(e, rev) {
  return _gfGainCycle(e.log, rev);   // DRY — un seul calcul (audit I9)
}

/**
 * V13 (point 1) + D15/D17 — LA BANDE « SUIVI ».
 * Les familles qui ne demandent AUCUN geste ne méritent pas un bloc chacune : elles
 * vivent dans une bande de pastilles chiffrées, et le clic ouvre le détail sous la bande.
 * L'information n'est pas perdue — elle est à un clic, et elle NE GROSSIT PAS l'écran.
 */
function _lyPanneauSuivi(kind, rev, ymCourant, moisCourant) {
  let head = '', rows = '', foot = '';
  if (kind === 'perdue') {
    head = `${_uiIcon('pause')} IRL non appliquées — ${rev.perdues.length} lot${rev.perdues.length > 1 ? 's' : ''}`;
    rows = rev.perdues.map(({ e, rev: r }) => {
      const prescritIso = (parseInt(r.perdue.effetIso.slice(0, 4), 10) + 1) + r.perdue.effetIso.slice(4);
      const gain = _lyGainCyclePerdu(e, r);
      return `<div class="ln"><span class="who"><b>${escHtml(_logLabel(e.ref))}</b> <span class="mu" style="display:inline">${escHtml(e.log.locataire || '—')}</span></span>
        <span class="mu">Cycle du ${fd(r.perdue.effetIso)} non appliqué, éteint le ${fd(prescritIso)} (délai d'un an)</span>
        <span class="am">${gain != null ? `<span class="ly2-p nu">≈ ${fmt(gain)}/mois non appliqués</span>` : '<span class="ly2-p nu">—</span>'}</span>
        <span class="ac"><button class="btn bs bb" onclick="_gfOuvrir('${_lyQ(e.ref)}',{surCyclePerdu:true})">Appliquer quand même</button></span></div>`;
    }).join('');
    foot = 'La révision revient de toute façon à chaque anniversaire du bail, sur les indices du moment. Seul le cycle passé s\'éteint (art. 17-1). <b>Appliquer un cycle éteint reste possible</b> : la fenêtre dit alors ce que ça engage.';
  } else if (kind === 'muet') {
    head = `${_uiIcon('lock')} Non révisables — ${rev.muets.length} lot${rev.muets.length > 1 ? 's' : ''}`;
    rows = rev.muets.map(({ e, rev: r }) =>
      `<div class="ln"><span class="who"><b>${escHtml(_logLabel(e.ref))}</b> <span class="mu" style="display:inline">${escHtml(e.log.locataire || '—')}</span></span>
        <span class="mu">${escHtml(_lyMotifMuet(r))}</span>
        <span class="am"><span class="ly2-p nu">${escHtml(_lyPastilleMuet(r))}</span></span>
        <span class="ac">${(typeof window.revisionForcable === 'function' && window.revisionForcable(r))
          ? `<button class="btn bs bb" onclick="_gfOuvrir('${_lyQ(e.ref)}')">${escHtml(window.libelleForcage(r) || 'Continuer quand même')}</button>`
            + ((r.gelDpeFG || r.dpeManquant) ? `<button class="btn bs bb" onclick="openLogModalOnTab('${_lyQ(e.ref)}','diag')" title="Voir le DPE">${_uiIcon('doc-text')}</button>` : '')
          : `<button class="btn bs bb" onclick="_gfOuvrir('${_lyQ(e.ref)}')" title="Pourquoi ce lot n’est pas révisable">Pourquoi ?</button>`}</span></div>`).join('');
    foot = 'Gel légal (DPE F/G) et DPE absent sont des <b>avertissements</b>, pas des verrous. Bail de moins d\'un an et indice non publié n\'ont rien à débloquer : la date ou l\'indice manquent.';
  } else if (kind === 'quit-mois') {
    const q = _lyQuittancesDuMois(ymCourant);
    head = `${_uiIcon('receipt')} ${escHtml(moisCourant.charAt(0).toUpperCase() + moisCourant.slice(1))} — quittances éditées`;
    rows = q.html || '<div class="foot" style="border-top:0">Aucune quittance éditée ce mois-ci.</div>';
    foot = 'Un état par (lot, mois) : le document n\'est pas stocké, chaque action le regénère depuis le barème du mois. Un mois plus ancien se réédite depuis la fiche du bien.';
  } else if (kind === 'suivi12') {
    head = _uiIcon('chart') + ' Suivi mois par mois';
    rows = `<div class="foot" style="border-top:0">Le tableau 12 mois × lots, avec le détail d'un mois au clic, est l'écran <b>Suivi des loyers</b> — déjà en prod, inchangé par ce chantier.
      <div style="margin-top:8px"><button class="btn bs" onclick="_impayesOpenVue()">Ouvrir le suivi mois par mois</button></div></div>`;
  }
  return `<div class="ly2-blk t-info" style="margin-top:8px"><div class="fr-det" style="border-top:0">
    <div class="h">${head}<button class="x" onclick="_lyOuvrirSuivi('${kind}')" title="Fermer">✕</button></div>
    ${rows}${foot ? `<div class="foot">${foot}</div>` : ''}</div></div>`;
}

function _lyMotifMuet(rev) {
  if (rev.gelDpeFG) return `DPE ${rev.dpe} — loyer gelé (loi Climat & Résilience, art. 23)`;
  if (rev.dpeManquant) return 'DPE non renseigné — à saisir sur la fiche du bien avant tout calcul';
  if (rev.etat === 'trop-jeune') return `Bail de moins d'un an — première révision au ${rev.effetPrevuIso ? fd(rev.effetPrevuIso) : (rev.premiereAnniv ? rev.premiereAnniv.toLocaleDateString('fr-FR') : '–')}`;
  if (rev.etat === 'indice-manquant') return `Indice ${rev.missingKey} pas encore publié par l'INSEE`;
  if (rev.etat === 'mobilite') return 'Bail mobilité — la révision du loyer est interdite pendant le bail';
  if (rev.etat === 'rien-a-reviser') return rev.message || 'Indice déjà appliqué — rien à réviser cette année';
  return '—';
}
function _lyPastilleMuet(rev) {
  if (rev.gelDpeFG) return 'Gelé';
  if (rev.dpeManquant) return 'DPE manquant';
  if (rev.etat === 'trop-jeune') return rev.joursAvantEffet != null ? `Dans ${rev.joursAvantEffet} j` : 'Bail < 1 an';
  if (rev.etat === 'indice-manquant') return 'Indice manquant';
  if (rev.etat === 'mobilite') return 'Bail mobilité';
  if (rev.etat === 'rien-a-reviser') return 'Rien à réviser';
  return '—';
}

/**
 * V3/V4 — LA FRISE DES RÉVISIONS : un ruban de douze tuiles, un chiffre par mois,
 * posé sous les révisions et TOUJOURS AFFICHÉ (ni replié, ni optionnel).
 *
 * Il remplace le Gantt « 1 lot × 12 mois » : sur le parc réel c'étaient 33 lignes,
 * l'un des postes qui portaient l'écran à 3 691 px. L'information n'est pas perdue —
 * cliquer un mois donne la liste des lots concernés, avec le bouton « Réviser ».
 *
 * Aucun calendrier n'est recalculé : `ganttRevisions` (js/core/irl-calendrier.js) reste
 * la source, `rubanRevisions` n'en fait que l'agrégation par colonne.
 */
const _LY_MOIS_COURT = ['janv', 'févr', 'mars', 'avr', 'mai', 'juin', 'juil', 'août', 'sept', 'oct', 'nov', 'déc'];

function _lyFriseRuban(etats) {
  if (typeof window === 'undefined' || !window.IrlCalendrier
      || typeof window.IrlCalendrier.rubanRevisions !== 'function') return '';
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  const toutes = _lyRevisions(etats);
  if (!toutes.length) return '';
  const lots = toutes.map(({ e, rev }) => ({
    ref: e.ref,
    libelle: (e.log.locataire || '') + (e.bail && e.bail.debut ? ' · bail du ' + fd(e.bail.debut) : ''),
    etat: { etat: rev.etat, effetPrevuIso: rev.effetPrevuIso || '', rappelYm: rev.rappelYm || '', muet: !!rev.muet,
      programmee: rev.programmee || null }   // R5 — la tuile d'une révision programmée = son mois d'effet
  }));
  const r = window.IrlCalendrier.rubanRevisions(window.IrlCalendrier.ganttRevisions(lots, today));
  if (!r.mois.length) return '';

  // D24 — LE RUBAN N'A QUE TROIS ÉTATS : à faire (orange, nbEffet), faite (verte, nbFaite), rien
  // (gris). La hachure « mois de rappel (M-1) » est retirée : agrégée en tuiles, elle produisait
  // une case rayée sans voisin ni chiffre. Le rappel M-1 reste ce qui fait APPARAÎTRE la ligne
  // dans « Révisions à préparer » (D13), il ne colore plus rien. Toute tuile colorée porte un
  // chiffre ≥ 1 ET un mot ; le gris veut dire « rien ce mois-ci » (I18).
  const tuiles = r.mois.map(m => {
    const aFaire = m.nbEffet;                 // révisions à préparer/en retard ce mois
    const faites = m.nbFaite;                 // révisions déjà appliquées ce mois (jamais rendues avant)
    const kind = aFaire > 0 ? 'eff' : (faites > 0 ? 'fait' : '');
    const n = aFaire > 0 ? aFaire : faites;   // le chiffre de la tuile colorée
    // R5 — une tuile verte dont toutes les révisions sont PROGRAMMÉES dit « programmée » : le
    // loyer n'a pas encore changé, « faite » serait faux.
    const toutesProg = faites > 0 && (m.faite || []).every(f => f && f.etat === 'programmee');
    const mot = aFaire > 0 ? 'à faire'
      : (faites > 0 ? (toutesProg ? (faites > 1 ? 'programmées' : 'programmée') : (faites > 1 ? 'faites' : 'faite')) : '—');
    const cls = 'fr-m' + (kind ? ' ' + kind : '')
      + (m.courant ? ' now' : '') + (_lyUI.frise === m.ym ? ' sel' : '');
    const titre = `${_LY_MOIS_COURT[m.mois - 1]} ${m.annee} — `
      + (aFaire > 0 ? `${aFaire} révision${aFaire > 1 ? 's' : ''} à faire`
         : faites > 0 ? `${faites} révision${faites > 1 ? 's' : ''} faite${faites > 1 ? 's' : ''}`
         : 'rien ce mois-ci')
      + (m.nbGel ? `, ${m.nbGel} lot${m.nbGel > 1 ? 's' : ''} non révisable${m.nbGel > 1 ? 's' : ''}` : '');
    return `<button class="${cls}" onclick="_lyOuvrirMois('${m.ym}')" title="${escHtml(titre)}">
      <span class="lbl">${_LY_MOIS_COURT[m.mois - 1]}<span class="an">${m.annee}</span></span>
      <div class="n${kind ? '' : ' z'}">${kind ? n : '·'}</div>
      <span class="u">${mot}</span>
      ${m.nbGel ? `<span class="gel">${_uiIcon('lock',12)}${m.nbGel}</span>` : ''}</button>`;
  }).join('');

  const parRef = new Map(toutes.map(({ e, rev }) => [e.ref, { e, rev }]));
  let detail = '';
  const sel = _lyUI.frise ? r.mois.find(m => m.ym === _lyUI.frise) : null;
  if (sel) {
    // D24 — le détail liste les trois natures du mois : à faire (bouton Réviser), FAITE (verte,
    // lecture seule, rendue enfin) et non révisable (motif muet). Sans les faites, une tuile
    // verte s'ouvrait sur « Rien ce mois-ci » — le défaut que D24 corrige.
    const items = (sel.effet || []).map(x => ({ x, kind: 'effet' }))
      .concat((sel.faite || []).map(x => ({ x, kind: 'faite' })))
      .concat((sel.gel || []).map(x => ({ x, kind: 'gel' })));
    const lignes = items.map(({ x, kind }) => {
      let o = parRef.get(x.ref);
      if (!o) return '';
      const effetProj = sel.ym + '-01';
      if (kind === 'gel') {
        return `<div class="ln"><span class="who"><b>${escHtml(_logLabel(x.ref))}</b> <span class="mu" style="display:inline">${escHtml(x.libelle || '')}</span></span>
          <span class="mu">${escHtml(_lyMotifMuet(o.rev))}</span>
          <span class="am"><span class="ly2-p nu">${escHtml(_lyPastilleMuet(o.rev))}</span></span>
          <span class="ac"></span></div>`;
      }
      if (kind === 'faite') {
        // Programmée : le nouveau loyer n'est pas encore en vigueur (projection du cycle, loyer
        // actuel inchangé). Faite : c'est le loyer COURANT — `nouveauHC` serait recalculé par-dessus.
        const prog = o.rev.programmee;
        // Audit M6 — le montant d'une révision programmée est celui de l'entrée VALIDÉE.
        const _hP = (prog && window.IrlRevision) ? window.IrlRevision.entreeValideeDuCycle(DB.irlHistorique || [], x.ref, prog.cycleIso, o.e.bail && o.e.bail.debut) : null;
        if (_hP) o = { ...o, rev: { ...o.rev, nouveauHC: Number(_hP.nouveauHC) } };
        return `<div class="ln"><span class="who"><b>${escHtml(_logLabel(x.ref))}</b> <span class="mu" style="display:inline">${escHtml(x.libelle || '')}</span></span>
          <span class="mu">${prog ? `programmée · effet au <b>${fd(prog.effetIso)}</b>` : `révisée · effet au <b>${fd(effetProj)}</b>`}</span>
          <span class="am"><b>${fmt(prog ? o.rev.nouveauHC : o.e.log.hc)}</b></span>
          <span class="ac"><span class="ly2-p" style="color:var(--pos)">${_uiIcon('check',13)} ${prog ? 'programmée' : 'faite'}</span></span></div>`;
      }
      // effet — le ruban PROJETTE un effet passé sur sa prochaine occurrence annuelle (« quand ça
      // retombe », pas « quand ça aurait dû ») : la ligne annonce la date de la tuile, et dit
      // séparément que le cycle d'origine n'a pas été appliqué.
      const pct = o.rev.variation != null ? ((o.rev.variation || 0) * 100).toFixed(2).replace('.', ',') : null;
      const decale = o.rev.effetPrevuIso && String(o.rev.effetPrevuIso).slice(0, 7) !== sel.ym;
      const quand = `effet au <b>${fd(effetProj)}</b>${pct != null ? ` · ${o.rev.variation >= 0 ? '+' : ''}${pct} %` : ''}`
        + (decale ? ` — cycle du ${fd(o.rev.effetPrevuIso)} non appliqué` : '');
      return `<div class="ln"><span class="who"><b>${escHtml(_logLabel(x.ref))}</b> <span class="mu" style="display:inline">${escHtml(x.libelle || '')}</span></span>
        <span class="mu">${quand}</span>
        <span class="am"><b>${fmt(o.rev.nouveauHC)}</b></span>
        <span class="ac"><button class="btn bp bb" onclick="applyIRL('${_lyQ(x.ref)}',${o.rev.nouveauHC})">Réviser</button></span></div>`;
    }).join('');
    const hParts = [];
    if (sel.nbEffet) hParts.push(`${sel.nbEffet} à faire`);
    if (sel.nbFaite) hParts.push(`${sel.nbFaite} faite${sel.nbFaite > 1 ? 's' : ''}`);
    if (sel.nbGel) hParts.push(`${sel.nbGel} non révisable${sel.nbGel > 1 ? 's' : ''}`);
    detail = `<div class="fr-det"><div class="h">${_LY_MOIS_COURT[sel.mois - 1]} ${sel.annee} — ${hParts.join(' · ') || 'rien ce mois-ci'}
      <button class="x" onclick="_lyOuvrirMois('${sel.ym}')" title="Fermer">✕</button></div>
      ${lignes || '<div class="foot" style="border-top:0">Rien ce mois-ci.</div>'}</div>`;
  }

  const gelTot = r.totalGel;
  return `<div class="ly2-frise">
    <div class="ly2-frise-h"><span class="t">${_uiIcon('calendar')} Révisions IRL — 12 mois glissants</span>
      <span class="s">${r.totalEffet} révision${r.totalEffet > 1 ? 's' : ''} à faire${gelTot ? ` · ${gelTot} lot${gelTot > 1 ? 's' : ''} non révisable${gelTot > 1 ? 's' : ''}` : ''}</span></div>
    <div class="fr-ruban">${tuiles}</div>
    <div class="fr-leg"><span><i class="eff"></i>à faire (1ᵉʳ du mois d'effet)</span>
      <span><i class="fait"></i>faite</span><span><i class="gel"></i>${_uiIcon('lock',13)} non révisable</span>
      <span><i class="now"></i>mois en cours</span><span>Clic sur un mois = la liste des lots concernés.</span></div>
    ${detail}</div>`;
}

// ── Gestes ──────────────────────────────────────────────────────────────────

/** D8/I7 — édite TOUS les mois soldés en attente d'un lot : N mois = N documents. */
function _lyEditerQuittances(ref) {
  const yms = window.moisAQuittancer(_loyerEtatLot(ref), _lyDejaYm(ref));
  if (!yms.length) { showToast('Aucun mois soldé à quittancer', 'info'); return; }
  const faites = [];
  for (const ym of yms) {
    const r = _creerQuittance(ref, ym);
    if (r.ok && !r.existante) faites.push(r.quittance);
  }
  if (!faites.length) { showToast('Aucune quittance émise', 'err'); return; }
  saveDB(); rLoyers();
  if (typeof _refreshAfterMutation === 'function') _refreshAfterMutation();
  if (faites.length === 1) { showToast('Quittance éditée ✓', 'ok'); previewQuit(faites[0].id); }
  else showToast(`${faites.length} quittances éditées ✓`, 'ok', 5000);
}

/**
 * D6 — le REÇU de paiement partiel. Art. 21 : « dans tous les cas de paiement partiel, le
 * bailleur délivre un reçu ». Ce n'est PAS une quittance : rien n'est écrit en base, le
 * document est éphémère (il ne libère pas le locataire, il ne doit donc pas devenir un titre).
 */
function _lyRecuPartiel(ref, ym) {
  const etat = _loyerEtatLot(ref);
  const m = etat && etat.byYm && etat.byYm[ym];
  if (!m) { showToast('Mois introuvable', 'err'); return; }
  const log = (DB.logements || []).find(l => l.ref === ref);
  const bail = _findBailByRefTolerant(ref);
  const ent = (DB.entites || []).find(e => e.nom === ((bail && bail.entity) || (log && log.entity)));
  const q = {
    logement: ref, mois: window.ymToMoisFr(ym), hc: m.hcDue, ch: m.chDue,
    locataire: (log && log.locataire) || '', entity: (ent && ent.nom) || '', date: td()
  };
  // I-DATE, surface 2 du §4 : un reçu partiel émis sur un mois EN RETARD affichait la date
  // du dernier encaissement du lot bornée à aujourd'hui — donc faux presque toujours. On
  // passe les versements réellement imputés À CE MOIS ; s'il n'y en a pas de daté, le
  // document se dit sans date.
  const info = (typeof window.datePaiementMois === 'function')
    ? window.datePaiementMois(etat, ym) : { date: null, dates: [], nb: 0 };
  const built = _buildQuittanceHtml(q, log, ent, bail, {
    totalRecu: Math.round((m.du - m.reste) * 100) / 100,
    // Un reçu partiel n'est jamais « soldé » : c'est la LISTE des versements qui parle.
    infoPaiement: { date: null, dates: info.dates, nb: info.nb },
    partiel: true,
    // AUDIT R1 — et il n'est JAMAIS forcé, par définition. Sans ce `false`, le builder
    // retombait sur la trace V7 du mois : un mois déjà quittancé de force puis partiellement
    // payé (la cascade impute un versement de juin sur mai) faisait sortir, sous une fenêtre
    // « Reçu de paiement partiel », une QUITTANCE PLEINE de 800 € datée du 14/06 pour 300 €
    // réellement reçus. Un document juridiquement faux, dans les deux sens à la fois.
    forceeV7: false
  });
  _lyPreviewEphemere(built, 'Reçu de paiement partiel', ent);
}

/** Aperçu d'un document NON persisté (reçu partiel, courrier de relance). */
function _lyPreviewEphemere(built, titre, ent) {
  const iframe = el('ov-quit-preview-iframe');
  if (!iframe) { showToast('Modale aperçu introuvable', 'err'); return; }
  iframe._quitId = null;
  iframe._docBuilt = built;
  // D27 — un document non persisté sort par le MÊME chemin que les autres : il faut donc son
  // entité (bandeau du gabarit) et son titre pour nommer le fichier.
  iframe._docEnt = ent || null;
  iframe._docTitre = titre || 'Document';
  const h = document.querySelector('#ov-quit-preview .m-head h3');
  if (h) h.textContent = '📄 ' + (titre || 'Aperçu');
  _qpMajBoutonAction();
  openM('ov-quit-preview');
  iframe.srcdoc = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>${built.title}</title><style>${QUIT_PRINT_CSS}${built.css}</style></head><body>${built.html}</body></html>`;
}

/**
 * D11 — LE courrier de relance, unique. Son TABLEAU détaille ce qui manque, ligne par ligne,
 * d'après la cascade (`lignesRelance`) : loyer, charges, arriérés. Que le manque porte sur le
 * loyer, les charges ou les deux, c'est le même bouton et le même document — seul le tableau
 * change. Pas de second document « rappel de charges ».
 * Le TON suit l'ancienneté (rappel → relance → mise en demeure), via les modèles existants.
 */
function _lyRelance(ref) {
  // FINANCES-SUIVI-V2 : le courrier est adressé au locataire EN PLACE — il ne réclame que la dette de SON bail
  // (jamais celle d'un locataire parti, cas Arslan), lue dans le moteur unique comme Finances.
  const _bR = (typeof _findBailByRefTolerant === 'function') ? _findBailByRefTolerant(ref) : null;
  const etat = _loyerEtatLot(ref, (_bR && _bR.debut) ? { bailDebut: _bR.debut } : {});
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  const tol = (typeof window._loyerToleranceActive === 'function') ? window._loyerToleranceActive(today) : false;
  const lignes = window.lignesRelance(etat, { toleranceActive: tol });
  if (!lignes.length) { showToast('Rien à réclamer — ce lot est à jour', 'info'); return; }
  // R0-C C1 — avertissement, jamais bloquant : un versement d'avant la date d'achat est peut-être ce terme.
  const _av = _lyAVerifierTexte(etat);
  if (_av) showToast(_av, 'warn', 9000);
  const r = window.retardLot(etat, { toleranceActive: tol });
  const niveau = window.niveauRelance(r.depuisYm, today);
  // AUDIT #1 — l'entité suit le document : sans elle, le PDF sortait sans bandeau bailleur.
  const _entRel = (DB.entites || []).find(e => e.nom === ((_findBailByRefTolerant(ref) || {}).entity
    || ((DB.logements || []).find(l => l.ref === ref) || {}).entity)) || {};
  _lyPreviewEphemere(_buildRelanceHtml(ref, lignes, r, niveau, today), 'Courrier de relance', _entRel);
}

const _LY_RELANCE_TON = {
  'rappel-impaye-1': { titre: 'Rappel — sommes restant dues',
    corps: 'Nous vous remercions de bien vouloir régulariser cette situation. Si le règlement a été effectué entre-temps, merci de ne pas tenir compte de ce courrier.' },
  'rappel-impaye-2': { titre: 'Relance — sommes restant dues',
    corps: 'Malgré un premier rappel, ces sommes demeurent impayées. Nous vous demandons de procéder au règlement sans délai, ou de nous contacter pour convenir d\'un échéancier.' },
  'rappel-impaye-3': { titre: 'Mise en demeure de payer',
    corps: 'À défaut de règlement sous quinze jours à compter de la réception du présent courrier, nous nous réservons le droit d\'engager toute procédure utile au recouvrement de ces sommes, ainsi que la mise en œuvre de la clause résolutoire du bail.' }
};

function _buildRelanceHtml(ref, lignes, retard, niveau, todayIso) {
  const log = (DB.logements || []).find(l => l.ref === ref) || {};
  const bail = _findBailByRefTolerant(ref) || {};
  const ent = (DB.entites || []).find(e => e.nom === (bail.entity || log.entity)) || {};
  const ton = _LY_RELANCE_TON[niveau] || _LY_RELANCE_TON['rappel-impaye-1'];
  const adrBien = bail.adrBien || log.adr || '–';
  const siegeStr = ent.siege || '';
  const villeMatch = siegeStr.match(/\d{5}\s+(.+)/);
  const ville = villeMatch ? villeMatch[1].split(',')[0].trim() : siegeStr;
  const villeTitre = ville ? ville.charAt(0).toUpperCase() + ville.slice(1).toLowerCase() : '';
  const locs = (bail.locataires || []).map(l => l && l.nom).filter(Boolean).join(', ') || log.locataire || '–';

  const corps = `
${_dt('docParties', [
  { label: '1. Le(s) Bailleur(s)', qui: escHtml(ent.nom || '–'),
    corps: `${siegeStr ? '<p>' + escHtml(siegeStr) + '</p>' : ''}` },
  { label: '2. Le(s) Locataire(s)', qui: escHtml(locs),
    corps: `<p>demeurant ${escHtml(adrBien)}&nbsp;;</p>` }
])}
${_dt('docActe', `Sauf erreur de notre part, les sommes suivantes restent dues au titre du logement sis <b>${escHtml(adrBien)}</b>&nbsp;:`)}
${_dt('docLignes', lignes.map(l => ({ lab: escHtml(l.libelle), val: fmt(l.montant) }))
  .concat([{ lab: `Total restant dû au ${fd(todayIso)}`, val: fmt(retard.reste), tot: true }]))}
<p>${ton.corps}</p>
${_dt('docMention', 'Ce courrier ne vaut pas quittance. Les sommes réglées après son envoi viennent en déduction du total ci-dessus.')}
${_dt('docLieu', `Fait à ${escHtml(villeTitre || '–')},<br>Le ${fd(todayIso)}`)}
${_dt('docSignzone', [{ sig: _docSigOnly(ent), label: 'Le(s) Bailleur(s)' }])}`;

  const css = `.pro-doc{max-width:700px;margin:0 auto}\n${_docCss()}`;
  const html = _docPage(ent, {
    titre: ton.titre,
    // R0-C (2ᵉ audit 🟠3) : l'arriéré noté au début du suivi est nommé, pas compté comme un « mois ».
    ctx: lignes.some(l => l.ouverture)
      ? `${retard.nbMois ? retard.nbMois + ' mois non soldé' + (retard.nbMois > 1 ? 's' : '') + ' et ' : ''}un arriéré antérieur au suivi`
      : `${retard.nbMois} mois non soldé${retard.nbMois > 1 ? 's' : ''}${retard.depuisYm ? ' depuis ' + escHtml(window.ymToMoisFr(retard.depuisYm)) : ''}`,
    corps, ref: escHtml(ref), date: `Émis le ${fd(todayIso)}`, withStyle: false
  });
  return { html, css, title: `Relance — ${escHtml(ref)}`, status: 'relance' };
}

// ============================================================================
// L'ÉDITEUR DE QUITTANCE — direction « Le document » (CDC-LOYERS-DESIGN V6→V12).
//
// « On ne retrouve pas une quittance. On permet à l'utilisateur d'éditer, comme pour l'EDL.
//   On ne fait pas de liste infinie. Quand on a édité une quittance, l'app retient (pour le
//   KPI de suivi) mais on ne garde pas le document en visuel. Si l'utilisateur veut une
//   quittance passée, il la réédite. »
//
// V6  — on ouvre L'OBJET, pas un formulaire : la quittance, plein écran, déjà remplie depuis
//       le barème du mois. Le rail ne porte que le choix du MOIS. Rééditer = revenir sur un
//       mois passé, même geste.
// V10 — UNE SEULE PORTE. La quittance libre est un MODE à l'intérieur, jamais un 2ᵉ bouton.
// V7  — un mois non soldé s'ouvre quand même : bandeau nommant les mois et le reste, reçu
//       partiel proposé en un clic, et une case à cocher. AUCUN bouton grisé.
// V9  — l'étiquette « sans paiement constaté » vit DANS L'APP (rail, fiche, panneau), avec
//       qui a confirmé et quand. Le document remis au locataire, lui, ne change pas.
//
// La logique pure est dans js/core/quittance-editeur.js (testée). Ici : le DOM.
// ============================================================================
// D27 (01/09) — UN LOT, UN MOIS, UN DOCUMENT. `sel` (Set de mois cochés) devient `ym`
// (le mois choisi, un seul) et `pile` disparaît avec l'enchaînement « lot suivant ».
const _qe = {
  ref: null, an: null, ym: null, libre: false,
  pick: false, filtre: '',
  saisie: null, rejoue: null
};
/** D27 — le mois choisi, sous la forme attendue par `verdictEmission` (0 ou 1 élément). */
function _qeSel() { return _qe.ym ? [_qe.ym] : []; }

/** Les mois déjà quittancés d'un lot + leur date d'édition (pour l'état « done » du rail). */
function _qeDeja(ref) {
  const alive = (typeof _isAlive === 'function') ? _isAlive : (x => x && !x._deleted);
  const yms = [], dates = {};
  for (const q of (DB.quittances || [])) {
    if (!alive(q) || q.logement !== ref) continue;
    const ym = window.moisFrToYm(q.mois);
    if (!ym) continue;
    yms.push(ym);
    if (!dates[ym] || String(q.date || '') > dates[ym]) dates[ym] = String(q.date || '');
  }
  return { yms, dates };
}

/**
 * V9/§6 — la trace du geste forcé, dans le blob de configuration (pas de colonne cloud neuve).
 *
 * AUDIT DE RETRAIT (I1) — l'appel était NU : en `file://` les modules ne sont pas chargés,
 * `window.cleMeta` n'existe pas, et l'aperçu, l'impression, le partage et la pièce jointe
 * e-mail de N'IMPORTE QUELLE quittance tombaient sur un `TypeError`. Le `typeof _qeMeta ===
 * 'function'` qui précède l'appel ne protégeait rien : `_qeMeta` est inline, donc toujours là.
 * Une clé de blob est une concaténation : elle n'a pas besoin d'un module pour exister.
 */
function _qeCleMeta(ref, ym) {
  return (typeof window !== 'undefined' && typeof window.cleMeta === 'function')
    ? window.cleMeta(ref, ym) : (String(ref) + '|' + String(ym));
}
function _qeMeta(ref, ym) {
  const m = (DB.params && DB.params.quittancesMeta) || {};
  return m[_qeCleMeta(ref, ym)] || null;
}
// (AUDIT DE RETRAIT, M1 — `_qeSetMeta` a été SUPPRIMÉE : plus aucun appelant, et c'était la
//  version sans branche `else` qu'un audit avait épinglée — une étiquette qui survivait à son
//  motif. Le cycle de vie passe par `_qeAppliquerMeta` / `metaApresEmission`, testés.)
/** Le cycle de vie de la trace, délégué au module testé : posée quand le mois est forcé,
 *  RETIRÉE quand il ne l'est plus. Une étiquette qui survit à son motif est un mensonge. */
function _qeAppliquerMeta(ref, moisEmis, forces) {
  if (!DB.params) DB.params = {};
  DB.params.quittancesMeta = window.metaApresEmission(DB.params.quittancesMeta || {}, {
    ref, moisEmis, moisForces: [...forces], par: _qeQui(), le: td()
  });
}
/** La trace meurt avec la quittance — même geste, même opération annulable. */
function _qeDelMeta(ref, ym) {
  if (!DB.params) DB.params = {};
  DB.params.quittancesMeta = window.metaApresSuppression(DB.params.quittancesMeta || {}, ref, ym);
}
/** Qui édite — utile au partage SCI : la trace nomme la personne, pas « quelqu'un ». */
function _qeQui() {
  const p = (DB.params && DB.params.userProfile) || {};
  return p.nom || p.prenom || p.email
    || (typeof window !== 'undefined' && window._authEmail) || 'l’utilisateur de cet espace';
}

/** Les lots quittançables (a un bail, courant ou archivé) — la pile de la porte globale, limitée au filtre
 *  d'entité ; `{ tous: true }` : tout le parc (un lot DEMANDÉ s'ouvre quel que soit le filtre). */
function _qeLots(o) {
  const alive = (typeof _isAlive === 'function') ? _isAlive : (x => x && !x._deleted);
  const tous = !!(o && o.tous);
  return (DB.logements || []).filter(alive)
    .filter(l => tous || (typeof _logInEnt !== 'function') || _logInEnt(l))
    .filter(l => l.locataire || _findBailByRefTolerant(l.ref));
}

/**
 * LA PORTE UNIQUE. `ref` absent = on entre par la porte globale : on demande quel lot, plutôt
 * que d'en imposer un. D27 — un lot à la fois, choisi ; ni pile ni tournée.
 */
function _openFaireQuittance(ref) {
  if (typeof window === 'undefined' || typeof window.moisRailLot !== 'function') {
    showToast("Module Loyers non chargé — ouvrir l'app via http (npx http-server)", 'err', 6000); return;
  }
  // RETOURS 15/10 (lot 1, point 5) — un lot DEMANDÉ (fiche du logement, ligne de Loyers) s'ouvre LUI-MÊME,
  // quel que soit le filtre d'entité en haut à gauche. Avant : absent du filtre, il était remplacé en silence
  // par le 1er lot du filtre — la quittance d'un lot en nom propre s'ouvrait sur un lot de la SCI filtrée.
  // Le filtre ne restreint que la liste de la porte globale. Règle pure testée : js/core/quittance-porte.js.
  const refsDe = (arr) => arr.map(l => l.ref);
  const choix = (typeof window.lotQuittanceAOuvrir === 'function')
    ? window.lotQuittanceAOuvrir({ ref, lotsPerimetre: refsDe(_qeLots()), lotsQuittancables: refsDe(_qeLots({ tous: true })) })
    : null;
  if (!choix || !choix.ok) {
    const motif = choix ? choix.motif : 'aucun-bail';
    showToast(motif === 'sans-bail' ? 'Aucun bail sur ce logement : pas de quittance à faire.'
      : motif === 'perimetre-vide' ? 'Aucun bail en cours pour le bailleur choisi en haut à gauche : changer de bailleur pour faire une quittance.'
        : "Aucun bail en cours — les quittances apparaîtront dès qu'un logement sera loué", 'info', 6000);
    return;
  }
  // D27 — plus de PILE ni d'enchaînement « lot suivant » : on ouvre UN lot. Entré sans `ref`
  // (porte globale), on demande lequel plutôt que d'en imposer un.
  const want = choix.ref;
  _qe.libre = false; _qe.saisie = null;
  _qeSetLot(want);
  _qe.pick = !ref;                        // porte globale : on choisit son lot
  openM('ov-quit-editeur');
  _qeRender();
}

function _qeSetLot(ref) {
  _qe.ref = ref; _qe.ym = null; _qe.pick = false;
  const etat = _loyerEtatLot(ref);
  const deja = _qeDeja(ref);
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  _qe.an = window.anneeParDefaut(etat, deja.yms, today.slice(0, 7));
  _qe.ym = window.moisParDefaut(_qeRailVisible()) || null;
}

function _qeRail() {
  const etat = _loyerEtatLot(_qe.ref);
  const deja = _qeDeja(_qe.ref);
  const today = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : new Date().toISOString().slice(0, 10);
  return window.moisRailLot(etat, deja.yms, _qe.an, today.slice(0, 7), deja.dates);
}
// D27 (retour Didier) — les mois À VENIR (non couverts) ne s'affichent pas et ne peuvent pas être
// le défaut : on ne quittance pas un mois pas encore arrivé. Le mois EN COURS, lui, n'est jamais
// 'fut' (il est 'ok'/'no'/'done'), donc il reste. Un mois futur COUVERT par une avance est 'ok',
// pas 'fut' — il reste visible (V8). Source unique du filtre, réutilisée au rendu et au défaut.
function _qeRailVisible() { return _qeRail().filter(m => m.etat !== 'fut'); }

// D27 — changer d'année garde un mois choisi : on n'atterrit jamais sur un écran sans document.
function _qeSetAn(an) {
  _qe.an = String(an); _qe.ym = window.moisParDefaut(_qeRailVisible()) || null;
  _qeRender();
}
/**
 * D27 — SÉLECTION UNIQUE. Cliquer un mois le choisit ; il n'y a rien à décocher, donc jamais
 * d'écran sans mois. TOUS les mois restent cliquables, y compris non soldés et déjà édités
 * (réédition) : le garde-fou avertit, il n'interdit pas.
 */
function _qeChoisirMois(ym) {
  if (_qe.ym === ym) return;
  _qe.ym = ym; _qeRender();
  // AUDIT #6 — `_qeRender` réécrit tout l'écran : sans ça le focus clavier retombe sur <body>
  // et il faut re-tabuler l'écran entier après chaque mois choisi.
  try { const b = document.querySelector('.qd-mois .qd-m.sel'); if (b) b.focus(); } catch (e) {}
}
function _qeTogglePick() { _qe.pick = !_qe.pick; _qe.filtre = ''; _qeRender(); }
/** Ouvre/ferme la liste des années (déroulant compact, à droite de « Changer de lot »). */
function _qeToggleYear() { const l = el('qd-yrlist'); if (l) l.classList.toggle('hidden'); }
function _qeFiltre(v) { _qe.filtre = String(v || ''); _qeRenderPick(); }
function _qeChoisirLot(ref) { _qe.libre = false; _qe.saisie = null; _qeSetLot(ref); _qeRender(); }
function _qeFermer() { closeM('ov-quit-editeur'); if (typeof rLoyers === 'function' && currentPage === 'loyers') rLoyers(); }

/**
 * Un versement a-t-il été imputé à ce mois ? Le bandeau V7 ne propose « émettre un reçu de
 * paiement partiel à la place » que dans ce cas : sur un mois où RIEN n'est arrivé, ce reçu
 * n'existe pas (il n'y a rien à reconnaître avoir reçu) et le bouton menait à un document
 * « non émissible » — une impasse. Le vrai choix reste alors : quittancer quand même (case
 * à cocher), décocher le mois, ou enregistrer le paiement d'abord.
 */
function _qeAPaiement(ym) {
  const e = _loyerEtatLot(_qe.ref);
  const m = e && e.byYm && e.byYm[ym];
  return !!(m && (m.montantImpute || 0) > 0.005);
}

/** V10/V11 — bascule vers la SAISIE LIBRE, à l'intérieur du même écran. */
function _qeModeLibre(depuisLot) {
  const l = depuisLot ? (DB.logements || []).find(x => x.ref === depuisLot) : null;
  const bail = depuisLot ? _findBailByRefTolerant(depuisLot) : null;
  const ent = (DB.entites || []).find(e => e.nom === ((bail && bail.entity) || (l && l.entity)));
  // V12 — la quittance libre peut PARTIR d'un logement existant ; tout reste modifiable ensuite.
  _qe.libre = true; _qe.pick = false; _qe.rejoue = null;
  _qe.saisie = {
    bailleurNom: (ent && ent.nom) || '', bailleurAdresse: (ent && ent.siege) || '',
    locataireNom: (l && l.locataire) || '', adresse: (bail && bail.adrBien) || (l && l.adr) || '',
    ville: '', debut: '', fin: '',
    hc: (bail && bail.hc) || (l && l.hc) || 0, ch: (bail && bail.ch) || (l && l.ch) || 0,
    datePaiement: ''
  };
  _qeRender();
}
function _qeSaisie(champ, val) { if (_qe.saisie) _qe.saisie[champ] = val; _qeFootBtn(); }

/** V11 — rouvrir une saisie libre retenue : c'est la SAISIE qui est l'état, le document se
 *  regarde regeneré. Rééditer écrase l'entrée (un état, pas une pile de versions). */
function _qeRejouerLibre(id) {
  const l = ((DB.params || {}).quittancesLibres || []).find(x => String(x.id) === String(id));
  if (!l) { showToast('Saisie introuvable', 'err'); return; }
  _qe.libre = true; _qe.pick = false; _qe.saisie = Object.assign({}, l);
  _qe.rejoue = l.id;
  _qeRender();
}

/* ── Le rendu ─────────────────────────────────────────────────────────────── */

function _qeRender() {
  const root = el('qd-root'); if (!root) return;
  const libre = _qe.libre;
  const log = libre ? null : (DB.logements || []).find(l => l.ref === _qe.ref);
  const bail = libre ? null : _findBailByRefTolerant(_qe.ref);
  // Ligne d'ACTIONS : « Changer de lot » à gauche, année (déroulant compact) à droite. Le lot
  // lui-même vit dans l'en-tête (fini le doublon). En libre : « Partir d'un logement existant ».
  let rail;
  if (libre) {
    rail = `<div class="qd-act"><button class="chg" onclick="_qeTogglePick()">Partir d'un logement existant ▾</button></div>`;
  } else {
    const etat = _loyerEtatLot(_qe.ref);
    const deja = _qeDeja(_qe.ref);
    const annees = window.anneesDisponibles(etat, deja.yms);
    rail = `<div class="qd-act">
      <button class="chg" onclick="_qeTogglePick()">Changer de lot ▾</button>
      <div class="qd-yr">
        <button class="chg qd-yrbtn" onclick="_qeToggleYear()">${escHtml(String(_qe.an))} ▾</button>
        <div class="qd-yrlist hidden" id="qd-yrlist">${annees.map(a =>
          `<button class="${a === String(_qe.an) ? 'on' : ''}" onclick="_qeSetAn('${a}')">${a}</button>`).join('')}</div>
      </div></div>`;
    // D27 — mois en BULLES, et les mois À VENIR (non couverts) masqués : on ne quittance pas un
    // mois pas encore arrivé (le mois EN COURS reste, même non soldé). Le mois choisi ne pointe
    // jamais sur un mois masqué : on retombe sur le dernier visible.
    const _vis = _qeRailVisible();
    // AUDIT (mineur) — le défaut/self-heal vise un mois RÉELLEMENT quittançable : ni à venir (déjà
    // filtré), ni hors bail ('off'). Sinon la ligne de détail pouvait afficher « hors bail » sur une
    // bulle sélectionnée pendant que le volet document disait « choisis un mois ».
    const _sel0 = _vis.filter(m => m.etat !== 'off');
    if (!_qe.ym || !_sel0.some(m => m.ym === _qe.ym)) _qe.ym = _sel0.length ? _sel0[_sel0.length - 1].ym : null;
    rail += `<div class="qd-mois" role="radiogroup" aria-label="Mois de l'année">${_vis.map(m => {
      const on = _qe.ym === m.ym;
      const meta = _qeMeta(_qe.ref, m.ym);
      const et = window.etiquetteSansPaiement(meta, fd);
      const nom = m.nom.charAt(0).toUpperCase() + m.nom.slice(1);
      const _mi = parseInt(String(m.ym).slice(5, 7), 10) - 1;
      const ab = (typeof MOIS_ABBR !== 'undefined' && MOIS_ABBR[_mi]) ? MOIS_ABBR[_mi] : nom.slice(0, 4);
      const st = m.etat === 'done' ? ('éditée le ' + (m.editeeLe ? fd(m.editeeLe) : '—'))
        : m.etat === 'ok' ? 'soldé — à quittancer'
        : m.etat === 'no' ? ('reste ' + fmt(m.reste)) : 'hors bail';
      // Une seule structure : LISTE sur PC/tablette (nom complet + état + montant), BULLE sur
      // téléphone (point + abréviation .nmab ; état/montant déportés dans .qd-selmo).
      return `<button class="qd-m ${m.etat}${on ? ' sel' : ''}" role="radio" aria-checked="${on ? 'true' : 'false'}" ${m.etat === 'off' ? 'disabled' : `onclick="_qeChoisirMois('${m.ym}')"`}${et.visible ? ` title="${escHtml(et.survol)}"` : ''}>
        <span class="bx"></span>
        <span class="lbl"><span class="nm">${escHtml(nom)}</span><span class="nmab">${escHtml(ab)}</span>
        <span class="st">${escHtml(st)}${et.visible ? ' · ' + escHtml(et.libelle) : ''}</span></span>
        <span class="am">${fmt(m.du)}</span></button>`;
    }).join('')}</div>`;
    // La ligne de détail du mois choisi : son état en clair + son montant, UNE fois, sous les bulles.
    const _sel = _qe.ym ? _vis.find(m => m.ym === _qe.ym) : null;
    if (_sel) {
      const meta = _qeMeta(_qe.ref, _sel.ym);
      const et = window.etiquetteSansPaiement(meta, fd);
      const st = _sel.etat === 'done' ? ('éditée le ' + (_sel.editeeLe ? fd(_sel.editeeLe) : '—'))
        : _sel.etat === 'ok' ? 'soldé — à quittancer'
        : _sel.etat === 'no' ? ('reste ' + fmt(_sel.reste)) : 'hors bail';
      rail += `<div class="qd-selmo"><b>${escHtml(_sel.nom.charAt(0).toUpperCase() + _sel.nom.slice(1))} ${escHtml(String(_qe.an))}</b>
        <span class="st ${_sel.etat}"${et.visible ? ` title="${escHtml(et.survol)}"` : ''}>${escHtml(st)}${et.visible ? ' · ' + escHtml(et.libelle) : ''}</span>
        <span class="am">${fmt(_sel.du)}</span></div>`;
    }
  }

  root.innerHTML = `<div class="qd-top">
      <button class="bk" onclick="_qeFermer()" title="Revenir">‹</button>
      <h3>Quittance</h3>
      <div class="who">${libre
        ? `<span class="wlo">saisie libre</span>`
        : `<span class="wrf">${escHtml(_logLabel(_qe.ref || ''))}</span><span class="wlo">${escHtml((log && log.locataire) || '— vacant —')} · ${escHtml((bail && bail.entity) || (log && log.entity) || '—')}</span>`}</div>
      <button class="x" onclick="_qeFermer()" title="Fermer">✕</button></div>
    <div class="qd-body">
      <div class="qd-rail">${rail}</div>
      <div class="qd-doc" id="qd-doc"></div>
    </div>
    <div class="qd-foot" id="qd-foot"></div>
    <div id="qd-pick-host"></div>`;
  _qeRenderDoc();
  _qeRenderFoot();
  _qeRenderPick();
}

/** Le bandeau du garde-fou (V7) + le document lui-même. */
function _qeRenderDoc() {
  const host = el('qd-doc'); if (!host) return;
  if (_qe.libre) { host.innerHTML = _qeDocLibre(); return; }
  const rail = _qeRail();
  const v = window.verdictEmission(rail, _qeSel());
  let warn = '';
  if (v.risques.length) {
    // V7 — l'avertissement NOMME les mois et le reste dû, propose le reçu partiel en un clic,
    // et demande une confirmation explicite. Fondement : l'article 21 de la loi du 6 juillet
    // 1989 fait de la quittance un REÇU — remise à un locataire qui n'a pas payé, elle vaut
    // preuve de paiement CONTRE le bailleur.
    const premier = v.risques[0];
    const resteStr = premier.etat === 'fut' ? 'à venir, non couvert' : 'reste ' + fmt(premier.reste);
    // Bandeau COMPACT (retour Didier : « un demi écran pour des infos peu utiles ») — l'essentiel,
    // sans répéter le mois ni le laïus juridique. Le fond légal reste sur le document lui-même.
    warn = `<div class="q-warn w"><span class="ic">⚠</span><div>
      <b>${escHtml(premier.mois)} non soldé</b> · ${resteStr}. <b>Édition possible quand même</b> : la
      quittance sort <b>sans « payé le »</b>, marquée « sans paiement constaté » en interne.
      <div class="act">
        ${_qeAPaiement(premier.ym)
          ? `<button class="btn bs bb" onclick="_qeRecuPartiel('${premier.ym}')" title="Émettre un reçu de paiement partiel à la place">Reçu partiel</button>`
          : ''}
        ${premier.etat === 'fut' ? '' : `<button class="btn bs bb" onclick="_qeEnregistrerPaiement()">Enregistrer le paiement</button>`}
      </div>
    </div></div>`;
  } else if (v.reedits.length) {
    const r = v.reedits[0];
    warn = `<div class="q-warn i"><span class="ic">↺</span><div>
      <b>${escHtml(r.mois.charAt(0).toUpperCase() + r.mois.slice(1))} a déjà été quittancé${r.editeeLe ? ' (éditée le ' + fd(r.editeeLe) + ')' : ''}.</b>
      Rééditer regénère le document depuis le barème de ce mois — mêmes montants, nouvelle date d'édition.
      L'app retiendra la nouvelle date ; rien d'autre n'est conservé.</div></div>`;
  }

  // D27 — un seul mois : plus d'onglets « N documents », plus d'index à borner.
  const m = _qe.ym ? rail.find(x => x.ym === _qe.ym && x.etat !== 'off') : null;
  if (!m) {
    // AUDIT (mineur) — distinguer « rien à quittancer » (bail à venir, ou année hors bail : aucun mois
    // ni soldé ni échu) d'un simple « choisis un mois ». Le premier n'est pas une impasse, c'est un
    // état légitime — on le dit clairement au lieu d'inviter à cliquer une bulle inexistante.
    const rienAQuittancer = !rail.some(x => x.etat !== 'off' && x.etat !== 'fut');
    host.innerHTML = warn + `<div class="q-warn i"><span class="ic">📄</span><div>${rienAQuittancer
      ? `<b>Aucun mois à quittancer pour ce bail sur ${escHtml(String(_qe.an))}.</b> Changer d'année ci-dessus — ou ce bail commence plus tard.`
      : `Choisir un mois pour voir la quittance. Le document est regénéré depuis le
      <b>barème de ce mois</b> — jamais depuis le loyer d'aujourd'hui.`}</div></div>`;
    return;
  }
  host.innerHTML = warn + `<iframe id="qd-iframe" title="Aperçu de la quittance"></iframe>`;
  _qeInjecterDoc(m);
}

/** Le document réel, construit par le MÊME builder que l'impression et le PDF (I5). */
function _qeInjecterDoc(m) {
  const iframe = el('qd-iframe'); if (!iframe) return;
  const log = (DB.logements || []).find(l => l.ref === _qe.ref);
  const bail = _findBailByRefTolerant(_qe.ref) || {};
  const ent = (DB.entites || []).find(e => e.nom === (bail.entity || (log && log.entity)));
  const du = _duMoisLot(_qe.ref, m.ym);
  const q = {
    logement: _qe.ref, mois: m.mois, hc: du.hc || 0, ch: du.ch || 0,
    locataire: ((bail.locataires || []).map(x => x && x.nom).filter(Boolean).join(', ')) || (log && log.locataire) || '',
    entity: (bail.entity || (log && log.entity) || ''), date: td()
  };
  // L'aperçu montre LE document qui sortira. D27 (retour Didier) : un mois non soldé s'édite
  // LIBREMENT (plus de case à cocher) — c'est donc TOUJOURS une quittance pleine forcée (V7),
  // sortie sans ligne « payé le ». L'étiquette « sans paiement constaté » reste DANS l'app.
  const built = _buildQuittanceHtml(q, log, ent, bail, {
    // R5/D27 — un mois non soldé (ou déjà forcé, via sa trace meta) rouvre en QUITTANCE pleine
    // sans « payé le ». (« Document non émissible » n'existe plus : la branche a été retirée de
    // _buildQuittanceHtml — un mois sans paiement produit une quittance, jamais une impasse.)
    forceeV7: (m.etat === 'no' || m.etat === 'fut')
      || !!(typeof _qeMeta === 'function' && _qeMeta(_qe.ref, m.ym))
  });
  iframe.srcdoc = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>${built.title}</title><style>${QUIT_PRINT_CSS}${built.css}</style></head><body>${built.html}</body></html>`;
}

/** V11/V12 — la feuille de saisie libre : le même écran, document vierge, champs éditables. */
function _qeDocLibre() {
  const s = _qe.saisie || {};
  const ch = (k, v, size, ph) => `<input class="ed" size="${size}" value="${escHtml(v || '')}" placeholder="${escHtml(ph || '')}" oninput="_qeSaisie('${k}',this.value)">`;
  return `<div class="q-warn i"><span class="ic">✎</span><div>
      <b>Saisie libre.</b> Aucun bail n'est requis : tout se remplit sur la feuille. L'app retient la
      <b>saisie</b>, pas le document — elle est rejouable et rééditable. Elle est <b>exclue de tous les
      calculs</b> (ni suivi des loyers, ni 2044) : elle ne prouve aucun encaissement.</div></div>
    <div class="qd-libre">
      <div>${ch('bailleurNom', s.bailleurNom, 28, 'Bailleur — nom / raison sociale')}<br>
        ${ch('bailleurAdresse', s.bailleurAdresse, 34, 'Adresse du bailleur')}</div>
      <div style="text-align:right;margin-top:-34px">${ch('ville', s.ville, 12, 'Ville')}, le ${fd(td())}</div>
      <h4>Quittance de loyer</h4>
      <div style="text-align:center">Période du ${ch('debut', s.debut, 10, 'JJ/MM/AAAA')} au ${ch('fin', s.fin, 10, 'JJ/MM/AAAA')}</div>
      <p><b>${ch('locataireNom', s.locataireNom, 28, 'Locataire — nom')}</b><br>
        ${ch('adresse', s.adresse, 40, 'Adresse du logement loué')}</p>
      <table>
        <tr><td>Loyer hors charges</td><td class="r">${ch('hc', s.hc, 8, '0,00')} €</td></tr>
        <tr><td>Provision sur charges</td><td class="r">${ch('ch', s.ch, 8, '0,00')} €</td></tr>
        <tr class="t"><td>Total</td><td class="r">${fmt((Number(s.hc) || 0) + (Number(s.ch) || 0))}</td></tr>
      </table>
      <div>Payé le ${ch('datePaiement', s.datePaiement, 10, 'facultatif')}
        <span class="q">— vide : la ligne ne sort pas sur le document (I-DATE)</span></div>
      <div class="mn">Cette quittance annule et remplace tout reçu antérieur pour la même période.
        Elle est délivrée sans préjudice des droits du bailleur (art. 21, loi n° 89-462 du 6 juillet 1989).</div>
      <div class="sg">Le bailleur<br><b>${escHtml(s.bailleurNom || '—')}</b></div>
    </div>`;
}

/** D27 (retour Didier) — le bouton NOMME le mois, élidé et sans année (« d'avril », « de septembre »),
 *  comme la maquette validée. L'année vit dans le sélecteur d'année et la ligne de détail. */
function _qeMoisLabel(ym) {
  if (!ym) return '';
  const mi = parseInt(String(ym).slice(5, 7), 10) - 1;
  const nom = (typeof MOIS_FR !== 'undefined' && MOIS_FR[mi]) ? MOIS_FR[mi] : String(ym);
  return ([3, 7, 9].indexOf(mi) >= 0 ? "d'" : 'de ') + nom;   // avril, août, octobre → d'
}
function _qeRenderFoot() {
  const foot = el('qd-foot'); if (!foot) return;
  if (_qe.libre) {
    const v = window.validerSaisieLibre(_qe.saisie);
    foot.innerHTML = `<span class="rec"><b>1</b> document · <b>${fmt(v.normalisee.total)}</b>
        ${v.valide ? '' : `<span class="mu sm"> — il manque ${escHtml(v.manquants.join(', '))}</span>`}</span>
      <span class="sp"></span>
      <button class="btn bs" onclick="_qeFermer()">Annuler</button>
      <button class="btn bp" id="qd-ok" onclick="_qeEditer()">✓ Éditer la quittance (PDF)</button>`;
  } else {
    // D27 — un seul mois, donc un seul document : le bouton NOMME le mois, il n'y a plus de
    // total à additionner ni d'enchaînement « lot suivant ».
    const v = window.verdictEmission(_qeRail(), _qeSel());
    const moisNom = _qe.ym ? window.ymToMoisFr(_qe.ym) : '';   // « avril 2026 » — pour le compteur
    const moisLbl = _qeMoisLabel(_qe.ym);                      // « d'avril » / « de septembre » — élidé, sans année
    const lbl = v.reedits.length ? `Rééditer la quittance ${moisLbl}`
      : moisLbl ? `Éditer la quittance ${moisLbl}`
      : 'Éditer la quittance';
    foot.innerHTML = `<span class="rec">${moisNom ? `${escHtml(moisNom)} · <b>${fmt(v.total)}</b>` : 'Choisir un mois'}</span>
      <span class="sp"></span>
      <button class="btn bs" onclick="_qeFermer()">Annuler</button>
      <button class="btn bp" id="qd-ok" onclick="_qeEditer()">✓ ${escHtml(lbl)}</button>`;
  }
  _qeFootBtn();
}

/** Le bouton principal : jamais grisé par une RÈGLE, seulement par une saisie incomplète. */
function _qeFootBtn() {
  const btn = el('qd-ok'); if (!btn) return;
  let off = false, why = '';
  if (_qe.libre) {
    const v = window.validerSaisieLibre(_qe.saisie);
    off = !v.valide; why = v.valide ? '' : 'Il manque ' + v.manquants.join(', ');
  } else {
    const v = window.verdictEmission(_qeRail(), _qeSel());
    // D27 (retour Didier) — AUCUNE règle ne grise le bouton : un mois non soldé s'édite librement,
    // l'app se contente d'avertir (« on met une alerte mais on laisse libre »). Seul un écran sans
    // mois choisi le désactive — et il ne peut pas rester sans mois (sélection unique).
    if (!v.nbDocs) { off = true; why = 'Choisir un mois'; }
  }
  btn.disabled = off;
  btn.style.opacity = off ? '.5' : '';
  btn.title = why;
}

/**
 * AUDIT #4 — la sortie « enregistrer le paiement » : elle ferme l'éditeur (la modale Mouvement
 * ne peut pas s'empiler dessus) mais elle NOMME le lot et le mois, comme le fait déjà la fiche
 * logement. Elle n'est proposée que sur un mois ÉCHU : sur un mois à venir, il n'y a rien à
 * encaisser.
 */
// B3 : « + Mouvement » depuis la fiche logement. Le texte de la consigne est calculé ICI à partir de la référence
// (jamais injecté dans un attribut onclick) et doit être identique à l'option du champ Logement (« Nom · réf »).
function _openNewMvPourLot(ref) {
  openNewMv();
  showToast(`Penser à sélectionner « ${_logLabelRef(ref)} » dans le champ Logement`, 'info', 4000);
}
function _qeEnregistrerPaiement() {
  const ref = _qe.ref, ym = _qe.ym;
  _qeFermer();
  openNewMv();
  if (ref) showToast(`Sélectionner « ${_logLabelRef(ref)} »${ym ? ' — ' + window.ymToMoisFr(ym) : ''}`, 'info', 4000);
}

/** V7 — la porte de sortie proposée dans le bandeau : le reçu partiel, en un clic. */
function _qeRecuPartiel(ym) {
  closeM('ov-quit-editeur');
  _lyRecuPartiel(_qe.ref, ym);
}

/**
 * D27/I7 — UN mois choisi = UN document. Il n'y a plus de boucle sur une sélection : la boucle
 * ne porte que sur le mois retenu, et l'enchaînement « lot suivant » a disparu.
 * V7 — le mois non soldé passe (`verifierSolde:false`) et laisse une TRACE : qui a confirmé,
 * quand. C'est cette trace qui alimente l'étiquette « sans paiement constaté » (V9).
 */
function _qeEditer() {
  if (_qe.libre) return _qeEditerLibre();
  let rail = _qeRail();
  let v = window.verdictEmission(rail, _qeSel());
  if (!v.nbDocs) { showToast('Choisir un mois', 'err'); return; }
  // DOC-Q (décision Didier 17/10) — mois échu SANS aucun paiement enregistré : « Paiement reçu hors relevé ? ». Oui →
  // le paiement est enregistré (encaissement du lot, daté du jour), PUIS la quittance sort. Non → elle sort quand même,
  // sans « payé le », tracée « sans paiement constaté ». Jamais bloquer.
  let horsReleve = null;
  const _QH = window.questionPaiementHorsReleve, _MH = window.mouvementHorsReleve;
  // Relecture Opus : un arriéré antérieur (la cascade lui impute d'abord les paiements) ou un encaissement de loyer du lot
  // daté dans le mois → le paiement est peut-être déjà enregistré : pas de question (jamais un loyer compté deux fois).
  const _etQ = (typeof _loyerEtatLot === 'function') ? _loyerEtatLot(_qe.ref) : null;
  // Relecture Fable : seulement les mois du bail EN COURS — la dette d'un ancien locataire ne tait pas la question.
  const _debQ = String(((typeof _findBailByRefTolerant === 'function') && (_findBailByRefTolerant(_qe.ref) || {}).debut) || '').slice(0, 7);
  const _arrQ = (_etQ && _etQ.byYm) ? Object.keys(_etQ.byYm).filter(k => k < _qe.ym && (!_debQ || k >= _debQ))
    .reduce((s, k) => s + Math.max(0, Number(_etQ.byYm[k] && _etQ.byYm[k].reste) || 0), 0) : 0;
  const _encQ = (DB.mouvements || []).some(m => m && !m._deleted && m.qui === _qe.ref && String(m.date || '').slice(0, 7) === _qe.ym
    && (Number(m.cr) || 0) > 0 && (typeof _finCatLigne === 'function' ? ((_finCatLigne(m.cat) || {}).ligne2044 === '211') : m.cat === 'Loyers encaissés'));
  const _qq = (typeof _QH === 'function' && typeof _MH === 'function')
    ? _QH(rail.find(x => x.ym === _qe.ym) || null, _qeAPaiement(_qe.ym), { arriereAnterieur: _arrQ, encaisseDansLeMois: _encQ }) : null;
  if (_qq) {
    const _moisMaj = String(_qq.mois).charAt(0).toUpperCase() + String(_qq.mois).slice(1);
    if (confirm2('Paiement reçu hors relevé (espèces, chèque) ?\n\n' + _moisMaj + ' : aucun paiement enregistré (' + fmt(_qq.montant) + ' dus).'
      + '\n\nOK : enregistrer ce paiement de ' + fmt(_qq.montant) + ', daté d\'aujourd\'hui (modifiable ensuite dans Mouvements), puis éditer la quittance.'
      + '\nChèque : à son arrivée sur un relevé importé, ne pas le classer une seconde fois en loyer.'
      + '\n\nAnnuler : autre montant, ou quittance sans paiement constaté (question suivante).')) {
      const _log = (DB.logements || []).find(l => l && l.ref === _qe.ref) || {};
      const _jour = (typeof window._loyerTodayLocal === 'function') ? window._loyerTodayLocal() : td();
      // Enregistré (saveDB) AVANT de relire le rail : le suivi des loyers est mémoïsé par génération de la base.
      horsReleve = _mvCreate(_MH({ id: nid(), ref: _qe.ref, imm: _log.imm || '', mois: _qq.mois, montant: _qq.montant, dateIso: _jour }), { refresh: false });
      rail = _qeRail();
      v = window.verdictEmission(rail, _qeSel());
    } else if (!confirm2('Éditer la quittance de ' + _qq.mois + ' SANS paiement constaté ?\n\nElle sort sans « payé le » et reste marquée « sans paiement constaté » dans l\'app. Une quittance vaut reçu (article 21 de la loi du 6 juillet 1989).'
      + '\n\nAnnuler : rien n\'est émis (un paiement d\'un autre montant s\'enregistre dans Mouvements).')) {
      return;
    }
  }
  const forces = new Set(v.risques.map(m => m.ym));
  if (horsReleve && forces.has(_qe.ym)) {
    showToast('Paiement enregistré, mais la cascade l\'impute d\'abord à un mois plus ancien encore dû : ' + window.ymToMoisFr(_qe.ym)
      + ' reste non soldé, la quittance sort sans « payé le ».', 'warn', 9000);
  }
  const faites = [], refusees = [];
  for (const ym of _qeSel()) {
    const m = rail.find(x => x.ym === ym);
    if (!m || m.etat === 'off') continue;
    const r = _creerQuittance(_qe.ref, ym, { verifierSolde: false });
    if (r.ok) {
      if (r.existante) {                      // réédition : nouvelle date d'édition, rien d'autre
        r.quittance.date = td();
        if (typeof _stamp === 'function') _stamp(r.quittance);
      }
      // AUDIT I-2 — la trace suit le GESTE, dans les deux sens. Sans le `else`, rééditer un
      // mois autrefois forcé et DEPUIS PAYÉ laissait l'étiquette « émise sans paiement rattaché »
      // collée à un mois soldé, pour toujours — et faisait sortir une quittance « forcée » là
      // où le paiement existe.
      _qeAppliquerMeta(_qe.ref, [ym], forces);
      faites.push(r.quittance);
    } else refusees.push(window.ymToMoisFr(ym) + ' — ' + r.motif);
  }
  if (faites.length) saveDB();
  if (typeof _refreshAfterMutation === 'function') _refreshAfterMutation();
  if (refusees.length) showToast('Non émis : ' + refusees.join(' · '), 'err', 7000);
  if (faites.length) showToast('Quittance éditée ✓', 'ok');
  // D27 (retour Didier « pourquoi on retombe sur Loyers ? ») — on NE FERME PLUS l'éditeur après
  // une quittance. Le document ÉDITÉ s'ouvre PAR-DESSUS (previewQuit) ; en le fermant (✕) on
  // retombe DANS l'éditeur, rail à jour (le mois passe « éditée le… »), prêt pour un autre mois.
  // On ne revient sur Loyers que si on ferme l'éditeur lui-même. Le geste reste « rendre la main
  // sur le document » — sans éjecter l'utilisateur de l'éditeur après chaque quittance.
  if (faites.length) { _qeRender(); previewQuit(faites[0].id); }
}

/**
 * V11 — la SAISIE LIBRE est retenue (rejouable, rééditable) et étiquetée. Elle n'entre dans
 * AUCUN calcul (I-LIBRE) : elle ne va pas dans DB.quittances, qui alimente le suivi et la
 * 2044 — elle vit dans le blob de configuration, à part.
 */
function _qeEditerLibre() {
  const v = window.validerSaisieLibre(_qe.saisie);
  if (!v.valide) { showToast('Il manque ' + v.manquants.join(', '), 'err', 6000); return; }
  if (!DB.params) DB.params = {};
  if (!Array.isArray(DB.params.quittancesLibres)) DB.params.quittancesLibres = [];
  const entree = Object.assign({ id: _qe.rejoue || nid(), editeeLe: td() }, v.normalisee);
  const i = DB.params.quittancesLibres.findIndex(x => String(x.id) === String(entree.id));
  if (i >= 0) DB.params.quittancesLibres[i] = entree; else DB.params.quittancesLibres.push(entree);
  _qe.rejoue = null;
  saveDB();
  const built = _qeBuildLibre(entree);
  closeM('ov-quit-editeur');
  // AUDIT #1 — idem : la saisie libre porte son bailleur dans sa saisie.
  _lyPreviewEphemere(built, 'Quittance — saisie libre',
    { nom: entree.bailleurNom || '', siege: entree.bailleurAdresse || '' });
  showToast('Quittance libre éditée ✓ — saisie retenue, exclue des calculs', 'ok', 6000);
}

/** Le document d'une saisie libre : le MÊME gabarit que les autres (jamais un second modèle). */
function _qeBuildLibre(s) {
  const q = { logement: '', mois: `${s.debut} → ${s.fin}`, hc: s.hc, ch: s.ch,
    locataire: s.locataireNom, entity: s.bailleurNom, date: s.editeeLe };
  const log = { ref: '', adr: s.adresse, locataire: s.locataireNom };
  const ent = { nom: s.bailleurNom, siege: s.bailleurAdresse };
  const bail = { adrBien: s.adresse, locataires: [{ nom: s.locataireNom }], entity: s.bailleurNom };
  return _buildQuittanceHtml(q, log, ent, bail, {
    totalRecu: s.total,
    // I-DATE : sans date saisie, la ligne « payé le » ne sort pas.
    infoPaiement: { date: s.datePaiement || null, dates: s.datePaiement ? [s.datePaiement] : [], nb: s.datePaiement ? 1 : 0 }
  });
}

/** Le sélecteur de lot — par-dessus le rail, jamais une seconde fenêtre (V10). */
function _qeRenderPick() {
  const host = el('qd-pick-host'); if (!host) return;
  if (!_qe.pick) { host.innerHTML = ''; return; }
  host.innerHTML = `<div class="qd-pick">
    <div class="srch"><span>🔍</span>
      <input id="qd-pick-q" value="${escHtml(_qe.filtre)}" placeholder="Chercher un lot, un locataire, un immeuble, un bailleur…" oninput="_qeFiltre(this.value)">
      <button class="btn bs bb" onclick="_qeTogglePick()">✕</button></div>
    <div class="list" id="qd-pick-list"></div></div>`;
  _qeRenderPickList();
  const inp = el('qd-pick-q'); if (inp) inp.focus();
}
function _qeRenderPickList() {
  const host = el('qd-pick-list'); if (!host) return;
  const f = _qe.filtre.trim().toLowerCase();
  const match = (l) => !f || [l.ref, l.locataire, l.imm, l.entity].some(x => String(x || '').toLowerCase().includes(f)) || _logLabelMatch(l, f);   // B3 : + nom affiché
  const lots = _qeLots().filter(match);
  const nbLibre = (ref) => { const e = _loyerEtatLot(ref); return e ? window.moisAQuittancer(e, _qeDeja(ref).yms).length : 0; };
  const item = (l) => {
    const n = nbLibre(l.ref);
    const bail = _findBailByRefTolerant(l.ref);
    return `<button class="it" onclick="_qeChoisirLot('${_lyQ(l.ref)}')">
      <span class="rf">${escHtml(_logLabelRef(l))}</span><span class="lo">${escHtml(l.locataire || '— vacant —')}</span>
      ${(bail && bail.quittanceDemandee) ? '<span class="bg ask">🧾 mensuelle</span>' : ''}
      <span class="bg ${n ? 'on' : ''}">${n ? n + ' mois libre' + (n > 1 ? 's' : '') : 'à jour'}</span></button>`;
  };
  let h = '';
  const attente = lots.filter(l => nbLibre(l.ref) > 0);
  if (attente.length) h += `<div class="sugg">Ce qui attend une quittance · ${attente.length} lot${attente.length > 1 ? 's' : ''}</div>`
    + attente.slice(0, 5).map(item).join('');
  const G = window.GroupByImm;
  if (G && typeof G._grouperLotsParBailleurEtImmeuble === 'function') {
    const parBailleur = !(typeof _entActif === 'function' && _entActif());
    for (const gb of G._grouperLotsParBailleurEtImmeuble(lots, { parBailleur })) {
      const nb = gb.immeubles.reduce((s, i) => s + i.logements.length, 0);
      h += `<div class="gb">🏛 ${gb.isUnassigned ? '<span class="orph">Sans bailleur</span>' : escHtml(gb.entite || '')}<span class="c">${nb}</span></div>`;
      for (const gi of gb.immeubles) {
        h += `<div class="gi">${gi.isUnassigned ? '<span class="orph">Sans immeuble</span>' : escHtml(gi.imm || '')}</div>`
          + gi.logements.map(item).join('');
      }
    }
  } else h += lots.map(item).join('');
  // V10 — la quittance libre est la DERNIÈRE entrée du sélecteur, pas un second bouton d'écran.
  h += `<div class="gb" style="border-top:1px solid var(--bor)">✎ Autre</div>
    <button class="it" onclick="_qeModeLibre(${_qe.ref ? `'${_lyQ(_qe.ref)}'` : 'null'})">
      <span class="rf">Quittance libre</span>
      <span class="lo">${_qe.ref ? 'partir de ' + escHtml(_logLabelRef(_qe.ref)) + ', tout reste modifiable' : 'sans bail — tout se remplit sur la feuille'}</span></button>`;
  // V11 — les saisies libres retenues sont REJOUABLES : l'app garde la SAISIE (pas le
  // document), on la rouvre et on la réédite. Pas de liste infinie : les cinq dernières.
  const libres = ((DB.params || {}).quittancesLibres || []).slice().reverse();
  if (libres.length) {
    h += `<div class="gi">saisies libres retenues — ${libres.length > 5 ? 'les 5 plus récentes sur ' + libres.length : libres.length}</div>`
      + libres.slice(0, 5).map((x) => `<button class="it" onclick="_qeRejouerLibre('${_lyQ(x.id)}')">
          <span class="rf">${escHtml(x.locataireNom || '—')}</span>
          <span class="lo">${escHtml(x.debut || '?')} → ${escHtml(x.fin || '?')} · ${fmt(x.total)}</span>
          <span class="bg">↺ rééditer</span></button>`).join('');
  }
  host.innerHTML = h || '<div class="sugg">Aucun lot ne correspond.</div>';
}

// =================== LETTRES IRL ===================
let _letterRef = null;

/* v13.37 IRL : wrapper utilisé par les boutons 👁 du tableau, des cards et de la
   popup rappel + bouton "Aperçu" dans la modale "Valider envoi" (#ov-irl-valider).
   v15.75 BUG-IRL-APERCU-LETTRE-V15 Bug 1+2 : ouvre TOUJOURS la modale #ov-irl-lettre
   (avant : seulement en mobile ≤900px). Résout :
     • Bug 1 : panneau latéral étroit peu lisible sur desktop → modale plein écran
     • Bug 2 : depuis modale Valider, l'injection silencieuse dans #pdf-irl-content
       masqué était invisible → la modale Lettre s'ouvre maintenant par-dessus.
   L'injection dans #pdf-irl-content reste car printIRLLetter et envoyerLettreIRLParEmail
   (boutons du panneau latéral) lisent depuis ce nœud. */
function previewIRLLetter(ref, opts) {
  const html = genIRLLetter(ref, opts);
  const dst = el('ov-irl-lettre-content');
  if (!dst) { showToast('Modale lettre introuvable', 'err'); return; }
  if (!html) { showToast('Lettre IRL non calculable pour ce lot', 'err'); return; }
  // DOC-3 : la lettre est un document `.pro-doc` comme les autres — elle passe par le cadre
  // isolé. Et on OUVRE AVANT DE RENDRE : le cadre se mesure, une modale cachée mesure 0.
  openM('ov-irl-lettre');
  _docRenderSandboxed(dst, html, 'Lettre de révision IRL', _docCarteCss());
}

// IRL-REVISION R6 — « Revoir la lettre » d'un événement de l'historique du bail : retrouve SON
// entrée (même lot, même date de validation, même date d'effet) et rejoue sa lettre.
function _irlLettreEvt(ref, dateIso, effetIso) {
  const _y = s => String(s || '').slice(0, 10);
  const entree = (DB.irlHistorique || []).slice().reverse().find(h => h && !h._deleted && h.ref === ref
    && h.action !== 'renonciation' && (_y(h.date) || _y(h.dateRevision)) === _y(dateIso)
    && (_y(h.dateEffet) || _y(h.dateApplication) || _y(h.dateRevision)) === _y(effetIso));
  previewIRLLetter(ref, { entree: entree || null });
}

// v14.58 — Aperçu IRL depuis la fiche logement (force la modale, même desktop)
// Bug remonté : depuis le panel Bail de la fiche logement, "👁 Voir lettre" appelle
// previewIRLLetter qui ne montre la modale qu'en mobile. Sur desktop, la lettre est
// injectée dans #pdf-irl-content (qui est sur l'onglet IRL invisible) → rien ne s'affiche.
// Ce wrapper force toujours la modale `#ov-irl-lettre` quel que soit le viewport.
function previewIRLLetterFromLog(ref) {
  if(typeof genIRLLetter !== 'function') { showToast('Module IRL indisponible','err'); return; }
  const html = genIRLLetter(ref);
  const src = html ? { innerHTML: html } : null;
  const dst = el('ov-irl-lettre-content');
  if(!src || !dst) {
    // Repli : l'onglet Loyers, où vivent les révisions (la lettre suit le clic).
    showToast('Aperçu de la lettre indisponible — ouverture de l\'onglet Loyers','info');
    _goFromLogFiche('loyers');
    return;
  }
  openM('ov-irl-lettre');   // DOC-3 : ouvrir AVANT de rendre
  _docRenderSandboxed(dst, src.innerHTML, 'Lettre de révision IRL', _docCarteCss());
}

/**
 * v15.111 — Build pur du HTML de la lettre IRL.
 * Retourne { html, css, title } OU { error, errorHtml, alertMsg? } si non-émissible.
 * Single source of truth pour 2 renderers : aperçu modale (#pdf-irl-content) +
 * PJ email (html2canvas via _rasterizeHtmlToPdfBlob).
 *
 * Copy-paste EXACT du HTML actuel — aucune modification visuelle.
 */
function _buildIRLLetterHtml(log, bail, ent, rev, opts) {
  // V20 — « la lettre part quand même si tu le décides » : sur un lot gelé ou sans DPE, le
  // refus dur devient franchissable DÈS LORS que l'utilisateur a coché la confirmation.
  const _force = !!(opts && opts.force);
  if (!log || !rev || rev.insuffisant || rev.pasEncoreApplicable) {
    return { error: 'insuffisant', errorHtml: '<span class="mu">Données IRL insuffisantes ou révision non encore applicable.</span>' };
  }
  if (rev.dpeManquant && !_force) {
    return {
      error: 'dpe-manquant',
      errorHtml: '<span class="mu">⚠️ DPE non renseigné — saisir le DPE sur la fiche du bien avant la révision IRL.</span>',
      alertMsg: '⚠️ DPE non renseigné\n\nImpossible de générer la lettre de révision IRL : le diagnostic de performance énergétique (DPE) n\'est pas saisi pour ce bien.\n\nLa loi Climat 2021 impose de vérifier le DPE avant toute révision (les classes F et G sont gelées).\n\nOuvrir la fiche du bien (onglet Diagnostics) et saisir le DPE avant de réessayer.'
    };
  }
  if (rev.gelDpeFG && !_force) {
    return {
      error: 'dpe-fg-gel',
      errorHtml: `<div style="background:#fee2e2;border:2px solid #dc2626;border-radius:6px;padding:14px;color:#991b1b;font-weight:bold">🔒 Loyer GELÉ — DPE ${rev.dpe}<br><span style="font-weight:normal;font-size:12px">Loi Climat 2021 — révision IRL interdite pour les passoires thermiques (classes F et G) depuis le 24/08/2022. Aucune lettre ne peut être générée.</span></div>`,
      alertMsg: `🔒 Loyer GELÉ — DPE ${rev.dpe}\n\nLa loi Climat & Résilience (n° 2021-1104, art. 23) interdit la révision IRL pour les logements classés F ou G en DPE depuis le 24 août 2022.\n\nLe loyer reste figé tant que le DPE n'est pas remonté à E ou mieux.\n\nAucune lettre de révision ne peut être générée.`
    };
  }

  const {irlRef,irlVigueur,dateRevision,variation,nouveauHC} = rev;
  const today = new Date();
  const _dfr = d => d.toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
  const _dfm = d => d.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});
  const dateLettre = _dfr(today);
  const moisAnniv = _dfm(dateRevision);
  // Échappé À LA SOURCE : 4 interpolations en aval (bloc parties, objet, corps, contexte).
  const adrBien = escHtml(bail?.adrBien || log.adr || '–');
  const dateBail = bail?.debut ? _dfr(new Date(bail.debut+'T00:00:00')) : '–';
  const ch = bail?.ch || log.ch || 0;
  const total = Math.round((nouveauHC + ch)*100)/100;

  // DOCS-UNIFIES — gabarit unique (variante B). Le fond est repris MOT POUR MOT : objet,
  // formule légale, les 6 lignes de calcul, articles 17-1 et 21, référence INSEE, formule de
  // politesse. Seuls la typographie (l'Arial et le tableau vert disparaissent), les gouttières
  // et la disposition changent — c'est exactement l'incohérence que le gabarit corrige.
  const corps = `
${_dt('docParties', [
  { label: 'Bailleur',
    qui: `${escHtml(ent?.nom||bail?.entity||'–')}`,
    corps: `<p>${escHtml(ent?.siege||'')}${ent?.gerant?'<br>'+escHtml(ent.gerant):''}</p>` },
  { label: 'Locataire',
    qui: `${escHtml(_civNoms(bail?.locataires, log.locataire))}`,
    corps: `<p>${adrBien}</p>` }
])}

      <p style="text-decoration:underline"><b>Objet : Révision annuelle du loyer — Indice de Référence des Loyers (IRL)<br>
      Logement : ${adrBien} — Bail du ${dateBail}</b></p>

      <p>${escHtml(_civSalut(bail?.locataires))}</p>

      <p>En application de la clause de révision stipulée dans le contrat de bail signé le <b>${dateBail}</b>
      et conformément à l'article 17-1 de la loi n° 89-462 du 6 juillet 1989 tendant à améliorer les rapports
      locatifs, nous vous informons de la révision annuelle du loyer de votre logement situé
      <b>${adrBien}</b>.</p>

      <p>La révision est calculée selon la formule légale :<br>
      <b>Nouveau loyer = Loyer actuel × IRL T${rev.T} ${rev.N} / IRL T${rev.T} ${rev.N-1}</b></p>

${_dt('docLignes', [
  { lab: 'Trimestre de référence (mois anniversaire du bail)', val: `T${rev.T}` },
  { lab: `IRL de référence — ${irlRef.key} (N-1) — publié par l'INSEE`, val: `${irlRef.val}` },
  { lab: `IRL en vigueur — ${irlVigueur.key} (N) — publié par l'INSEE`, val: `${irlVigueur.val}` },
  { lab: `Variation annuelle de l'IRL`, val: `+ ${(variation*100).toFixed(2)} %` },
  { lab: 'Loyer mensuel hors charges actuel', val: fmt(log.hc) },
  { lab: 'Nouveau loyer mensuel hors charges', val: fmt(nouveauHC), tot: true, hi: true }
])}

      ${(opts && /^\d{4}-\d{2}-\d{2}$/.test(String(opts.dateEffetIso || '')))
        ? `<p>Conformément à l'article 17-1 de la loi du 6 juillet 1989, ce nouveau loyer prend effet
      le <b>${_dfr(new Date(opts.dateEffetIso + 'T00:00:00'))}</b>.</p>`
        : `<p>Conformément à l'article 17-1 de la loi du 6 juillet 1989, ce nouveau loyer prend effet
      au <b>mois anniversaire du bail (${moisAnniv})</b>.</p>`}

      ${ch>0?`<p>Les charges locatives provisionnelles restent inchangées à <b>${fmt(ch)}/mois</b>,
      portant le montant total mensuel (loyer + charges) à <b>${fmt(total)}/mois</b>.</p>`:''}

${_dt('docMention', `Réf. : art. 17-1, loi n° 89-462 du 6/7/1989 — Indices INSEE série 001515333, hexagone, base 100 = T4 1998.<br>
      À défaut de révision notifiée dans l'année suivant sa date d'effet, le bailleur est réputé avoir renoncé à la révision (art. 17-1 al. 3).`)}

      <p>Nous vous prions d'agréer, ${escHtml(_civConge(bail?.locataires))} l'expression de nos salutations distinguées.</p>

${_dt('docLieu', `Fait le ${dateLettre}`)}
${_dt('docSignzone', [{ sig: _docSigOnly(ent), label: `Le bailleur<br><b>${escHtml(ent?.gerant||ent?.nom||'')}</b>` }])}`;

  const html = _docPage(ent, {
    titre: 'Révision annuelle du loyer',
    ctx: `Indice de Référence des Loyers · ${adrBien} — bail du ${dateBail}`,
    corps: corps,
    ref: escHtml(log.ref || ''), date: `Émis le ${dateLettre}`
  });

  return { html, css: '', title: 'Lettre IRL — ' + (log.ref || '–') + ' — ' + moisAnniv };
}
if (typeof window !== 'undefined') window._buildIRLLetterHtml = _buildIRLLetterHtml;

// CDC-QUITTANCES-IRL étape 6 — la lettre ne transite plus par le panneau latéral de
// l'ancien onglet IRL (`#pdf-irl-content`), qui n'existe plus : elle est GARDÉE ici et
// servie aux trois consommateurs (aperçu modale, impression, e-mail). Sans ça, la lettre
// jetait sur un nœud absent.
let _irlLetterHtml = '';
// IRL-REVISION R6 — le CONTEXTE de la lettre affichée (lot, révision, loyers, options du gabarit),
// posé ici et relu tel quel par Télécharger / Partager : les trois sorties montrent LA MÊME lettre.
// Avant : chacune recalculait la révision sur le loyer courant, et refusait un lot sans DPE même
// après la confirmation du garde-fou (constats 8 et 10).
let _irlLetterCtx = null;
/**
 * @param {string} ref
 * @param {{entree?:Object}} [opts] `entree` = une entrée précise du journal (ligne de l'historique)
 */
function genIRLLetter(ref, opts) {
  _letterRef = ref;
  _irlLetterHtml = '';
  _irlLetterCtx = null;
  const log = DB.logements.find(l=>l.ref===ref); if(!log) return '';
  const bail = DB.baux[ref];
  const ent = DB.entites.find(e=>e.nom===(bail?.entity||log.entity));
  // V20 — un lot révisé « quand même » garde la trace du geste : la lettre suit, mais
  // SEULEMENT pour le cycle qui a été confirmé (audit I1). Le cycle suivant repose la question.
  const _forcee = _irlModeLecture(log).force;
  const rev = computeIRLRevision(log, { force: _forcee });
  const IR = (typeof window !== 'undefined') ? window.IrlRevision : null;

  let built = null, lc = null;
  // R6 — une révision VALIDÉE (programmée ou appliquée) : la lettre REJOUE l'entrée du journal
  // (loyers, indices, date d'effet réelle). Jamais un recalcul sur le loyer courant.
  // Audit M2 — une entrée DEMANDÉE (ligne de l'historique) sans indices exploitables : on le dit,
  // on n'affiche pas à sa place la lettre d'un autre cycle.
  const _explicite = !!(opts && Object.prototype.hasOwnProperty.call(opts, 'entree'));
  let entree = (opts && opts.entree) || null;
  if (!_explicite && IR && rev && rev.dejaApplique && !rev.renonce) {
    entree = IR.entreeValideeDuCycle(DB.irlHistorique || [], ref,
      (rev.programmee && rev.programmee.cycleIso) || rev.effetPrevuIso, bail && bail.debut);
  }
  const revE = (entree && IR) ? IR.revDepuisEntree(entree) : null;
  if (_explicite && !revE) {
    built = { error: 'origine', errorHtml: '<span class="mu">Lettre d’origine indisponible pour cette révision : l’historique n’a pas conservé ses indices.</span>' };
  } else if (revE) {
    const logE = Object.assign({}, log, { hc: revE.ancienHC });
    // Validée = confirmée (garde-fou compris) : la lettre part, DPE absent ou non.
    const o = { force: true, dateEffetIso: revE.dateEffetIso };
    built = _buildIRLLetterHtml(logE, bail, ent, revE, o);
    lc = { log: logE, rev: revE, opts: o, ancienHC: revE.ancienHC, nouveauHC: revE.nouveauHC, dateEffetIso: revE.dateEffetIso };
  } else if (rev && rev.dejaApplique) {
    // Cycle traité sans entrée exploitable (renonciation, donnée ancienne) : aucune lettre inventée.
    built = { error: 'deja', errorHtml: rev.renonce
      ? '<span class="mu">Révision renoncée pour ce cycle — aucune lettre à envoyer.</span>'
      : '<span class="mu">Révision déjà appliquée — la lettre d\'origine n\'est pas disponible (historique incomplet).</span>' };
  } else {
    // Projet de lettre AVANT validation : la date d'effet annoncée est celle que la validation
    // proposera aujourd'hui (R2), pas « le mois anniversaire ».
    const annivIso = (rev && rev.effetPrevuIso) || '';
    const eff = (annivIso && typeof window._baremeComputeDateEffetIRL === 'function')
      ? window._baremeComputeDateEffetIRL({ anniversaireIso: annivIso, validationIso: _todayIsoLocal(), dernierMoisQuittanceYm: _dernierMoisQuittanceYm(ref) }).effetIso
      : '';
    const o = { force: _forcee, dateEffetIso: eff };
    // O6 : « loyer actuel » = la base réelle de la révision (barème de la veille de l'effet), comme le calcul.
    const logL = (rev && rev.ancienHC != null) ? Object.assign({}, log, { hc: rev.ancienHC }) : log;
    built = _buildIRLLetterHtml(logL, bail, ent, rev, o);
    lc = { log: logL, rev, opts: o, ancienHC: logL.hc, nouveauHC: rev && rev.nouveauHC, dateEffetIso: eff };
  }
  _irlLetterHtml = built.error ? (built.errorHtml || '') : built.html;
  if (!built.error && lc) _irlLetterCtx = Object.assign({ ref, bail, ent }, lc);
  if (built.error && built.alertMsg) alert(built.alertMsg);
  // v13.33 IRL-VALIDATION : aucune zone validation injectée dans la lettre.
  // La lettre reste un document propre, prêt à imprimer.
  return _irlLetterHtml;
}
/* v13.32 IRL-VALIDATION : marque/démarque la lettre IRL comme envoyée */
function markIRLLetterSent(ref) {
  const log = DB.logements.find(l => l.ref === ref);
  if (!log) return;
  // AUDIT I1 — le MÊME mode de lecture que `genIRLLetter` : sinon la lettre d'un lot gelé
  // s'édite mais ne peut jamais être marquée envoyée (« Révision IRL non calculable »).
  const rev = computeIRLRevision(log, _irlModeLecture(log));
  if (!rev || !rev.dateRevision) { showToast('Révision IRL non calculable', 'err'); return; }
  log.irlLettreEnvoyee = true;
  log.irlLettreEnvoyeeDate = new Date().toISOString().slice(0, 10);
  log.irlLettreEnvoyeePour = _isoLocal(rev.dateRevision);
  saveDB();
  refreshAllIRL();
  // v13.33 : si la popup rappel est ouverte, rafraîchir son contenu
  if (!el('ov-irl-rappel')?.classList.contains('hidden')) _renderIRLRappelModal();
  try { _rPeriodPage(); } catch(e) {}
  if (_letterRef === ref) genIRLLetter(ref);
  showToast(`✓ Lettre IRL pour ${_logLabel(ref)} marquée comme envoyée`, 'ok');
}

function unmarkIRLLetterSent(ref) {
  const log = DB.logements.find(l => l.ref === ref);
  if (!log) return;
  if (!confirm2('Annuler la validation d\'envoi de la lettre IRL ?')) return;
  delete log.irlLettreEnvoyee;
  delete log.irlLettreEnvoyeeDate;
  delete log.irlLettreEnvoyeePour;
  saveDB();
  refreshAllIRL();
  if (!el('ov-irl-rappel')?.classList.contains('hidden')) _renderIRLRappelModal();
  try { _rPeriodPage(); } catch(e) {}
  if (_letterRef === ref) genIRLLetter(ref);
  showToast(`Validation envoi annulée pour ${_logLabel(ref)}`, 'info');
}

/* v13.33 IRL-VALIDATION : collecte les baux dont la révision est applicable
   et non encore appliquée (le mois anniversaire est passé). */
function _collectIRLRappels() {
  if (!DB.logements || !DB.logements.length) return [];
  const out = [];
  // v14.47 audit tombstones
  (DB.logements||[]).filter(_isAlive).forEach(l => {
    if (!_lotEstLoue(l) || !l.debut) return;
    const rev = (typeof computeIRLRevision === 'function') ? computeIRLRevision(l) : null;
    if (!rev || !rev.isApplicable || rev.dejaApplique || !rev.diff) return;
    // ⚠️ Recoupe le JOURNAL irlHistorique (source indexée par `ref`, robuste aux DOUBLONS et à la désync
    // de `log.irlDerniereApplication`) : une révision de CE cycle (même ref + même dateRevision) déjà
    // APPLIQUÉE / RENONCÉE / ENVOYÉE-EN-ATTENTE (pendingApply) y possède une entrée → on ne la repropose PAS.
    // Sinon un jumeau dupliqué (irlDerniereApplication='' → dejaApplique=false) ou une révision envoyée en
    // différé réapparaissait dans le popup alors que la page IRL, elle, la montre déjà réglée. Même clé que
    // la page (ref + dateRevision « AAAA-MM-JJ »). Ne dépend PAS de `log.irlDerniereApplication` (désyncable).
    const revKey = (rev.dateRevision instanceof Date) ? _isoLocal(rev.dateRevision) : String(rev.dateRevision || '').slice(0, 10);
    if (revKey && (DB.irlHistorique || []).some(h => h && !h._deleted && h.ref === l.ref && String(h.dateRevision || '').slice(0, 10) === revKey)) return;
    out.push({ log:l, rev });
  });
  return out;
}

/* v13.33 IRL-VALIDATION : peuple #ov-irl-rappel-list.
   Une carte par bail à réviser : récap chiffré + 2 boutons (envoi + appli). */
function _renderIRLRappelModal() {
  const list = _collectIRLRappels();
  const host = el('ov-irl-rappel-list');
  if (!host) return;
  if (!list.length) {
    host.innerHTML = `<div style="padding:18px;text-align:center;color:var(--grn);font-size:13px;background:rgba(22,163,74,.08);border-radius:8px;border:1px solid rgba(22,163,74,.2)">
      ${_uiIcon('check',13)} Aucune révision IRL en attente.</div>`;
    return;
  }
  host.innerHTML = list.map(({log, rev}) => {
    const st = _irlLettreState(log, rev);
    const moisAnniv = rev.dateRevision.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});
    const diff = rev.nouveauHC - log.hc;
    const sign = diff > 0 ? '+' : '';
    return `<div class="irl-rappel-card" style="margin-bottom:10px;padding:12px 14px;background:var(--sur2);border:1px solid var(--bor);border-left:4px solid ${st?st.border:'var(--ora)'};border-radius:8px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:8px">
        <div>
          <div style="font-weight:600;font-size:14px"><b>${escHtml(_logLabel(log))}</b> · ${escHtml(log.locataire||'–')}</div>
          <div class="mu sm" style="font-size:11.5px">Anniversaire bail : ${moisAnniv}</div>
        </div>
        <div style="text-align:right;font-size:12px;line-height:1.5">
          <span class="mu sm">${fmt(log.hc)}</span>
          <span style="color:var(--t2)"> → </span>
          <b style="color:${diff>=0?'var(--grn)':'var(--red)'}">${fmt(rev.nouveauHC)}</b>
          <div class="mu sm" style="font-size:11px">${sign}${fmtN(diff)} €/mois (${sign}${(rev.variation*100).toFixed(2)} %)</div>
        </div>
      </div>
      <div class="flex-c irl-actions" style="gap:6px;flex-wrap:wrap;justify-content:flex-end;align-items:center">
        <button class="btn bs bb" onclick="previewIRLLetter('${_lyQ(log.ref)}');closeM('ov-irl-rappel');go('irl',null)" title="Voir la lettre">${_uiIcon('eye')} Aperçu lettre</button>
        ${_irlEnvelopeBtn(log, st)}
        <button class="btn bg bb" onclick="applyIRL('${_lyQ(log.ref)}',${rev.nouveauHC})" title="Appliquer ${fmt(rev.nouveauHC)}" style="font-weight:600">${_uiIcon('money')} Valider IRL</button>
      </div>
    </div>`;
  }).join('');
}

/* v13.33 IRL-VALIDATION : ouvre la popup si des révisions sont en attente.
   - source : 'login' (1×/jour) ou 'tab' (1×/session)
   - condition stricte : isApplicable && !dejaApplique (mois anniversaire dépassé)
   Si déjà affichée pour la session (même source), on n'ouvre pas la popup mais on
   maintient le toast léger pour signaler discrètement les révisions à traiter. */
// CDC-QUITTANCES-IRL D22 / I14 — `_checkIRLRappelsAuLogin` SUPPRIMÉE. Elle ouvrait au boot la
// modale `ov-irl-rappel` (+ un toast), ce qui contredisait trois décisions : déclenchée sur
// `rev.isApplicable` (après l'anniversaire, jamais au rappel M-1 de D13), elle portait un bouton
// « Valider IRL » qui appliquait une révision depuis une fenêtre ouverte automatiquement (hors de
// la fenêtre de validation D18), et elle interrompait là où D5 met le travail dans l'écran. Le
// rappel vit désormais sur la PASTILLE de l'entrée de menu « Loyers » (_lyBadgeCount). Preuve
// d'atteignabilité : `openM('ov-irl-rappel')` n'était appelé que d'ici, et cette fonction n'était
// planifiée qu'au boot — la modale est donc désormais inatteignable (reste masquée, I14).

// v15.249 B8 (D-B12) — Rappel au login : diagnostics expirés. Toast léger (PAS de modale,
// pour ne pas empiler sur la popup IRL). Anti-spam : 1 toast/jour max (sessionStorage).
// Mirroir du pattern _checkIRLRappelsAuLogin (skip lecture seule / Drive non connecté).
function _checkDiagRappelsAuLogin(source) {
  source = source || 'login';
  if (typeof _appReadOnly !== 'undefined' && _appReadOnly) return;
  if (typeof _DIAGS_CATALOG_INLINE === 'undefined') return;
  const now = new Date();
  let nExp = 0, nLogs = 0;
  (DB.logements || []).forEach(l => {
    if (!l || !l.ref || l.archived) return;
    let any = false;
    _DIAGS_CATALOG_INLINE.forEach(entry => {
      if (_diagExpireARefaire(entry.key, l, now)) { nExp++; any = true; }
    });
    if (any) nLogs++;
  });
  if (!nExp) return;
  const today = now.toISOString().slice(0, 10);
  try {
    if (sessionStorage.getItem('diagRappelShown') === today) return;
    sessionStorage.setItem('diagRappelShown', today);
  } catch(e) {}
  const msg = `🔴 ${nExp} diagnostic${nExp>1?'s':''} expiré${nExp>1?'s':''} sur ${nLogs} logement${nLogs>1?'s':''} — à renouveler`;
  try { showToast(msg, 'warn', 5000); } catch(e) {}
}

// v14.97 EMAIL-AUTO.4 : envoi lettre IRL par email (lettre détaillée jointe en PDF
// à générer côté app, l'email contient un résumé court + invite à consulter la PJ).
// Lit _letterRef (let-scope du même bloc <script>) positionné par genIRLLetter(ref).
function envoyerLettreIRLParEmail() {
  const ref = _letterRef;
  if (!ref) { showToast('Sélectionner d\'abord un logement avec révision IRL','err'); return; }
  if (typeof window._openEmailModal !== 'function') {
    showToast('Module email non chargé — vérifier http-server (npx serve)', 'err', 6000);
    return;
  }
  const ctx = _irlCtxEnvoi(ref);
  if (!ctx) return;
  _docShareOpen('irl-revision', ctx, { entityType: 'bail', entityId: ref });
}

/**
 * IRL-REVISION R6 — le contexte d'envoi (e-mail / PDF / partage) de la lettre AFFICHÉE : la même
 * révision, les mêmes loyers, les mêmes options de gabarit que l'aperçu (constats 8 et 10). Une
 * lettre qui s'affiche s'envoie — le gabarit a déjà tranché DPE et forçage en la construisant.
 */
function _irlCtxEnvoi(ref) {
  const c = _irlLetterCtx;
  if (!c || c.ref !== ref || !c.rev) { showToast('Ouvrir d\'abord la lettre de révision de ce lot', 'err'); return null; }
  const log = c.log;
  const bail = c.bail;
  // Mois annoncé dans le mail = celui de la date d'effet réelle (plus « le mois anniversaire »).
  const _dr = c.dateEffetIso ? new Date(c.dateEffetIso + 'T00:00:00')
    : (c.rev.dateRevision instanceof Date ? c.rev.dateRevision : new Date(String(c.rev.dateRevision) + 'T00:00:00'));
  const moisApplication = _dr.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
  const locataire = (bail?.locataires && bail.locataires[0]) || { nom: log.locataire || '', email: log.mail || '' };
  return {
    locataire,
    bail: bail || { adrBien: log.adr || '', hc: log.hc, ch: log.ch },
    logement: log,
    entite: c.ent || {},
    ancienHC: c.ancienHC,
    nouveauHC: c.nouveauHC,
    moisApplication,
    rev: c.rev,              // v15.111 — _genPdfIrlRevision rejoue _buildIRLLetterHtml sans recalcul
    letterOpts: c.opts       // … avec les MÊMES options (date d'effet, forçage)
  };
}

/**
 * v15.99 EM-2d V1.1 — Partage lettre IRL avec PDF (Web Share API niveau 2).
 * Lit _letterRef (positionné par genIRLLetter). Construit ctx + appelle
 * _emailGenPdfAttachment + share/download. Pattern identique à
 * _shareQuittanceWithPdf.
 */
window._shareIRLLetterWithPdf = async function(ref) {
  ref = ref || _letterRef;
  if (!ref) { showToast('Sélectionner d\'abord un logement avec révision IRL', 'err'); return; }
  if (typeof window._emailGenPdfAttachment !== 'function') {
    showToast('Module PDF non chargé (rafraîchir la page)', 'err', 5000);
    return;
  }
  const ctx = _irlCtxEnvoi(ref);
  if (!ctx) return;
  const log = ctx.logement, bail = ctx.bail, ent = ctx.entite, rev = ctx.rev;
  const moisApplication = ctx.moisApplication;

  showToast('Génération du PDF en cours…', 'info', 2000);
  let pdfResult;
  try {
    pdfResult = await window._emailGenPdfAttachment('irl-revision', ctx);
  } catch (e) {
    showToast('Erreur génération PDF : ' + e.message, 'err', 5000);
    return;
  }
  if (pdfResult && pdfResult.error) {
    showToast('Génération PDF échouée : ' + (pdfResult.message || pdfResult.error), 'err', 5000);
    return;
  }

  const bin = atob(pdfResult.base64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const file = new File([bytes], pdfResult.filename, { type: 'application/pdf' });

  const subject = `Révision IRL ${moisApplication} — ${bail?.adrBien || log.adr || ''}`;
  const body = `Bonjour,\n\nLa lettre officielle de révision annuelle IRL (art. 17-1 loi 6/7/1989) est jointe en PDF.\n\nNouveau loyer hors charges : ${rev.nouveauHC} € (vs ${log.hc} € actuel).\nApplication : à compter du mois de ${moisApplication}.\n\nCordialement,\n${ent?.gerant || ''}${ent?.nom ? '\n' + ent.nom : ''}`;
  const shareData = { title: subject, text: body, files: [file] };

  if (typeof navigator !== 'undefined' && typeof navigator.share === 'function'
      && typeof navigator.canShare === 'function' && navigator.canShare(shareData)) {
    try {
      await navigator.share(shareData);
      showToast('Partagé ✓ (avec PDF)', 'ok', 3000);
      return;
    } catch (e) {
      if (e && e.name === 'AbortError') return;
      showToast('Erreur partage : ' + (e.message || e), 'err', 4000);
      return;
    }
  }
  // Fallback : download PDF + copy texte
  try {
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url; a.download = pdfResult.filename; a.style.display = 'none';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(subject + '\n\n' + body).catch(() => {});
    }
    showToast('Partage natif indisponible — PDF téléchargé + texte copié', 'ok', 5000);
  } catch (e) {
    showToast('Erreur download : ' + e.message, 'err', 5000);
  }
};

function printIRLLetter() {
  // DOC-3 : la lettre partait dans une popup de MÊME ORIGINE (`window.open` hérite de l'origine
  // de l'app) où son HTML était écrit tel quel — un `<img onerror>` glissé dans un nom de
  // locataire s'y exécutait avec le jeton de session. Même fenêtre isolée que les 4 autres
  // documents. Le repli ne lit plus `innerHTML` (ce serait le markup DU CADRE, emboité une
  // seconde fois — le timbre-poste en silence) mais le document brut conservé par le rendu.
  const host = el('ov-irl-lettre-content');
  const html = _irlLetterHtml || (host && host._docHtml) || '';
  if(!html.trim()) { showToast('Aucune lettre ouverte', 'err'); return; }
  const fr = host ? host.querySelector('iframe.doc-sandbox') : null;
  _docPrintSandboxed(html, 'Lettre IRL', fr ? parseInt(fr.style.height, 10) : 0, _docCarteCss());
}


// =================== EDL ===================

const EDL_ETATS  = ['Neuf','Bon état',"État d'usage",'Mauvais état','Absent'];
// EDL TERRAIN lot 5 (§7ter, §9 inv. 34j/34k/34l) — les 5 états quittent la palette
// GitHub (contrastes 2,5:1, figée dans les deux thèmes) pour les tokens sémantiques de
// la charte, recalibrés à 4,5:1. À L'ÉCRAN : variables CSS qui SUIVENT le thème.
const EDL_CSSVAR = {'Neuf':'var(--e-neuf)',"Bon état":'var(--e-bon)',"État d'usage":'var(--e-usage)','Mauvais état':'var(--e-mauvais)','Absent':'var(--e-absent)'};
const _edlEtatBg = et => `color-mix(in srgb, ${EDL_CSSVAR[et]} 22%, transparent)`;
// DANS LE PDF : mêmes couleurs, en valeurs d'impression FIGÉES (un PDF n'a pas de thème)
// = exactement les tokens CLAIRS de la charte. Aucune coordonnée de signature n'est
// déplacée par ce changement (§7ter) — c'est ce qui l'autorise hors du gate PDF.
const EDL_PDF_RGB = {'Neuf':[22,121,94],"Bon état":[46,109,177],"État d'usage":[143,98,14],'Mauvais état':[201,47,47],'Absent':[66,80,106]};
const EDL_ABBREV = {'Neuf':'N',"Bon état":'B',"État d'usage":'U','Mauvais état':'M','Absent':'–'};
const EDL_DESC   = {'Neuf':'Jamais utilisé',"Bon état":'Propre et fonctionnel',"État d'usage":'Vétusté normale, non imputable','Mauvais état':'Dégradation anormale à charge du locataire','Absent':'Absent ou non applicable'};

// v14.12.6 — Source unique de vérité pour les textes du cadre jaune "Engagement
// des locataires" affichés en PDF ET dans le formulaire EDL (au-dessus des
// signatures, pour que le locataire voie ce qu'il signe AVANT de signer).
const EDL_ENGAGEMENT_TITRE = 'Engagement des locataires :';
const EDL_ENGAGEMENT_TXT1 = "Les locataires s'engagent à restituer le logement dans son état initial (murs, plafonds, sols). L'usure normale n'est pas retenue. Réf. décret n°2016-382 du 30/03/2016 (vétusté).";
const EDL_ENGAGEMENT_TXT2 = "Les soussignés reconnaissent les constatations sur l'état du logement, sous réserve du bon fonctionnement des canalisations, appareils et installations sanitaires, électriques et du chauffage qui n'ont pu être vérifiés ce jour, toute défectuosité dans le fonctionnement de ceux-ci devant être signalée dans le délai maximum de dix jours, et pendant le premier mois de la période de chauffe en ce qui concerne les éléments de chauffage. Les cosignataires aux présentes ont convenu du caractère probant et indiscutable des signatures y figurant pour être recueillies selon procédé informatique sécurisé au contradictoire des parties, ils s'accordent pour y faire référence lors du départ du locataire. Le présent état des lieux établi contradictoirement entre les parties qui le reconnaissent exact, fait partie intégrante du contrat de location dont il ne peut être dissocié.";
// EDL-TÉLÉPHONE (CDC §2.8) — l'engagement de SORTIE est DISTINCT de celui d'entrée : on ne
// remet pas au locataire sortant un texte qui l'engage à « restituer le logement » (absurde à
// la sortie). Ici les parties reconnaissent le constat de sortie et les écarts vs l'entrée.
// AUCUN montant, aucune mention de dépôt (invariant §2.10). Sélection par _edlEngagement(isSortie).
const EDL_ENGAGEMENT_SORTIE_TITRE = "Accord des parties sur l'état des lieux de sortie :";
const EDL_ENGAGEMENT_SORTIE_TXT1 = "Le présent état des lieux de sortie, établi contradictoirement, décrit l'état du logement au départ du locataire. Les parties reconnaissent les écarts constatés par rapport à l'état des lieux d'entrée. L'usure normale et la vétusté ne sont pas retenues (décret n°2016-382 du 30/03/2016).";
const EDL_ENGAGEMENT_SORTIE_TXT2 = "Les cosignataires conviennent du caractère probant et indiscutable des signatures recueillies par procédé informatique sécurisé au contradictoire des parties. Le présent état des lieux de sortie est comparé à l'état des lieux d'entrée et fait partie intégrante du dossier de location dont il ne peut être dissocié. Aucun montant, ni retenue ou restitution de dépôt de garantie, ne figure dans le présent document.";
// Sélecteur unique (écran + PDF) du triplet d'engagement selon le type d'EDL.
function _edlEngagement(isSortie) {
  return isSortie
    ? { titre: EDL_ENGAGEMENT_SORTIE_TITRE, txt1: EDL_ENGAGEMENT_SORTIE_TXT1, txt2: EDL_ENGAGEMENT_SORTIE_TXT2 }
    : { titre: EDL_ENGAGEMENT_TITRE, txt1: EDL_ENGAGEMENT_TXT1, txt2: EDL_ENGAGEMENT_TXT2 };
}

// v14.12.7 — "Fait à Ville le Date" + intro signatures (templates dynamiques).
// Mêmes formules que celles imprimées dans le PDF natif. Source unique de vérité.
