  el('edl-page-title').textContent = title;
  el('edl-page-body').innerHTML = bodyHtml;
  const ft = el('edl-page-foot'); ft.innerHTML = footHtml || ''; ft.style.display = footHtml ? '' : 'none';
  pg.style.display = 'flex';
