function _renderLogementCardFlat(l) {
  const bail = _bienIsBailActif(l.ref) ? _bienActiveBail(l.ref) : null;   // statut : occupé aujourd'hui
  const occupied = !!bail;
  const ratioPct = occupied ? 100 : 0;
  const fillCls = occupied ? '' : 'empty';
  const occupLabel = escHtml(_lotStatutLibelle(l.ref));   // « Loué » / « Vacant » / « Vacant (départ le …, bail à clôturer) »
  const _nomAff = _logLabel(l);                          // B3 : nom d'affichage (libellé), sinon la référence
  const _aUnNom = !!l.ref && _nomAff !== l.ref;          // un nom est défini → « Réf. D-101 » en petit dessous
  const titleEsc = escHtml(_nomAff || '—');
  const refSousTitre = _aUnNom ? `<div class="mu sm" style="font-size:11.5px;margin-top:2px">Réf. ${escHtml(l.ref)}</div>` : '';
  const subtitleEsc = escHtml(l.locataire || (occupied ? 'Bail actif' : 'Aucun locataire'));
  const bailleurEsc = escHtml(l.entity || '—');
  const period = bail
    ? `${fd(bail.debut)} → ${bail.fin?fd(bail.fin):'en cours'}`
    : (l.archived ? `Archivé le ${fd(l.archivedAt)}` : 'Vacant');
  const typeLabel = l.type || 'Habitation';
  const onClick = `openLogFiche('${_lyQ(l.ref)}')`;
  const isArchived = !!l.archived;
  const archCls = isArchived ? ' is-archived' : '';
  const archBadge = isArchived ? '<span class="bien-card-archived-badge">Archivé</span>' : '';
  // MOBILE-REFONTE lot 2a — carte compacte sur téléphone (données identiques ; PC inchangé).
  if (_isPhone()) {
    _ensureBiencPhCss();
    const badgeCls = isArchived ? 'arch' : (occupied ? 'loue' : 'vac');
    const badgeLbl = isArchived ? 'Archivé' : occupLabel;
    const metaBits = [(_aUnNom ? 'Réf. ' + l.ref : ''), typeLabel, (l.surf?fmtN(l.surf)+' m²':''), (l.imm||'')].filter(Boolean).map(escHtml).join(' · ');
    const rentPh = (occupied || !isArchived)
      ? `${fmt(l.hc||0)}<small> HC</small>${l.ch?` <small>+${fmt(l.ch)}</small>`:''}`
      : `${fmt(l.hc||0)}<small> /mois</small>`;
    return `<article class="bienc-ph${archCls}" tabindex="0" onclick="${onClick}" onkeydown="if(event.key==='Enter'||event.key===' '){${onClick};event.preventDefault()}">`
      +`<div class="bienc-thumb">${_coverImg('logement', l.id, '' + _uiIcon('home',26) + '')}<span class="bienc-badge ${badgeCls}">${escHtml(badgeLbl)}</span></div>`
      +`<div class="bienc-mid"><div class="bienc-ref">${titleEsc}</div><div class="bienc-ten">${subtitleEsc}</div>`
      +`<div class="bienc-r3"><span class="bienc-meta">${metaBits}</span><span class="bienc-rent">${rentPh}</span></div></div>`
      +`<span class="bienc-chev" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg></span>`
      +`</article>`;
  }
  return `<article class="bien-card${archCls}" tabindex="0" onclick="${onClick}" onkeydown="if(event.key==='Enter'||event.key===' '){${onClick};event.preventDefault()}">
    <div class="bien-card-header">
      <span class="bch-bailleur" title="${bailleurEsc}">${bailleurEsc}</span>
      ${archBadge}
      <button class="bien-card-menu" onclick="event.stopPropagation();openBienMenu(event,'logement','${_lyQ(l.ref)}','${_lyQ(l.imm||'')}')" aria-label="Actions">⋮</button>
    </div>
    <div class="bien-card-img">
      ${_coverImg('logement', l.id, '' + _uiIcon('home',36) + '')}
      <div class="bien-card-occup">
        <span class="bien-card-occup-label">${occupLabel}</span>
        <span class="bien-card-occup-bar"><span class="bien-card-occup-fill ${fillCls}" style="width:${ratioPct}%"></span></span>
      </div>
    </div>
    <div class="bien-card-body">
      <div class="bien-card-title" title="${titleEsc}">${titleEsc}</div>
      ${refSousTitre}
      <div class="bien-card-subtitle">${subtitleEsc}</div>
      <div class="bien-card-meta">
        <span class="bien-card-badge">${escHtml(typeLabel)}</span>
        ${l.imm?`<span class="bien-card-badge b-mute">${escHtml(l.imm)}</span>`:''}
        ${l.surf?`<span>${fmtN(l.surf)} m²</span>`:''}
      </div>
      <div class="bien-card-period">${period}</div>
      <div class="bien-card-rent">
        <span>${fmt(l.hc||0)}<small> /mois HC</small></span>
        ${l.ch?`<small>+ ${fmt(l.ch)} ch.</small>`:''}
      </div>
    </div>
  </article>`;
}

// ════════════════════════════════════════════════════════════════════════════
// MOBILE-REFONTE lot 3 — Vue Logements TÉLÉPHONE regroupée par immeuble.
// Grief user « où sont les séparateurs ? » : la liste plate ne montrait pas la
// hiérarchie immeuble › lots. On regroupe par (bailleur, immeuble) avec un
// en-tête repliable (vignette + nom + « Ville · N lots · M loués » + chevron) et
// les cartes lots en retrait, en RÉUTILISANT _renderLogementCardFlat (DRY).
// Logements sans immeuble → groupe « Logements isolés » (rangé en dernier).
// État déplié/replié persisté en localStorage (motif _lsKey), comme les blocs A.
// PC (≥768px) inchangé : rBiens garde la grille plate hors _isPhone().
// ════════════════════════════════════════════════════════════════════════════
function _readLogGroupsCollapsed() {
  try { return JSON.parse(localStorage.getItem(_lsKey('logGroupsCollapsed')) || '{}'); }
  catch(e) { return {}; }
}
function _toggleLogGroup(hEl) {
  const grp = hEl && hEl.closest ? hEl.closest('.log-grp') : null;
  if(!grp) return;
  grp.classList.toggle('collapsed');
  try {
    const key = _lsKey('logGroupsCollapsed');
    const stored = JSON.parse(localStorage.getItem(key) || '{}');
    const gkey = grp.getAttribute('data-gkey') || '';
    if(grp.classList.contains('collapsed')) stored[gkey] = true; else delete stored[gkey];
    localStorage.setItem(key, JSON.stringify(stored));
  } catch(e) {}
}
function _renderLogementsGroupedPhone(logs) {
  // Regroupe par (bailleur, immeuble) ; logements sans immeuble → « Logements isolés ».
  const groups = new Map();
  (logs||[]).forEach(l => {
    const hasImm = !!(l.imm && String(l.imm).trim());
    const key = hasImm ? ((l.entity||'—') + '||' + l.imm) : '__ISOLES__';
    if(!groups.has(key)) groups.set(key, { entNom:l.entity||'', immNom: hasImm ? l.imm : '', isoles:!hasImm, logs:[] });
    groups.get(key).logs.push(l);
  });
  const arr = [...groups.values()];
  arr.sort((a,b) => {
    if(a.isoles !== b.isoles) return a.isoles ? 1 : -1;   // isolés toujours en dernier
    return _natCmp(a.entNom, b.entNom) || _natCmp(a.immNom, b.immNom);
  });
  const collapsed = _readLogGroupsCollapsed();
  return arr.map(g => {
    const ent = (!g.isoles && g.entNom) ? (DB.entites||[]).find(e => e.nom === g.entNom) : null;
    const im  = ent ? (ent.immeubles||[]).find(i => i && i.nom === g.immNom && !i._deleted) : null;
    const nbLots  = g.logs.length;
    const nbLoues = g.logs.filter(l => _bienIsBailActif(l.ref)).length;
    const ville = g.isoles ? '' : ((im && im.ville) || _extractVilleFromAdr(im && im.adr) || _extractVilleFromAdr(g.logs[0] && g.logs[0].adr) || '');
    const sub = [ville, `${nbLots} lot${nbLots>1?'s':''}`, `${nbLoues} loué${nbLoues>1?'s':''}`]
      .filter(Boolean).map(escHtml).join(' · ');
    const title = g.isoles ? 'Logements isolés' : escHtml(g.immNom || '—');
    const thumb = g.isoles ? '<span>' + _uiIcon('home',20) + '</span>' : (im && im.id ? _coverImg('immeuble', im.id, '' + _uiIcon('building',20) + '') : '<span>' + _uiIcon('building',20) + '</span>');
    const gkey  = g.isoles ? '__ISOLES__' : (g.entNom + '||' + g.immNom);
    const isCol = !!collapsed[gkey];
    const cards = g.logs.slice().sort(_logLabelCmp).map(_renderLogementCardFlat).join('');
    return `<div class="log-grp${isCol?' collapsed':''}" data-gkey="${escHtml(gkey)}">
      <div class="log-grp-h" onclick="_toggleLogGroup(this)" tabindex="0" role="button" aria-label="Replier ou déplier ${title}" onkeydown="if(event.key==='Enter'||event.key===' '){_toggleLogGroup(this);event.preventDefault()}">
        <span class="log-grp-thumb">${thumb}</span>
        <span class="log-grp-info"><div class="log-grp-name">${title}</div><div class="log-grp-sub">${sub}</div></span>
        <svg class="log-grp-chev" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>
      </div>
      <div class="log-grp-lots">${cards}</div>
    </div>`;
  }).join('');
}

// v14.2 LOG-LISTE-CARDS Phase 2 — état toolbar (recherche / filtres / tri).
// Persiste uniquement le mode de vue ; les filtres restent en RAM (volatile par session).
let _biensFilters = { search:'', entity:'', occup:'', type:'', sort:'name', layout:'cards-b' }; // v15.238 : cards par défaut (demande user "comme avant")

function setBiensSearch(val) {
  _biensFilters.search = (val||'').trim();
  const inp = el('biens-search'); if(inp && inp.value !== val) inp.value = val||'';
  const clr = el('biens-search-clear'); if(clr) clr.classList.toggle('show', !!_biensFilters.search);
  rBiens();
}

function setBiensFilter(key, val) {
  if(!(key in _biensFilters)) return;
  _biensFilters[key] = val||'';
  rBiens();
}

function setBiensSort(val) {
  _biensFilters.sort = val||'name';
  rBiens();
  // Laisse le popover ouvert pour permettre l'essai de plusieurs tris ; ferme via clic extérieur.
}

function clearBiensFilters() {
  _biensFilters.search = ''; _biensFilters.entity = ''; _biensFilters.occup = ''; _biensFilters.type = '';
  const inp = el('biens-search'); if(inp) inp.value = '';
  ['biens-f-entity','biens-f-occup','biens-f-type'].forEach(id => { const e = el(id); if(e) e.value = ''; });
  el('biens-search-clear')?.classList.remove('show');
  rBiens();
}

function _biensActiveFilterCount() {
  let n = 0;
  if(_biensFilters.search) n++;
  if(_biensFilters.entity) n++;
  if(_biensFilters.occup) n++;
  if(_biensFilters.type) n++;
  return n;
}

function _populateBiensFilterSelects() {
  const ents = [...new Set((DB.logements||[]).map(l=>l.entity).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const types = [...new Set((DB.logements||[]).map(l=>l.type).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const entSel = el('biens-f-entity');
  if(entSel) {
    const cur = _biensFilters.entity;
    entSel.innerHTML = '<option value="">Tous</option>' + ents.map(e=>`<option value="${escHtml(e)}"${e===cur?' selected':''}>${escHtml(e)}</option>`).join('');
  }
  const typeSel = el('biens-f-type');
  if(typeSel) {
    const cur = _biensFilters.type;
    typeSel.innerHTML = '<option value="">Tous</option>' + types.map(t=>`<option value="${escHtml(t)}"${t===cur?' selected':''}>${escHtml(t)}</option>`).join('');
  }
  const occupSel = el('biens-f-occup'); if(occupSel) occupSel.value = _biensFilters.occup||'';
}

function _filterAndSortLogs(logs) {
  let out = logs.slice();
  const q = (_biensFilters.search||'').toLowerCase();
  if(q) {
    out = out.filter(l =>
      _logLabelMatch(l, q) ||   // B3 : nom affiché OU référence (sans casse ni accents)
      (l.imm||'').toLowerCase().includes(q) ||
      (l.entity||'').toLowerCase().includes(q) ||
      (l.locataire||'').toLowerCase().includes(q) ||
      (l.adr||'').toLowerCase().includes(q) ||
      (l.type||'').toLowerCase().includes(q)
    );
  }
  if(_biensFilters.entity) out = out.filter(l => l.entity === _biensFilters.entity);
  if(_biensFilters.type)   out = out.filter(l => l.type === _biensFilters.type);
  if(_biensFilters.occup) {
    const wantLoue = _biensFilters.occup === 'loue';
    out = out.filter(l => _bienIsBailActif(l.ref) === wantLoue);
  }
  switch(_biensFilters.sort) {
    case 'name-desc':  out.sort((a,b)=>_natCmp(b.imm, a.imm) || _logLabelCmp(b, a)); break;
    case 'rent-desc':  out.sort((a,b)=>(+b.hc||0)-(+a.hc||0)); break;
    case 'rent-asc':   out.sort((a,b)=>(+a.hc||0)-(+b.hc||0)); break;
    case 'occup-desc': out.sort((a,b)=>(_bienIsBailActif(b.ref)?1:0)-(_bienIsBailActif(a.ref)?1:0)); break;
    case 'recent':     out.sort((a,b)=>(b._modifiedAt||'').localeCompare(a._modifiedAt||'')); break;
    // #7 : immeuble PUIS réf (naturel) — sinon, dans un même immeuble, tous les `imm` sont égaux
    // → aucun classement par numéro de logement (D-2 / D-10 / Garage…). (test partage 2026-06-21)
    default:           out.sort((a,b)=>_natCmp(a.imm, b.imm) || _logLabelCmp(a, b));
  }
  return out;
}

function exportBiensCSV() {
  if(!DB.logements || !DB.logements.length) { showToast('Aucun bien à exporter','err'); return; }
  // Exporte ce que l'utilisateur voit : pool selon tab Actifs/Archivés + filtres en cours
  const pool = _biensTab === 'archives' ? _archivedLogements() : _activeLogements();
  const rowsLogs = _filterAndSortLogs(pool);
  if(!rowsLogs.length) { showToast('Aucun bien ne correspond aux filtres','err'); return; }
  const headers = ['Ref','Immeuble','Bailleur','Type','Surface m²','Étage','Adresse','HC €','Charges €','DG €','Locataire','Date début','Date fin','Statut','IRL','Nom affiché'];
  const escCsv = v => `"${String(v==null?'':v).replace(/"/g,'""')}"`;
  // Injection de formule (Excel/Sheets) : seuls les champs TEXTE LIBRES (Locataire, Nom affiché) sont neutralisés par un « ' »
  // en tête s'ils commencent par = + - @ ; montants (négatifs possibles) et dates ne changent pas.
  // 🟡5 (audit d'intégration) : aussi tabulation / retour chariot en tête ; le texte libre est d'abord NORMALISÉ (même nettoyage
  // que le nom affiché, sans la coupe) : caractères de contrôle → espace, invisibles et surcharges bidi retirés, blancs ramenés à un espace.
  const txtLibre = v => {
    const s = String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/[​-‏‪-‮⁦-⁩﻿]+/g, '').replace(/\s+/g, ' ').trim();
    return /^[=+\-@\t\r]/.test(s) ? "'" + s : s;   // texte libre : « -2+3+cmd|… » est une formule pour un tableur, même suivi d'un chiffre
  };
  const rows = rowsLogs.map(l => [
    txtLibre(l.ref),txtLibre(l.imm||''),txtLibre(l.entity||''),txtLibre(l.type||''),l.surf||'',txtLibre(l.etage||''),txtLibre(l.adr||''),   // lot C : toutes les colonnes de texte libre neutralisées
    l.hc||0,l.ch||0,l.dg||0,txtLibre(l.locataire||''),l.debut||'',l.fin||'',
    _lotStatutLibelle(l.ref), l.irl||'',
    txtLibre(_logLabel(l) !== l.ref ? _logLabel(l) : '')   // B3 : nom affiché, en dernière colonne (colonnes existantes inchangées)
  ]);
  const csv = [headers, ...rows].map(r => r.map(escCsv).join(';')).join('\n');
  const blob = new Blob(['﻿'+csv], {type:'text/csv;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = `Propryo_biens_${td()}.csv`; a.click();
  URL.revokeObjectURL(url);
  showToast(`${rows.length} bien${rows.length>1?'s':''} exporté${rows.length>1?'s':''}`,'ok');
}

function toggleBiensFilter(evt) {
  if(evt) evt.stopPropagation();
  el('biens-sort-popover')?.classList.remove('open');
  const pop = el('biens-filter-popover'); if(!pop) return;
  const opening = !pop.classList.contains('open');
  if(opening) _populateBiensFilterSelects();
  pop.classList.toggle('open', opening);
  el('biens-filter-btn')?.setAttribute('aria-expanded', opening);
}
function closeBiensFilter() {
  el('biens-filter-popover')?.classList.remove('open');
  el('biens-filter-btn')?.setAttribute('aria-expanded','false');
}
function toggleBiensSort(evt) {
  if(evt) evt.stopPropagation();
  closeBiensFilter();
  const pop = el('biens-sort-popover'); if(!pop) return;
  const opening = !pop.classList.contains('open');
  pop.classList.toggle('open', opening);
  el('biens-sort-btn')?.setAttribute('aria-expanded', opening);
}

// Click hors popover ferme + Esc ferme (v15.440 DRY : via _bindPopoverDismiss).
_bindPopoverDismiss({
  safe: ['.biens-filter-wrap'],
  onClose: () => {
    closeBiensFilter();
    el('biens-sort-popover')?.classList.remove('open');
    el('biens-sort-btn')?.setAttribute('aria-expanded','false');
  }
});

// v14.3 PATRIMOINE-NAV-UNIFY — carte d'un bailleur (entité juridique propriétaire)
// Aggrège : N immeubles · M logements actifs · ratio occupation global · loyer HC mensuel cumulé
function _renderBailleurCard(ent, isArchivedTab) {
  // v14.47 audit tombstones — filter _isAlive d'abord
  // v14.54 BUG-BIENS-TABS-FILTER : compte les biens archivés si on est en vue
  // "Biens archivés", sinon les actifs. Cohérent avec le tab actif au niveau page.
  const myLogs   = (DB.logements||[]).filter(_isAlive).filter(l =>
    l.entity === ent.nom && (isArchivedTab ? !!l.archived : !l.archived)
  );
  const nbImms   = (ent.immeubles||[]).filter(_isAlive).length;
  const nbLogs   = myLogs.length;
  const occupes  = myLogs.filter(l => _bienIsBailActif(l.ref)).length;
  const ratioPct = nbLogs ? Math.round(occupes / nbLogs * 100) : 0;
  const fillCls  = nbLogs === 0 || occupes === 0 ? 'empty' : (occupes < nbLogs ? 'partial' : '');
  const loyerHC  = myLogs.filter(l => _bienIsBailActif(l.ref)).reduce((s,l) => s + (+l.hc || 0), 0);
  const idEsc    = +ent.id || 0;
  const onClick  = `openEntFiche(${idEsc})`;
  const occupTxt = nbLogs ? `${occupes}/${nbLogs} ${nbLogs>1?'logements loués':'logement loué'}` : 'Aucun logement';
  const subtitle = ent.siren ? `SIREN ${escHtml(ent.siren)}` : (ent.gerant ? `Gérant : ${escHtml(ent.gerant)}` : '');
  // MOBILE-REFONTE lot 4b — carte bailleur compacte sur téléphone.
  if (_isPhone()) {
    _ensureBiencPhCss();
    const occLbl = nbLogs ? `${occupes}/${nbLogs} loué${occupes>1?'s':''}` : 'Aucun bien';
    const metaBits = [`${nbImms} immeuble${nbImms>1?'s':''}`, `${nbLogs} bien${nbLogs>1?'s':''}`].map(escHtml).join(' · ');
    return `<article class="bienc-ph" tabindex="0" onclick="${onClick}" onkeydown="if(event.key==='Enter'||event.key===' '){${onClick};event.preventDefault()}">`
      +`<div class="bienc-thumb${ent.logo?' logo':''}">${ent.logo ? `<img src="${escHtml(ent.logo)}" alt="">` : '<span>' + _uiIcon('building',26) + '</span>'}<span class="bienc-badge vac">${escHtml(occLbl)}</span></div>`
      +`<div class="bienc-mid"><div class="bienc-ref">${escHtml(ent.nom||'—')}</div>${subtitle?`<div class="bienc-ten">${subtitle}</div>`:''}`
      +`<div class="bienc-r3"><span class="bienc-meta">${metaBits}</span><span class="bienc-rent">${fmt(loyerHC)}<small> HC</small></span></div></div>`
      +`<span class="bienc-chev" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg></span>`
      +`</article>`;
  }
  return `<article class="bien-card" tabindex="0" onclick="${onClick}" onkeydown="if(event.key==='Enter'||event.key===' '){${onClick};event.preventDefault()}">
    <div class="bien-card-header">
      <span class="bch-bailleur" title="${escHtml(ent.type||'Bailleur')}">${escHtml(ent.type||'Bailleur')}</span>
      <button class="bien-card-menu" onclick="event.stopPropagation();openBailleurMenu(event,${idEsc})" aria-label="Actions">⋮</button>
    </div>
    <div class="bien-card-img">
      ${ent.logo ? `<img src="${escHtml(ent.logo)}" alt="" style="max-width:65%;max-height:75%;object-fit:contain">` : '<span aria-hidden="true">' + _uiIcon('building',36) + '</span>'}
      <div class="bien-card-occup">
        <span class="bien-card-occup-label">${occupTxt}</span>
        <span class="bien-card-occup-bar"><span class="bien-card-occup-fill ${fillCls}" style="width:${ratioPct}%"></span></span>
      </div>
    </div>
    <div class="bien-card-body">
      <div class="bien-card-title" title="${escHtml(ent.nom||'—')}">${escHtml(ent.nom||'—')}</div>
      ${subtitle ? `<div class="bien-card-subtitle">${subtitle}</div>` : ''}
      <div class="bien-card-meta">
        <span class="bien-card-badge">${nbImms} ${nbImms>1?'immeubles':'immeuble'}</span>
        <span>${nbLogs} ${nbLogs>1?'biens':'bien'}</span>
      </div>
      <div class="bien-card-period">${ent.siege ? escHtml(ent.siege) : '—'}</div>
      <div class="bien-card-rent">
        <span>${fmt(loyerHC)}<small> /mois HC</small></span>
      </div>
    </div>
  </article>`;
}

// v14.8 ENT-FICHE-360 Phase 1 — vue dédiée d'un bailleur (entité juridique).
// Symétrique d'IMM-FICHE-360, complète la chaîne hub : Bailleur > Immeuble > Logement.
let _currentEntFiche = null; // entId

function openEntFiche(entId) {
  if(!entId) return;
  _currentEntFiche = +entId;
  go('ent-fiche', null);
  try {
    const target = `#ent-fiche-${+entId}`;
    if(location.hash !== target) history.pushState(null, '', target);
  } catch(e){}
  // Titre topbar dynamique avec le nom du bailleur
  const ent = (DB.entites||[]).find(e => +e.id === +entId);
  if(ent) {
    const tb = el('tb-title');
    if(tb) tb.textContent = ent.nom || 'Bailleur';
  }
}

function closeEntFiche() {
  _currentEntFiche = null;
  // Retour à Biens en mode bailleurs (cohérent avec le drill : on est venu de cette vue)
  _biensViewMode = 'bailleurs';
  try { localStorage.setItem(_lsKey('immotrack_biens_view'), 'bailleurs'); } catch(e){}
  const navBiens = document.querySelector('.ni[data-tip*="Biens"]');
  go('biens', navBiens || null);
  // v15.408 NAV-HISTORY-BACK — plus de pushState hashless ici : go() pose désormais lui-même
  // le hash de la page cible (#p-biens…), l'entrée vide ne créait qu'un « retour mort ».
}

// v14.74 REPORTING-BAILLEUR — état du sous-onglet de la fiche bailleur
let _currentEntFicheTab = 'immeubles';
let _entFicheComptaYear = new Date().getFullYear();
function setEntFicheTab(t) {
  // BIENS étape 10 — 3 onglets (+2 grisés) → 1. REDIRECTIONS de compat plutôt qu'un retrait sec :
  //   'documents' → l'onglet est devenu la pastille « Documents » de l'entête (on la déplie) ;
  //   'compta'    → la comptabilité globale du bailleur est SUPPRIMÉE (décision 2 du 11/08 : le
  //                 P&L de Finances suffit) — on retombe sur l'unique onglet.
  if(t === 'documents') { _fichePastilles['ent:' + (+_currentEntFiche || '')] = 'docs'; t = 'immeubles'; }
  if(t === 'compta') t = 'immeubles';
  if(t !== 'immeubles') return;
  _currentEntFicheTab = t;
  rEntFiche();
}
/** Options d'années de la déclaration 2044 (l'exercice courant et les 4 précédents).
 *  Extrait du panneau de comptabilité globale supprimé — le Wizard 2044 en a toujours besoin. */
function _ent2044YearOptions() {
  const courante = new Date().getFullYear();
  const active = _entFicheComptaYear || courante;
  let out = '';
  for (let y = courante; y >= courante - 4; y--) {
    out += '<option value="' + y + '"' + (y === active ? ' selected' : '') + '>' + y + '</option>';
  }
  return out;
}

function setEntFicheComptaYear(y) {
  _entFicheComptaYear = parseInt(y) || new Date().getFullYear();
  rEntFiche();
}

function rEntFiche() {
  const wrap = el('ent-fiche-content'); if(!wrap) return;
  try{ if(_isPhone()) _ensureLogFichePhCss(); }catch(e){}   // MOBILE-REFONTE — compaction fiche bailleur sur téléphone
  if(!_currentEntFiche) { wrap.innerHTML = '<p class="mu">Aucun bailleur sélectionné.</p>'; return; }
  const ent = (DB.entites||[]).find(e => +e.id === _currentEntFiche);
  if(!ent) {
    wrap.innerHTML = `<div class="biens-empty">
      <div class="biens-empty-icon">${_uiIcon('warn',44)}</div>
      <div class="biens-empty-title">Bailleur introuvable</div>
      <div class="biens-empty-msg">Le bailleur demandé n'existe pas ou a été supprimé.</div>
      <button class="btn bs" onclick="closeEntFiche()">← Retour aux biens</button>
    </div>`;
    return;
  }
  // Aggrégats — v14.47 audit tombstones
  const myLogs    = (DB.logements||[]).filter(_isAlive).filter(l => l.entity === ent.nom);
  const activeLogs = myLogs.filter(l => !l.archived);
  const archivedLogs = myLogs.filter(l => l.archived);
  const nbImms    = (ent.immeubles||[]).filter(_isAlive).length;
  const nbLogs    = activeLogs.length;
  const occupes   = activeLogs.filter(l => _bienIsBailActif(l.ref)).length;
  const vacance   = nbLogs - occupes;
  const vacancePct = nbLogs ? Math.round(vacance/nbLogs*100) : 0;
  const loyerHC   = activeLogs.filter(l => _bienIsBailActif(l.ref)).reduce((s,l)=>s+(+l.hc||0), 0);
  const occupCls  = nbLogs && occupes === nbLogs ? 'k-ok' : (vacance > 0 && nbLogs ? 'k-warn' : '');
  const entNomEsc = escHtml(ent.nom||'—');
  // Logo entité ou icône fallback
  const heroVisual = ent.logo
    ? `<img src="${escHtml(ent.logo)}" alt="" style="max-width:75%;max-height:75%;object-fit:contain;background:#fff;border-radius:6px;padding:8px">`
    : `<span aria-hidden="true">${_uiIcon('building',36)}</span>`;

  wrap.innerHTML = `
    <button class="logf-back" onclick="closeEntFiche()">← Aux biens</button>
    <div class="logf-breadcrumb">
      <a onclick="_goToBiensRoot();return false">Biens</a>
      <span class="sep">›</span>
      <span>${entNomEsc}</span>
    </div>
    <!-- v14.34 — hero compact 3 colonnes (option C) : image | info+stats+actions | donut compact.
         Plus de bande KPI séparée : tout intégré dans la bulle hero. Hauteur ~210px (vs ~380px). -->
    <div class="logf-hero entf-hero-compact">
      <div class="logf-photos entf-photos-mini" aria-hidden="true">${heroVisual}</div>
      <div class="logf-info">
        <h1 class="logf-title">${entNomEsc}</h1>
        ${ent.type?`<div class="logf-adr">${escHtml(ent.type)}${ent.siege?' · '+escHtml(ent.siege):''}</div>`:(ent.siege?`<div class="logf-adr">${escHtml(ent.siege)}</div>`:'')}
        <div class="logf-badges">
          ${ent.siren?`<span class="logf-badge">SIREN ${escHtml(ent.siren)}</span>`:''}
          ${ent.rcs?`<span class="logf-badge b-mute">${escHtml(ent.rcs)}</span>`:''}
          ${ent.gerant?`<span class="logf-badge b-mute">Gérant : ${escHtml(ent.gerant)}</span>`:''}
        </div>
        <div class="logf-hero-stats logf-hero-stats-4">
          <div class="logf-stat"><div class="logf-stat-v k-num">${nbImms}</div><div class="logf-stat-l">Immeuble${nbImms>1?'s':''}</div></div>
          <div class="logf-stat"><div class="logf-stat-v k-num">${nbLogs}</div><div class="logf-stat-l">Logement${nbLogs>1?'s':''}</div></div>
          <div class="logf-stat"><div class="logf-stat-v k-num ${occupCls}">${occupes}<small>/${nbLogs}</small></div><div class="logf-stat-l">Loué${occupes>1?'s':''}</div></div>
          <div class="logf-stat"><div class="logf-stat-v k-money">${fmt(loyerHC)}</div><div class="logf-stat-l">Loyer HC /mois</div></div>
        </div>
        <div class="logf-actions">
          <button class="btn bp" onclick="_frStartCtx('imm', ${+ent.id})">${_uiIcon('plus',15)} Ajouter un bien</button>
          <button class="btn bs" onclick="openNewEnt(${+ent.id})">${_uiIcon('edit')} Modifier le bailleur</button>
          <!-- BIENS étape 10 — le Wizard 2044 est REMIS ICI. La comptabilité globale du bailleur a
               été supprimée (le P&L de Finances suffit), mais elle hébergeait le SEUL appel de
               openWizard2044 — et avec lui _renderWizard2044, ses 4 étapes, le mapping éditable et
               _print2044, UNIQUE chemin d'impression du CERFA 2044. Finances sort un CSV, pas le
               formulaire imprimable : ce n'était pas remplaçable. Son sélecteur d'année vient avec. -->
          <span class="flex-c" style="gap:6px;align-items:center">
            <button class="btn bs" onclick="openWizard2044(${+ent.id})" title="Préparer et imprimer la déclaration CERFA 2044 (revenus fonciers) de ce bailleur">${_uiIcon('doc-text')} Déclaration 2044</button>
            <select class="inp" onchange="setEntFicheComptaYear(this.value)" style="width:92px;padding:4px 8px" title="Année de la déclaration" aria-label="Année de la déclaration 2044">${_ent2044YearOptions()}</select>
          </span>
          <button class="btn br" onclick="delEnt(${+ent.id})">${_uiIcon('trash')} Supprimer</button>
        </div>
      </div>
      <div class="entf-donut-compact">
        ${_renderOccupationDonut(occupes, nbLogs, 96)}
        <div class="entf-donut-cap">Occupation</div>
      </div>
    </div>
    ${/* BIENS étape 10 — l'entête absorbe le complément d'identité (IBAN/BIC, e-mail d'envoi, signature, logo, co-gérants) et les DOCUMENTS JURIDIQUES (ex-onglet). Une ligne de 34 px au lieu de panneaux dépliés : les bulles Immeubles restent visibles sans scroller. */''}
    ${_renderFichePastilles('ent:' + (+ent.id), [
      { id: 'identite', label: 'Coordonnées & identité juridique', html: _renderEntIdentitePastille(ent) },
      { id: 'docs', label: 'Documents', count: _attCount('entite', ent.id, 'documents'),
        html: _renderAttachmentSection({parentType:'entite', parentId:ent.id, parentRef:ent.nom, category:'documents', title:'' + _uiIcon('doc') + ' Documents juridiques', emptyText:'Aucun document. Ajouter K-bis, statuts SCI, RIB, mandats, attestations…'}) }
    ], 'rEntFiche')}
    <!-- PC-REFONTE — un ruban d'onglets à 1 seul item = bruit inutile → simple titre de section. -->
    <div class="ct" style="display:flex;align-items:center;gap:8px;margin:0 0 4px;padding-bottom:8px;border-bottom:1px solid var(--bor)">${_uiIcon('building',18)} Immeubles (${nbImms})</div>
    ${`
        <div class="flex-b" style="margin:14px 0 10px">
          <span class="mu sm">${nbImms} immeuble${nbImms>1?'s':''} pour ce bailleur</span>
          ${/* BIENS (P1-13, retours user 11/08 : « pourquoi 2 boutons : Ajouter un bien et + Immeuble ? bien = logement ou immeuble ? ») — « + Immeuble » retiré d'ici : le fil rouge est déjà la porte unique et démarre à la bonne étape (＋ Ajouter un bien, dans l'entête). addImmForm reste appelé depuis l'ÉTAT VIDE ci-dessous, seul endroit où la création directe a du sens. */''}
        </div>
        ${nbImms
          ? _renderEntFicheImmeubles(ent)
          : `<div class="biens-empty">
              <div class="biens-empty-icon">${_uiIcon('building',44)}</div>
              <div class="biens-empty-title">Ce bailleur n'a pas encore d'immeuble</div>
              <div class="biens-empty-msg">Ajouter le premier immeuble pour commencer le suivi.</div>
              <button class="btn bp" onclick="addImmForm(${+ent.id})">+ Ajouter un immeuble</button>
            </div>`
        }
        ${archivedLogs.length ? `<div class="mu sm" style="margin-top:18px;text-align:center">${_uiIcon('archive')} ${archivedLogs.length} logement${archivedLogs.length>1?'s':''} archivé${archivedLogs.length>1?'s':''} chez ce bailleur — visible${archivedLogs.length>1?'s':''} dans Biens > tab "Archivés"</div>` : ''}
      `}
  `;
}

// Grille des immeubles d'un bailleur — réutilise _renderBuildingCard (homogénéité visuelle).
// Logements orphelins (sans imm) du bailleur = 1 carte virtuelle "Logements isolés".
function _renderEntFicheImmeubles(ent) {
  // v14.47 audit tombstones
  const allLogs = (DB.logements||[]).filter(_isAlive).filter(l => l.entity === ent.nom && !l.archived);
  const imms = (ent.immeubles||[]).filter(_isAlive).slice().sort((a,b)=>_natCmp(a.nom, b.nom));
  const cards = [];
  imms.forEach(im => {
    const logs = allLogs.filter(l => l.imm === im.nom);
    cards.push(_renderBuildingCard(ent.nom, im.nom, logs, ent, false));
  });
  // Orphelins : logements sans imm (ou imm qui n'existe pas dans ent.immeubles)
  const orphans = allLogs.filter(l => !l.imm || !imms.some(i=>i.nom===l.imm));
  if(orphans.length) cards.push(_renderBuildingCard(ent.nom, '', orphans, ent, false));
  return `<div class="biens-grid">${cards.join('')}</div>`;
}

// ════════════════════════════════════════════════════════════════════════════
// v14.74 REPORTING-BAILLEUR — Panel "Comptabilité globale" sur la fiche bailleur
// Vue agrégée tous logements/immeubles : KPIs annuels + tableau mensuel 12 mois
// + sparkline encaissé/dépensé + export CSV annuel/mensuel + part bailleur 2044
// ════════════════════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════════════════════
// v14.75 LEGAL-2044 — Wizard déclaration revenus fonciers (formulaire CERFA 2044)
// Mapping catégories Propryo → lignes du CERFA, calcul résultat foncier, PDF récap.
// ⚠ Valeurs indicatives à confirmer avec un expert-comptable / centre des impôts.
// Mapping ajustable par l'utilisateur et persisté dans DB.params.legal2044Mapping.
// ════════════════════════════════════════════════════════════════════════════

// Lignes du CERFA 2044 (régime réel revenus fonciers — version simplifiée).
// Chaque ligne a : numéro, libellé, type ('recette' / 'charge' / 'interet' / 'special'),
// description (tooltip), et une cible par défaut depuis les catégories Propryo standard.
// v14.78 — Lignes du CERFA 2044 alignées sur la notice officielle (revenus 2024,
// publication mars 2025 - DGFP). Source : impots.gouv.fr formulaire 2044 + notice 2044_5135.
// Erreurs corrigées par rapport à v14.75 : 225/226/227/228 étaient mal libellés.
const LIGNES_2044 = [
  // === RECETTES (Cadre IV — total ligne 215) ============================
  { num: '211', libelle: 'Loyers ou fermages bruts encaissés', type: 'recette',
    desc: 'Loyers, fermages, arriérés, loyers d\'avance + recettes exceptionnelles (pas de porte, droit d\'entrée, indemnité d\'expropriation pour perte de loyer).' },
  { num: '212', libelle: 'Dépenses mises par convention à la charge des locataires', type: 'recette',
    desc: 'Dépenses incombant au bailleur mais payées par le locataire en application du bail (grosses réparations, taxe foncière, prime incendie). Cas rare.' },
  { num: '213', libelle: 'Recettes brutes diverses', type: 'recette',
    desc: 'Indemnités GLI (« contrats dits de garantie de loyers »), subventions ANAH, indemnités assurance sinistre destinées à charges déductibles, location toits antennes mobiles, panneaux pub, droit chasse/pêche, dépôts de garantie utilisés.' },
  { num: '214', libelle: 'Valeur locative réelle des propriétés dont vous vous réservez la jouissance', type: 'recette',
    desc: 'Locaux commerciaux nus mis gratuitement à disposition + étangs/lacs/terrains. NB : habitation perso non imposable (charges non déductibles).' },
  { num: '215', libelle: 'TOTAL des recettes', type: 'total',
    desc: 'Calcul automatique = 211 + 212 + 213 + 214.' },
  // === FRAIS ET CHARGES (Cadre V — total ligne 240) =====================
  { num: '221', libelle: 'Frais d\'administration et de gestion', type: 'charge',
    desc: 'Rémunérations gardes/concierges, honoraires gérants/agences/comptables, frais de procédure (avocat, huissier, notaire, expert), cotisations chambres syndicales bailleurs.' },
  { num: '222', libelle: 'Autres frais de gestion (forfait 20 € par local)', type: 'charge',
    desc: 'Forfait LÉGAL automatique de 20 €/local (correspondance, déplacement, téléphone, mobilier de bureau, enregistrement baux). Pas de saisie utilisateur — calculé sur le nombre de logements.' },
  { num: '223', libelle: 'Primes d\'assurance', type: 'charge',
    desc: 'Toutes primes : incendie, dégâts des eaux, bris glace, tempête, vol, catastrophe naturelle, RC bailleur, PNO, GLI cotisation. Exclus : récoltes, bétail, mobilier.' },
  { num: '224', libelle: 'Dépenses de réparation, d\'entretien ou d\'amélioration', type: 'charge',
    desc: 'Réparation/entretien (maintien en état) + amélioration (équipement moderne sans modifier structure). EXCLUS : construction, reconstruction, agrandissement.' },
  { num: '224bis', libelle: 'Dépenses de travaux de rénovation énergétique', type: 'charge',
    desc: 'Logement E/F/G → A/B/C/D. Devis post 5/11/2022, paiement 1/1/2023→31/12/2025. Plafond déficit rehaussé à 21 400 €. ⚠ Si mis en 224bis, ne PAS remettre en 224.' },
  { num: '225', libelle: 'Charges récupérables non récupérées au départ du locataire', type: 'charge',
    desc: 'Charges du locataire payées par le bailleur, non remboursées au 31/12 de l\'année du départ. Inclut la part bailleur des charges communes en cas de vacance ou logements exclus du compteur.' },
  { num: '226', libelle: 'Indemnités d\'éviction, frais de relogement', type: 'charge',
    desc: 'Indemnité d\'éviction pour relouer dans meilleures conditions + frais relogement pendant travaux. EXCLUS : reprise pour usage perso, revente, démolition.' },
  { num: '227', libelle: 'Taxes foncières et taxes annexes', type: 'charge',
    desc: 'TF + taxes annexes (équipement). EXCLUS : taxe d\'enlèvement OM (incombe locataire) ; taxe annuelle locaux bureaux Île-de-France.' },
  { num: '228', libelle: 'Déductions spécifiques (Borloo ancien, Cosse, carrières)', type: 'charge',
    desc: 'Régimes de défiscalisation : Borloo ancien (30/45/60/70 %), Cosse (15/30/50/70/85 %), Carrières (40 %). Cumulables avec frais réels.' },
  { num: '229', libelle: 'Provisions pour charges de copropriété', type: 'charge',
    desc: 'Total des provisions versées au syndic en N. EXCLUS : provisions spéciales pour travaux non encore décidés (art. 18 loi 65-557).' },
  { num: '230', libelle: 'Régularisation des provisions pour charges déduites au titre de N-1', type: 'deduction',
    desc: 'Réintégration : charges non déductibles + charges récupérables locataires + solde positif provisions. Si solde négatif → ligne 229.' },
  { num: '240', libelle: 'TOTAL des frais et charges', type: 'total',
    desc: 'Calcul automatique = (221 à 229) − 230.' },
  // === INTÉRÊTS D'EMPRUNT ===============================================
  { num: '250', libelle: 'Intérêts d\'emprunt et frais accessoires', type: 'interet',
    desc: 'Intérêts + frais (constitution dossier, hypothèque, cautionnement, main levée, agios, primes assurance-vie/décès garantissant le prêt). Capital EXCLU.' }
];

// v14.78 — Mapping par défaut vers les lignes 2044.
// Pour les catégories STANDARD (STD_CATEGORIES) : lookup direct via std.ligne2044 (figé).
// Pour les catégories CUSTOM utilisateur : regex de fallback (l'utilisateur affine ensuite via le wizard).
// Format : { 'NomCategorie': '225' } (numéro de ligne 2044, ou '224bis', ou '' si non mappé)
function _default2044Mapping() {
  const m = {};
  (DB.categories||[]).forEach(c => {
    // 1) Cherche d'abord dans STD_CATEGORIES (mapping figé sourcé notice officielle)
    const std = _stdCategoryByName(c);
    if(std) { m[c] = std.ligne2044 || ''; return; }
    // 2) Fallback regex pour les catégories custom utilisateur
    const k = c.toLowerCase();
    if(/loyer/.test(k))                                 m[c] = '211';
    else if(_finEstNomAssurancePret(k))             m[c] = '250';   // 15/10 : assurance de prêt (famille fixée par _finMigrateAssuranceEmprunteur)
    else if(/pr[êe]t|emprunt|int[ée]r[êe]t/.test(k))    m[c] = '250';
    else if(/r[ée]nov.*[ée]nerg|[ée]nerg.*r[ée]nov/.test(k)) m[c] = '224bis';
    else if(/assurance/.test(k))                        m[c] = '223';
    else if(/trav|r[ée]no|r[ée]par/.test(k))            m[c] = '224';
    else if(/taxe.*fonci[èe]re|tf\b/.test(k))           m[c] = '227';
    else if(/charge.*commune|charge.*r[ée]cup|r[ée]cup/.test(k)) m[c] = '225';
    else if(/charge/.test(k))                           m[c] = '225';
    else if(/gli|loyers?\s*impay/.test(k))              m[c] = '213';
    else if(/anah|subvention/.test(k))                  m[c] = '213';
    else if(/[ée]viction|relogement/.test(k))           m[c] = '226';
    else if(/copropri|provision/.test(k))               m[c] = '229';
    else if(/r[ée]gul.*N-?1|r[ée]gul.*provision/.test(k)) m[c] = '230';
    else if(/borloo|cosse|carri[èe]re/.test(k))         m[c] = '228';
    else                                                m[c] = ''; // non mappé → user décide
  });
  return m;
}

// Récupère le mapping persisté (et complète avec les défauts si nouvelles catégories)
function _get2044Mapping() {
  if(!DB.params) DB.params = {};
  if(!DB.params.legal2044Mapping || typeof DB.params.legal2044Mapping !== 'object') {
    DB.params.legal2044Mapping = _default2044Mapping();
  }
  // Compléter avec les nouvelles cat sans écraser les choix user
  const def = _default2044Mapping();
  Object.keys(def).forEach(k => {
    if(!(k in DB.params.legal2044Mapping)) DB.params.legal2044Mapping[k] = def[k];
  });
  return DB.params.legal2044Mapping;
}

// === MOTEUR 2044 UNIFIÉ (Chantier A Phase 2 — V3-REFONTE-LOYERS) ===
// L'ancien _compute2044 INLINE (moteur séparé) a été SUPPRIMÉ : le moteur unique est
// désormais js/core/legal-2044.js (window._compute2044). Motif : 2 moteurs divergents +
// collision de noms (l'inline hoisté créait window._compute2044, écrasé par le module →
// le wizard plantait). Les 2 fonctions ci-dessous adaptent le moteur module aux besoins
// du wizard PDF : options scopées par entité, puis reshape vers la forme `byLine` que
// consomment le rendu (step 3) et _print2044.

// Options 2044 pour le wizard PDF (entité objet + année). Mirror de _legal2044BuildOpts
// (panneau) mais scopé sur un ent précis, + mapping custom + detail pour le PDF.
function _legal2044WizardOpts(ent, year) {
  const yr = parseInt(year);
  const from = `${yr}-01-01`, to = `${yr}-12-31`;
  const entityNom = ent.nom;
  const aliveLogs = (DB.logements||[]).filter(l => _isAlive(l) && !l.archived && l.entity === entityNom);
  // FEAT-REGIMES P0 : exclure les lots meublés (BIC) du périmètre foncier 2044 (cf builder panneau).
  const _split = (typeof window.splitFonciereLots === 'function')
    ? window.splitFonciereLots(aliveLogs, { baux: DB.baux || {}, bauxHisto: DB.baux_historique || [], year: yr, finOccupation: _bailFinOccupation })
    : { fonciereRefs: aliveLogs.map(l => l.ref), exclus: [], flagues: [] };
  const refs = _split.fonciereRefs;
  const nbLocaux = refs.length;
  const imms = (ent.immeubles||[]).filter(_isAlive).map(i => i.nom);
  // Ligne 225 : lecteur unique _rgSegments225 (immeubles de l'entité, périmètre foncier, hors 229…).
  let partBailleur225 = 0;
  try {
    if (typeof computeRegul === 'function') partBailleur225 = _rgSegments225(computeRegul(from, to), imms, refs).total;
  } catch (e) { console.warn('[_legal2044WizardOpts] partBailleur', e); }
  // Mapping custom : on ne passe QUE les catégories non-STD (le module fige les STD).
  const fullMap = _get2044Mapping();
  const mapping = {};
  Object.keys(fullMap).forEach(cat => { if (!_isStdCategory(cat) && fullMap[cat]) mapping[cat] = fullMap[cat]; });
  return { yr: String(yr), from, to, entityNom, refs, imms, nbLocaux, partBailleur225, mapping, detail: true, exclus: _split.exclus, flagues: _split.flagues };
}

// Adaptateur : appelle le MOTEUR UNIQUE (module) et reshape sa sortie vers la forme
// historique { byLine, totaux, resultat, deficitDeductible, mapping, mvtsCount } que
// consomment le rendu wizard (step 3) et _print2044. Remplace l'ancien _compute2044 inline.
function _legal2044WizardData(ent, year) {
  const opts = _legal2044WizardOpts(ent, year);
  const result = window._compute2044(DB.mouvements || [], STD_CATEGORIES, opts);

  // byLine à partir des métadonnées UI (LIGNES_2044) + lignes/mvtsByLigne du moteur.
  const byLine = {};
  LIGNES_2044.forEach(l => {
    byLine[l.num] = {
      num: l.num, libelle: l.libelle, type: l.type,
      total: result.lignes[l.num] || 0,
      mvts: (result.mvtsByLigne && result.mvtsByLigne[l.num]) ? result.mvtsByLigne[l.num].slice() : []
    };
  });
  byLine['___'] = { num: '—', libelle: 'Non mappé (à ajuster dans le wizard)', type: 'unmapped', total: 0, mvts: [] };
  (result.nonMappes || []).forEach(nm => {
    byLine['___'].mvts.push({ id: nm.id, date: nm.date, lib: nm.lib, montant: (nm.db||0)-(nm.cr||0), cat: nm.cat });
    byLine['___'].total += (nm.db||0)-(nm.cr||0);
  });

  // Détail d'affichage des 2 lignes synthétiques (total DÉJÀ compté par le moteur via opts
  // → on n'ajoute ici QUE l'affichage, jamais au total, sinon double-compte).
  if (opts.nbLocaux > 0 && byLine['222']) {
    byLine['222'].mvts.push({ date: opts.from, lib: `Forfait légal 20 € × ${opts.nbLocaux} local${opts.nbLocaux>1?'aux':''}`, montant: opts.nbLocaux * 20, auto: true, motif: 'Notice 2044 § 222' });
  }
  try {
    if (typeof computeRegul === 'function' && opts.partBailleur225) {
      // MÊMES segments que le total injecté (opts.partBailleur225) : lecteur unique _rgSegments225.
      _rgSegments225(computeRegul(opts.from, opts.to), opts.imms, opts.refs).segments.forEach(seg => byLine['225'].mvts.push({
        date: seg.date, lib: seg.lib, montant: seg.montant, auto: true, motif: seg.motif, cc: seg.cc
      }));
    }
  } catch (e) { console.warn('[_legal2044WizardData] partBailleur seg', e); }

  // Totaux selon notice (le moteur fait déjà 240 = (221..229) − 230).
  const recettes215 = result.totalRecettes;
  const charges240 = result.totalCharges;
  const interets250 = result.totalInterets;
  const resultat = result.resultatFoncier;
  const deficitHorsInt = recettes215 - charges240;
  const deficitDeductible = (deficitHorsInt < 0) ? Math.max(deficitHorsInt, -10700) : 0;
  const mvtsCount = (result.mvtsByLigne
    ? Object.values(result.mvtsByLigne).reduce((s, a) => s + a.length, 0)
    : 0) + (result.nonMappes ? result.nonMappes.length : 0);

  return {
    byLine,
    totaux: { recettes215, charges240, interets250, partBailleurInjectee: opts.partBailleur225 },
    resultat, deficitDeductible,
    mapping: opts.mapping, mvtsCount,
    exclus: opts.exclus || [], flagues: opts.flagues || []
  };
}

// Encart « périmètre foncier » : ce que le récap 2044 a écarté (meublé/BIC) ou flagué
// (mixte / usage à qualifier). Affiché dans le wizard ET le PDF — l'utilisateur et son
// comptable doivent VOIR le périmètre (transparence anti-redressement).
// FEAT-REGIMES P0 / audit code-reviewer #3 (symétrie panneau ↔ wizard ↔ PDF).
function _legal2044PerimetreHtml(data, opt) {
  // ecran:true (wizard) → nom d'affichage ; sans option (impression remise à un tiers) → RÉFÉRENCE (règle d'or B3).
  const _nm = (opt && opt.ecran) ? _logLabel : (r => r);
  const ex = (data && data.exclus) || [];
  const fl = (data && data.flagues) || [];
  if (!ex.length && !fl.length) return '';
  let h = '<div style="margin:14px 0;padding:11px 13px;border:1px solid #e0a800;border-radius:8px;background:#fff8e6;font-size:11.5px;color:#7a5a18;line-height:1.55">';
  h += '<b>⚠ Périmètre foncier (2044)</b> — la 2044 ne couvre que la <b>location nue</b>. Ce récap a écarté :';
  if (ex.length) h += `<div style="margin-top:5px">• <b>${ex.length} lot(s) meublé(s) EXCLU(S)</b> — relèvent du BIC/LMNP (déclaration séparée) : ${ex.map(e => escHtml(_nm(e.ref))).join(', ')}</div>`;
  if (fl.length) h += `<div style="margin-top:4px">• <b>${fl.length} lot(s) à VÉRIFIER</b> (mixte nu+meublé, ou usage à qualifier) : ${fl.map(f => escHtml(_nm(f.ref))).join(', ')}</div>`;
  if (ex.length) h += '<div style="margin-top:6px;color:#9a7b2a">Note : les charges d\'immeuble (taxe foncière, assurance PNO, syndic) restent comptées à 100 % au foncier même si l\'immeuble comporte des lots meublés. Si un immeuble est <b>mixte</b>, la quote-part meublée est à retirer (ventilation à venir).</div>';
  h += '</div>';
  return h;
}

// === WIZARD UI ===
let _wiz2044 = { step: 1, entId: null, year: null, mappingDraft: null };

function openWizard2044(entId) {
  _wiz2044 = {
    step: 1,
    entId: +entId,
    year: _entFicheComptaYear || new Date().getFullYear(),
    mappingDraft: { ..._get2044Mapping() }
  };
  _renderWizard2044();
}

function _renderWizard2044() {
  const ent = (DB.entites||[]).find(e => +e.id === _wiz2044.entId);
  if(!ent) { showToast('Bailleur introuvable','err'); return; }
  const step = _wiz2044.step;
  const titles = ['Bailleur & année', 'Mapping catégories → lignes 2044', 'Récapitulatif', 'Génération PDF'];
  const stepHeader = `<div style="display:flex;gap:6px;margin-bottom:14px">
    ${[1,2,3,4].map(s => `<div style="flex:1;padding:8px 10px;border-radius:6px;background:${s===step?'var(--acc)':'var(--bg2)'};color:${s===step?'#fff':'var(--t2)'};font-size:11px;font-weight:600;text-align:center">
      ${s}. ${escHtml(titles[s-1])}
    </div>`).join('')}
  </div>`;
  let body = '';
  let footerNav = '';

  if(step === 1) {
    body = _renderWiz2044Step1(ent);
    footerNav = `<button class="btn bs" onclick="closeM('ov-wiz-2044')">Annuler</button>
      <button class="btn bp" onclick="_wizard2044Next()">Suivant →</button>`;
  } else if(step === 2) {
    body = _renderWiz2044Step2();
    footerNav = `<button class="btn bs" onclick="_wizard2044Prev()">← Précédent</button>
      <button class="btn bs" onclick="_wizard2044ResetMapping()" title="Restaurer le mapping par défaut">↺ Reset défaut</button>
      <button class="btn bp" onclick="_wizard2044Next()">Suivant →</button>`;
  } else if(step === 3) {
    const data = _legal2044WizardData(ent, _wiz2044.year);
    body = _renderWiz2044Step3(ent, data);
    footerNav = `<button class="btn bs" onclick="_wizard2044Prev()">← Précédent</button>
      <button class="btn bp" onclick="_wizard2044Next()">Générer PDF →</button>`;
  } else {
    const data = _legal2044WizardData(ent, _wiz2044.year);
    body = _renderWiz2044Step4(ent, data);
    footerNav = `<button class="btn bs" onclick="_wizard2044Prev()">← Récap</button>
      <button class="btn bp" onclick="_print2044(${+ent.id},${+_wiz2044.year})">${_uiIcon('printer')} Imprimer / PDF</button>
      <button class="btn bs" onclick="closeM('ov-wiz-2044')">Fermer</button>`;
  }

  const html = `
    <div class="ov" id="ov-wiz-2044" onclick="closeBg(event,'ov-wiz-2044')">
      <div class="modal" style="max-width:920px;max-height:92vh">
        <div class="m-head">
          <h3>${_uiIcon('doc-text')} Wizard 2044 — ${escHtml(ent.nom)} <span class="mu sm">(année ${_wiz2044.year})</span></h3>
          <button class="m-close" onclick="closeM('ov-wiz-2044')">${_uiIcon('close')}</button>
        </div>
        <div class="m-body" style="max-height:75vh;overflow-y:auto">
          ${stepHeader}
          ${body}
        </div>
        <div class="m-foot">${footerNav}</div>
      </div>
    </div>`;
  const old = document.getElementById('ov-wiz-2044');
  if(old) old.remove();
  document.body.insertAdjacentHTML('beforeend', html);
  openM('ov-wiz-2044');
}

function _wizard2044Next() {
  if(_wiz2044.step === 1) {
    const yr = parseInt((document.getElementById('wiz2044-year')||{}).value || _wiz2044.year);
    if(!yr || yr < 2000 || yr > 2100) { showToast('Année invalide','err'); return; }
    _wiz2044.year = yr;
  }
  if(_wiz2044.step === 2) {
    // v14.78 — Save mapping draft (uniquement les customs, les standards sont figés)
    const sels = document.querySelectorAll('#wiz2044-mapping select.wiz2044-cat-sel');
    sels.forEach(s => { _wiz2044.mappingDraft[s.dataset.cat] = s.value || ''; });
    // Re-injecte les standards dans le draft (au cas où ils auraient été perdus)
    STD_CATEGORIES.forEach(std => { _wiz2044.mappingDraft[std.nom] = std.ligne2044 || ''; });
    DB.params.legal2044Mapping = { ..._wiz2044.mappingDraft };
    saveDB();
  }
  _wiz2044.step++;
  if(_wiz2044.step > 4) _wiz2044.step = 4;
  _renderWizard2044();
}

function _wizard2044Prev() {
  _wiz2044.step--;
  if(_wiz2044.step < 1) _wiz2044.step = 1;
  _renderWizard2044();
}

function _wizard2044ResetMapping() {
  if(!confirm2('Restaurer le mapping par défaut ? Les choix actuels seront écrasés.')) return;
  _wiz2044.mappingDraft = _default2044Mapping();
  _renderWizard2044();
}

function _renderWiz2044Step1(ent) {
  const curYr = new Date().getFullYear();
  const yrs = [curYr, curYr-1, curYr-2, curYr-3];
  const yrOpts = yrs.map(y => `<option value="${y}"${y===_wiz2044.year?' selected':''}>${y}</option>`).join('');
  const activeLogs = (DB.logements||[]).filter(_isAlive).filter(l => l.entity === ent.nom && !l.archived);
  return `
    <div style="padding:10px 0">
      <p>Cette assistance prépare la <b>déclaration des revenus fonciers</b> (CERFA 2044) à partir des mouvements Propryo.</p>
      <div class="fg" style="max-width:200px"><label>Année déclarée *</label>
        <select class="inp" id="wiz2044-year">${yrOpts}</select>
      </div>
      <div style="background:var(--bg2);border:1px solid var(--bor);border-radius:8px;padding:14px 16px;margin-top:14px">
        <b style="font-size:13px;display:block;margin-bottom:6px">Périmètre du bailleur</b>
        <ul style="margin:6px 0;padding-left:20px;font-size:12px;line-height:1.7">
          <li><b>${escHtml(ent.nom)}</b> · ${escHtml(ent.type||'particulier')}</li>
          <li>${(ent.immeubles||[]).filter(_isAlive).length} immeuble${(ent.immeubles||[]).filter(_isAlive).length>1?'s':''} · ${activeLogs.length} logement${activeLogs.length>1?'s':''} actif${activeLogs.length>1?'s':''}</li>
          <li>Mouvements considérés : tout ce qui est rattaché aux logements (qui=ref) ou à la SCI (qui=SCI:${escHtml(ent.nom)}) ou aux immeubles (imm=…)</li>
        </ul>
      </div>
      <div style="background:#fffbf0;border:1px solid #f59e0b44;border-radius:8px;padding:12px 14px;margin-top:14px;font-size:12px">
        <b>⚠ Avertissement</b> — Propryo n'est pas un logiciel comptable agréé. Les valeurs proposées sont <b>indicatives</b>. Vérifier avec le centre des impôts ou un expert-comptable avant de déclarer.
      </div>
    </div>`;
}

function _renderWiz2044Step2() {
  // v14.78 LEGAL-2044 — Sépare les catégories standard (mapping figé, en lecture seule)
  // des catégories custom (mapping ajustable). L'utilisateur ne mappe que ses customs.
  const allCats = [...(DB.categories||[])].sort();
  const stdCats = allCats.filter(c => _isStdCategory(c));
  const customCats = allCats.filter(c => !_isStdCategory(c));
  // Pour les selects, on n'inclut que les lignes saisissables (pas 215 et 240 qui sont des totaux)
  const saisissables = LIGNES_2044.filter(l => l.type !== 'total');
  const lineOpts = ['<option value="">— Non déclaré —</option>'].concat(
    saisissables.map(l => `<option value="${l.num}">${l.num} · ${escHtml(l.libelle)}</option>`)
  ).join('');

  // Tableau des standards : lecture seule, libellé + ligne 2044 + icône
  const stdRows = stdCats.map(c => {
    const std = _stdCategoryByName(c);
    const lineLabel = std.ligne2044
      ? `<b>${escHtml(std.ligne2044)}</b> — ${escHtml((LIGNES_2044.find(l=>l.num===std.ligne2044)||{}).libelle || '')}`
      : `<i style="color:var(--t3)">— hors résultat foncier (informatif) —</i>`;
    return `<tr>
      <td>${_catIconHTML(c)} <b>${escHtml(c)}</b></td>
      <td>${lineLabel}</td>
    </tr>`;
  }).join('');

  // Tableau des customs : éditables avec select
  const customRows = customCats.map(c => {
    const cur = _wiz2044.mappingDraft[c] || '';
    const opts = cur ? lineOpts.replace(`value="${cur}"`, `value="${cur}" selected`) : lineOpts;
    return `<tr>
      <td><b>${escHtml(c)}</b></td>
      <td><select class="inp wiz2044-cat-sel" data-cat="${escHtml(c).replace(/'/g,"\\'")}" style="width:100%;padding:4px 6px;font-size:12px">
        ${opts}
      </select></td>
    </tr>`;
  }).join('');

  return `
    <p>Les <b>catégories standard</b> sont mappées automatiquement (sourcées notice CERFA 2044 - DGFP). Seules les <b>catégories personnalisées</b> sont à mapper.</p>
    <p class="mu sm" style="font-size:11px">${_uiIcon('bulb',13)} Le mapping est mémorisé (DB.params.legal2044Mapping) — inutile de le refaire chaque année.</p>

    <details style="margin:14px 0" ${stdCats.length<8?'open':''}>
      <summary style="cursor:pointer;padding:6px 10px;background:#3b82f622;border:1px solid #3b82f644;border-radius:6px;font-size:12px"><b>${_uiIcon('lock')} Mapping standard (${stdCats.length} catégories pré-câblées)</b></summary>
      <table class="tbl" style="font-size:12px;margin-top:10px">
        <thead><tr><th>Catégorie</th><th>Ligne CERFA 2044</th></tr></thead>
        <tbody>${stdRows || '<tr><td colspan="2" class="mu sm" style="text-align:center;padding:14px">Aucune (état impossible — STD_CATEGORIES devrait toujours être présent)</td></tr>'}</tbody>
      </table>
    </details>

    <div style="margin-top:14px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;padding-bottom:6px;border-bottom:1px solid var(--bor)">
        <span style="font-size:14px">${_uiIcon('edit')}</span>
        <b style="font-size:13px">Mapping des catégories personnalisées <span class="mu sm" style="font-weight:400">(${customCats.length})</span></b>
      </div>
      ${customCats.length
        ? `<table class="tbl" id="wiz2044-mapping" style="font-size:12px">
            <thead><tr><th>Catégorie Propryo</th><th>Ligne 2044 à choisir</th></tr></thead>
            <tbody>${customRows}</tbody>
          </table>`
        : '<p class="mu sm" style="font-style:italic;text-align:center;padding:14px;background:var(--bg2);border-radius:6px">Aucune catégorie personnalisée. Création possible dans Paramètres → Catégories.</p>'}
    </div>

    <details style="margin-top:14px">
      <summary style="cursor:pointer;padding:6px 10px;background:var(--bg2);border-radius:6px;font-size:12px"><b>${_uiIcon('doc-text')} Aide-mémoire des lignes 2044 (notice CERFA officielle)</b></summary>
      <div style="padding:10px 4px;font-size:11px;line-height:1.7">
        ${LIGNES_2044.map(l => `<div style="padding:4px 0;border-bottom:1px solid var(--bor)"><b>${l.num}</b> — ${escHtml(l.libelle)}<br><span class="mu sm">${escHtml(l.desc)}</span></div>`).join('')}
      </div>
    </details>`;
}

function _renderWiz2044Step3(ent, data) {
  const t = data.totaux;
  const resultatCls = data.resultat >= 0 ? 'pos' : 'neg';
  const recettesRows = LIGNES_2044.filter(l => l.type==='recette').map(l => {
    const v = data.byLine[l.num];
    return `<tr><td>${l.num}</td><td>${escHtml(l.libelle)}</td><td class="num">${v.total?fmt(v.total):'—'}</td><td class="mu sm">${v.mvts.length}</td></tr>`;
  }).join('');
  const chargesRows = LIGNES_2044.filter(l => l.type==='charge').map(l => {
    const v = data.byLine[l.num];
    const auto = v.mvts.some(x=>x.auto) ? ` <span style="font-size:9px;background:#3b82f622;color:#1e40af;padding:1px 4px;border-radius:3px">+ part bailleur auto</span>` : '';
    return `<tr><td>${l.num}</td><td>${escHtml(l.libelle)}${auto}</td><td class="num">${v.total?fmt(v.total):'—'}</td><td class="mu sm">${v.mvts.length}</td></tr>`;
  }).join('');
  const intRows = `<tr><td>250</td><td>${escHtml(LIGNES_2044.find(l=>l.num==='250').libelle)}</td><td class="num">${data.byLine['250'].total?fmt(data.byLine['250'].total):'—'}</td><td class="mu sm">${data.byLine['250'].mvts.length}</td></tr>`;
  const unmapped = data.byLine['___'];
  const unmappedHtml = unmapped.mvts.length
    ? `<div style="background:#fffbf0;border:1px solid #f59e0b44;border-radius:8px;padding:12px 14px;margin-top:14px">
        <b style="font-size:12px">${_uiIcon('warn')} ${unmapped.mvts.length} mouvement${unmapped.mvts.length>1?'s':''} sans ligne 2044 (${fmt(unmapped.total)})</b>
        <p class="mu sm" style="font-size:11px;margin:6px 0">Retourner à l'étape 2 pour les mapper.</p>
      </div>` : '';
  return `
    ${_legal2044PerimetreHtml(data, { ecran: true })}
    <div class="kpis" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-bottom:14px">
      <div class="kpi"><div class="kv pos">${fmt(t.recettes215)}</div><div class="kl">Recettes (l. 215)</div></div>
      <div class="kpi"><div class="kv neg">${fmt(t.charges240)}</div><div class="kl">Charges (l. 240)</div></div>
      <div class="kpi"><div class="kv neg">${fmt(t.interets250)}</div><div class="kl">Intérêts (l. 250)</div></div>
      <div class="kpi"><div class="kv ${resultatCls}"><b>${data.resultat>=0?'+':''}${fmt(data.resultat)}</b></div><div class="kl">${data.resultat>=0?'Bénéfice':'Déficit'} foncier</div></div>
    </div>
    ${data.deficitDeductible < 0 ? `<div style="background:#fffbf0;border:1px solid #f59e0b44;border-radius:8px;padding:12px 14px;margin-bottom:14px;font-size:12px">
      <b>${_uiIcon('bulb')} Déficit foncier déductible du revenu global</b> : ${fmt(Math.abs(data.deficitDeductible))} (plafonné à 10 700 €/an, hors intérêts).
      L'excédent éventuel s'impute sur les revenus fonciers des 10 années suivantes.
    </div>`:''}
    ${t.partBailleurInjectee>0 ? `<div style="background:#eff6ff;border:1px solid #3b82f644;border-radius:8px;padding:10px 12px;margin-bottom:14px;font-size:12px">
      ${_uiIcon('building')} <b>Part bailleur auto-injectée ligne 225</b> : ${fmt(t.partBailleurInjectee)} (charges de vacances + logements exclus, calculé par computeRegul).
    </div>`:''}
    <h4 style="margin:8px 0 6px;font-size:13px">Recettes brutes</h4>
    <table class="tbl" style="font-size:12px"><thead><tr><th>Ligne</th><th>Libellé</th><th class="num">Montant</th><th>Nb mvts</th></tr></thead><tbody>${recettesRows}</tbody>
    <tfoot><tr style="font-weight:bold;background:var(--bg2)"><td colspan="2">TOTAL — ligne 215</td><td class="num">${fmt(t.recettes215)}</td><td></td></tr></tfoot></table>
    <h4 style="margin:14px 0 6px;font-size:13px">Charges déductibles</h4>
    <table class="tbl" style="font-size:12px"><thead><tr><th>Ligne</th><th>Libellé</th><th class="num">Montant</th><th>Nb mvts</th></tr></thead><tbody>${chargesRows}</tbody>
    <tfoot><tr style="font-weight:bold;background:var(--bg2)"><td colspan="2">TOTAL — ligne 240</td><td class="num">${fmt(t.charges240)}</td><td></td></tr></tfoot></table>
    <h4 style="margin:14px 0 6px;font-size:13px">Intérêts d'emprunt</h4>
    <table class="tbl" style="font-size:12px"><thead><tr><th>Ligne</th><th>Libellé</th><th class="num">Montant</th><th>Nb mvts</th></tr></thead><tbody>${intRows}</tbody></table>
    ${unmappedHtml}`;
}

function _renderWiz2044Step4(ent, data) {
  return `
    <div style="padding:10px 0">
      <p>Récapitulatif prêt à imprimer / sauvegarder en PDF.</p>
      ${_legal2044PerimetreHtml(data, { ecran: true })}
      <ul style="font-size:12px;line-height:1.8">
        <li>Recettes ligne 215 : <b>${fmt(data.totaux.recettes215)}</b></li>
        <li>Charges ligne 240 : <b>${fmt(data.totaux.charges240)}</b></li>
        <li>Intérêts ligne 250 : <b>${fmt(data.totaux.interets250)}</b></li>
        <li><b>Résultat foncier : ${data.resultat>=0?'+':''}${fmt(data.resultat)}</b> ${data.resultat>=0?'(à reporter case BBA/BBB)':'(déficit — case BAB / BAA selon le cas)'}</li>
      </ul>
      <p class="mu sm" style="font-size:11px;margin-top:10px;font-style:italic">Le PDF récap reprend toutes les lignes + le détail des mouvements pour justification. Les valeurs peuvent ensuite être recopiées dans le CERFA 2044 officiel (impots.gouv.fr).</p>
    </div>`;
}

// PDF récap 2044 — modale dédiée pour impression / save PDF (window.print)
function _print2044(entId, year) {
  const ent = (DB.entites||[]).find(e => +e.id === +entId);
  if(!ent) return;
  const activeLogs = (DB.logements||[]).filter(_isAlive).filter(l => l.entity === ent.nom && !l.archived);
  const data = _legal2044WizardData(ent, year);
  const t = data.totaux;
  const headerInfo = `
    <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:18px">
      <div>
        <p style="font-size:11px;color:#666;margin:4px 0">${(ent.immeubles||[]).filter(_isAlive).length} immeuble${(ent.immeubles||[]).filter(_isAlive).length>1?'s':''} · ${activeLogs.length} logement${activeLogs.length>1?'s':''} · ${data.mvtsCount} mouvement${data.mvtsCount>1?'s':''} considéré${data.mvtsCount>1?'s':''}</p>
      </div>
      <div style="text-align:right;font-size:11px">
        <p style="margin:0"><b>Bailleur</b><br>${escHtml(ent.nom)}<br>${escHtml(ent.siege||'')}</p>
        ${ent.siren?`<p style="margin:6px 0 0">SIREN : ${escHtml(ent.siren)}</p>`:''}
        <p style="margin:6px 0 0;color:#888">Généré le ${fd(td())}</p>
      </div>
    </div>`;
  const linesTable = (filterFn, totalLabel, totalValue) => {
    const rows = LIGNES_2044.filter(filterFn).map(l => {
      const v = data.byLine[l.num];
      return `<tr>
        <td style="padding:5px;border:1px solid #ccc">${l.num}</td>
        <td style="padding:5px;border:1px solid #ccc">${escHtml(l.libelle)}</td>
        <td style="padding:5px;border:1px solid #ccc;text-align:right">${v.total?fmt(v.total):'—'}</td>
      </tr>`;
    }).join('');
    return `<table style="width:100%;border-collapse:collapse;font-size:12px;margin:10px 0">
      <thead><tr style="background:#f0f0f0"><th style="padding:5px;border:1px solid #ccc;text-align:left">Ligne</th><th style="padding:5px;border:1px solid #ccc;text-align:left">Libellé</th><th style="padding:5px;border:1px solid #ccc;text-align:right">Montant</th></tr></thead>
      <tbody>${rows}</tbody>
      <tfoot><tr style="font-weight:bold;background:#f8f8f8"><td colspan="2" style="padding:5px;border:1px solid #ccc">${totalLabel}</td><td style="padding:5px;border:1px solid #ccc;text-align:right">${fmt(totalValue)}</td></tr></tfoot>
    </table>`;
  };
  const detailsTable = (() => {
    const cats = LIGNES_2044.filter(l => data.byLine[l.num].mvts.length > 0);
    if(!cats.length) return '';
    return cats.map(l => {
      const v = data.byLine[l.num];
      const rows = v.mvts.slice(0, 100).map(m => `<tr>
        <td style="padding:3px 6px;border-bottom:1px solid #eee;font-size:10px">${escHtml(m.date||'')}</td>
        <td style="padding:3px 6px;border-bottom:1px solid #eee;font-size:10px">${escHtml(m.lib||'')}${m.auto?' <i style="color:#888">(auto)</i>':''}</td>
        <td style="padding:3px 6px;border-bottom:1px solid #eee;font-size:10px;text-align:right">${fmt(m.montant)}</td>
      </tr>`).join('');
      return `<div style="margin-top:14px;page-break-inside:avoid">
        <h4 style="font-size:12px;margin:0 0 4px;background:#f0f0f0;padding:4px 8px">Ligne ${l.num} — ${escHtml(l.libelle)} (${v.mvts.length} mvt${v.mvts.length>1?'s':''}, ${fmt(v.total)})</h4>
        <table style="width:100%;border-collapse:collapse"><tbody>${rows}</tbody></table>
      </div>`;
    }).join('');
  })();
  const summary = `
    <div style="margin-top:18px;padding:12px 14px;border:2px solid #333;border-radius:4px;background:#fafafa">
      <h3 style="margin:0 0 8px;font-size:13px">Résultat foncier ${year}</h3>
      <table style="width:100%;font-size:12px;border-collapse:collapse">
        <tr><td style="padding:4px">Recettes (ligne 215)</td><td style="padding:4px;text-align:right;color:#059669">+ ${fmt(t.recettes215)}</td></tr>
        <tr><td style="padding:4px">Charges (ligne 240)</td><td style="padding:4px;text-align:right;color:#dc2626">− ${fmt(t.charges240)}</td></tr>
        <tr><td style="padding:4px">Intérêts (ligne 250)</td><td style="padding:4px;text-align:right;color:#dc2626">− ${fmt(t.interets250)}</td></tr>
        <tr style="border-top:1px solid #333;font-weight:bold;font-size:13px"><td style="padding:6px 4px">${data.resultat>=0?'BÉNÉFICE FONCIER':'DÉFICIT FONCIER'}</td><td style="padding:6px 4px;text-align:right;color:${data.resultat>=0?'#059669':'#dc2626'}">${data.resultat>=0?'+':''}${fmt(data.resultat)}</td></tr>
      </table>
      ${data.deficitDeductible < 0 ? `<p style="font-size:11px;margin:8px 0 0;color:#666">Déficit déductible du revenu global : ${fmt(Math.abs(data.deficitDeductible))} (plafond 10 700 €). L'excédent s'impute sur les revenus fonciers N+1 à N+10.</p>`:''}
    </div>`;
  const legalNote = `
    <div style="margin-top:30px;padding:10px 14px;border:1px solid #bbb;border-radius:4px;font-size:9.5px;color:#555;line-height:1.6;background:#fafafa">
      <b>Mentions importantes</b><br>
      • Document généré par <b>Propryo</b> à partir des mouvements bancaires saisis. Valeurs <b>indicatives</b> à vérifier avec le centre des impôts ou un expert-comptable agréé.<br>
      • La ligne 225 inclut automatiquement les charges restées à charge bailleur (vacances + logements exclus du poste de charge), calculées par le moteur de régularisation.<br>
      • Cette synthèse <b>ne remplace pas</b> le formulaire CERFA 2044 officiel. Recopier les totaux dans le formulaire (impots.gouv.fr → déclaration en ligne).<br>
      • Conserver les pièces justificatives (factures, baux, contrats, relevés bancaires) pendant 6 ans (art. L102 B LPF).
    </div>`;
  const win = window.open('', '_blank');
  if(!win) { showToast('Popup bloquée — autoriser les pop-ups pour ce site','err'); return; }
  // DOCS-UNIFIES — ce récapitulatif est remis à un tiers (comptable, centre des impôts) :
  // il prend la coquille du gabarit unique — bandeau d'identité, titre, ligne de contexte,
  // pied. Les tableaux CERFA ne sont PAS re-composés : leurs colonnes de chiffres et leurs
  // numéros de ligne sont le fond du document.
  const _corps2044 = `${headerInfo}
<h2 style="font-size:14px;margin-top:18px">Synthèse par ligne CERFA 2044</h2>
${linesTable(l=>l.type==='recette', 'TOTAL recettes — ligne 215', t.recettes215)}
${linesTable(l=>l.type==='charge', 'TOTAL charges — ligne 240', t.charges240)}
${linesTable(l=>l.type==='interet', "Intérêts d'emprunt — ligne 250", t.interets250)}
${summary}
${_legal2044PerimetreHtml(data)}
<h2 style="font-size:14px;margin-top:24px;page-break-before:always">Détail des mouvements par ligne</h2>
${detailsTable}
${legalNote}`;
  win.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Récap 2044 — ${escHtml(ent.nom)} ${year}</title>
<style>body{margin:0;padding:16mm 20mm;background:#fff}@media print{button{display:none}}
.print-btn{position:fixed;top:10px;right:10px;background:#ff5a3c;color:#fff;border:none;padding:8px 16px;border-radius:6px;cursor:pointer;font-size:13px}
${_docCss()}</style>
</head><body>
<button class="print-btn no-print" onclick="window.print()">${_uiIcon('printer')} Imprimer / PDF</button>
${/* AUDIT I2 : ni ref ni date au pied, headerInfo porte deja bailleur+SIREN+« Genere le » */''}
${_docPage(ent, { titre: 'Récapitulatif 2044', ctx: escHtml(ent.nom) + ' — revenus fonciers, année ' + year, corps: _corps2044, withStyle: false })}
</body></html>`);
  win.document.close();
}

function openBailleurMenu(evt, entId) {
  const ent = (DB.entites||[]).find(e => +e.id === +entId);
  if(!ent) { evt.preventDefault(); evt.stopPropagation(); _closeBienMenus(); return; }
  const idEsc = +entId;
  const html =
    `<button class="bmp-item" role="menuitem" onclick="event.stopPropagation();_closeBienMenus();openEntFiche(${idEsc})">${_uiIcon('eye')} Voir détails</button>` +
    `<button class="bmp-item" role="menuitem" onclick="event.stopPropagation();_closeBienMenus();openNewEnt(${idEsc})">${_uiIcon('edit')} Modifier</button>` +
    `<div class="bmp-divider" role="separator"></div>` +
    `<button class="bmp-item bmp-danger" role="menuitem" onclick="event.stopPropagation();_closeBienMenus();delEnt(${idEsc})">${_uiIcon('trash')} Supprimer</button>`;
  _openMenuPopover(evt, html);
}

// v14.3 PATRIMOINE-NAV-UNIFY — render mode Bailleurs (cards d'entités)
// Search inclut nom/SIREN/RCS/gérant/siège/IBAN/type. Tri par nom A-Z (default) ou Z-A.
function _renderBiensModeBailleurs(wrap, cntEl) {
  // v14.31 BUG-DRIVE-RESURRECTION : exclure tombstones
  let ents = (DB.entites||[]).filter(_isAlive).slice();

  // v14.54 BUG-BIENS-TABS-FILTER : si onglet "Biens archivés" actif, ne montrer
  // que les bailleurs ayant ≥1 logement archivé (sinon vue archivés affichait
  // tous les bailleurs comme la vue actifs → confusion utilisateur).
  const isArchivedTab = _biensTab === 'archives';
  const _entsWithArchived = () => {
    const set = new Set(
      (DB.logements||[]).filter(_isAlive).filter(l => l.archived).map(l => l.entity).filter(Boolean)
    );
    return (DB.entites||[]).filter(_isAlive).filter(e => set.has(e.nom));
  };
  if (isArchivedTab) {
    ents = _entsWithArchived();
  }

  const q = (_biensFilters.search||'').toLowerCase();
  if(q) {
    ents = ents.filter(e =>
      (e.nom||'').toLowerCase().includes(q) ||
      (e.siren||'').toLowerCase().includes(q) ||
      (e.rcs||'').toLowerCase().includes(q) ||
      (e.gerant||'').toLowerCase().includes(q) ||
      (e.siege||'').toLowerCase().includes(q) ||
      (e.iban||'').toLowerCase().includes(q) ||
      (e.type||'').toLowerCase().includes(q)
    );
  }
  switch(_biensFilters.sort) {
    case 'name-desc': ents.sort((a,b)=>_natCmp(b.nom, a.nom)); break;
    default:          ents.sort((a,b)=>_natCmp(a.nom, b.nom));
  }
  // v14.47 audit tombstones — totalEnts et nbBiens excluaient les tombstones
  // v14.54 : totalEnts et nbBiens dépendent du tab actif (scope archivés vs actifs)
  const totalEnts = isArchivedTab ? _entsWithArchived().length : (DB.entites||[]).filter(_isAlive).length;
  const nbBiens   = ents.reduce((s,e)=> s + (DB.logements||[]).filter(_isAlive).filter(l =>
    l.entity===e.nom && (isArchivedTab ? !!l.archived : !l.archived)
  ).length, 0);

  // Empty state global
  if(!totalEnts) {
    if(cntEl) cntEl.textContent = '';
    if(isArchivedTab) {
      wrap.innerHTML = `<div class="biens-empty">
        <div class="biens-empty-icon">${_uiIcon('archive',44)}</div>
        <div class="biens-empty-title">Aucun bailleur n'a de bien archivé</div>
        <div class="biens-empty-msg">Les bailleurs n'apparaissent ici que s'ils ont au moins 1 bien archivé. Pour archiver un bien, ouvrir sa fiche et utiliser le menu ⋮.</div>
        <button class="btn bs" onclick="setBiensTab('actifs')">← Retour aux bailleurs actifs</button>
      </div>`;
    } else {
      wrap.innerHTML = `<div class="biens-empty">
        <div class="biens-empty-icon">${_uiIcon('building',44)}</div>
        <div class="biens-empty-title">Aucun bailleur enregistré</div>
        <div class="biens-empty-msg">Créer la première entité juridique propriétaire (SCI, particulier, indivision…) pour commencer.</div>
        <button class="btn bp" onclick="openNewEnt()">+ Ajouter un bailleur</button>
      </div>`;
    }
    return;
  }
  if(!ents.length) {
    if(cntEl) cntEl.textContent = `0 résultat sur ${totalEnts}`;
    wrap.innerHTML = `<div class="biens-empty">
      <div class="biens-empty-icon">${_uiIcon('search',44)}</div>
      <div class="biens-empty-title">Aucun bailleur ne correspond à la recherche</div>
      <button class="btn bs" onclick="clearBiensFilters()">${_uiIcon('refresh')} Réinitialiser</button>
    </div>`;
    return;
  }
  const filtSuffix = ents.length < totalEnts ? ' (filtré)' : '';
  // v14.54 : libellé "actif" / "archivé" selon tab
  const scopeLbl  = isArchivedTab ? 'archivé' : 'actif';
  if(cntEl) cntEl.textContent = `${ents.length} ${ents.length>1?'bailleurs':'bailleur'}${filtSuffix} · ${nbBiens} ${nbBiens>1?'biens':'bien'} ${scopeLbl}${nbBiens>1?'s':''}`;
  wrap.innerHTML = `<div class="biens-grid">${ents.map(e => _renderBailleurCard(e, isArchivedTab)).join('')}</div>`;
}

function rBiens() {
  const wrap = el('biens-list-wrap'); if(!wrap) return;
  try{ if(_isPhone()) _ensureBiencPhCss(); }catch(e){}   // MOBILE-REFONTE lot 2b — CSS toolbar téléphone présent quel que soit le mode
  // Fil COMPLET (Task 8) : bandeau de reprise AVANT les early-returns (empty states, mode bailleurs)
  // pour qu'il soit rafraîchi à chaque rendu de la page, quel que soit le sous-onglet.
  if(typeof _frRenderResumeBanner==='function') _frRenderResumeBanner();
  if(!DB.logements) { wrap.innerHTML='<p class="mu">Chargement…</p>'; return; }
  _closeBienMenus();

  // Compteurs des tabs (toujours basés sur l'ensemble, pas sur les filtres)
  const totalActifs   = _activeLogements().length;
  const totalArchives = _archivedLogements().length;
  const cntA = el('biens-tab-count-actifs');   if(cntA) cntA.textContent = totalActifs;
  const cntZ = el('biens-tab-count-archives'); if(cntZ) cntZ.textContent = totalArchives;
  // Sync UI tabs (active state)
  const tabA = el('biens-tab-actifs'), tabZ = el('biens-tab-archives');
  if(tabA && tabZ) {
    tabA.classList.toggle('act', _biensTab==='actifs'); tabA.setAttribute('aria-selected', _biensTab==='actifs');
    tabZ.classList.toggle('act', _biensTab==='archives'); tabZ.setAttribute('aria-selected', _biensTab==='archives');
  }
  // Sync UI toggle vue (3 modes : Bailleurs / Immeubles / Logements)
  [['bvt-bailleurs','bailleurs'],['bvt-immeubles','immeubles'],['bvt-logements','logements']].forEach(([id,m])=>{
    const btn = el(id); if(!btn) return;
    btn.classList.toggle('act', _biensViewMode===m); btn.setAttribute('aria-selected', _biensViewMode===m);
  });
  // Bouton "+" UNIFIÉ (fidélité mockup validé) : « + Ajouter un bien » quel que soit le sous-onglet (cf openBiensAdd).
  const addBtn = el('biens-add-btn');
  if(addBtn) addBtn.textContent = '+ Ajouter un bien';
  const inpSearch = el('biens-search');
  if(inpSearch) inpSearch.placeholder = _biensViewMode==='bailleurs'
    ? 'Rechercher un bailleur (nom, SIREN, gérant…)'
    : 'Rechercher (nom, locataire, adresse…)';
  // Sync badge filtres
  const fbtn = el('biens-filter-btn'), fbadge = el('biens-filter-badge');
  if(fbtn && fbadge) {
    const c = _biensActiveFilterCount();
    fbtn.classList.toggle('has-active', c > 0);
    fbadge.style.display = c > 0 ? 'inline-flex' : 'none';
    fbadge.textContent = c;
  }
  const sc = el('biens-search-clear'); if(sc) sc.classList.toggle('show', !!_biensFilters.search);
  const cnt = el('biens-count');

  // MOBILE-REFONTE lot 3c — le mode Bailleurs n'a que Trier + Exporter (mockup BOOK-BAILLEURS) :
  // les filtres (bailleur / occupation / type) sont des attributs de LOGEMENT, sans objet ici.
  try {
    const _fb = el('biens-filter-btn');
    const _fw = _fb && _fb.closest ? _fb.closest('.biens-filter-wrap') : null;
    if(_fw) _fw.style.display = (_biensViewMode === 'bailleurs') ? 'none' : '';
  } catch(e) {}

  // v14.3 PATRIMOINE-NAV-UNIFY : mode Bailleurs = render dédié sur DB.entites
  // Le tab Actifs/Archivés ne s'applique pas aux bailleurs (les entités n'ont pas de cycle de vie soft-delete)
  if(_biensViewMode === 'bailleurs') {
    return _renderBiensModeBailleurs(wrap, cnt);
  }

  // Pool selon le tab actif (LOG-ARCHIVE)
  const pool = _biensTab === 'archives' ? _archivedLogements() : _activeLogements();
  const isArchivedTab = _biensTab === 'archives';

  // Empty state global (pas de bien du tout) — v14.47 audit : exclure tombstones
  if(!_aliveLogements().length) {
    if(cnt) cnt.textContent = '';
    wrap.innerHTML = `<div class="biens-empty">
      <div class="biens-empty-icon">${_uiIcon('home',44)}</div>
      <div class="biens-empty-title">Aucun bien enregistré</div>
      <div class="biens-empty-msg">Commencer par ajouter le premier logement pour visualiser le patrimoine en cartes.</div>
      <!-- FIL-ROUGE FIDÉLITÉ (trouvé au vrai clic) : cet empty-state ouvrait la modale logement
           BRUTE (openNewLog) sans bailleur ni immeuble existants — « + Ajouter un bien » doit
           lancer le parcours guidé partout (mockup validé). -->
      <button class="btn bp" onclick="if(typeof _frStart==='function')_frStart('bien');else openNewLog()">+ Ajouter un bien</button>
    </div>`;
    return;
  }
  // Empty state spécifique tab archivés vide
  if(isArchivedTab && !pool.length) {
    if(cnt) cnt.textContent = '';
    wrap.innerHTML = `<div class="biens-empty">
      <div class="biens-empty-icon">${_uiIcon('archive',44)}</div>
      <div class="biens-empty-title">Aucun bien archivé</div>
      <div class="biens-empty-msg">Les biens vendus ou non gérés peuvent être archivés depuis le menu ⋮ d'une carte. L'historique (baux, mouvements, EDL) est conservé.</div>
      <button class="btn bs" onclick="setBiensTab('actifs')">← Retour aux biens actifs</button>
    </div>`;
    return;
  }

  const filtered = _filterAndSortLogs(pool);
  // Empty state filtres (avec biens dans pool mais aucun ne matche)
  if(!filtered.length) {
    if(cnt) cnt.textContent = `0 résultat sur ${pool.length}`;
    wrap.innerHTML = `<div class="biens-empty">
      <div class="biens-empty-icon">${_uiIcon('search',44)}</div>
      <div class="biens-empty-title">Aucun bien ne correspond aux filtres</div>
      <div class="biens-empty-msg">Modifier la recherche ou réinitialiser les filtres.</div>
      <button class="btn bs" onclick="clearBiensFilters()">${_uiIcon('refresh')} Réinitialiser les filtres</button>
    </div>`;
    return;
  }

  if(_biensViewMode === 'logements') {
    if(cnt) cnt.textContent = `${filtered.length} ${filtered.length>1?'logements':'logement'}${filtered.length<pool.length?` sur ${pool.length}`:''}`;
    // MOBILE-REFONTE lot 3 — téléphone : regroupement par immeuble (en-têtes repliables + lots en retrait).
    // PC (≥768px) : grille plate d'origine inchangée.
    if(_isPhone()) {
      wrap.innerHTML = _renderLogementsGroupedPhone(filtered);
    } else {
      wrap.innerHTML = `<div class="biens-grid">${filtered.map(_renderLogementCardFlat).join('')}</div>`;
    }
    return;
  }

  // Mode Immeubles : group par (entité, immeuble.nom). Logements sans imm → groupe orphelins par entité.
  const groups = new Map();
  filtered.forEach(l => {
    const key = (l.entity||'—') + '||' + (l.imm||'');
    if(!groups.has(key)) groups.set(key, { entNom:l.entity||'—', immNom:l.imm||'', logs:[] });
    groups.get(key).logs.push(l);
  });
  const groupsArr = [...groups.values()];
  groupsArr.forEach(g => g._agg = _aggregateBuilding(g.logs));
  switch(_biensFilters.sort) {
    case 'name-desc':  groupsArr.sort((a,b)=>_natCmp(b.immNom, a.immNom)); break;
    case 'rent-desc':  groupsArr.sort((a,b)=>b._agg.loyerHC - a._agg.loyerHC); break;
    case 'rent-asc':   groupsArr.sort((a,b)=>a._agg.loyerHC - b._agg.loyerHC); break;
    case 'occup-desc': groupsArr.sort((a,b)=>(b._agg.nbOccupes/Math.max(1,b._agg.nbTotal)) - (a._agg.nbOccupes/Math.max(1,a._agg.nbTotal))); break;
    case 'recent':     groupsArr.sort((a,b)=>{
      const am = a.logs.reduce((m,l) => (l._modifiedAt||'') > m ? (l._modifiedAt||'') : m, '');
      const bm = b.logs.reduce((m,l) => (l._modifiedAt||'') > m ? (l._modifiedAt||'') : m, '');
      return bm.localeCompare(am);
    }); break;
    // v15.236 : tri par défaut groupé par BAILLEUR (entité) puis immeuble, pour
    // que tous les immeubles d'un même bailleur soient consécutifs.
    default:           groupsArr.sort((a,b)=>_natCmp(a.entNom, b.entNom) || _natCmp(a.immNom, b.immNom));
  }
  // MOBILE-REFONTE lot 3 — vue Immeubles TÉLÉPHONE : cartes compactes _renderBuildingCard
  // (jamais le bloc desktop 7 colonnes _renderBuildingBlockA, illisible à 375px), groupées
  // par bailleur avec un séparateur de groupe (mockup BOOK-IMMEUBLES). PC inchangé plus bas.
  if(_isPhone()) {
    let html = '', curEnt = null, buf = [];
    const flush = () => { if(buf.length) { html += `<div class="biens-grid">${buf.join('')}</div>`; buf = []; } };
    groupsArr.forEach(g => {
      if(g.entNom !== curEnt) { flush(); curEnt = g.entNom; html += `<div class="biens-grp-sep">${escHtml(curEnt||'—')}</div>`; }
      const ent = (DB.entites||[]).find(e => e.nom === g.entNom) || null;
      buf.push(_renderBuildingCard(g.entNom, g.immNom, g.logs, ent, isArchivedTab));
    });
    flush();
    const filtSuffixP = filtered.length < pool.length ? ' (filtré)' : '';
    if(cnt) cnt.textContent = `${groupsArr.length} ${groupsArr.length>1?'immeubles':'immeuble'} · ${filtered.length} ${filtered.length>1?'biens':'bien'}${filtSuffixP}`;
    wrap.innerHTML = html;
    return;
  }
  // v15.230 ARCHI-FICHES-UNIFIED Session 4 Commit 3 — Variante A par défaut.
  // Bascule via _biensFilters.layout = 'cards-b' pour conserver l'ancien rendu cards.
  const useBlocksA = (_biensFilters && _biensFilters.layout === 'cards-b') ? false : true;
  const cards = groupsArr.map(g => {
    const ent = (DB.entites||[]).find(e=>e.nom===g.entNom) || null;
    return useBlocksA
      ? _renderBuildingBlockA(g.entNom, g.immNom, g.logs, ent, isArchivedTab)
      : _renderBuildingCard(g.entNom, g.immNom, g.logs, ent, isArchivedTab);
  });
  const filtSuffix = filtered.length < pool.length ? ' (filtré)' : '';
  if(cnt) cnt.textContent = `${groupsArr.length} ${groupsArr.length>1?'immeubles':'immeuble'} · ${filtered.length} ${filtered.length>1?'biens':'bien'}${filtSuffix}`;
  // En variante A (blocs), pas besoin du wrapper .biens-grid (les blocs s'empilent verticalement)
  wrap.innerHTML = useBlocksA ? cards.join('') : `<div class="biens-grid">${cards.join('')}</div>`;
  // v15.230 — Restaure l'état collapsed mémorisé localStorage (variante A uniquement)
  if (useBlocksA) try { _applyImmBlocksCollapsedState(); } catch(e) {}
}

// v14.2 LOG-FICHE-360 Phase 1 — vue dédiée full-page d'un bien.
// Route hash #log-fiche-{ref} pour deeplink ; navigation interne via go('log-fiche').
let _currentLogFicheRef = null;

function openLogFiche(ref, replace) {
  if(!ref) return;
  _currentLogFicheRef = ref;
  // BAIL-SIGNATURE-DISTANCE C3 (Task 12) : poll ciblé du logement ouvert (throttlé 30 s).
  setTimeout(() => { try { if (typeof _pollRemoteSignSessions === 'function') _pollRemoteSignSessions({ logRef: ref }); } catch (e) {} }, 300);
  // Active la page interne (rLogFiche est appelée par go() via le map des renderers)
  go('log-fiche', null);
  // Met à jour le hash sans recharger — bookmarkable / partageable / back navigable.
  // replace=true (renommage) : remplace l'entrée d'historique courante au lieu d'en empiler une —
  // sinon l'ancien hash #log-fiche-<ancienne réf> reste joignable via Retour → « Bien introuvable ».
  try {
    const target = '#log-fiche-' + encodeURIComponent(ref);
    if(location.hash !== target) history[replace ? 'replaceState' : 'pushState'](null, '', target);
  } catch(e){}
  // Update titre topbar avec le nom du bien
  const log = (DB.logements||[]).find(l=>l.ref===ref);
  if(log) {
    const tb = el('tb-title');
    if(tb) tb.textContent = log.imm ? `${log.imm} — ${_logLabel(ref)}` : _logLabel(ref);
  }
}

// v14.13 A3 + v14.18 FICHES-PARITE-360 Session 1 — état du sous-onglet actif dans la fiche logement
// BIENS étape 8 (P0-3) — « Général » était À LA FOIS l'onglet par défaut ET la branche finale du
// ternaire de rLogFiche(). Le supprimer sans toucher aux deux endroits ouvrait une fiche VIDE.
let _currentLogFicheTab = 'bail';
let _logFicheComptaYear = new Date().getFullYear();

function setLogFicheTab(t) {
  // v14.50 FICHES-PARITE-360 Sessions 5+6 : Entretien + Documents activés
  // v14.51 : 'entretien' renommé 'conformite' (équipements + assurances obligatoires)
  //         + nouveau sous-onglet 'agenda' dédié (sorti du panel Conformité)
  // v14.56 : sous-onglet 'compteurs' activé (extraction relevés depuis EDL + saisies manuelles)
  // v14.57 : sous-onglet 'edl' activé (États des lieux fiche logement, FICHES-PARITE-360 Session 3)
  // v15.05 Sprint 7 V1.1 : ajout sous-onglet 'diagnostics' (DDT bailleur)
  // v15.234 MODALE-LOGEMENT B2 : sous-onglet 'diagnostics' retiré de la fiche 360°
  //   (saisie consolidée dans la modale logement → onglet 🏷 Diagnostics). Deep-links
  //   repointés vers openLogModalOnTab(ref,'diag'). Compat : 'diagnostics' redirige.
  if(t === 'diagnostics') { try { const _r=(typeof _currentLogFicheRef!=='undefined'&&_currentLogFicheRef)?_currentLogFicheRef:null; if(_r && typeof openLogModalOnTab==='function'){ openLogModalOnTab(_r,'diag'); return; } } catch(_){} t = 'bail'; }
  // BIENS étape 8 — 9 onglets → 4 : Bail (+ états des lieux) · Entretien & assurances · Documents
  // (+ photos) · Comptabilité. REDIRECTIONS de compat plutôt qu'un retrait sec : ce setter fait
  // `if(liste.indexOf(t)<0) return;`, donc un hash d'URL ou un favori existant deviendrait un clic
  // SANS EFFET ni message (même motif que 'diagnostics' ci-dessus).
  if(t === 'general') t = 'bail';        // l'ex-Général est absorbé par l'entête + l'onglet Bail
  if(t === 'edl')     t = 'bail';        // les états des lieux vivent dans l'onglet Bail
  if(t === 'photos')  t = 'documents';   // les photos vivent dans l'onglet Documents
  if(t === 'agenda')  t = 'bail';        // onglet Agenda supprimé (la page globale Agenda reste)
  // Les relevés de compteurs n'ont plus qu'UN écran : fiche immeuble → Charges communes (P1-7).
  // Un logement sans immeuble n'a pas la fonction → on ne duplique pas le point d'entrée.
  if(t === 'compteurs') {
    try {
      const _r = (typeof _currentLogFicheRef !== 'undefined' && _currentLogFicheRef) ? _currentLogFicheRef : null;
      const _l = _r ? (DB.logements||[]).find(x => x && x.ref === _r) : null;
      const _e = (_l && _l.entity) ? (DB.entites||[]).find(x => x && x.nom === _l.entity) : null;
      const _i = (_e && Array.isArray(_e.immeubles) && _l.imm) ? _e.immeubles.find(x => x && x.nom === _l.imm && !x._deleted) : null;
      if (_i && typeof openImmFiche === 'function') {
        _currentImmFicheTab = 'charges';
        // audit (mineur) : arriver sur les relevés d'un AUTRE logement que celui qu'on quittait
        // n'aurait aucun sens — on présélectionne celui d'origine dans le sélecteur.
        if (_r && typeof _setImmCompteursRef === 'function') _immCompteursRef = _r;
        openImmFiche(_e.id, _i.id);
        return;
      }
    } catch(_){}
    t = 'bail';
  }
  if(['bail','conformite','documents','compta'].indexOf(t) < 0) return;
  _currentLogFicheTab = t;
  rLogFiche();
}

function setLogFicheComptaYear(y) {
  _logFicheComptaYear = parseInt(y) || new Date().getFullYear();
  rLogFiche();
}

// ════════════════════════════════════════════════════════════════════════════
// FICHES-PARITE-360 Session 1 — Compta riche logement (mvt + quittances + IRL + KPIs + cash-flow)
// Source de vérité : single. Helpers _renderXForLog(ref, year) factorisables Phase 2 onglet.
// Cf docs/subjects/FICHES-PARITE-360.md
// ════════════════════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════════════════════
// VACANCE-VIZ v14.33 — Visualisation occupation/manque à gagner intégrée au hero.
// REFONTE TOTALE vs v14.29 (retour utilisateur "trop imposant, redondant avec
// timeline Bail, hero déjà trop haut") :
//   - SUPPRESSION du bandeau status pleine largeur
//   - SUPPRESSION de la timeline 24 mois pleine largeur (redondante avec
//     l'ex-timeline horizontale de l'onglet Bail — elle-même remplacée 17/07 par
//     la timeline en accordéons « Historique du bail »)
//   - HERO compact intégré : 4 KPIs scoreboard (loyer/durée/occup/manque)
//     + pulse fine 8px de haut servant de séparateur entre badges et KPIs
// Hauteur fiche avant les sous-onglets : ~420px → ~190px (gain ~55%).
// Helpers _daysBetweenIso, _monthsBetweenIso, _getLastBailForLog,
// _getLastClosedBailEndIso conservés (utilisés par les KPIs hero).
// ════════════════════════════════════════════════════════════════════════════

// Nombre de jours entre 2 dates ISO (yyyy-mm-dd). Toujours >= 0.
function _daysBetweenIso(iso1, iso2) {
  if(!iso1 || !iso2) return 0;
  const d1 = new Date(iso1+'T00:00:00');
  const d2 = new Date(iso2+'T00:00:00');
  return Math.max(0, Math.round((d2 - d1) / 86400000));
}

// Nombre de mois (approximé sur 30.44 jours/mois moyen) entre 2 dates ISO.
function _monthsBetweenIso(iso1, iso2) {
  return Math.floor(_daysBetweenIso(iso1, iso2) / 30.44);
}

// Le dernier bail (chronologiquement le plus récent par debut), incluant historique + courant.
// R0-H : LE dernier bail d'un lot = celui qui s'est terminé le plus tard, pas le dernier
// ÉLÉMENT d'un tableau trié par date de DÉBUT. Deux baux qui se chevauchent, ou un bail
// commencé avant et fini après un autre, faisaient désigner le mauvais — et avec lui le
// mauvais loyer sur la fiche du bien (« dernier bail : 660 € » au lieu de 890 €) et dans son
// manque à gagner. Un bail encore EN COURS (sans fin) l'emporte sur tous les terminés.
function _getLastBailForLog(ref) {
  const bails = _getAllBailsForLog(ref);
  if(!bails.length) return null;
  const enCours = bails.filter(b => !b.fin);
  if (enCours.length) {
    return enCours.reduce((a, b) => (String(b.debut||'') > String(a.debut||'') ? b : a));
  }
  return bails.reduce((a, b) => (String(b.fin||'') > String(a.fin||'') ? b : a));
}

// Date ISO de fin effective du dernier bail clôturé pour ce logement.
function _getLastClosedBailEndIso(ref) {
  const bails = _getAllBailsForLog(ref);
  if(!bails.length) return null;
  const closed = bails.filter(b => b.fin && b.fin <= td());
  if(!closed.length) return null;
  closed.sort((a, b) => (b.fin || '').localeCompare(a.fin || ''));
  return closed[0].fin;
}

// ──────────────────────────────────────────────────────────────────────────
// Pulse bar fine (8px) — séparateur visuel entre badges et KPIs scoreboard.
// 24 mois en cellules égales (flex:1), sans label, tooltip natif via attr title.
// Vert = loué, rouge = vacant, gris = avant mise en gestion.
// Mois courant : box-shadow bleue 2px sous la dernière cellule.
//
// v14.35 : refonte SVG → DIV flexbox. Le SVG avec preserveAspectRatio="none"
// + height fixe 11px posait des problèmes de rendu sur iOS Safari mobile (la
// barre n'apparaissait pas). Les DIVs flex sont 100% fiables.
// ──────────────────────────────────────────────────────────────────────────
function _renderLogFicheHeroPulse(ref) {
  const today = new Date();
  const months = [];
  for(let i = 23; i >= 0; i--) {
    const d = new Date(today.getFullYear(), today.getMonth() - i, 15);
    const yr = d.getFullYear();
    const mi = d.getMonth();
    months.push({
      yr, mi,
      iso15: `${yr}-${String(mi+1).padStart(2,'0')}-15`,
      label: ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'][mi]
    });
  }
  const bails = _getAllBailsForLog(ref);
  const startIso = bails.length ? bails[0].debut : null;
  if(!bails.length) {
    return `<div class="logf-hero-pulse logf-hero-pulse-empty" title="Aucun bail enregistré">
      <span class="mu sm">Pulse 24 mois — disponible dès le 1er bail créé</span>
    </div>`;
  }

  const cellsHtml = months.map((m, i) => {
    let type, tenant = '', loyer = 0;
    if(startIso && m.iso15 < startIso) {
      type = 'avant';
    } else {
      const active = bails.find(b => b.debut <= m.iso15 && (b.fin || '9999-12-31') >= m.iso15);
      if(active) {
        type = 'loue';
        tenant = active.nom || '—';
        loyer = (+active.hc || 0) + (+active.ch || 0);
      } else {
        const prev = bails.filter(b => b.debut <= m.iso15);
        const ref_ = prev.length ? prev[prev.length-1] : null;
        type = 'vacant';
        tenant = ref_ ? `dernier : ${ref_.nom||'—'}` : '';
        loyer = ref_ ? (+ref_.hc || 0) + (+ref_.ch || 0) : 0;
      }
    }
    const tip = type === 'loue'
      ? `${m.label} ${m.yr} — Loué à ${tenant} · ${fmt(loyer)}/mois`
      : (type === 'vacant'
          ? `${m.label} ${m.yr} — Vacant${tenant?' ('+tenant+')':''}${loyer?' · ref '+fmt(loyer)+'/mois':''}`
          : `${m.label} ${m.yr} — Avant mise en gestion`);
    const isNow = i === 23; // dernière cellule = mois courant
    return `<div class="lhp-cell lhp-${type}${isNow?' lhp-now':''}" title="${escHtml(tip)}" aria-label="${escHtml(tip)}"></div>`;
  }).join('');

  return `<div class="logf-hero-pulse" role="img" aria-label="Occupation sur les 24 derniers mois">
    <div class="logf-hero-pulse-bar">${cellsHtml}</div>
  </div>`;
}

// ──────────────────────────────────────────────────────────────────────────
// Scoreboard : 4 micro-KPIs en ligne dans le hero.
// 1. Loyer mensuel courant (bail actif) ou dernier loyer ref (vacant)
// 2. Durée loué OU jours vacance (selon état)
// 3. Taux occupation 24 mois
// 4. Manque à gagner cumulé (vacant) ou solde positif YTD (loué)
// ──────────────────────────────────────────────────────────────────────────
function _renderLogFicheHeroStats(log, ref) {
  if(log.archived) {
    return `<div class="logf-hero-stats">
      <div class="logf-stat"><div class="logf-stat-v">${_uiIcon('archive',18)}</div><div class="logf-stat-l">Archivé</div></div>
      <div class="logf-stat"><div class="logf-stat-v">${fd(log.archivedAt)||'—'}</div><div class="logf-stat-l">Date archive</div></div>
    </div>`;
  }
  const bail = _bienIsBailActif(ref) ? _bienActiveBail(ref) : null;   // statut : occupé aujourd'hui
  const today = td();

  // ── KPI 1 : Loyer mensuel
  let loyerKPI;
  if(bail) {
    // R-0 (lot 1, R5) : le loyer EN VIGUEUR aujourd'hui — LA règle partagée avec la fiche téléphone.
    const loyer = _loyerEnVigueurLot(ref, bail, log);
    loyerKPI = (loyer == null)
      ? { v: '—', unit: '', label: 'Loyer à renseigner', cls: 'k-mute' }     // bail sans montant : rien d'inventé
      : { v: fmt(loyer), unit: '/mois', label: 'Loyer actuel', cls: 'k-money' };
  } else {
    // LOYER-REFERENCE — bien vacant : afficher le LOYER SOUHAITÉ (loyer de référence), éditable (✏️),
    // avec rappel du dernier bail en sous-titre s'il diffère (variante B). C'est cette valeur qui
    // alimente le candidat, l'invitation, l'annonce et le prochain bail.
    const refTot  = (Number(log.loyerHcRef)||Number(log.hc)||0) + (Number(log.chargesRef)||Number(log.ch)||0);
    const last    = _getLastBailForLog(ref);
    const lastTot = last ? (+last.hc || 0) + (+last.ch || 0) : 0;
    if(refTot > 0){
      loyerKPI = { v: fmt(refTot), unit: '/mois', label: 'Loyer souhaité', cls: 'k-money', edit: ref,
                   sub: (lastTot>0 && lastTot!==refTot) ? ('dernier bail : '+fmt(lastTot)) : '' };
    } else if(lastTot > 0){
      loyerKPI = { v: fmt(lastTot), unit: '/mois', label: 'Dernier loyer ref', cls: 'k-money k-mute', edit: ref };
    } else {
      loyerKPI = { v: '—', unit: '', label: 'Loyer souhaité', cls: 'k-mute', edit: ref };
    }
  }

  // ── KPI 2 : Durée loué OU jours vacance
  let dureeKPI;
  if(bail && bail.debut) {
    const months = _monthsBetweenIso(bail.debut, today);
    const tenant = (bail.locataires?.[0]?.nom) || log.locataire || '';
    const txt = months >= 12
      ? `${Math.floor(months/12)} an${months>=24?'s':''}${months%12 ? ' ' + (months%12) + 'm' : ''}`
      : `${months} mois`;
    dureeKPI = { v: txt, unit: '', label: tenant ? `Loué à ${tenant.length>14?tenant.slice(0,12)+'…':tenant}` : 'Loué', cls: 'k-ok' };
  } else {
    // Départ déclaré passé (bail encore ouvert) : vacant depuis la date de sortie.
    const _ouvert = _bienActiveBail(ref);
    const lastEnd = (_ouvert && _ouvert.depart && _ouvert.depart.dateSortie) ? String(_ouvert.depart.dateSortie).slice(0,10) : _getLastClosedBailEndIso(ref);
    if(lastEnd) {
      const days = _daysBetweenIso(lastEnd, today);
      const txt = days >= 60 ? `${Math.floor(days/30.44)} mois` : `${days} j`;
      dureeKPI = { v: txt, unit: '', label: 'Vacant depuis', cls: 'k-warn' };
    } else {
      dureeKPI = { v: '—', unit: '', label: 'Jamais loué', cls: 'k-mute' };
    }
  }

  // ── KPI 3 : Taux occupation sur 24 derniers mois
  const bails = _getAllBailsForLog(ref);
  const startIso = bails.length ? bails[0].debut : null;
  let nbLoue = 0, nbEnGestion = 0;
  for(let i = 23; i >= 0; i--) {
    const d = new Date(today.split('-')[0]*1, today.split('-')[1]*1 - 1 - i, 15);
    const iso = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-15`;
    if(startIso && iso < startIso) continue;
    nbEnGestion++;
    const active = bails.find(b => b.debut <= iso && (b.fin || '9999-12-31') >= iso);
    if(active) nbLoue++;
  }
  const tauxOccup = nbEnGestion > 0 ? Math.round(nbLoue / nbEnGestion * 100) : 0;
  const occupCls = tauxOccup === 100 ? 'k-ok' : (tauxOccup >= 80 ? '' : 'k-warn');
  const occupKPI = nbEnGestion > 0
    ? { v: `${tauxOccup}%`, unit: '', label: `Occupation 24m`, cls: occupCls }
    : { v: '—', unit: '', label: 'Occupation 24m', cls: 'k-mute' };

  // ── KPI 4 : Manque à gagner cumulé (vacance) ou solde YTD si loué
  let dernierKPI;
  if(bail) {
    // Loué : afficher le solde YTD (encaissé - charges) — chiffre rassurant
    // v14.79 Bug #1 (audit transversal) : inclure aussi la quote-part des compteurs
    // collectifs scopés sur ce logement (sinon KPI sous-estime les dépenses).
    const yr = today.slice(0,4);
    const ytdMvts = (DB.mouvements||[]).filter(_isAlive).filter(m => m.qui === ref && m.date && m.date.startsWith(yr));
    // R0-G : au référentiel, pas au libellé (cf. `_finLotCatRole`). Le « Solde » du lot ne
    // compte plus une restitution de dépôt ni un virement interne comme une charge.
    const enc = ytdMvts.filter(_finLotEstLoyer).reduce((s,m)=>s+_finLotNet(m), 0);
    // Charges directes (exclut compteurCcId, déjà comptabilisé via quote-part)
    const depDirect = ytdMvts.filter(m => _finLotEstCharge(m) && !m.compteurCcId).reduce((s,m)=>s+_finLotNet(m,'charge'), 0);
    // Quote-part des compteurs collectifs scopés (lecture unique, cf. `_lotCcQuotePartMois`)
    const depCc = _lotCcQuotePartMois(ref, yr).reduce((a,b)=>a+b, 0);
    const dep = depDirect + depCc;
    const solde = enc - dep;
    const cls = solde > 0 ? 'k-ok' : (solde < 0 ? 'k-warn' : '');
    dernierKPI = { v: fmt(solde), unit: '', label: `Solde ${yr}`, cls: 'k-money '+cls };
  } else {
    // Vacant : manque à gagner cumulé depuis fin du dernier bail.
    // R0-H : le loyer se lit À LA DATE où le lot s'est vidé (`loyerDuLotA`, barème puis bail
    // trouvé sur sa date de FIN). `_getLastBailForLog` rendait `bails[bails.length-1]` — le
    // dernier ÉLÉMENT d'un tableau trié par date de DÉBUT, qui n'est pas le dernier bail.
    const lastEnd = _getLastClosedBailEndIso(ref);
    const lastBail = _getLastBailForLog(ref);
    if(lastEnd && lastBail) {
      const days = _daysBetweenIso(lastEnd, today);
      const _ld = (typeof loyerDuLotA === 'function') ? loyerDuLotA(lastEnd, ref, _ctxLoyerLot(ref)) : null;
      const lastRent = _ld ? (_ld.hc + _ld.ch) : ((+lastBail.hc || 0) + (+lastBail.ch || 0));
      const manque = Math.round(days / 30.44 * lastRent);
      dernierKPI = { v: '-' + fmt(manque), unit: '', label: 'Manque à gagner', cls: 'k-money k-warn' };
    } else {
      dernierKPI = { v: '—', unit: '', label: 'Manque à gagner', cls: 'k-mute' };
    }
  }

  const stats = [loyerKPI, dureeKPI, occupKPI, dernierKPI];
  return `<div class="logf-hero-stats" role="group" aria-label="Indicateurs clés du bien">
    ${stats.map(s => `<div class="logf-stat"${s.edit?' style="position:relative"':''}>
      <div class="logf-stat-v ${s.cls||''}">${s.v}${s.unit?`<small>${s.unit}</small>`:''}</div>
      <div class="logf-stat-l">${escHtml(s.label)}${s.sub?`<span style="color:var(--mut);font-weight:400"> · ${escHtml(s.sub)}</span>`:''}</div>
      ${s.edit?`<button title="Modifier le loyer de référence (bien vacant)" data-ref="${escHtml(s.edit)}" onclick="event.stopPropagation();openLoyerBienModal(null,this.dataset.ref)" style="position:absolute;top:8px;right:8px;border:1px solid var(--bor);background:var(--sur,#fff);border-radius:6px;width:24px;height:22px;font-size:12px;cursor:pointer;padding:0;line-height:1">${_uiIcon('edit',13)}</button>`:''}
    </div>`).join('')}
  </div>`;
}

// ════════════════════════════════════════════════════════════════════════════
// FICHES-PARITE-360 Session 2 — Plan d'occupation Gantt immeuble (v14.38).
// Killer feature différenciante vs Qalimo / BailFacile / Smovin.
//
// 36 mois affichés (24 passés + mois courant + 11 futurs) sur PC/tablette,
// 24 mois (12+12) sur mobile (zoom out). Une ligne par logement, des barres
// colorées par locataire (couleur déterministe via hash HSL), zones vacantes
// hachurées rouge léger, marker vertical "Aujourd'hui" pulsé.
//
// Cf docs/subjects/FICHES-PARITE-360.md Session 2.
// ════════════════════════════════════════════════════════════════════════════

// Hash déterministe nom locataire → couleur HSL stable (mémoire visuelle inter-vues).
// Évite la zone rouge (350-20°) pour ne pas confondre avec "vacance".
function _tenantColor(name) {
  if(!name) return 'hsl(220, 12%, 60%)';
  let hash = 0;
  for(let i = 0; i < name.length; i++) {
    hash = ((hash << 5) - hash) + name.charCodeAt(i);
    hash = hash & hash; // force 32-bit
  }
  // Mappe sur 320° (skip 340-360° rouge) puis offset de 20° pour démarrer dans le orange/jaune
  const h = (Math.abs(hash) % 320 + 20);
  return `hsl(${h}, 62%, 52%)`;
}
// Variante claire (pour bordures, glow)
function _tenantColorLight(name) {
  if(!name) return 'hsl(220, 12%, 75%)';
  let hash = 0;
  for(let i = 0; i < name.length; i++) {
    hash = ((hash << 5) - hash) + name.charCodeAt(i);
    hash = hash & hash;
  }
  const h = (Math.abs(hash) % 320 + 20);
  return `hsl(${h}, 62%, 86%)`;
}

// Le Gantt principal — appelé depuis rImmFiche quand sous-onglet 'plan' actif.
// activeLogs = logements non archivés du même immeuble.
function _renderImmFichePlanGantt(ent, im, activeLogs) {
  if(!activeLogs.length) {
    return `<div class="biens-empty">
      <div class="biens-empty-icon">${_uiIcon('calendar',44)}</div>
      <div class="biens-empty-title">Pas encore de logement dans cet immeuble</div>
      <div class="biens-empty-msg">Le plan d'occupation se construira automatiquement dès le premier logement avec un bail.</div>
      <button class="btn bp" onclick="_immFicheNewLog('${_lyQ(ent.nom)}','${_lyQ(im.nom)}')">+ Ajouter un logement</button>
    </div>`;
  }

  // ── Plage temporelle : 24 mois passés + mois courant + 11 futurs = 36 mois
  // (sur mobile on rétrécira à 12+12 = 24 via CSS / option future)
  const today = new Date();
  const TS = (yr, mi, day) => new Date(yr, mi, day || 1).getTime();
  const todayMs = today.getTime();
  // Premier mois (24 mois passés depuis aujourd'hui, jour 1)
  const startDate = new Date(today.getFullYear(), today.getMonth() - 24, 1);
  // Dernier mois exclusif (12 mois futurs)
  const endDate   = new Date(today.getFullYear(), today.getMonth() + 12, 1);
  const startMs = startDate.getTime();
  const endMs   = endDate.getTime();
  const totalMs = endMs - startMs;
  // 36 mois à représenter
  const monthCount = 36;
  const monthLabels = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'];
  const months = [];
  for(let i = 0; i < monthCount; i++) {
    const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
    months.push({
      yr: d.getFullYear(),
      mi: d.getMonth(),
      label: monthLabels[d.getMonth()],
      labelShort: monthLabels[d.getMonth()][0],
      isFuture: d.getTime() > todayMs,
      isCurrent: d.getFullYear() === today.getFullYear() && d.getMonth() === today.getMonth()
    });
  }

  // Position % du marker "Aujourd'hui"
  const todayPct = ((todayMs - startMs) / totalMs) * 100;

  // Helper : convertit une date ISO en % de la timeline (clampée)
  const toPct = isoOrMs => {
    let ms;
    if(typeof isoOrMs === 'string') ms = new Date(isoOrMs + 'T00:00:00').getTime();
    else ms = isoOrMs;
    return Math.max(0, Math.min(100, ((ms - startMs) / totalMs) * 100));
  };

  // ── Pour chaque logement : récupérer les bails, calculer barres + zones vacance
  const todayIso = today.toISOString().slice(0,10);
  const rows = activeLogs.map(log => {
    const bails = _getAllBailsForLog(log.ref); // déjà trié par debut ASC
    // v14.49 — délégation à _bailEcheanceEffective qui gère 3 cas :
    //   1. bail.fin renseigné et future
    //   2. bail.fin renseigné mais passé (tacite reconduction par tranches dureeMois)
    //   3. bail.fin VIDE → calcul depuis debut + dureeMois (3 ans nu, 1 an meublé, etc.)
    // Avant v14.49 le helper retournait null si bail.fin vide (bug ZITO).
    const rawCurrent = DB.baux && DB.baux[log.ref];
    // BAUX-ECHUS — LA règle du type (js/core/bail-echeance.js), la même que la pastille et l'agenda :
    //   • reconduit (nu, meublé, garage de l'app) → la barre court jusqu'à la fin de la période en cours ;
    //   • en cours sans date de fin saisie → la fin théorique (pas une « tacite reconduction ») ;
    //   • arrivé à terme (étudiant, mobilité, garage repris, autre) → JAMAIS reconduit : le locataire est
    //     toujours en place (rien n'est clôturé), la barre réelle court donc jusqu'à aujourd'hui, sans
    //     projection, et le terme est dit dans l'infobulle — plus de « tacite reconduction » inventée.
    const _echCur = rawCurrent ? _bailEcheance(rawCurrent, log) : null;
    const isTaciteReconduction = !!(_echCur && _echCur.statut === 'reconduit' && _echCur.prochaine);
    const _finSansSaisie = (_echCur && _echCur.statut === 'en_cours' && !rawCurrent.fin) ? _echCur.prochaine : null;
    const taciteEnd = isTaciteReconduction ? _echCur.prochaine : _finSansSaisie;
    const arriveATerme = !!(_echCur && _echCur.statut === 'arrive_a_terme');

    // Identifier le bail courant (dernier dans la liste si _type === 'current')
    // pour appliquer la tacite reconduction sur lui uniquement.
    const currentBailIdx = bails.findIndex(b => b._type === 'current');

    const bars = bails.map((b, idx) => {
      const debutMs = b.debut ? new Date(b.debut + 'T00:00:00').getTime() : null;
      if(!debutMs) return null;
      // fin réelle si clôturé, sinon fin théorique (échéance) ; si tacite reconduction,
      // étendre la fin pour ce bail courant à la prochaine échéance anniversaire.
      // b.fin du bail courant = la fin d'OCCUPATION (départ déclaré) : quand elle existe, elle fait foi.
      let finForThis = b.fin;
      if(idx === currentBailIdx && taciteEnd && !b.fin) {
        finForThis = taciteEnd;
      }
      const termeCourant = idx === currentBailIdx && arriveATerme && !b.fin;   // occupé au-delà du terme
      if(termeCourant) finForThis = null;
      const finMs = finForThis ? new Date(finForThis + 'T00:00:00').getTime() : null;
      const realEndMs = finMs ? Math.min(finMs, todayMs) : todayMs;
      const projEndMs = finMs;
      const segments = [];
      // Segment réalisé : [debut → min(fin, today)]
      if(debutMs < realEndMs) {
        segments.push({
          left: toPct(debutMs),
          right: toPct(realEndMs),
          kind: 'real',
          bail: b,
          terme: termeCourant ? _echCur.finContrat : '',
          ended: !termeCourant && !isTaciteReconduction && finForThis && finForThis <= todayIso // bail clôturé
        });
      }
      // Segment projection (de today à fin) : bail courant ou tacite reconduction
      if(projEndMs && projEndMs > todayMs && b.debut <= todayIso && (!finForThis || finForThis >= todayIso)) {
        segments.push({
          left: toPct(Math.max(debutMs, todayMs)),
          right: toPct(projEndMs),
          kind: 'proj',
          bail: b,
          tacite: idx === currentBailIdx && isTaciteReconduction // marquer pour tooltip
        });
      }
      return segments;
    }).filter(Boolean).flat().filter(s => s && (s.right - s.left) > 0.05); // filtrer micro-barres

    // ── v14.48 GANTT-PREAVIS — zone préavis bailleur sur le bail courant
    // 6 mois (nu) ou 3 mois (meublé) avant l'échéance effective.
    let preavisOverlay = null;
    let preavisInfo = null;
    if(rawCurrent) {
      preavisInfo = _bailPreavisInfo(rawCurrent, log);
      if(preavisInfo) {
        const preavisStartMs = new Date(preavisInfo.preavisStart + 'T00:00:00').getTime();
        const preavisFinMs = new Date(preavisInfo.fin + 'T00:00:00').getTime();
        // N'afficher que si la zone préavis est dans la fenêtre visible
        if(preavisFinMs > startMs && preavisStartMs < endMs) {
          preavisOverlay = {
            left: toPct(preavisStartMs),
            right: toPct(preavisFinMs),
            preavisInfo
          };
        }
      }
    }

    // ── v14.46 — calcul des zones de vacance ≥ 3 mois dans la fenêtre 36m
    // Une zone est un span où aucun bail n'est actif.
    // Borné par : début fenêtre (ou debut du 1er bail) à gauche, today (ou fin du dernier bail
    // si pas de tacite reconduction) à droite.
    const vacancySpans = [];
    if(bails.length) {
      // Construire les périodes occupées dans la fenêtre
      const occupied = bails.map((b, idx) => {
        const dMs = new Date(b.debut + 'T00:00:00').getTime();
        let fEnd;
        if(idx === currentBailIdx && arriveATerme && !b.fin) {
          fEnd = Infinity;   // arrivé à terme mais toujours occupé : jamais une vacance
        } else if(idx === currentBailIdx && taciteEnd && !b.fin) {
          fEnd = new Date(taciteEnd + 'T00:00:00').getTime();
        } else {
          fEnd = b.fin ? new Date(b.fin + 'T00:00:00').getTime() : Infinity;
        }
        return [dMs, fEnd];
      }).sort((a,b) => a[0] - b[0]);
      // Premier bail : zone vacance avant si commence après début fenêtre (pas affichée — c'est "avant gestion")
      // Entre baux : zones de gap
      let cursor = startMs;
      // On considère "début gestion" = debut du 1er bail (avant = pas en gestion, hachures ok mais pas de label vacance)
      const firstBailStart = occupied[0][0];
      cursor = Math.max(cursor, firstBailStart);
      for(const [bDeb, bFin] of occupied) {
        if(bDeb > cursor) {
          // gap entre cursor et bDeb
          vacancySpans.push({ startMs: cursor, endMs: Math.min(bDeb, endMs) });
        }
        cursor = Math.max(cursor, bFin);
      }
      // Si après le dernier bail, on est encore dans la fenêtre → zone vacance jusqu'à endMs
      if(cursor < endMs) {
        vacancySpans.push({ startMs: cursor, endMs });
      }
    }
    // Filtrer : ≥ 3 mois ET dans la fenêtre visible
    const MIN_VAC_MS = 90 * 86400000; // ≈ 3 mois
    const visibleVac = vacancySpans
      .map(s => ({ startMs: Math.max(s.startMs, startMs), endMs: Math.min(s.endMs, endMs) }))
      .filter(s => s.endMs - s.startMs >= MIN_VAC_MS);

    // Calcul du loyer ref (dernier bail antérieur) + manque cumul pour chaque zone
    const vacBadges = visibleVac.map(s => {
      const months = Math.round((s.endMs - s.startMs) / (30.44 * 86400000));
      // dernier bail antérieur à cette vacance (basé sur le startMs de la vacance)
      const startIso = new Date(s.startMs).toISOString().slice(0,10);
      const prev = bails.filter(b => b.debut && b.debut <= startIso);
      const lastBail = prev.length ? prev[prev.length - 1] : null;
      const lastRent = lastBail ? (+lastBail.hc || 0) + (+lastBail.ch || 0) : 0;
      const manque = Math.round(months * lastRent);
      return {
        left: toPct(s.startMs),
        right: toPct(s.endMs),
        months,
        manque
      };
    }).filter(v => (v.right - v.left) > 4); // ne label que si la zone fait > 4% de la timeline (~lisible)

    const refSafe = _lyQ(log.ref);
    const typeLabel = (log.type||'').slice(0, 12);
    const surfLabel = log.surf ? `${fmtN(log.surf)} m²` : '';
    const subtitleParts = [typeLabel, surfLabel, log.etage ? `ét. ${log.etage}` : ''].filter(Boolean);

    return { log, refSafe, subtitleParts, bars, vacBadges, preavisOverlay, preavisInfo };
  });

  // ── Mini-strip occupation globale (taux mensuel agrégé sur l'immeuble)
  const stripCells = months.map((m, idx) => {
    const monthStart = new Date(m.yr, m.mi, 1).getTime();
    const monthEnd   = new Date(m.yr, m.mi + 1, 1).getTime();
    let totalLog = 0, occupLog = 0;
    activeLogs.forEach(log => {
      const bails = _getAllBailsForLog(log.ref);
      // Ne compter le logement comme "en gestion" que si au moins un bail a démarré avant ou pendant ce mois
      const startedAny = bails.some(b => b.debut && new Date(b.debut + 'T00:00:00').getTime() < monthEnd);
      if(!startedAny) return; // pas en gestion ce mois → exclure
      totalLog++;
      const active = bails.find(b => {
        if(!b.debut) return false;
        const bDeb = new Date(b.debut + 'T00:00:00').getTime();
        const bFin = b.fin ? new Date(b.fin + 'T00:00:00').getTime() : Infinity;
        return bDeb <= monthEnd - 1 && bFin >= monthStart;
      });
      if(active) occupLog++;
    });
    const pct = totalLog ? Math.round(occupLog / totalLog * 100) : 0;
    // Couleur : vert→jaune→rouge selon taux ; gris si pas de gestion
    let color;
    if(totalLog === 0) color = 'var(--bor)';
    else if(pct >= 95) color = '#16a34a';
    else if(pct >= 70) color = '#22c55e';
    else if(pct >= 40) color = '#f59e0b';
    else if(pct > 0)   color = '#dc2626';
    else color = '#dc2626';
    const opacity = totalLog === 0 ? 0.35 : (m.isFuture ? 0.5 : 0.95);
    const tipMois = `${m.label} ${m.yr}`;
    const tip = totalLog === 0
      ? `${tipMois} — Avant mise en gestion`
      : `${tipMois} — ${pct}% occupation (${occupLog}/${totalLog})`;
    return `<div class="immf-strip-cell${m.isCurrent?' immf-strip-now':''}" style="background:${color};opacity:${opacity}" title="${escHtml(tip)}"></div>`;
  }).join('');

  // ── Stats footer (occup moy 24m, durée bail moyenne, manque à gagner cumul)
  let totalMoisOccupes = 0, totalMoisGestion = 0;
  let dureesBails = []; // mois par bail terminé
  let manqueCumul = 0;
  activeLogs.forEach(log => {
    const bails = _getAllBailsForLog(log.ref);
    if(!bails.length) return;
    // Occupation 24m : compter mois loué vs total mois en gestion sur les 24 derniers mois
    for(let i = 23; i >= 0; i--) {
      const d = new Date(today.getFullYear(), today.getMonth() - i, 15);
      const ms15 = d.getTime();
      const startedAny = bails.some(b => b.debut && new Date(b.debut + 'T00:00:00').getTime() <= ms15);
      if(!startedAny) continue;
      totalMoisGestion++;
      const active = bails.find(b => {
        const bDeb = new Date(b.debut + 'T00:00:00').getTime();
        const bFin = b.fin ? new Date(b.fin + 'T00:00:00').getTime() : Infinity;
        return bDeb <= ms15 && bFin >= ms15;
      });
      if(active) totalMoisOccupes++;
      else {
        // Manque à gagner du mois sur la base du dernier bail antérieur
        // R0-H : le loyer de CE mois-là, lu au barème puis au bail (même lecteur que partout
        // ailleurs). Avant : `prev[prev.length-1]`, le dernier ÉLÉMENT du tableau.
        // `ms15` est un timestamp LOCAL : `toISOString()` le reconvertit en UTC et rend le 14
        // sous tout fuseau à offset positif. On formate donc localement, comme `active` le lit.
        const _d15 = new Date(ms15);
        const _iso15 = _d15.getFullYear() + '-' + String(_d15.getMonth()+1).padStart(2,'0')
          + '-' + String(_d15.getDate()).padStart(2,'0');
        const _ld15 = (typeof loyerDuLotA === 'function')
          ? loyerDuLotA(_iso15, log.ref, _ctxLoyerLot(log.ref, log))
          : null;
        if (_ld15) manqueCumul += _ld15.hc + _ld15.ch;
        else {
          const prev = bails.filter(b => b.debut && new Date(b.debut + 'T00:00:00').getTime() <= ms15);
          if(prev.length) {
            const last = prev[prev.length - 1];
            manqueCumul += (+last.hc || 0) + (+last.ch || 0);
          }
        }
      }
    }
    // Durées des baux clôturés (en mois)
    bails.filter(b => b.debut && b.fin).forEach(b => {
      const months = _monthsBetweenIso(b.debut, b.fin);
      if(months > 0) dureesBails.push(months);
    });
  });
  const tauxOccup24m = totalMoisGestion ? Math.round(totalMoisOccupes / totalMoisGestion * 100) : 0;
  const dureeMoy = dureesBails.length ? Math.round(dureesBails.reduce((a,b)=>a+b,0) / dureesBails.length) : 0;
  const dureeTxt = dureeMoy >= 12
    ? `${Math.floor(dureeMoy/12)} an${dureeMoy>=24?'s':''}${dureeMoy%12 ? ' '+(dureeMoy%12)+'m' : ''}`
    : (dureeMoy ? `${dureeMoy} mois` : '—');

  // v14.48 GANTT-PREAVIS — compteur baux en zone préavis (today entre preavisStart et fin)
  let preavisCount = 0;
  let preavisNext = null; // bail dont le préavis est le plus proche (urgent)
  rows.forEach(r => {
    if(r.preavisInfo && r.preavisInfo.inPreavisZone) {
      preavisCount++;
      if(!preavisNext || r.preavisInfo.daysToFin < preavisNext.daysToFin) preavisNext = r.preavisInfo;
    }
  });

  // ── Construction des labels d'année (afficher quand le millésime change)
  let lastYear = null;
  const monthHeaders = months.map((m, idx) => {
    const showYear = m.yr !== lastYear;
    lastYear = m.yr;
    return `<div class="immf-gantt-mh${m.isCurrent?' immf-gantt-mh-now':''}${m.isFuture?' immf-gantt-mh-fut':''}">
      <span class="immf-gantt-mh-month">${m.labelShort}</span>
      ${showYear ? `<span class="immf-gantt-mh-year">${m.yr}</span>` : ''}
    </div>`;
  }).join('');

  // ── Render des lignes
  const rowsHtml = rows.map(({log, refSafe, subtitleParts, bars, vacBadges, preavisOverlay, preavisInfo}) => {
    const barsHtml = bars.map(seg => {
      const b = seg.bail;
      const tenant = b.nom || (b.locataires && b.locataires[0] && b.locataires[0].nom) || '—';
      const color = _tenantColor(tenant);
      const colorLight = _tenantColorLight(tenant);
      const loyer = (+b.hc || 0) + (+b.ch || 0);
      const finTxt = b.fin ? fd(b.fin) : 'en cours';
      const debutTxt = b.debut ? fd(b.debut) : '?';
      // v14.46 — tooltip enrichi : indique tacite reconduction ou bail clôturé
      let kindSuffix = '';
      if(seg.kind === 'proj') {
        kindSuffix = seg.tacite ? ' (tacite reconduction → prochaine échéance)' : ' (échéance projetée)';
      } else if(seg.terme) {
        kindSuffix = ' (arrivé à terme le ' + fd(seg.terme) + ', non reconduit — locataire toujours en place)';
      } else if(seg.ended) {
        kindSuffix = ' (bail terminé)';
      }
      const tip = `${tenant} · ${debutTxt} → ${finTxt}${loyer ? ' · '+fmt(loyer)+'/mois' : ''}${kindSuffix}`;
      const widthPct = seg.right - seg.left;
      const showLabel = widthPct > 6;
      const segCls = seg.kind === 'proj'
        ? 'immf-gantt-bar-proj'
        : ('immf-gantt-bar-real' + (seg.ended ? ' immf-gantt-bar-ended' : ''));
      return `<div class="immf-gantt-bar ${segCls}" data-tenant="${escHtml(tenant)}"
        style="left:${seg.left.toFixed(2)}%;width:${widthPct.toFixed(2)}%;background:${color};border-color:${colorLight}"
        title="${escHtml(tip)}"
        onclick="event.stopPropagation();openLogFiche('${refSafe}')"
        onmouseenter="_ganttHighlight('${_lyQ(tenant)}',true)"
        onmouseleave="_ganttHighlight('${_lyQ(tenant)}',false)">
        ${showLabel ? `<span class="immf-gantt-bar-lbl">${escHtml(tenant)}</span>` : ''}
      </div>`;
    }).join('');

    // v14.46 — labels zones de vacance ≥ 3 mois et > 4% de la timeline
    const vacHtml = (vacBadges||[]).map(v => {
      const widthPct = v.right - v.left;
      const moisTxt = v.months >= 12
        ? `${Math.floor(v.months/12)}an${v.months>=24?'s':''}${v.months%12 ? ' '+(v.months%12)+'m' : ''}`
        : `${v.months} mois`;
      const manqueTxt = v.manque > 0 ? ` · -${fmt(v.manque)}` : '';
      // Label : full si large (>10%), compact (juste durée) si étroit
      const isNarrow = widthPct < 10;
      const labelTxt = isNarrow ? moisTxt : `Vacant ${moisTxt}${manqueTxt}`;
      const tip = `Vacance · ${moisTxt}${v.manque > 0 ? ' · manque à gagner cumulé '+fmt(v.manque) : ''}`;
      return `<div class="immf-gantt-vac" style="left:${v.left.toFixed(2)}%;width:${widthPct.toFixed(2)}%" title="${escHtml(tip)}">
        <span class="immf-gantt-vac-lbl">🚫 ${escHtml(labelTxt)}</span>
      </div>`;
    }).join('');

    // v14.48 — overlay zone préavis bailleur (orange) sur la projection du bail courant
    let preavisHtml = '';
    if(preavisOverlay && preavisInfo) {
      const widthPct = preavisOverlay.right - preavisOverlay.left;
      const monthsLabel = preavisInfo.preavisMonths;
      const tip = `⚠️ Préavis bailleur ${monthsLabel} mois (bail ${preavisInfo.isMeuble?'meublé':'nu'})\nÀ donner avant le ${fd(preavisInfo.preavisStart)}\nÉchéance : ${fd(preavisInfo.fin)}`;
      const isUrgent = preavisInfo.inPreavisZone;
      preavisHtml = `<div class="immf-gantt-preavis${isUrgent?' immf-gantt-preavis-urgent':''}"
        style="left:${preavisOverlay.left.toFixed(2)}%;width:${widthPct.toFixed(2)}%"
        title="${escHtml(tip)}">
        ${widthPct > 8 ? `<span class="immf-gantt-preavis-lbl">${_uiIcon('warn',13)} Préavis ${monthsLabel}m</span>` : ''}
      </div>`;
    }

    // v14.48 — badge ⚠️ urgent sur le label de la ligne si en zone préavis aujourd'hui
    const preavisBadge = (preavisInfo && preavisInfo.inPreavisZone)
      ? `<span class="immf-gantt-rowlabel-warn" title="Préavis bailleur à donner avant le ${fd(preavisInfo.preavisStart)} (échéance ${fd(preavisInfo.fin)})">${_uiIcon('warn',13)}</span>`
      : '';

    return `<div class="immf-gantt-row${preavisInfo&&preavisInfo.inPreavisZone?' immf-gantt-row-preavis':''}" onclick="openLogFiche('${refSafe}')" tabindex="0" onkeydown="if(event.key==='Enter')openLogFiche('${refSafe}')">
      <div class="immf-gantt-rowlabel">
        <div class="immf-gantt-rowlabel-ref">${escHtml(_logLabel(log))}${preavisBadge}</div>
        ${subtitleParts.length ? `<div class="immf-gantt-rowlabel-sub">${escHtml(subtitleParts.join(' · '))}</div>` : ''}
      </div>
      <div class="immf-gantt-track">
        ${vacHtml}
        ${barsHtml}
        ${preavisHtml}
      </div>
    </div>`;
  }).join('');

  return `<div class="immf-gantt-wrap">
    <div class="immf-gantt-head">
      <div class="immf-gantt-head-l">
        <div class="immf-gantt-head-title">${_uiIcon('calendar')} Plan d'occupation</div>
        <div class="immf-gantt-head-sub">24 mois passés · aujourd'hui · 12 mois projetés</div>
      </div>
      <div class="immf-gantt-head-r">
        <span class="immf-gantt-legend"><i class="ig-dot ig-real"></i> Bail actuel/passé</span>
        <span class="immf-gantt-legend"><i class="ig-dot ig-proj"></i> Échéance projetée</span>
        <span class="immf-gantt-legend"><i class="ig-dot ig-vac"></i> Vacance</span>
      </div>
    </div>

    <!-- Mini-strip taux occupation global (1 ligne, 8px) -->
    <div class="immf-gantt-row immf-gantt-row-strip" aria-label="Taux d'occupation mensuel agrégé sur l'immeuble">
      <div class="immf-gantt-rowlabel">
        <div class="immf-gantt-rowlabel-ref">Occup. mensuelle</div>
        <div class="immf-gantt-rowlabel-sub">${activeLogs.length} logement${activeLogs.length>1?'s':''}</div>
      </div>
      <div class="immf-gantt-track immf-gantt-strip">
        ${stripCells}
        <div class="immf-gantt-today" style="left:${todayPct.toFixed(2)}%" aria-hidden="true"></div>
      </div>
    </div>

    <!-- Header mois -->
    <div class="immf-gantt-row immf-gantt-row-header">
      <div class="immf-gantt-rowlabel"></div>
      <div class="immf-gantt-track immf-gantt-track-headers">
        ${monthHeaders}
        <div class="immf-gantt-today" style="left:${todayPct.toFixed(2)}%" aria-hidden="true"></div>
      </div>
    </div>

    <!-- Lignes logements -->
    <div class="immf-gantt-body">
      ${rowsHtml}
      <!-- Marker today vertical sur le body entier (en plus des markers des lignes) -->
    </div>

    <!-- Stats footer -->
    <div class="immf-gantt-footer">
      <div class="logf-hero-stats logf-hero-stats-4">
        <div class="logf-stat">
          <div class="logf-stat-v k-num ${tauxOccup24m===100?'k-ok':(tauxOccup24m>=70?'':'k-warn')}">${tauxOccup24m}%</div>
          <div class="logf-stat-l">Taux d'occupation moyen 24 mois</div>
        </div>
        <div class="logf-stat">
          <div class="logf-stat-v k-num">${dureeTxt}</div>
          <div class="logf-stat-l">Durée moyenne d'un bail</div>
        </div>
        <div class="logf-stat">
          <div class="logf-stat-v k-money ${manqueCumul>0?'k-warn':'k-ok'}">${manqueCumul>0?'-':''}${fmt(manqueCumul)}</div>
          <div class="logf-stat-l">Manque à gagner cumulé 24m</div>
        </div>
        <div class="logf-stat${preavisCount>0?' logf-stat-warn':''}" title="${preavisNext ? `Plus proche échéance : ${fd(preavisNext.fin)} (préavis ${preavisNext.preavisMonths}m)` : 'Aucun bail en zone préavis'}">
          <div class="logf-stat-v k-num ${preavisCount>0?'k-warn':'k-ok'}">${preavisCount>0?'' + _uiIcon('warn') + ' '+preavisCount:'' + _uiIcon('check') + ' 0'}</div>
          <div class="logf-stat-l">Préavis bailleur à donner${preavisNext?` <small>(éch. ${fd(preavisNext.fin)})</small>`:''}</div>
        </div>
      </div>
    </div>
  </div>`;
}

// Highlight cross-row : sur hover d'une barre, on illumine toutes les barres du même locataire.
function _ganttHighlight(tenant, on) {
  if(!tenant) return;
  document.querySelectorAll('.immf-gantt-bar').forEach(b => {
    if(b.getAttribute('data-tenant') === tenant) {
      b.classList.toggle('immf-gantt-bar-hl', on);
    } else if(on) {
      b.classList.add('immf-gantt-bar-dim');
    } else {
      b.classList.remove('immf-gantt-bar-dim');
    }
  });
}

// ════════════════════════════════════════════════════════════════════════════
// FICHES-PARITE-360 Session 8 — Compteurs collectifs + Charges communes (v14.59)
// Phase 1 : sous-onglet "⚡ Charges communes" sur fiche immeuble.
//
// Permet au bailleur de :
//   - Saisir 1 ou plusieurs compteurs collectifs (eau, élec parties communes, gaz...)
//   - Définir une clé de répartition par compteur (mixable) :
//     · 'tantiemes'      : selon log.tantiemes / 1000 (lot copro)
//     · 'surface'        : selon log.surf / sum(surfaces immeuble)
//     · 'sous-compteurs' : selon conso log (relevés divisionnaires) / sum(consos)
//     · 'forfait'        : parts manuelles définies par bailleur
//   - Saisir relevés et factures du compteur général
//   - Voir le tableau auto-calculé des quotes-parts par logement
//
// Stockage : ent.immeubles[i].compteursCollectifs[] (sub-collection imm)
// ════════════════════════════════════════════════════════════════════════════

// Configuration des types de compteurs collectifs (réutilise la palette logement)
// v14.68 — enrichi avec chauffage / ascenseur / entretien-pc + types custom user (DB.params.ccTypesCustom)
const CC_TYPES = [
  { key: 'eau-f',        label: 'Eau froide générale',          unit: 'm³',  icon: '💧', color: '#3b82f6' },
  { key: 'eau-c',        label: 'Eau chaude générale',          unit: 'm³',  icon: '🚿', color: '#0ea5e9' },
  { key: 'elec',         label: 'Électricité parties communes', unit: 'kWh', icon: '⚡', color: '#f59e0b' },
  { key: 'gaz',          label: 'Gaz collectif',                unit: 'm³',  icon: '🔥', color: '#dc2626' },
  { key: 'chauff',       label: 'Chauffage collectif',          unit: 'kWh', icon: '🔥', color: '#ea580c' },
  { key: 'ascenseur',    label: 'Ascenseur',                    unit: '',    icon: '🛗', color: '#7c3aed' },
  { key: 'entretien-pc', label: 'Entretien parties communes',   unit: '',    icon: '🧹', color: '#10b981' },
  { key: 'autre',        label: 'Autre',                        unit: '',    icon: '📊', color: '#64748b' }
];

// v14.68 — Récupère TOUS les types disponibles (built-in + user custom DB.params.ccTypesCustom)
function _allCcTypes() {
  const custom = (DB && DB.params && Array.isArray(DB.params.ccTypesCustom)) ? DB.params.ccTypesCustom : [];
  return [...CC_TYPES, ...custom];
}

// v14.68 — Génère les <option> du select Type compteur (utilisé par les modales)
function _renderCcTypesOptions(selectedKey) {
  return _allCcTypes().map(t =>
    `<option value="${t.key}"${t.key===selectedKey?' selected':''}>${escHtml(t.label)}${t.unit?' ('+t.unit+')':''}</option>`
  ).join('');
}

// v14.68 — Génère les <option> du select Clé de répartition
function _renderCcRepartOptions(selectedKey) {
  return Object.entries(CC_REPARTITION_LABELS).map(([k,v]) =>
    `<option value="${k}"${k===selectedKey?' selected':''}>${escHtml(v.label)}</option>`
  ).join('');
}

// v14.68 — Génère le hint descriptif d'une clé de répartition
function _ccRepartHint(key) {
  const v = CC_REPARTITION_LABELS[key];
  return v ? v.desc : '';
}

const CC_REPARTITION_LABELS = {
  'tantiemes':      { label: 'Tantièmes / millièmes',     icon: '🔢', desc: 'Selon log.tantiemes (lot copro)' },
  'surface':        { label: 'Surface (m²)',               icon: '📐', desc: 'Selon log.surf' },
  'sous-compteurs': { label: 'Sous-compteurs (réel)',      icon: '📊', desc: 'Selon conso individuelle relevée' },
  // v14.61 : parts égales 1/N par logement (TV collective, antenne, vidéo-surveillance...)
  'proportionnel':  { label: 'Proportionnel (1/N parts égales)', icon: '⚖️', desc: 'Division par le nombre de logements (chaque logement compte pour 1)' },
  'forfait':        { label: 'Forfait (parts manuelles)',  icon: '✋', desc: 'Parts définies manuellement par logement' },
  // CDC Charges É1b : clé Mixte — combine plusieurs clés en % (moteur composite _calcCcRepartition).
  'composite':      { label: 'Mixte (plusieurs clés en %)', icon: '🧩', desc: 'Combine plusieurs clés (ex. chauffage 50 % tantièmes + 50 % sous-compteurs)' }
};
// Clés « simples » proposables dans une composition Mixte (composite exclu = pas de récursion).
const CC_SIMPLE_KEYS = ['tantiemes','surface','sous-compteurs','proportionnel','forfait'];

// Calcule la quote-part d'un logement sur un compteur collectif.
// Retourne { ratio: 0-1, methode, denomLabel, exclu? } ou null si exclu/non-applicable.
// `cumulSurface` et `cumulTantiemes` sont passés pour éviter de re-calculer dans la boucle.
function _calcCcQuotePart(im, log, cc, allLogs) {
  if(!im || !log || !cc) return null;
  const mode = cc.cleRepartition || 'tantiemes';

  // CDC Charges É1b — Mixte : ratio pondéré = Σ (ratio de la ligne × quote-part de sa clé simple).
  if(mode === 'composite' && Array.isArray(cc.composition)) {
    let ratio = 0;
    for(const ligne of cc.composition.filter(c => c && c.ratio > 0 && CC_SIMPLE_KEYS.includes(c.cle))) {
      const sub = _calcCcQuotePart(im, log, Object.assign({}, cc, { cleRepartition: ligne.cle, composition: null }), allLogs);
      if(sub && !sub.exclu) ratio += (sub.ratio || 0) * ligne.ratio;
    }
    return { ratio, methode: 'composite', denomLabel: 'Mixte' };
  }

  if(mode === 'tantiemes') {
    const t = +log.tantiemes || 0;
    if(!t) return { ratio: 0, methode: 'tantiemes', denomLabel: 'Tantièmes non renseignés', exclu: true };
    const sum = (allLogs||[]).reduce((s,l)=>s+(+l.tantiemes||0), 0);
    if(!sum) return { ratio: 0, methode: 'tantiemes', denomLabel: 'Total tantièmes 0', exclu: true };
    return { ratio: t/sum, methode: 'tantiemes', denomLabel: `${t} / ${sum} tantièmes` };
  }

  if(mode === 'surface') {
    const s = +log.surf || 0;
    if(!s) return { ratio: 0, methode: 'surface', denomLabel: 'Surface non renseignée', exclu: true };
    const sum = (allLogs||[]).reduce((acc,l)=>acc+(+l.surf||0), 0);
    if(!sum) return { ratio: 0, methode: 'surface', denomLabel: 'Total surfaces 0', exclu: true };
    return { ratio: s/sum, methode: 'surface', denomLabel: `${fmtN(s)} / ${fmtN(sum)} m²` };
  }

  if(mode === 'forfait') {
    const parts = cc.forfaitParts || {};
    const v = +parts[log.ref];
    if(!isFinite(v) || v <= 0) return { ratio: 0, methode: 'forfait', denomLabel: 'Pas de part définie', exclu: true };
    // Si parts en %, normaliser ; si parts en valeur libre, normaliser sur la somme.
    const sum = Object.values(parts).reduce((a,b) => a + (+b||0), 0);
    if(!sum) return { ratio: 0, methode: 'forfait', denomLabel: 'Total parts 0', exclu: true };
    return { ratio: v/sum, methode: 'forfait', denomLabel: `${v} / ${sum} parts` };
  }

  // v14.61 : parts égales — chaque logement compte pour 1 (TV collective, antenne, vidéo)
  if(mode === 'proportionnel') {
    const N = (allLogs||[]).length;
    if(N <= 0) return { ratio: 0, methode: 'proportionnel', denomLabel: 'Aucun logement', exclu: true };
    return { ratio: 1/N, methode: 'proportionnel', denomLabel: `1 / ${N} logements` };
  }

  if(mode === 'sous-compteurs') {
    // Conso individuelle = somme conso pendant la période (entre 2 derniers relevés)
    // V1 simplifiée : conso = (dernier relevé - 1er relevé) du logement, type matchant
    // CDC Charges §13 : élec = HP + HC (avant : HP seul). cptTypes = liste des index à sommer.
    const cptTypes = (cc.type === 'eau-c') ? ['eau-c'] : (cc.type === 'eau-f') ? ['eau-f']
                  : (cc.type === 'elec')  ? ['elec-hp','elec-hc'] : (cc.type === 'gaz') ? ['gaz'] : null;
    if(!cptTypes) return { ratio: 0, methode: 'sous-compteurs', denomLabel: 'Type non mappable', exclu: true };
    // Helper : conso totale du logement sur le(s) type(s) (somme HP+HC pour l'élec)
    // (Bug #8 perf O(N²) connu — acceptable pour <100 logements V1, à refondre si nécessaire)
    const consoOf = (l) => {
      if(typeof _collectCompteurReleves !== 'function') return 0;
      const rs = _collectCompteurReleves(l.ref);
      if(!rs) return 0;
      let total = 0;
      for(const t of cptTypes){
        const arr = rs[t] || [];
        if(arr.length < 2) continue;
        total += arr[arr.length-1].value - arr[0].value;
      }
      return total;
    };
    const c = consoOf(log);
    if(c <= 0) return { ratio: 0, methode: 'sous-compteurs', denomLabel: 'Pas de conso relevée', exclu: true };
    const sum = (allLogs||[]).reduce((acc,l) => acc + (consoOf(l)>0 ? consoOf(l) : 0), 0);
    if(!sum) return { ratio: 0, methode: 'sous-compteurs', denomLabel: 'Total conso 0', exclu: true };
    return { ratio: c/sum, methode: 'sous-compteurs', denomLabel: `${fmtN(c)} / ${fmtN(sum)} ${cc.unit||''}` };
  }

  return null;
}

// ════════════════════════════════════════════════════════════════════════════
// v14.61 CHARGES-COMMUNES Phase 2 — Helper unifié _calcCcRepartition
// ────────────────────────────────────────────────────────────────────────────
// Calcule la répartition COMPLÈTE d'une facture (mouvement) sur les logements
// d'un immeuble selon la clé de répartition du compteur. Gère :
//   • Part locataires (ratio × prorata jours occupation)
//   • Part bailleur (vacances) avec dimension isBailleur=true
//   • Scope restreint (cc.scope = liste de logRefs)
//   • Composition (chaînage de plusieurs clés, ex chauffage 30/70)
//   • Fallback pour sous-compteurs partiels (cc.fallbackRepartition)
//   • Exclusions (compteCharges=false, données manquantes)
//
// Retourne :
//   { parts: [{ref, locataire, montant, occJours, methode, isBailleur, exclu, raison}],
//     totaux: { montantFacture, totalLocataires, totalBailleur, totalExclu } }
//
// IMPORTANT : ce helper est conçu pour la régul (Phase 3 v14.62) qui boucle
// sur les mouvements liés à un compteur sur une période. Pour la card Phase 1
// (vue annuelle simple), _calcCcQuotePart suffit.
// ════════════════════════════════════════════════════════════════════════════

// Filtre les logements selon scope explicite + compteCharges
function _ccLogsInScope(cc, allLogs) {
  let logs = (allLogs||[]).filter(l => l && _isAlive(l));
  // Scope explicite (sous-ensemble du cas 2)
  if(cc.scope && cc.scope.length > 0) {
    logs = logs.filter(l => cc.scope.includes(l.ref));
  }
  // Compte-charges = exclusion garages/parkings/caves
  logs = logs.filter(l => l.compteCharges !== false);
  return logs;
}

// Calcule la conso individuelle d'un logement sur le type de compteur,
// idéalement bornée sur une période donnée [periodFrom, periodTo].
// Si pas de relevés encadrant la période, retourne 0.
function _ccConsoLogPeriod(log, ccType, periodFrom, periodTo) {
  if(typeof _collectCompteurReleves !== 'function') return 0;
  // CDC Charges §13 : élec = HP + HC (avant : HP seul) → liste des index à sommer.
  const cptTypes = (ccType === 'eau-c') ? ['eau-c']
                : (ccType === 'eau-f') ? ['eau-f']
                : (ccType === 'elec')  ? ['elec-hp','elec-hc']
                : (ccType === 'gaz')   ? ['gaz'] : null;
  if(!cptTypes) return 0;
  const all = _collectCompteurReleves(log.ref);
  if(!all) return 0;
  let total = 0;
  for(const cptType of cptTypes){
    const arr = all[cptType] || [];
    if(arr.length < 2) continue;
    // Si pas de bornage période → utilise dernier - premier (V1)
    if(!periodFrom || !periodTo) { total += arr[arr.length-1].value - arr[0].value; continue; }
    // Bornage : trouve dernier relevé <= periodFrom et dernier <= periodTo
    const before = arr.filter(r => (r.date||'') <= periodFrom).pop();
    const within = arr.filter(r => (r.date||'') <= periodTo);
    if(!within.length) continue;
    const start = before ? before.value : within[0].value;
    const end = within[within.length-1].value;
    total += Math.max(0, end - start);
  }
  return total;
}

// Calcul prorata jours d'occupation d'un logement par locataire sur la période.
// Retourne [{ bailId, locataire, debut, fin, occDays }] segments + total
// vacance non couverte par un bail (= part bailleur).
function _ccLogOccupations(log, periodFrom, periodTo) {
  // Helpers de date
  const fromMs = new Date(periodFrom + 'T00:00:00').getTime();
  const toMs = new Date(periodTo + 'T00:00:00').getTime();
  const totalDays = Math.max(1, Math.round((toMs - fromMs) / 86400000) + 1);
  // Décalage en jours CALENDAIRES (± 24 h de ms tombe à 23 h / 1 h aux changements d'heure) ;
  // dates formatées en LOCAL (_isoLocal) : toISOString() donnerait la veille en UTC+ (Paris).
  const _jourDecale = (ms, n) => { const d = new Date(ms); d.setDate(d.getDate() + n); return d; };
  const segments = [];
  // Bails : courant + historique (même structure que _getAllBailsForLog)
  const bails = (typeof _getAllBailsForLog === 'function') ? _getAllBailsForLog(log.ref) : [];
  // Trier les bails par debut
  const sorted = bails.slice().sort((a,b) => (a.debut||'').localeCompare(b.debut||''));
  let cursorMs = fromMs;
  for(const b of sorted) {
    if(!b.debut) continue;
    const bDebMs = Math.max(fromMs, new Date(b.debut + 'T00:00:00').getTime());
    const bFinMs = Math.min(toMs, b.fin ? new Date(b.fin + 'T00:00:00').getTime() : toMs);
    if(bDebMs > toMs || bFinMs < fromMs) continue;
    // Période avant ce bail (si gap depuis cursor) → vacance bailleur
    if(bDebMs > cursorMs) {
      const vacDays = Math.round((bDebMs - cursorMs) / 86400000);
      if(vacDays > 0) segments.push({ bailId: null, locataire: '—', debut: _isoLocal(new Date(cursorMs)), fin: _isoLocal(_jourDecale(bDebMs, -1)), occDays: vacDays, isBailleur: true });
    }
    // Période du bail
    const occDays = Math.round((bFinMs - bDebMs) / 86400000) + 1;
    if(occDays > 0) segments.push({
      bailId: b._type === 'current' ? 'current' : 'hist',
      locataire: b.nom || '—',
      debut: _isoLocal(new Date(bDebMs)),
      fin: _isoLocal(new Date(bFinMs)),
      occDays, isBailleur: false
    });
    cursorMs = Math.max(cursorMs, _jourDecale(bFinMs, 1).getTime());
  }
  // Vacance résiduelle après le dernier bail
  if(cursorMs <= toMs) {
    const vacDays = Math.round((toMs - cursorMs) / 86400000) + 1;
    if(vacDays > 0) segments.push({ bailId: null, locataire: '—', debut: _isoLocal(new Date(cursorMs)), fin: periodTo, occDays: vacDays, isBailleur: true });
  }
  // Si aucun bail du tout : tout en vacance bailleur
  if(segments.length === 0) segments.push({ bailId: null, locataire: '—', debut: periodFrom, fin: periodTo, occDays: totalDays, isBailleur: true });
  return { segments, totalDays };
}

// Helper interne — applique une clé simple (sans composition, sans sous-compteurs hybrides)
// sur un montant donné, pour un sous-ensemble de logements. Utilisé par _calcCcRepartition
// et la composition.
function _ccApplyCleSimple(cle, montant, logs, cc, im) {
  const out = {};
  if(!logs.length || !montant || montant === 0) return out;
  if(cle === 'tantiemes') {
    const sumT = logs.reduce((s,l) => s + (+l.tantiemes||0), 0);
    if(sumT <= 0) {
      logs.forEach(l => out[l.ref] = { ratio: 0, montant: 0, methode: 'tantiemes', exclu: true, raison: 'Total tantièmes 0' });
      return out;
    }
    logs.forEach(l => {
      const t = +l.tantiemes||0;
      if(t === 0) out[l.ref] = { ratio: 0, montant: 0, methode: 'tantiemes', exclu: true, raison: 'Tantièmes non saisis' };
      else out[l.ref] = { ratio: t/sumT, montant: montant * (t/sumT), methode: 'tantiemes', denomLabel: `${t} / ${sumT}` };
    });
    return out;
  }
  if(cle === 'surface') {
    const sumS = logs.reduce((s,l) => s + (+l.surf||0), 0);
    if(sumS <= 0) {
      logs.forEach(l => out[l.ref] = { ratio: 0, montant: 0, methode: 'surface', exclu: true, raison: 'Surfaces non saisies' });
      return out;
    }
    logs.forEach(l => {
      const s = +l.surf||0;
      if(s === 0) out[l.ref] = { ratio: 0, montant: 0, methode: 'surface', exclu: true, raison: 'Surface non saisie' };
      else out[l.ref] = { ratio: s/sumS, montant: montant * (s/sumS), methode: 'surface', denomLabel: `${fmtN(s)} / ${fmtN(sumS)} m²` };
    });
    return out;
  }
  if(cle === 'proportionnel') {
    const N = logs.length;
    if(N <= 0) return out;
    const ratio = 1/N;
    logs.forEach(l => out[l.ref] = { ratio, montant: montant * ratio, methode: 'proportionnel', denomLabel: `1 / ${N} logements` });
    return out;
  }
  if(cle === 'forfait') {
    const parts = cc.forfaitParts || {};
    const sum = logs.reduce((s,l) => s + (+parts[l.ref]||0), 0);
    if(sum <= 0) {
      logs.forEach(l => out[l.ref] = { ratio: 0, montant: 0, methode: 'forfait', exclu: true, raison: 'Aucune part forfait définie' });
      return out;
    }
    logs.forEach(l => {
      const v = +parts[l.ref]||0;
      if(v === 0) out[l.ref] = { ratio: 0, montant: 0, methode: 'forfait', exclu: true, raison: 'Part forfait non définie' };
      else out[l.ref] = { ratio: v/sum, montant: montant * (v/sum), methode: 'forfait', denomLabel: `${v} / ${sum}` };
    });
    return out;
  }
  return out;
}

// Helper — applique le mode sous-compteurs avec fallback pour les logements
// SANS sous-compteur. Si fallback non défini, exclus.
function _ccApplySousCompteurs(montant, logs, cc, im, periodFrom, periodTo) {
  const out = {};
  // Conso de chaque logement bornée sur la période
  const conso = {};
  logs.forEach(l => { conso[l.ref] = _ccConsoLogPeriod(l, cc.type, periodFrom, periodTo); });
  const avecCompteur = logs.filter(l => conso[l.ref] > 0);
  const sansCompteur = logs.filter(l => conso[l.ref] <= 0);
  // Calcul des parts au réel
  const sumAvec = avecCompteur.reduce((s,l) => s + conso[l.ref], 0);
  if(sumAvec > 0 && avecCompteur.length > 0) {
    // Part proportionnelle à la conso individuelle, sur le total mesuré
    avecCompteur.forEach(l => {
      const ratio = conso[l.ref] / sumAvec;
      out[l.ref] = {
        ratio, montant: 0, // recalculé après
        methode: 'sous-compteurs', denomLabel: `${fmtN(conso[l.ref])} / ${fmtN(sumAvec)} ${_ccType(cc).unit}`
      };
    });
  }
  // Si fallback défini, applique sur les logements SANS compteur (sur le RESTE)
  if(sansCompteur.length > 0) {
    if(cc.fallbackRepartition && cc.fallbackRepartition !== 'sous-compteurs') {
      // V1 simple : on calcule d'abord les parts au réel proportionnellement (= 100% du montant si tous fallback)
      // Approche honnête : si tous logements avaient sous-compteur, on aurait imputé 100%. Ici, on impute :
      //   - Aux logements avec compteur : leur part proportionnelle de conso
      //   - Aux logements sans compteur : la quote-part fallback du RESTE (= montant - parts conso)
      const partAvec = avecCompteur.reduce((s,l) => s + (out[l.ref].ratio || 0), 0);
      // Si avecCompteur prend X% du montant, le reste (1-X%) va aux sans compteur via fallback
      const reste = montant * (1 - partAvec);
      // Appliquer ratio conso × montant pour avecCompteur
      avecCompteur.forEach(l => {
        out[l.ref].montant = (out[l.ref].ratio || 0) * montant;
      });
      // Appliquer fallback sur reste
      const fallbackParts = _ccApplyCleSimple(cc.fallbackRepartition, reste, sansCompteur, cc, im);
      Object.keys(fallbackParts).forEach(ref => {
        const p = fallbackParts[ref];
        out[ref] = { ...p, methode: 'fallback ' + p.methode, fallbackOf: 'sous-compteurs' };
      });
    } else {
      // Pas de fallback → exclus
      sansCompteur.forEach(l => {
        out[l.ref] = { ratio: 0, montant: 0, methode: 'sous-compteurs', exclu: true, raison: 'Pas de relevé sous-compteur sur la période' };
      });
      // Avec compteur : ratio × montant
      avecCompteur.forEach(l => { out[l.ref].montant = (out[l.ref].ratio||0) * montant; });
    }
  } else if(avecCompteur.length > 0) {
    avecCompteur.forEach(l => { out[l.ref].montant = (out[l.ref].ratio||0) * montant; });
  }
  return out;
}

// Helper principal : calcule la répartition complète d'un montant facture
// pour un compteur donné, sur un sous-ensemble de logements + période.
// Le prorata jours d'occupation EST appliqué (sauf pour sous-compteurs où la
// conso intègre déjà la durée de présence).
function _calcCcRepartition(im, cc, allLogs, montant, periodFrom, periodTo) {
  const result = {
    parts: [],
    totaux: { montantFacture: montant, totalLocataires: 0, totalBailleur: 0, totalExclu: 0 }
  };
  if(!im || !cc || !montant) return result;
  const logs = _ccLogsInScope(cc, allLogs);
  if(!logs.length) return result;

  // Composition : chaque ligne = un sous-montant + sa propre clé
  const lignes = (cc.cleRepartition === 'composite' && Array.isArray(cc.composition))
    ? cc.composition.filter(c => c && c.ratio > 0 && c.cle)
    : [{ ratio: 1, cle: cc.cleRepartition || 'tantiemes' }];

  // Pour chaque ligne de répartition, calculer la part par logement
  // puis appliquer le prorata jours d'occupation (sauf sous-compteurs).
  const partsParRef = {}; // { ref: { totalMontant, segments: [...] } }
  logs.forEach(l => { partsParRef[l.ref] = { log: l, segments: [] }; });

  for(const ligne of lignes) {
    const sousMontant = montant * ligne.ratio;
    const cleApplique = ligne.cle;
    const skipProrata = (cleApplique === 'sous-compteurs'); // conso = déjà prorata réel

    let partsCle;
    if(cleApplique === 'sous-compteurs') {
      partsCle = _ccApplySousCompteurs(sousMontant, logs, cc, im, periodFrom, periodTo);
    } else {
      partsCle = _ccApplyCleSimple(cleApplique, sousMontant, logs, cc, im);
    }

    // Pour chaque logement, distribuer le montant entre locataires + part bailleur (sauf sous-compteurs)
    Object.keys(partsCle).forEach(ref => {
      const p = partsCle[ref];
      if(p.exclu || !p.montant) {
        partsParRef[ref].segments.push({
          montant: 0, methode: p.methode, exclu: true, raison: p.raison || '—',
          isBailleur: false, denomLabel: p.denomLabel
        });
        return;
      }
      if(skipProrata) {
        // Pas de prorata jours : la conso est le réel
        partsParRef[ref].segments.push({
          montant: p.montant, methode: p.methode, isBailleur: false,
          locataire: 'Locataire(s) actuels', denomLabel: p.denomLabel
        });
        return;
      }
      // Prorata jours occupation : découper en segments locataires + bailleur
      const occ = _ccLogOccupations(partsParRef[ref].log, periodFrom, periodTo);
      occ.segments.forEach(seg => {
        const partSeg = p.montant * (seg.occDays / occ.totalDays);
        partsParRef[ref].segments.push({
          montant: partSeg, methode: p.methode,
          isBailleur: seg.isBailleur,
          locataire: seg.locataire, occJours: seg.occDays,
          debut: seg.debut, fin: seg.fin,
          denomLabel: p.denomLabel
        });
      });
    });
  }

  // Aplatir les segments par logement → result.parts
  Object.keys(partsParRef).forEach(ref => {
    const r = partsParRef[ref];
    r.segments.forEach(seg => {
      result.parts.push({ ref, log: r.log, ...seg });
      if(seg.exclu) result.totaux.totalExclu += 0; // pas de montant
      else if(seg.isBailleur) result.totaux.totalBailleur += seg.montant;
      else result.totaux.totalLocataires += seg.montant;
    });
  });

  result.totaux.totalNonImpute = montant - result.totaux.totalLocataires - result.totaux.totalBailleur;
  return result;
}

// Helper : id unique compteur collectif
function _ccId() { return 'cc_' + Date.now() + '_' + Math.random().toString(36).slice(2,7); }

// Trouve le type config (avec fallback 'autre')
function _ccType(cc) {
  // v14.68 : inclut les types custom user (DB.params.ccTypesCustom)
  // v14.72 BUG #17 : si type custom supprimé de DB.params.ccTypesCustom, fallback safe
  // qui préserve le typeLabel si présent (au lieu de retomber sur "autre" ou un index aléatoire).
  if(!cc) return { key:'autre', label:'Autre', icon:'📊', unit:'', color:'#64748b' };
  const found = _allCcTypes().find(t => t.key === cc.type);
  if(found) return found;
  // Fallback explicite : type non trouvé → on construit un objet stable
  return {
    key: cc.type || 'autre',
    label: cc.typeLabel || 'Autre',
    icon: '📊',
    unit: '',
    color: '#64748b'
  };
}

// v14.60 — Total facturé sur l'année courante pour un compteur.
// Single source of truth = DB.mouvements (filtré par compteurCcId === cc.id).
// Les anciens cc.factures[] sont migrés au boot via _migrateCcFacturesToMouvements().
function _ccTotalFactureYear(cc, year) {
  const yr = year || new Date().getFullYear();
  return (DB.mouvements||[]).filter(_isAlive)
    .filter(m => m.compteurCcId === cc.id)
    .filter(m => (m.date||'').startsWith(String(yr)))
    .reduce((s,m) => s + (+m.db||0), 0);
}

// v14.60 — Liste des mouvements liés à un compteur (utile pour drill-down)
function _ccMouvementsForCc(cc, year) {
  let arr = (DB.mouvements||[]).filter(_isAlive).filter(m => m.compteurCcId === cc.id);
  if(year) arr = arr.filter(m => (m.date||'').startsWith(String(year)));
  return arr.sort((a,b) => (b.date||'').localeCompare(a.date||''));
}

// v14.60 — Ouvre la modale Nouveau mouvement pré-rempli pour un compteur collectif :
// immeuble + compteur lié + débit (charge). L'utilisateur n'a plus qu'à saisir
// la date / le libellé / le montant et choisir la catégorie (eau, élec...).
function openNewMvForCc(ccId, immNom) {
  if(!ccId) return;
  if(typeof openNewMv !== 'function') { showToast('Module Mouvements indisponible','err'); return; }
  openNewMv();   // synchrone : ouvre la modale + rend _affZone (niveau par défaut « logement »)
  // CDC Charges §13 (friction) : piloter la zone d'affectation _affZone (#mv-aff) au niveau
  // « Récupérable » avec l'immeuble + le poste présélectionnés — l'ancien #mv-cc-wrap est superseded.
  const apply = () => {
    try {
      if(el('mv-imm') && immNom) el('mv-imm').value = immNom;   // champ caché lu par saveMv + _affZone
      if(el('mv-qui')) el('mv-qui').value = '';
      if(typeof _affState === 'object') (_affState['mv'] || (_affState['mv'] = {})).niv = 'recup';
      if(typeof _affRender === 'function') _affRender('mv', 'mv');   // rend recup + peuple #mv-cc-comp / #mv-cc
      if(el('mv-cc')) el('mv-cc').value = ccId;                      // les options existent maintenant
      if(typeof _affRender === 'function') _affRender('mv', 'mv');   // présélectionne le poste + badge destination
      if(typeof _mvEnforceExclusivity === 'function') _mvEnforceExclusivity();
    } catch(e) { console.warn('[openNewMvForCc]', e); }
  };
  apply();                    // synchrone (openNewMv l'est aussi)
  setTimeout(apply, 60);      // belt-and-suspenders si un rendu différé réinitialise la zone
  setTimeout(() => { const f = el('mv-lib'); if(f) f.focus(); }, 90);
}

// v14.60/v14.72 BUG #19 — Modale tableau des mouvements liés à un compteur (au lieu d'alert)
function viewCcMouvements(ccId) {
  const arr = (DB.mouvements||[]).filter(_isAlive).filter(m => m.compteurCcId === ccId)
    .sort((a,b) => (b.date||'').localeCompare(a.date||''));
  // Trouve le compteur pour le titre
  let ccTitle = 'Compteur';
  outer: for(const ent of (DB.entites||[]).filter(_isAlive)) {
    for(const im of (ent.immeubles||[]).filter(_isAlive)) {
      const cc = (im.compteursCollectifs||[]).filter(_isAlive).find(c => c.id === ccId);
      if(cc) { ccTitle = cc.nom + ' · ' + im.nom; break outer; }
    }
  }
  const total = arr.reduce((s,m) => s + (+m.db||0), 0);
  const rows = arr.length
    ? arr.map(m => `<tr>
        <td>${escHtml(m.date||'—')}</td>
        <td>${escHtml(m.lib||'—')}</td>
        <td class="mu sm">${escHtml(m.cat||'—')}</td>
        <td class="num"><b>${fmt(+m.db||0)}</b></td>
        <td class="mu sm">${m.fac?'#'+escHtml(m.fac):'—'}</td>
      </tr>`).join('')
    : '<tr><td colspan="5" class="mu sm" style="padding:14px;text-align:center">Aucun mouvement lié à ce compteur</td></tr>';
  const html = `
    <div class="ov" id="ov-cc-view-mvts" onclick="closeBg(event,'ov-cc-view-mvts')">
      <div class="modal" style="max-width:760px">
        <div class="m-head">
          <h3>↗ Mouvements liés — ${escHtml(ccTitle)} <span class="mu sm">(${arr.length})</span></h3>
          <button class="m-close" onclick="closeM('ov-cc-view-mvts')">${_uiIcon('close')}</button>
        </div>
        <div class="m-body">
          <p class="mu sm" style="margin-bottom:10px;font-size:12px">Total facturé : <b>${fmt(total)}</b> · Pour modifier un mouvement : onglet 💰 Loyers &amp; Mouvements</p>
          <table class="tbl"><thead><tr><th>Date</th><th>Libellé</th><th>Catégorie</th><th class="num">Montant</th><th>Facture</th></tr></thead>
          <tbody>${rows}</tbody></table>
        </div>
        <div class="m-foot">
          <button class="btn bs" onclick="closeM('ov-cc-view-mvts')">Fermer</button>
        </div>
      </div>
    </div>`;
  const old = document.getElementById('ov-cc-view-mvts');
  if(old) old.remove();
  document.body.insertAdjacentHTML('beforeend', html);
  openM('ov-cc-view-mvts');
}

// v14.60 — Migration douce : convertir les anciens cc.factures[] en mouvements liés.
// Appelée au boot (loadDB). Idempotente : si cc.factures vide, ne fait rien.
function _migrateCcFacturesToMouvements() {
  if(!DB || !DB.entites || !Array.isArray(DB.entites)) return;
  if(!DB.mouvements) DB.mouvements = [];
  let migratedCount = 0;
  const catFromType = (t) => {
    // Map type compteur → catégorie de mouvement (utilise les catégories existantes ou 'Charges')
    const cats = (DB.categories||[]).map(c => (c||'').toLowerCase());
    const has = (s) => cats.find(c => c.includes(s));
    if(t === 'eau-f' || t === 'eau-c') return has('eau') ? DB.categories[cats.indexOf(has('eau'))] : 'Charges';
    if(t === 'elec') return has('élec') || has('elec') ? DB.categories[cats.findIndex(c=>c.includes('élec')||c.includes('elec'))] : 'Charges';
    if(t === 'gaz') return has('gaz') ? DB.categories[cats.indexOf(has('gaz'))] : 'Charges';
    return 'Charges';
  };
  DB.entites.filter(_isAlive).forEach(ent => {
    (ent.immeubles||[]).forEach(im => {
      const ccs = im.compteursCollectifs || [];
      ccs.forEach(cc => {
        if(!cc.factures || !cc.factures.length) return;
        cc.factures.forEach(f => {
          // Anti-double-migration : si déjà un mouvement avec ce compteurCcId à cette date+montant, skip
          const dup = DB.mouvements.find(m => m.compteurCcId === cc.id
            && m.date === f.dateFacture
            && +m.db === +f.montant);
          if(dup) return;
          // TRAVAUX : QUI PAIE ? — API unique, sans horodatage _stamp ni audit (comportement d'origine :
          // _modifiedAt posé dans le littéral), saveDB une seule fois plus bas si au moins une facture.
          _mvCreate({
            id: nid(),
            date: f.dateFacture || td(),
            lib: `Facture ${cc.nom}${f.datePeriode?' · '+f.datePeriode:''}`,
            imm: im.nom || '',
            cat: catFromType(cc.type),
            qui: '',
            db: +f.montant || 0,
            cr: 0,
            fac: '',
            compteurCcId: cc.id,
            _migratedFromCcFacture: true,
            _modifiedAt: new Date().toISOString()
          }, { stamp: false, audit: false, save: false, refresh: false });
          migratedCount++;
        });
        // Vide cc.factures après migration
        cc.factures = [];
      });
    });
  });
  if(migratedCount > 0) {
    console.log('[CHARGES-COMMUNES] Migration v14.60 :', migratedCount, 'factures cc → mouvements');
    try { saveDB(); } catch(e){}
  }
}

// Total relevé sur l'année (delta du compteur si releves[] présents)
function _ccTotalConsoYear(cc, year) {
  const yr = String(year || new Date().getFullYear());
  const rels = (cc.releves||[]).slice().sort((a,b) => (a.date||'').localeCompare(b.date||''));
  if(rels.length < 2) return 0;
  // Trouve le dernier relevé avant le 1er janvier de l'année et le dernier de l'année
  const before = rels.filter(r => (r.date||'') < `${yr}-01-01`).pop();
  const within = rels.filter(r => (r.date||'').startsWith(yr));
  if(!within.length) return 0;
  const start = before ? before.value : within[0].value;
  const end = within[within.length-1].value;
  return end - start;
}

// ── Rendu : sous-onglet "⚡ Charges communes" sur fiche immeuble
// BIENS étape 9 (P1-7, décision 3 du 11/08) — UN SEUL écran de relevés : ici, avec un sélecteur
// de logement. Un logement sans immeuble n'a pas la fonction, on ne duplique pas le point d'entrée.
// Les DONNÉES ne bougent pas (DB.compteursReleves[ref] + log.compteurs) : openCompteursInitModal,
// openCompteurReleve et viewCcReleves sont REPOINTÉS, pas dupliqués. Mémoire seule, comme le reste
// des états d'affichage.
let _immCompteursRef = '';
function _setImmCompteursRef(ref) { _immCompteursRef = ref || ''; rImmFiche(); }

/** Section « Relevés compteurs des logements » — DRY : réutilise _renderLogFichePanelCompteurs.
 *  Les logements ARCHIVÉS sont inclus (audit) : un bien archivé garde ses relevés, et c'est
 *  précisément après un départ qu'on vient les consulter. Ils sont signalés comme tels. */
function _renderImmRelevesLogements(activeLogs, archivedLogs) {
  const logs = [].concat(activeLogs || [], archivedLogs || []).filter(Boolean);
  if (!logs.length) return '';
  const courant = logs.some(l => l.ref === _immCompteursRef) ? _immCompteursRef : logs[0].ref;
  const log = logs.find(l => l.ref === courant);
  const opts = logs.map(l => `<option value="${escHtml(l.ref)}"${l.ref === courant ? ' selected' : ''}>${escHtml(_logLabelRef(l))}${l.locataire ? ' — ' + escHtml(l.locataire) : ''}${l.archived ? ' (archivé)' : ''}</option>`).join('');
  return '<div class="logf-section-head" style="margin-top:26px">'
    + '<h3 class="logf-section-title">' + _uiIcon('bolt') + ' Relevés compteurs des logements</h3>'
    + `<select class="inp" style="max-width:280px" onchange="_setImmCompteursRef(this.value)" aria-label="Logement dont on affiche les relevés">${opts}</select>`
    + '</div>'
    + (log ? _renderLogFichePanelCompteurs(log, log.ref) : '');
}

function _renderImmFichePanelCharges(ent, im, activeLogs, archivedLogs) {
  // v14.71 : on garde le tableau brut pour préserver les ccIdx passés aux callbacks
  // (editCcForImm, delCcForImm, addCcReleve…). Les tombstones sont skippés au rendu.
  const ccs = im.compteursCollectifs || [];
  const ccsAlive = ccs.filter(_isAlive); // pour les compteurs visibles + empty state
  const entIdSafe = +ent.id;
  const immIdSafe = +im.id;

  // Header CTA
  const headerActions = `<div style="display:flex;gap:6px;flex-wrap:wrap">
    <button class="btn bp bb" onclick="openNewCcForImm(${entIdSafe},${immIdSafe})">+ Poste de charge</button>
  </div>`;

  // Banner pédagogique : règle de répartition disponible
  const totalSurf = activeLogs.reduce((s,l)=>s+(+l.surf||0), 0);
  const totalTant = activeLogs.reduce((s,l)=>s+(+l.tantiemes||0), 0);
  const banner = `<div class="logf-edl-tpl-banner logf-edl-tpl-inactive" style="margin-bottom:14px">
    <div class="logf-edl-tpl-icon">${_uiIcon('scale',24)}</div>
    <div class="logf-edl-tpl-info">
      <div class="logf-edl-tpl-title">Bases de répartition disponibles pour cet immeuble</div>
      <div class="logf-edl-tpl-meta">
        <b>Tantièmes</b> : ${totalTant>0 ? `total renseigné ${totalTant}` : '<span style="color:var(--ora)">non renseignés (à saisir sur les fiches logement)</span>'} ·
        <b>Surfaces</b> : ${totalSurf>0 ? `total ${fmtN(totalSurf)} m²` : '<span style="color:var(--ora)">non renseignées</span>'} ·
        <b>Sous-compteurs</b> : ${activeLogs.length} logement${activeLogs.length>1?'s':''} (relevés EDL + manuels) ·
        <b>Forfait</b> : toujours disponible
      </div>
    </div>
  </div>`;

  if(!ccsAlive.length) {
    return `<div class="logf-section-head">
      <h3 class="logf-section-title">${_uiIcon('bolt')} Postes de charges & charges communes</h3>
      ${headerActions}
    </div>
    ${banner}
    <div class="logf-doc-empty">
      Aucun poste de charge enregistré pour cet immeuble.
      <div class="mu sm" style="margin-top:6px">Saisir ici les <b>postes de charges</b> de l'immeuble (eau, chauffage collectif, électricité des parties communes, ascenseur, entretien…) pour calculer automatiquement la quote-part de chaque logement à la régularisation annuelle. <b>Sans règle particulière, un poste est réparti au prorata (parts égales)</b> ; on ne définit une clé (tantièmes, surface, sous-compteur…) que pour les postes qui le méritent.</div>
      <div style="margin-top:10px"><button class="btn bp bb" onclick="openNewCcForImm(${entIdSafe},${immIdSafe})">+ Premier poste de charge</button></div>
    </div>`
    + _renderImmRelevesLogements(activeLogs, archivedLogs);
  }

  const yr = new Date().getFullYear();
  // v14.71 : on map sur le tableau brut pour préserver les ccIdx, on skippe les tombstones
  const cards = ccs.map((cc, ccIdx) => {
    if(!_isAlive(cc)) return '';
    const t = _ccType(cc);
    const repart = CC_REPARTITION_LABELS[cc.cleRepartition] || CC_REPARTITION_LABELS.tantiemes;
    const totalFact = _ccTotalFactureYear(cc, yr);
    const totalConso = _ccTotalConsoYear(cc, yr);
    const nbReleves = (cc.releves||[]).length;
    // v14.60 : nb mouvements liés (single source DB.mouvements) au lieu de cc.factures
    const nbMvLies = _ccMouvementsForCc(cc, yr).length;

    // v14.69 BUGFIX : appliquer cc.scope (logements concernés) avant le calcul de la quote-part.
    // Les logements décochés à la création/édition ne doivent pas apparaître dans la table.
    const logsScoped = (typeof _ccLogsInScope === 'function')
      ? _ccLogsInScope(cc, activeLogs)
      : activeLogs;
    const nExclus = activeLogs.length - logsScoped.length;
    const scopeBanner = nExclus > 0
      ? `<div class="mu sm" style="font-size:11px;color:var(--ora);margin-bottom:6px">${_uiIcon('warn',13)} ${nExclus} logement${nExclus>1?'s':''} exclu${nExclus>1?'s':''} de ce compteur (scope ou compte-charges désactivé)</div>`
      : '';

    // Calcul tableau quote-part (uniquement les logements en scope)
    const rows = logsScoped.map(log => {
      const qp = _calcCcQuotePart(im, log, cc, logsScoped);
      const partFact = qp && !qp.exclu ? totalFact * qp.ratio : 0;
      const ratioPct = qp ? (qp.ratio*100).toFixed(1) : '—';
      const exclu = qp && qp.exclu;
      return `<tr class="${exclu?'cc-row-exclu':''}">
        <td><b>${escHtml(_logLabel(log))}</b><br><span class="mu sm">${escHtml(log.locataire||'Vacant')}</span></td>
        <td class="num">${exclu ? '—' : ratioPct + '%'}</td>
        <td class="mu sm">${escHtml(qp?.denomLabel||'—')}</td>
        <td class="num">${exclu ? '—' : '<b>'+fmt(partFact)+'</b>'}</td>
      </tr>`;
    }).join('');
    const totalDuesum = logsScoped.reduce((s,log) => {
      const qp = _calcCcQuotePart(im, log, cc, logsScoped);
      return s + (qp && !qp.exclu ? totalFact * qp.ratio : 0);
    }, 0);
    const reste = totalFact - totalDuesum;

    return `<div class="logf-cpt-card cc-card">
      <div class="logf-cpt-card-head">
        <span class="logf-cpt-icon" style="background:${t.color}22;color:${t.color}">${_ccIconSvg(t.key,19)}</span>
        <div class="logf-cpt-card-title">${escHtml(cc.nom)} <span class="mu sm">· <span style="display:inline-flex;vertical-align:-2px">${_repartIconSvg(cc.cleRepartition,12)}</span> ${repart.label}</span></div>
        <button class="btn bs bb" onclick="editCcForImm(${entIdSafe},${immIdSafe},${ccIdx})" title="Modifier ce poste de charge">${_uiIcon('edit')}</button>
        <button class="btn br bb" onclick="delCcForImm(${entIdSafe},${immIdSafe},${ccIdx})" title="Supprimer">${_uiIcon('trash')}</button>
      </div>
      <div class="logf-cpt-kpis">
        <div class="logf-cpt-kpi">
          <div class="logf-cpt-kpi-v k-money">${fmt(totalFact)}</div>
          <div class="logf-cpt-kpi-l">Facturé ${yr}<small>(${nbMvLies} mvt liés)</small></div>
        </div>
        <div class="logf-cpt-kpi">
          <div class="logf-cpt-kpi-v">${fmtN(totalConso)}<small> ${escHtml(t.unit||'')}</small></div>
          <div class="logf-cpt-kpi-l">Conso ${yr}<small>(${nbReleves} relevés)</small></div>
        </div>
        <div class="logf-cpt-kpi">
          <div class="logf-cpt-kpi-v ${reste>0.5?'k-warn':''}">${fmt(reste)}</div>
          <div class="logf-cpt-kpi-l">Reste à imputer<small>(non récupérable)</small></div>
        </div>
      </div>

      <div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap">
        <button class="btn bs bb" onclick="addCcReleve(${entIdSafe},${immIdSafe},${ccIdx})">+ Relevé</button>
        <button class="btn bp bb" onclick="openNewMvForCc('${_lyQ(cc.id)}','${_lyQ(im.nom)}')" title="Nouveau mouvement bancaire pré-lié à ce compteur">+ Facture (mouvement)</button>
        <button class="btn bs bb" onclick="viewCcReleves(${entIdSafe},${immIdSafe},${ccIdx})">${nbReleves} relevé${nbReleves>1?'s':''}</button>
        <button class="btn bs bb" onclick="viewCcMouvements('${_lyQ(cc.id)}')" title="Voir tous les mouvements liés à ce compteur">↗ ${nbMvLies} mouvement${nbMvLies>1?'s':''} lié${nbMvLies>1?'s':''}</button>
      </div>

      <div class="cc-table-wrap" style="margin-top:12px">
        <div class="mu sm" style="font-weight:600;margin-bottom:6px">Quote-part par logement (sur facturé ${yr} = ${fmt(totalFact)})</div>
        ${scopeBanner}
        <table class="cc-table">
          <thead><tr>
            <th>Logement</th><th class="num">Quote-part</th><th>Base</th><th class="num">Montant ${yr}</th>
          </tr></thead>
          <tbody>${rows||'<tr><td colspan="4" class="mu sm" style="padding:14px;text-align:center">Aucun logement concerné par ce compteur</td></tr>'}</tbody>
        </table>
      </div>
    </div>`;
  }).join('');

  return `<div class="logf-section-head">
    <h3 class="logf-section-title">${_uiIcon('bolt')} Postes de charges & charges communes <span class="mu sm">(${ccsAlive.length})</span></h3>
    ${headerActions}
  </div>
  ${banner}
  <div class="cc-grid">${cards}</div>`
    + _renderImmRelevesLogements(activeLogs, archivedLogs);
}

// ─────────────────────────────────────────────────────────────────────────
// CRUD compteur collectif (modale rapide via prompts en V1, à raffiner si besoin)
// ─────────────────────────────────────────────────────────────────────────

function _findImm(entId, immId) {
  const ent = (DB.entites||[]).find(e => +e.id === +entId);
  if(!ent) return { ent: null, im: null };
  const im = (ent.immeubles||[]).find(i => +i.id === +immId);
  return { ent, im };
}

// D1 — garantit un id numérique UNIQUE sur chaque entité et chaque immeuble (ids immeuble uniques
// PAR entité, ce que _findImm exige). Sans ça, un id manquant / non-numérique / dupliqué fait
// échouer _findImm (+id → NaN ou mauvais immeuble) → boutons compteur morts. Idempotent : ne touche
// que les ids invalides ou dupliqués. Retourne true si une correction a eu lieu.
function _ensureEntImmIds() {
  if (!DB || !Array.isArray(DB.entites)) return false;
  let changed = false;
  const fixSet = (items) => {
    if (!Array.isArray(items)) return;
    const used = new Set();
    let next = 0;
    items.forEach(it => { if (it && Number.isFinite(+it.id)) next = Math.max(next, +it.id); });
    items.forEach(it => {
      if (!it) return;
      const v = +it.id;
      if (!Number.isFinite(v) || used.has(v)) { it.id = ++next; changed = true; }
      used.add(+it.id);
    });
  };
  fixSet(DB.entites);
  DB.entites.forEach(e => { if (e) fixSet(e.immeubles); });
  return changed;
}

function _ensureCcArray(im) {
  if(!im.compteursCollectifs) im.compteursCollectifs = [];
  return im.compteursCollectifs;
}

function _saveImmCc(ent, im) {
  if(typeof _stamp === 'function') _stamp(ent);
  saveDB();
  if(typeof rImmFiche === 'function' && currentPage === 'imm-fiche') rImmFiche();
}

// v14.68 — Ouvre la modale de création OU édition d'un compteur collectif.
// ccIdx === null/undefined → mode création
// ccIdx fourni → mode édition (pré-rempli)
function openNewCcForImm(entId, immId) { openCcFormModal(entId, immId, null); }
function editCcForImm(entId, immId, ccIdx) { openCcFormModal(entId, immId, ccIdx); }

// v14.68 — Modale unifiée création/édition compteur collectif.
function openCcFormModal(entId, immId, ccIdx) {
  const { ent, im } = _findImm(entId, immId);
  if(!ent || !im) { showToast('Immeuble introuvable','err'); return; }
  const isEdit = (ccIdx !== null && ccIdx !== undefined);
  const cc = isEdit ? (im.compteursCollectifs||[])[ccIdx] : null;
  if(isEdit && !cc) { showToast('Compteur introuvable','err'); return; }

  // Logements de l'immeuble (pour les checkboxes scope)
  const logsImm = (DB.logements||[]).filter(_isAlive).filter(l => l.imm === im.nom);

  const cur = {
    nom: cc ? (cc.nom||'') : '',
    type: cc ? (cc.type||'eau-f') : 'eau-f',
    typeLabel: cc ? (cc.typeLabel||'') : '',
    cleRepartition: cc ? (cc.cleRepartition||'proportionnel') : 'proportionnel',  // CDC W2 : défaut = prorata (parts égales 1/N)
    fallbackRepartition: cc ? (cc.fallbackRepartition||'') : '',
    scope: cc ? (cc.scope||[]) : [],
    numCompteur: cc ? (cc.numCompteur||'') : '',
    fournisseur: cc ? (cc.fournisseur||'') : ''
  };
  const allCheckedByDefault = !isEdit || cur.scope.length === 0;

  const checkboxesHtml = logsImm.map(l => {
    const isChecked = allCheckedByDefault || cur.scope.includes(l.ref);
    const isCC = l.compteCharges !== false;
    const badge = isCC
      ? '<span style="font-size:10px;background:#10b98122;color:#059669;padding:1px 6px;border-radius:8px;margin-left:6px">compte-charges</span>'
      : '<span style="font-size:10px;background:#94a3b822;color:#64748b;padding:1px 6px;border-radius:8px;margin-left:6px">exclu charges</span>';
    return `<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;background:var(--bg2)">
      <input type="checkbox" class="cc-form-log" value="${escHtml(l.ref)}"${isChecked?' checked':''}>
      <span style="flex:1"><b>${escHtml(_logLabelRef(l))}</b> · ${escHtml(l.locataire||'Vacant')}</span>
      ${badge}
    </label>`;
  }).join('');

  const html = `
    <div class="ov" id="ov-cc-form" onclick="closeBg(event,'ov-cc-form')">
      <div class="modal" style="max-width:680px">
        <div class="m-head">
          <h3>${isEdit?'' + _uiIcon('edit') + ' Modifier':'' + _uiIcon('plus') + ' Nouveau'} poste de charge — ${escHtml(im.nom||'')}</h3>
          <button class="m-close" onclick="closeM('ov-cc-form')">${_uiIcon('close')}</button>
        </div>
        <div class="m-body">
          <div class="fg">
            <label>Nom du poste *</label>
            <input class="inp" id="cc-form-nom" placeholder="Ex : Eau froide, Chauffage collectif, Ascenseur, Entretien" value="${escHtml(cur.nom)}">
          </div>

          <div class="fg">
            <label>Type *</label>
            <div style="display:flex;gap:8px;align-items:center">
              <select class="inp" id="cc-form-type" style="flex:1" onchange="_ccFormOnTypeChange()">
                ${_renderCcTypesOptions(cur.type)}
              </select>
              <button class="btn bs" type="button" onclick="openCcAddTypeModal()" title="Ajouter un type personnalisé (ex : entretien gouttières)">+ Nouveau type</button>
            </div>
            <div id="cc-form-type-custom-row" class="fg" style="margin-top:8px;${cur.type==='autre'?'':'display:none'}">
              <label class="mu sm">Libellé custom (si type = Autre)</label>
              <input class="inp" id="cc-form-type-label" placeholder="Ex : Entretien gouttières" value="${escHtml(cur.typeLabel)}">
            </div>
          </div>

          <div class="fg">
            <label>① Logements concernés *</label>
            <div style="display:flex;gap:6px;margin-bottom:8px">
              <button class="btn bs" type="button" onclick="_ccFormToggleAllLogs(true)" style="font-size:11px;padding:4px 10px">☑ Tous</button>
              <button class="btn bs" type="button" onclick="_ccFormToggleAllLogs(false)" style="font-size:11px;padding:4px 10px">☐ Aucun</button>
              <span class="mu sm" style="font-size:11px;align-self:center;margin-left:6px">${logsImm.length} logement${logsImm.length>1?'s':''} dans cet immeuble</span>
            </div>
            <div id="cc-form-logs" style="display:flex;flex-direction:column;gap:4px;max-height:220px;overflow-y:auto;padding:4px;border:1px solid var(--bor);border-radius:6px">
              ${checkboxesHtml || '<p class="mu sm" style="padding:10px;text-align:center">Aucun logement dans cet immeuble. Créer d\'abord les logements.</p>'}
            </div>
            <div class="mu sm" style="margin-top:6px;font-size:11px">${_uiIcon('bulb',13)} Décocher un logement pour l'exclure de ce poste (ex : garage non chauffé pour le chauffage).</div>
          </div>

          <div class="fg">
            <label>② Clé de répartition entre les logements retenus *</label>
            <select class="inp" id="cc-form-repart" onchange="_ccFormOnRepartChange()">
              ${_renderCcRepartOptions(cur.cleRepartition)}
            </select>
            <div class="mu sm" style="margin-top:4px;font-size:11px">Par défaut : <b>prorata (parts égales, 1/N)</b> — ne change la clé que pour les postes qui le méritent (chauffage aux tantièmes, eau au sous-compteur…).</div>
            <div id="cc-form-repart-hint" class="mu sm" style="margin-top:4px;font-size:11px;font-style:italic">${escHtml(_ccRepartHint(cur.cleRepartition))}</div>
            <div id="cc-form-fallback-row" class="fg" style="margin-top:10px;${cur.cleRepartition==='sous-compteurs'?'':'display:none'}">
              <label class="mu sm">Clé secondaire (logements SANS sous-compteur)</label>
              <select class="inp" id="cc-form-fallback">
                <option value="">— Aucun (tous ont sous-compteur) —</option>
                ${_renderCcRepartOptions(cur.fallbackRepartition).replace(/<option value="sous-compteurs"[^<]*<\/option>/, '').replace(/<option value="composite"[^<]*<\/option>/, '')}
              </select>
            </div>
            <div id="cc-form-comp-row" class="fg" style="margin-top:10px;${cur.cleRepartition==='composite'?'':'display:none'}">
              <label class="mu sm">Composition — combine plusieurs clés (le total doit faire 100 %)</label>
              <div id="cc-form-comp-rows"></div>
              <button class="btn bs" type="button" onclick="_ccCompAddRow()" style="font-size:11px;padding:4px 10px;margin-top:4px">+ Ajouter une clé</button>
              <div id="cc-form-comp-total" class="mu sm" style="margin-top:6px;font-size:11px"></div>
            </div>
          </div>

          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
            <div class="fg"><label>N° compteur</label>
              <input class="inp" id="cc-form-num" placeholder="Optionnel" value="${escHtml(cur.numCompteur)}">
            </div>
            <div class="fg"><label>Fournisseur</label>
              <input class="inp" id="cc-form-fourn" placeholder="EDF, Veolia, Suez…" value="${escHtml(cur.fournisseur)}">
            </div>
          </div>
        </div>
        <div class="m-foot">
          <button class="btn bs" onclick="closeM('ov-cc-form')">Annuler</button>
          <button class="btn bp" onclick="saveCcForm(${entId},${immId},${isEdit?ccIdx:'null'})">${isEdit?'' + _uiIcon('check') + ' Enregistrer':'' + _uiIcon('plus') + ' Créer le poste'}</button>
        </div>
      </div>
    </div>`;
  const old = document.getElementById('ov-cc-form');
  if(old) old.remove();
  document.body.insertAdjacentHTML('beforeend', html);
  openM('ov-cc-form');
  _ccCompInit(cur.composition);   // CDC É1b : peuple l'éditeur de composition (Mixte)
  setTimeout(() => { const f = document.getElementById('cc-form-nom'); if(f) f.focus(); }, 80);
}

function _ccFormOnTypeChange() {
  const sel = document.getElementById('cc-form-type');
  const row = document.getElementById('cc-form-type-custom-row');
  if(!sel || !row) return;
  row.style.display = (sel.value === 'autre') ? '' : 'none';
}

function _ccFormOnRepartChange() {
  const sel = document.getElementById('cc-form-repart');
  const row = document.getElementById('cc-form-fallback-row');
  const comp = document.getElementById('cc-form-comp-row');
  const hint = document.getElementById('cc-form-repart-hint');
  if(!sel) return;
  const isComposite = (sel.value === 'composite');
  if(row) row.style.display = (sel.value === 'sous-compteurs') ? '' : 'none';
  if(comp) comp.style.display = isComposite ? '' : 'none';
  if(hint) hint.textContent = _ccRepartHint(sel.value);
  // Passage à Mixte sans composition déjà saisie → amorce 2 lignes 50/50.
  if(isComposite) {
    const rows = document.getElementById('cc-form-comp-rows');
    if(rows && !rows.children.length) { _ccCompAddRow('tantiemes', 50); _ccCompAddRow('sous-compteurs', 50); }
  }
}

// CDC Charges É1b — éditeur de composition (clé Mixte). 1 ligne = {cle simple, pct}. Σ pct doit = 100.
function _ccCompRowHtml(cle, pct) {
  const opts = CC_SIMPLE_KEYS.map(k => `<option value="${k}"${k===cle?' selected':''}>${escHtml((CC_REPARTITION_LABELS[k]||{}).label||k)}</option>`).join('');
  return `<div class="cc-comp-row" style="display:flex;gap:6px;align-items:center;margin-bottom:4px">
    <select class="inp cc-comp-cle" style="flex:1" onchange="_ccCompRenderTotal()">${opts}</select>
    <input class="inp cc-comp-pct" type="number" min="0" max="100" step="1" value="${(pct!=null?pct:0)}" style="width:72px" oninput="_ccCompRenderTotal()">
    <span class="mu sm">%</span>
    <button class="btn bs" type="button" title="Retirer cette clé" onclick="_ccCompRemoveRow(this)" style="padding:2px 8px">${_uiIcon('close')}</button>
  </div>`;
}
function _ccCompAddRow(cle, pct) {
  const rows = document.getElementById('cc-form-comp-rows'); if(!rows) return;
  rows.insertAdjacentHTML('beforeend', _ccCompRowHtml(cle || 'tantiemes', pct != null ? pct : 0));
  _ccCompRenderTotal();
}
function _ccCompRemoveRow(btn) {
  const r = btn.closest('.cc-comp-row'); if(r) r.remove();
  _ccCompRenderTotal();
}
function _ccCompRenderTotal() {
  const rows = Array.from(document.querySelectorAll('#cc-form-comp-rows .cc-comp-row'));
  const total = rows.reduce((s,r) => s + (parseFloat((r.querySelector('.cc-comp-pct')||{}).value) || 0), 0);
  const box = document.getElementById('cc-form-comp-total'); if(!box) return;
  const ok = Math.abs(total - 100) < 0.01 && rows.length >= 2;
  box.innerHTML = `Total : <b style="color:${ok?'var(--grn)':'var(--red,#d23f3f)'}">${total}%</b> ${ok?'' + _uiIcon('check') + '':(rows.length<2?'· ajouter au moins 2 clés':'· doit faire 100 %')}`;
}
function _ccCompInit(composition) {
  const rows = document.getElementById('cc-form-comp-rows'); if(!rows) return;
  rows.innerHTML = '';
  (Array.isArray(composition)?composition:[]).filter(c=>c&&c.cle).forEach(c => _ccCompAddRow(c.cle, Math.round((c.ratio||0)*100)));
  _ccCompRenderTotal();
}
// Lit l'éditeur → [{cle, ratio}] (ratio = pct/100), ou null si invalide (≥2 clés, chacune >0, total = 100).
function _ccCompRead() {
  const rows = Array.from(document.querySelectorAll('#cc-form-comp-rows .cc-comp-row'));
  if(rows.length < 2) return null;
  const comp = rows.map(r => ({ cle: (r.querySelector('.cc-comp-cle')||{}).value, pct: parseFloat((r.querySelector('.cc-comp-pct')||{}).value)||0 }));
  if(comp.some(c => !CC_SIMPLE_KEYS.includes(c.cle) || !(c.pct > 0))) return null;
  if(Math.abs(comp.reduce((s,c)=>s+c.pct,0) - 100) > 0.01) return null;
  return comp.map(c => ({ cle: c.cle, ratio: c.pct/100 }));
}

function _ccFormToggleAllLogs(checked) {
  document.querySelectorAll('#cc-form-logs .cc-form-log').forEach(cb => { cb.checked = !!checked; });
}

function saveCcForm(entId, immId, ccIdx) {
  const { ent, im } = _findImm(entId, immId);
  if(!ent || !im) { showToast('Immeuble introuvable','err'); return; }
  const isEdit = (ccIdx !== null && ccIdx !== undefined);
  const nom = (document.getElementById('cc-form-nom')||{}).value || '';
  const type = (document.getElementById('cc-form-type')||{}).value || 'eau-f';
  const typeLabel = (document.getElementById('cc-form-type-label')||{}).value || '';
  const cleRepart = (document.getElementById('cc-form-repart')||{}).value || 'tantiemes';
  const fallback = (document.getElementById('cc-form-fallback')||{}).value || '';
  const numCompteur = (document.getElementById('cc-form-num')||{}).value || '';
  const fournisseur = (document.getElementById('cc-form-fourn')||{}).value || '';
  if(!nom.trim()) { showToast('Nom obligatoire','err'); return; }
  if(!_allCcTypes().find(t => t.key === type)) { showToast('Type invalide','err'); return; }
  if(!CC_REPARTITION_LABELS[cleRepart]) { showToast('Clé de répartition invalide','err'); return; }
  if(type === 'autre' && !typeLabel.trim()) { showToast('Libellé custom requis pour type = Autre','err'); return; }
  // CDC É1b — clé Mixte : lire la composition (≥2 clés, total = 100 %).
  let composition = [];
  if(cleRepart === 'composite') {
    composition = _ccCompRead();
    if(!composition) { showToast('Composition Mixte invalide : au moins 2 clés et un total de 100 %','err'); return; }
  }
  // Scope = refs des logements cochés (vide si tous cochés = "tous concernés")
  const allCheckboxes = Array.from(document.querySelectorAll('#cc-form-logs .cc-form-log'));
  const checked = allCheckboxes.filter(cb => cb.checked).map(cb => cb.value);
  const total = allCheckboxes.length;
  if(total > 0 && checked.length === 0) { showToast('Au moins un logement doit être coché','err'); return; }
  const scope = (checked.length === total) ? [] : checked; // vide = tous

  if(isEdit) {
    const cc = (im.compteursCollectifs||[])[ccIdx];
    if(!cc) { showToast('Compteur introuvable','err'); return; }
    cc.nom = nom.trim();
    cc.type = type;
    cc.typeLabel = (type === 'autre') ? typeLabel.trim() : '';
    cc.cleRepartition = cleRepart;
    cc.fallbackRepartition = (cleRepart === 'sous-compteurs') ? fallback : '';
    cc.composition = composition;
    cc.scope = scope;
    cc.numCompteur = numCompteur;
    cc.fournisseur = fournisseur;
    cc._modifiedAt = new Date().toISOString();
    _saveImmCc(ent, im);
    closeM('ov-cc-form');
    showToast('Compteur modifié','ok');
  } else {
    const newCc = {
      id: _ccId(),
      nom: nom.trim(),
      type: type,
      typeLabel: (type === 'autre') ? typeLabel.trim() : '',
      cleRepartition: cleRepart,
      fallbackRepartition: (cleRepart === 'sous-compteurs') ? fallback : '',
      scope: scope,
      numCompteur: numCompteur,
      fournisseur: fournisseur,
      composition: composition,
      releves: [], factures: [], forfaitParts: {},
      _modifiedAt: new Date().toISOString()
    };
    _ensureCcArray(im).push(newCc);
    _saveImmCc(ent, im);
    closeM('ov-cc-form');
    showToast(`Compteur "${nom}" créé`,'ok');
  }
}

