// v14.69 — Sélectionne une icône depuis la grille (highlight visuel + remplit l'input)
// v14.72 BUG #16 : null-safe — la modale peut avoir été fermée entre temps
function _ccPickIcon(em) {
  if(!em) return;
  const inp = document.getElementById('cc-newtype-icon');
  if(inp) inp.value = em;
  const grid = document.getElementById('cc-newtype-icons-grid');
  if(!grid) return; // modale fermée → on ne fait rien (évite TypeError silencieux)
  grid.querySelectorAll('.cc-icon-btn').forEach(btn => {
    if(!btn || !btn.style) return;
    if(btn.dataset && btn.dataset.icon === em) {
      btn.style.borderColor = 'var(--acc)';
      btn.style.background = 'rgba(59,130,246,0.12)';
      btn.style.boxShadow = '0 0 0 2px rgba(59,130,246,0.25)';
    } else {
      btn.style.borderColor = 'var(--bor)';
      btn.style.background = 'var(--bg2)';
      btn.style.boxShadow = 'none';
    }
  });
}

function saveCcAddType() {
  const label = (document.getElementById('cc-newtype-label')||{}).value || '';
  const icon  = (document.getElementById('cc-newtype-icon')||{}).value || '📋';
  const unit  = (document.getElementById('cc-newtype-unit')||{}).value || '';
  if(!label.trim()) { showToast('Libellé obligatoire','err'); return; }
  // Slugify la clé : "Entretien gouttières" → "entretien-gouttieres"
  const slug = label.trim().toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g,'') // retire accents
    .replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,40);
  if(!slug) { showToast('Libellé invalide','err'); return; }
  const key = 'custom-' + slug;
  // Vérif unicité
  if(_allCcTypes().find(t => t.key === key)) { showToast('Ce type existe déjà','warn'); return; }
  if(!DB.params) DB.params = {};
  if(!Array.isArray(DB.params.ccTypesCustom)) DB.params.ccTypesCustom = [];
  DB.params.ccTypesCustom.push({ key, label: label.trim(), unit: unit.trim(), icon: icon.trim()||'📋', color: '#64748b', custom: true });
  saveDB();
  // Refresh le select Type dans la modale créa/édit s'il est ouvert
  const sel = document.getElementById('cc-form-type');
  if(sel) {
    sel.innerHTML = _renderCcTypesOptions(key);
    _ccFormOnTypeChange();
  }
  closeM('ov-cc-newtype');
  showToast(`Type "${label}" ajouté`,'ok');
}

function delCcForImm(entId, immId, ccIdx) {
  const { ent, im } = _findImm(entId, immId);
  if(!ent || !im) return;
  const cc = (im.compteursCollectifs||[])[ccIdx];
  if(!cc) return;
  if(!confirm2(`Supprimer le poste de charge "${cc.nom}" et tous ses relevés/factures ?`)) return;
  // v14.71 BUG-DRIVE-RESURRECTION pattern : tombstone au lieu de splice direct.
  // Sans ça, la suppression ne se propage pas via Drive merge et le compteur
  // ressuscite après reload sur un autre device.
  cc._deleted = true;
  cc._deletedAt = new Date().toISOString();
  cc._modifiedAt = cc._deletedAt;
  _saveImmCc(ent, im);
  showToast('Compteur supprimé','ok');
}

