function saveCcFactureModal(entId, immId, ccIdx) {
  const { ent, im } = _findImm(entId, immId);
  const cc = im && (im.compteursCollectifs||[])[ccIdx];
  if(!cc) { showToast('Compteur introuvable','err'); return; }
  const dateFacture = (document.getElementById('cc-fact-date')||{}).value || '';
  const datePeriode = (document.getElementById('cc-fact-periode')||{}).value || '';
  const montantStr = (document.getElementById('cc-fact-montant')||{}).value || '';
  const consoStr = (document.getElementById('cc-fact-conso')||{}).value || '';
  const notes = (document.getElementById('cc-fact-notes')||{}).value || '';
  if(!/^\d{4}-\d{2}-\d{2}$/.test(dateFacture)) { showToast('Date facture invalide','err'); return; }
  const montant = parseFloat(String(montantStr).replace(',','.'));
  if(!montantStr || isNaN(montant) || montant <= 0) { showToast('Montant invalide','err'); return; }
  const conso = consoStr ? parseFloat(String(consoStr).replace(',','.')) : 0;
  if(!cc.factures) cc.factures = [];
  cc.factures.push({ id: 'f_'+Date.now(), dateFacture, datePeriode, montant, conso: isNaN(conso)?0:conso, notes });
  cc._modifiedAt = new Date().toISOString();
  _saveImmCc(ent, im);
  closeM('ov-cc-facture');
  showToast(`Facture ${fmt(montant)} ajoutée`,'ok');
}

