function genActeCautionnementDoc(bail, log, ref) {
  if(!bail.garant) {
    if(bail.visale && String(bail.visale.visaId||'').trim()) { showToast('Garantie Visale (visa n° '+String(bail.visale.visaId).trim()+') — aucun acte de cautionnement requis (Action Logement garantit directement).','info',6000); return; }
    showToast('Aucun garant renseigné dans le bail','err'); return;
  }
  const ent = DB.entites.find(e=>e.nom===bail.entity)||{};
  // v13.25 → v13.26 BAIL-PRINT-POLISH points 2+3 : refonte CSS impression cautionnement.
  // FIX v13.26 : revert @page margin à 1.8cm 2cm (au lieu de 0). Avec margin:0
  // les pages 2+ (après page-break garant 2) n'avaient plus de marge top/bottom
  // car body padding ne s'applique qu'au début du body. Solution propre = @page
  // margin sur chaque page imprimée + body padding 0. L'utilisateur doit décocher
  // "En-têtes et pieds de page" dans Chrome/Edge — le print-hint l'informe.
  // Plus : page-break-inside:avoid sur tous les blocs longs (alerte, mention-bloc,
  // sig-bloc, grid2, table) pour éviter les coupures en pleine page.
  // DOCS-UNIFIES — le gabarit unique (variante B) remplace le CSS Times de l'acte.
  // Les classes propres a l'acte (.alerte, .mention-bloc, .grid2, .sig-bloc, .page-break,
  // .print-hint) sont conservees TELLES QUELLES cote balisage : seules leurs couleurs et
  // leurs arrondis sont realignes sur la charte. Aucune mention n'est deplacee ni reecrite.
  const _css = `@page{size:A4;margin:1.8cm 2cm}*{box-sizing:border-box}body{padding:0;margin:0;background:#fff}
${_docCss()}
.pro-doc .alerte{background:#fff8ef;border:.35mm solid #f0c987;border-radius:2.5mm;padding:3mm 4mm;margin:0 0 4mm;font-size:9pt;line-height:1.5;page-break-inside:avoid}.pro-doc .mention-bloc{background:#f7f8fb;border:.35mm dashed #b8c0cd;border-radius:2.5mm;padding:3mm 4mm;margin:0 0 3mm;font-size:9pt;line-height:1.55;page-break-inside:avoid}.pro-doc .mention-bloc strong{display:block;margin-bottom:1mm;font-size:8pt;color:#8b94a5;text-transform:uppercase;letter-spacing:.1em}.pro-doc .grid2{display:grid;grid-template-columns:1fr 1fr;gap:5mm;margin-top:3mm;page-break-inside:avoid}.pro-doc .sig-bloc{border:.3mm solid #b8c0cd;border-radius:2.5mm;min-height:88px;padding:3mm;margin-top:2mm;font-size:9pt;background:#fff;page-break-inside:avoid}.pro-doc .sig-bloc em{color:#8b94a5;font-size:8.5pt}.page-break{page-break-before:always;border-top:none;margin-top:0;padding-top:0}.print-hint{background:#f7f8fb;border-left:1mm solid #ff5a3c;padding:3mm 4mm;margin:0 0 4mm;font-size:9pt;color:#3c4658;border-radius:2.5mm;font-family:\"Inter\",system-ui,sans-serif}@media screen{body{max-width:780px;margin:20px auto;padding:1.8cm 2cm;background:#f4f5f8}.pro-doc{background:#fff}}@media print{.no-print,.print-hint{display:none!important}body{background:#fff!important;max-width:none!important}.pro-doc .alerte,.pro-doc .mention-bloc,.pro-doc .pro-lignes,.pro-doc .pro-partie,.pro-doc .pro-kv td:first-child{-webkit-print-color-adjust:exact;print-color-adjust:exact}.pro-doc .sig-bloc{background:#fff!important;border-color:#555!important}}`;
  const bloc1 = _cautionnementBlock(bail, log, ent, bail.garant, bail.adrGarant, bail.ddnGarant, bail.lieuGarant);
  const bloc2 = bail.garant2
    ? `<div class="page-break">${_cautionnementBlock(bail, log, ent, bail.garant2, bail.adrGarant2, bail.ddnGarant2, bail.lieuGarant2)}<\/div>`
    : '';
  const html = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8">
<title>Acte de cautionnement \u2013 ${escHtml(bail.garant||'')}<\/title>
<style>${_css}<\/style><\/head><body>
<div class="print-hint">💡 <b>Avant d'imprimer</b> : dans la fenêtre Chrome/Edge (Ctrl+P), cliquer sur "Plus de paramètres" puis <b>décocher "En-têtes et pieds de page"</b> pour un rendu professionnel sans URL ni date d'impression.<\/div>
${bloc1}${bloc2}
<div class="no-print" style="margin-top:16px;text-align:center;display:flex;justify-content:center;gap:12px">
<button onclick="window.print()" style="padding:8px 20px;font-size:11pt;cursor:pointer;background:#1a4b8c;color:#fff;border:none;border-radius:4px">\uD83D\uDDA8 Imprimer \/ PDF<\/button>
<button onclick="window.close()" style="padding:8px 20px;font-size:11pt;cursor:pointer;background:#ccc;color:#333;border:none;border-radius:4px">Fermer<\/button>
<\/div>
<\/body><\/html>`;

  const win = window.open('','_blank');
  if(!win) { showToast('Popup bloqu\u00e9e \u2014 autoriser les popups pour ce site','err'); return; }
  win.document.write(_injectPreviewCloseButton(html));
  win.document.close();
}

// ─── Phase 3a (v12.52) — Namespace BailDocument ──────────────────────────────
// API canonique des générateurs de documents Bail.
// Implémentation alias-only : pointe vers les fonctions globales existantes
// (zéro déplacement de code → zéro risque de régression sur le rendu).
// Les corps évolueront en 3b (templates ES6) et 3c (extraction des constantes).
// Phase 3d intégrera ce namespace dans Bail.document = BailDocument.
const BailDocument = {
  previewHTML:               previewBailData,
  exportWord:                exportBailWord,
  generateActeCautionnement: genActeCautionnementDoc,
};

// ─── Phase 3d (v12.56) — Namespace Bail global ───────────────────────────────
// API canonique du module Bail. Alias des fonctions globales existantes
// (zéro déplacement de code → zéro risque). Les onclick HTML inline et les
// callers JS continuent de marcher tels quels.
// Permet l'introspection du module : taper `Bail.` dans la console DevTools
// autocomplète toute l'API publique du module.
const Bail = {
  // ── CRUD ──────────────────────────────────────────────
  open:    openBail,
  save:    saveBail,
  delete:  delBail,
  copy:    copyBailFrom,

  // ── Cycle de vie (clôture / fin de bail) ──────────────
  cloreOpen: openBailClore,    // ouvre la modale de clôture
  cloreSave: saveBailClore,    // confirme la clôture
  terminate: terminerBail,     // bouton "Terminer" depuis le formulaire
  archive:   archiverBail,     // archivage direct (legacy)

  // ── Render listes (page principale / historique) ──────
  renderActifs:     rBaux,
  renderHistorique: rBauxHistorique,

  // ── Render formulaire (sous-listes dynamiques) ────────
  renderLocs:        renderBailLocs,
  renderGarants:     renderBailGarants,
  renderSignataires: renderBailSignataires,

  // ── Locataires / Garants — CRUD inline ────────────────
  addLocataire,
  removeLocataire,
  addGarant,
  removeGarant,

  // ── Helpers form (extraction des données saisies) ─────
  getDataFromForm: getBailDataFromForm,
  getLocs:         getBailLocs,
  getGarants:      getBailGarants,
  getSignataires:  getBailSignataireSelection,

  // ── Status (calculés) ─────────────────────────────────
  getProgress: getBailProgress,

  // ── Auto-fill / handlers form ─────────────────────────
  onRefChange:        onBailRefChange,
  onDebutChange:      onBailDebutChange,
  onLoyerChange:      onBailLoyerChange,
  autoFin:            autoFinBail,
  autoIRLTrimestre,
  autoPlafondCaution,
  toggleMandataire:   toggleBailMandataire,

  // ── Wizard 4 étapes ───────────────────────────────────
  wizard: {
    goStep:   goBailStep,
    nextStep: nextBailStep,
    prevStep: prevBailStep,
    close:    closeBailWizard,
  },

  // ── Preview / Documents (façades + sub-namespace) ─────
  preview:    previewBail,        // preview depuis form courant
  previewRef: previewBailRef,     // preview depuis ref logement
  document:   BailDocument,       // sub-namespace exports docs (Phase 3a)

  // ── Historique (sous-objet dédié) ─────────────────────
  hist: {
    open:       openBailHist,
    close:      closeBailHist,
    preview:    previewBailHist,
    exportWord: exportBailHistWord,
    delete:     delBailHist,
  },

  // ── Template editor (Params > Bail) ───────────────────
  templateEditor: {
    save:    saveBailTemplate,
    preview: previewBailTemplate,
    reset:   resetBailTemplate,
  },
};

function autoPlafondCaution() {
  const hc = parseFloat(el('b-hc')?.value||0);
  const ch = parseFloat(el('b-ch')?.value||0);
  const debut = el('b-debut')?.value;
  const fin   = el('b-fin')?.value;
  var ans = 6;
  if(debut && fin) {
    const ms = new Date(fin) - new Date(debut);
    ans = Math.max(1, Math.ceil(ms / (1000*60*60*24*365.25)));
  }
  const plafond = Math.round(ans * 12 * (hc + ch) * 100) / 100;
  if(el('b-plafondCaution')) el('b-plafondCaution').value = plafond;
  showToast('Plafond : '+fmtN(plafond)+' € ('+ans+' ans × 12 × '+fmtN(hc+ch)+' €)', 'ok');
}

function toggleBailMandataire(on) {
  const info = el('b-mandataire-info');
  if(!info) return;
  info.style.display = on ? '' : 'none';
  if(on) {
    const m = DB.params&&DB.params.mandataire;
    const prev = el('b-mandataire-preview');
    if(prev && m && m.nom) {
      prev.innerHTML = '<strong>'+escHtml(m.nom)+'</strong>'
        +(m.activite?' &mdash; '+escHtml(m.activite):'')
        +(m.carte?'<br>Carte prof. n° <strong>'+escHtml(m.carte)+'</strong> délivrée par CCI de '+escHtml(m.cci||'—'):'')
        +(m.garantNom?'<br>Garant financier : '+escHtml(m.garantNom)+(m.garantMontant?' ('+escHtml(m.garantMontant)+' €)':''):'')
        +'<br><span style="font-size:10px;color:var(--mu)">Les informations du mandataire seront imprimées dans le bail.</span>';
    } else if(prev) {
      prev.innerHTML = '⚠️ Aucun mandataire configuré — aller dans <strong>Référentiel → 🤝 Mandataire</strong>';
    }
  }
}
function toggleZoneTendue() {
  const on = el('b-zoneTendue')?.checked;
  const ew = el('b-encadrement-wrap'); if(ew) ew.style.display = on ? '' : 'none';
  const zf = el('b-zone-tendue-fields'); if(zf) zf.style.display = on ? '' : 'none';
  if(!on) { if(el('b-encadrementLoyers')) el('b-encadrementLoyers').checked=false; toggleEncadrement(); }
  toggleTravauxInterLoc();
}
function toggleEncadrement() {
  const on = el('b-encadrementLoyers')?.checked;
  const ef = el('b-encadrement-fields'); if(ef) ef.style.display = on ? '' : 'none';
  toggleTravauxInterLoc();
}
function togglePremiereLoc() {
  const v = el('b-premiereLoc')?.value;
  const w = el('b-dernier-loyer-wrap'); if(w) w.style.display = (v==='relocation') ? '' : 'none';
  toggleTravauxInterLoc();
}
/* v13.23 BAIL-TRAVAUX-INTERLOC : champ travaux visible si zone tendue OR
   encadrement OR précédent loc < 18 mois (cas où la majoration est justifiable). */
function toggleTravauxInterLoc() {
  const w = el('b-travaux-inter-loc-wrap'); if(!w) return;
  const zt = !!el('b-zoneTendue')?.checked;
  const enc = !!el('b-encadrementLoyers')?.checked;
  const recent = el('b-precedentLoc')?.value === 'moinsde18';
  w.style.display = (zt || enc || recent) ? '' : 'none';
}

function saveGlobalParams() {
  if(!DB.params) DB.params = {};
  // PC-REFONTE étape 2 : prénom + représentant vivent dans « Mon profil ». Gardes :
  // si l'input n'est pas rendu, on préserve la valeur existante (jamais d'écrasement à vide).
  DB.params.gerantDefaut = el('param-gerant-defaut') ? v('param-gerant-defaut').trim() : (DB.params.gerantDefaut || '');
  DB.params.userName     = el('param-user-name')     ? v('param-user-name').trim()     : (DB.params.userName || '');
  // Relais signature retiré des réglages (défaut RELAY_BASE_DEFAULT). Champ absent → rien à écrire.
  saveDB();
  showToast('Paramètres enregistrés ✓', 'ok');
}

/* v2 Dashboard — salutation contextuelle (cahier §3.1 & §8.1).
   Appelée par la Context bar en Phase 2. Safe si userName absent. */
function getSalutation() {
  const h = new Date().getHours();
  const base = h < 12 ? 'Bonjour' : h < 18 ? 'Bon après-midi' : 'Bonsoir';
  const nm = (DB && DB.params && DB.params.userName) ? String(DB.params.userName).trim() : '';
  return nm ? (base + ' ' + nm) : base;
}


// ══════════════════════════════════════════════════════════════
// RÈGLES D'IMPORT AUTOMATIQUE
// ══════════════════════════════════════════════════════════════
// V3-REFONTE-LOYERS v15.319 : _ruleFieldSel supprimé (colonnes indépendantes remplacées par _affZone ; plus d'appelant).

// ─── V3-REFONTE-LOYERS — éditeur de règles d'import : affectation via le bloc réutilisable _affZone ───
// Une règle = une affectation (qui / imm / compteurCcId). On réutilise _affZone (comme le formulaire et
// le split) → exclusivité qui↔compteur GARANTIE. Avant : 3 selects indépendants pouvaient poser qui ET
// compteur simultanément, propagés tels quels à l'import → mouvement importé en violation du
// contrat (et l'import court-circuite le garde-fou de saveMv).
// Le hook _affHooks['rule'+i] recopie chaque pick dans DB.importRules[i].
function _ruleDeriveNiv(r) {
  if (r.compteurCcId) return 'recup';
  if (String(r.qui||'').startsWith('SCI:')) return 'sci';
  if (r.imm && !r.qui) return 'imm';
  if (r.qui) return 'log';
  return (typeof _catNiveau==='function') ? _catNiveau(r.cat||'') : 'log';
}
// Résout l'immeuble d'un compteur collectif (compat règles anciennes : compteur sans immeuble).
function _ccImmeuble(ccId) {
  let nom = '';
  (DB.entites||[]).filter(_isAlive).forEach(e => (e.immeubles||[]).forEach(im => {
    if((im.compteursCollectifs||[]).some(c => c && c.id === ccId)) nom = im.nom;
  }));
  return nom;
}

// ══════════════════════════════════════════════════════════════
// REGLES-REFONTE phase 6b — « MES RÈGLES » (maquette mes-regles.html, version SIMPLE décidée par Didier)
// Une seule liste, deux accès (Réglages ▸ Règles, et Loyers & Mouvements ▸ fenêtre « Mes règles »).
//  · groupée par COMPTE (avec son bailleur), filtre bailleur + « Voir tout » ;
//  · règles historiques sans compte : groupe « Compte à choisir » en tête (pas d'assistant de migration) ;
//  · signal de DOUBLON : « Fusionner » (garde la plus LARGE, audit I2) ou « Garder les deux » (mémorisé sur la règle,
//    champ `gardeAvec`, voir _bankRuleGarderLesDeux) ;
//  · « N exception(s) » dépliable, chacune retirable ;
//  · Modifier = la MÊME fenêtre que la création (`_bankRuleOpen(id)`) ; Supprimer = confirmation + tombstone.
// NON fait volontairement (« on fait simple ») : test de libellé, statistiques d'utilisation.
// La logique (regroupement, doublons, fusion) est dans js/core/bank-import.js (pur, testé) ; ici : le rendu.
// Les identifiants / libellés passent par data-*, jamais dans le code d'un onclick ; tout texte est échappé.
// ══════════════════════════════════════════════════════════════
function _bankRulesOpen() { openM('ov-bank-rules'); rParamsRules('import-rules-list-modal'); }

let _bankRulesBailleur = null;   // null = bailleur actif de la barre de gauche (à défaut : tout) · 'all' = Voir tout · sinon un bailleur
const _bankRulesExOpen = {};     // règles dont les exceptions sont dépliées { id: true } (le dépliage survit au rafraîchissement)

// Les textes statiques d'index.html (« …dans l'ordre », « + Règle ») datent d'avant la refonte : on les met à jour ici.
function _bankRulesEntete() {
  const hd = document.querySelector('#tp-rules .flex-b');
  if (hd) {
    const d = hd.querySelector('.mu.sm'); if (d) d.textContent = 'À l\'import bancaire, si le libellé contient tous les mots d\'une règle, sa catégorie et son affectation sont proposées.';
    const b = hd.querySelector('button'); if (b) b.textContent = '+ Nouvelle règle';
  }
  const f = document.querySelector('#ov-bank-rules .m-foot .bp'); if (f) f.textContent = '+ Nouvelle règle';
}
// Bailleur affiché : le choix de l'utilisateur, sinon le bailleur actif de la barre de gauche s'il porte un compte, sinon tout.
function _bankRulesBailleurEff(bailleurs) {
  const norm = _bankRuleNorm;
  const has = b => bailleurs.some(x => norm(x) === norm(b));
  if (_bankRulesBailleur === 'all') return 'all';
  if (_bankRulesBailleur && has(_bankRulesBailleur)) return _bankRulesBailleur;
  if (_bankRulesBailleur === null && typeof _activeEntity !== 'undefined' && _activeEntity && has(_activeEntity)) return _activeEntity;
  return 'all';
}
function _bankRulesRefresh() {
  if (el('import-rules-list')) rParamsRules();
  if (el('import-rules-list-modal')) rParamsRules('import-rules-list-modal');
}

function _bankRulesAffTxt(r) {
  if (r.bailleurDuCompte) return 'le bailleur du compte';
  if (r.compteurCcId) { const im = _ccImmeuble(r.compteurCcId); return 'Compteur collectif' + (im ? ' — ' + im : ''); }
  if (String(r.qui || '').startsWith('SCI:')) return r.qui.slice(4);
  if (r.qui) return _logLabel(r.qui);   // B3 : nom affiché
  if (r.imm) return 'Immeuble ' + r.imm;
  return '(aucune affectation)';
}

function _bankRulesCarteHtml(r, doublonAvec) {
  const v = window._bankRuleVue(r);
  const motif = rr => window._bankRuleMotif(rr);
  const pills = v.mots.map(w => '<span class="brg-pill">' + escHtml(w) + '</span>').join('')
    + v.motsLibres.map(w => '<span class="brg-pill brg-pill--saisi">' + escHtml(w) + ' <em>saisi</em></span>').join('');
  const montant = v.montant ? _bankRuleMontantTxt(v.montant) : '';
  const sens = v.sens === 'db' ? '<span class="brg-bdg neg">Dépense</span>' : (v.sens === 'cr' ? '<span class="brg-bdg pos">Recette</span>' : '<span class="brg-bdg">Les deux</span>');
  const n = v.exceptions.length;
  const rid = escHtml(v.id);
  const act = (a, lbl, cls, extra) => '<button type="button" class="brg-lnk' + (cls ? ' ' + cls : '') + '" data-act="' + a + '" data-rid="' + rid + '"' + (extra || '') + ' onclick="_bankRulesAct(this)">' + lbl + '</button>';
  const exc = n
    ? '<details class="brg-exn"' + (_bankRulesExOpen[v.id] ? ' open' : '') + ' data-rid="' + rid + '" ontoggle="_bankRulesToggle(this)"><summary>' + n + ' exception' + (n > 1 ? 's' : '') + '</summary>'
      + '<ul class="brg-exc">' + v.exceptions.map(e => '<li><span>' + (e.date ? escHtml(fd(e.date)) + ' · ' : '') + escHtml(e.libelle || '(libellé inconnu)')
        + (e.montant != null && e.montant !== '' ? ' · ' + (e.sens === 'cr' ? '+' : '−') + fmt(Math.abs(Number(e.montant) || 0)) : '')
        + ' <span class="brg-mut">— sortie de la règle</span></span>'
        + act('xdel', 'Retirer', '', ' data-cle="' + escHtml(e.cle) + '"') + '</li>').join('') + '</ul></details>'
    : '';
  const dbl = doublonAvec
    ? '<div class="brg-alert warn brg-rule-wide"><b>Doublon probable</b> : même compte, même résultat que <span class="brg-mot">« ' + escHtml(motif(doublonAvec)) + ' »</span>. '
      + 'Fusionner garde « ' + escHtml(motif(doublonAvec)) + ' », la plus large : elle attrape aussi toutes les lignes de celle-ci, aucune ne perd son classement. Les exceptions des deux sont réunies.'
      + '<div class="brg-acts">'
      + '<button type="button" class="brg-btn" data-act="merge" data-rid="' + rid + '" data-other="' + escHtml(doublonAvec.id) + '" onclick="_bankRulesAct(this)">Fusionner (garder « ' + escHtml(motif(doublonAvec)) + ' »)</button>'
      + '<button type="button" class="brg-btn" data-act="keep" data-rid="' + rid + '" data-other="' + escHtml(doublonAvec.id) + '" onclick="_bankRulesAct(this)">Garder les deux</button></div></div>'
    : '';
  return '<div class="brg-rule' + (doublonAvec ? ' dup' : '') + '" data-rid="' + rid + '">'
    + '<div class="brg-rule-mo"><div class="brg-pills">' + (pills || '<span class="brg-mut">(motif vide)</span>') + '</div>'
    + '<div class="brg-rule-bd">' + (v.compteAChoisir ? '<span class="brg-bdg warn">Compte à choisir</span>' : '') + sens
    + (montant ? '<span class="brg-bdg adv">' + escHtml(montant) + '</span>' : '') + '</div></div>'
    + '<div class="brg-rule-rs">→ ' + (r.cat ? escHtml(r.cat) : '<span class="brg-mut">(aucune catégorie)</span>') + '<small>' + escHtml(_bankRulesAffTxt(r)) + '</small></div>'
    + '<div class="brg-rule-ac">' + act('edit', v.compteAChoisir ? 'Ouvrir et choisir le compte' : 'Modifier') + act('del', 'Supprimer', 'brg-lnk--neg') + '</div>'
    + dbl + exc + '</div>';
}

function rParamsRules(hostId) {
  if(!DB.importRules) DB.importRules = [];
  // REGLES-REFONTE phase 4 — identité par id : une règle sans id (base pas encore migrée) en reçoit un ici.
  _bankMigrerRegles('liste des règles');
  _bankRulesEntete();
  const host = el(hostId || 'import-rules-list'); if (!host) return;
  if(!DB.importRules.some(r => r && !r._deleted)) {
    host.innerHTML = '<div class="mu sm" style="padding:16px;text-align:center;line-height:1.6">'
      + '<b>Aucune règle.</b><br>Propryo ne livre aucune règle toute faite : ce sont <b>des données propres au compte</b>, pas celles de Propryo.<br>'
      + 'À créer depuis une ligne d\'import (' + _uiIcon('save',12) + ' Mémoriser la règle) ou avec « + Nouvelle règle ».</div>';
    return;
  }
  const accounts = (DB.params.bankAccounts || []).filter(a => a && !a._deleted);
  const tous = window._bankRulesParCompte(DB.importRules, accounts, {});
  const bail = _bankRulesBailleurEff(tous.bailleurs);
  const g = window._bankRulesParCompte(DB.importRules, accounts, { bailleur: bail });
  const dup = window._bankRulesDoublonsParId(DB.importRules);
  const cartes = rs => rs.map(r => _bankRulesCarteHtml(r, dup[r.id] || null)).join('');
  const nb = rs => '<span class="brg-mut" style="font-size:var(--fs-sm)">' + rs.length + ' règle' + (rs.length > 1 ? 's' : '') + '</span>';
  const bailBtn = (val, lbl) => '<button type="button" class="brg-btn" aria-pressed="' + (bail === val || (val !== 'all' && bail !== 'all' && _bankRuleNorm(bail) === _bankRuleNorm(val))) + '" data-act="bail" data-val="' + escHtml(val) + '" onclick="_bankRulesAct(this)">' + escHtml(lbl) + '</button>';
  let h = '<div class="brg-rl"><div class="brg-bar"><p class="brg-hint">Classées par compte. Une règle s\'applique aux prochains imports ; elle ne touche pas aux mouvements déjà enregistrés.</p>'
    + (tous.bailleurs.length > 1
      ? '<div class="brg-acts" role="group" aria-label="Bailleur" style="margin:0">' + tous.bailleurs.map(b => bailBtn(b, 'Bailleur : ' + b)).join('') + bailBtn('all', 'Voir tout') + '</div>'
      : '')
    + '</div>';
  if (g.sansCompte.length) {
    h += '<section class="brg-grp warn"><div class="brg-grp-h"><h3>Compte à choisir <span class="brg-bdg warn">règles historiques</span></h3>' + nb(g.sansCompte) + '</div>'
      + '<p class="brg-hint">Ces règles datent d\'avant l\'obligation de compte : elles restent actives sur tous les comptes. Les ouvrir pour choisir leur compte (obligatoire pour enregistrer).</p>'
      + cartes(g.sansCompte) + '</section>';
  }
  g.groupes.forEach(({ compte: a, regles }) => {
    h += '<section class="brg-grp"><div class="brg-grp-h"><h3>' + escHtml(a.label || '(compte)') + ' <span class="brg-bdg">'
      + (a.mixte ? 'compte mixte' : (a.bailleur ? 'bailleur : ' + escHtml(a.bailleur) : 'bailleur à renseigner')) + '</span></h3>' + nb(regles) + '</div>' + cartes(regles) + '</section>';
  });
  if (g.inconnus.length) {
    h += '<section class="brg-grp warn"><div class="brg-grp-h"><h3>Compte supprimé <span class="brg-bdg warn">à vérifier</span></h3>' + nb(g.inconnus) + '</div>'
      + '<p class="brg-hint">Le compte de ces règles n\'existe plus dans les Réglages.</p>' + cartes(g.inconnus) + '</section>';
  }
  if (g.masquees) {
    h += '<p class="brg-hint" style="text-align:center">Les règles de ' + g.bailleursMasques.map(b => '« ' + escHtml(b) + ' »').join(', ') + ' (' + g.masquees + ') ne sont pas affichées. '
      + '<button type="button" class="brg-lnk" data-act="bail" data-val="all" onclick="_bankRulesAct(this)">Voir tout</button></p>';
  }
  host.innerHTML = h + '</div>';
}

function _bankRulesToggle(det) {
  const rid = det && det.dataset.rid; if (!rid) return;
  if (det.open) _bankRulesExOpen[rid] = true; else delete _bankRulesExOpen[rid];
}

// Point d'entrée unique des boutons de la liste : l'action et les identifiants viennent des data-attributes.
function _bankRulesAct(btn) {
  const act = btn.dataset.act, rid = btn.dataset.rid;
  if (act === 'edit') { _bankRuleOpen(rid); return; }
  if (act === 'del') { delRule(rid); return; }
  if (act === 'bail') { _bankRulesBailleur = btn.dataset.val || 'all'; _bankRulesRefresh(); return; }
  if (act === 'merge') { _bankRulesFusionner(rid, btn.dataset.other); return; }
  if (act === 'keep') { _bankRulesGarderLesDeux(rid, btn.dataset.other); return; }
  if (act === 'xdel') { _bankRulesRetirerException(rid, btn.dataset.cle); return; }
}

// « Fusionner » : la plus LARGE est gardée (audit I2 : rien n'est perdu ; exceptions réunies, `_stamp`),
// l'autre devient un tombstone par id.
function _bankRulesFusionner(idA, idB) {
  const ia = window._bankRuleIdxById(DB.importRules, idA), ib = window._bankRuleIdxById(DB.importRules, idB);
  if (ia < 0 || ib < 0) { showToast('Règle introuvable', 'err'); return; }
  const f = window._bankRulesFuse(DB.importRules[ia], DB.importRules[ib]);
  if (!confirm2('Fusionner les deux règles ?\n\n« ' + window._bankRuleMotif(f.garder) + ' » est conservée, « ' + window._bankRuleMotif(f.retirer) + ' » est supprimée. Les mouvements déjà classés ne changent pas.')) return;
  const ig = window._bankRuleIdxById(DB.importRules, f.garder.id), ir = window._bankRuleIdxById(DB.importRules, f.retirer.id);
  _stamp(f.garder);
  DB.importRules[ig] = f.garder;
  DB.importRules[ir] = f.tombstone;
  _stamp(DB);
  saveDB();
  const motif = window._bankRuleMotif(f.garder);
  if (typeof _auditLog === 'function') _auditLog('update', 'import-rule', f.garder.id, 'fusion : « ' + window._bankRuleMotif(f.retirer) + ' » fusionnée dans « ' + motif + ' »');
  _bankRuleAfterChange(null);
  showToast('✓ Règles fusionnées : « ' + motif + ' » est conservée', 'ok', 4000);
}

// « Garder les deux » : le signal ne revient plus pour cette paire (champ `gardeAvec` sur la règle).
function _bankRulesGarderLesDeux(idA, idB) {
  const ia = window._bankRuleIdxById(DB.importRules, idA), ib = window._bankRuleIdxById(DB.importRules, idB);
  if (ia < 0 || ib < 0) { showToast('Règle introuvable', 'err'); return; }
  const rule = window._bankRuleGarderLesDeux(DB.importRules[ia], DB.importRules[ib]);
  if (rule !== DB.importRules[ia]) {
    _stamp(rule);
    DB.importRules[ia] = rule;
    _stamp(DB);
    saveDB();
  }
  _bankRulesRefresh();
  showToast('Les deux règles sont conservées', 'ok', 3000);
}

// Retire UNE exception (même fonction pure que « Réintégrer à la règle »). Aucun mouvement en base n'est reclassé.
function _bankRulesRetirerException(rid, cle) {
  const idx = window._bankRuleIdxById(DB.importRules, rid);
  if (idx < 0) { showToast('Règle introuvable', 'err'); return; }
  const rule = window._bankRuleRemoveException(DB.importRules[idx], cle);
  if (rule === DB.importRules[idx]) return;
  _stamp(rule);
  DB.importRules[idx] = rule;
  _stamp(DB);
  saveDB();
  if (typeof _auditLog === 'function') _auditLog('update', 'import-rule', rule.id, 'exception retirée sur « ' + window._bankRuleMotif(rule) + ' »');
  _bankRuleAfterChange(rule);
  showToast('✓ Exception retirée : les mouvements déjà en base ne sont pas reclassés', 'ok', 4000);
}


function addImportRule() {
  if(!DB.importRules) DB.importRules = [];
  _bankRuleOpen(null, null);   // ⑦.4 : création à froid, avec aperçu — plus de ligne vide à remplir (compte à choisir, obligatoire)
}

// REGLES-REFONTE phase 4 (D6) — la règle à supprimer est désignée par son IDENTIFIANT,
// jamais par son motif ni par une position : deux règles au même motif (une par compte)
// ne se confondent plus.
function delRule(id) {
  _bankRuleDeleteById(id);
}
// Suppression commune (liste des règles + fenêtre de règle). Renvoie true si supprimée.
// v15.186 : tombstone EN PLACE (jamais de splice), désormais indexé sur l'identifiant
// (`_bankRuleTombstone` garde aussi motif + compte pour la compat et le journal).
function _bankRuleDeleteById(id) {
  if (!Array.isArray(DB.importRules)) return false;
  const i = window._bankRuleIdxById(DB.importRules, id);
  const r = i >= 0 ? DB.importRules[i] : null;
  if (!r) { showToast('Règle introuvable', 'err'); return false; }
  const motif = window._bankRuleMotif(r);
  if (!confirm2('Supprimer la règle « ' + motif + ' » ?\n\nLes mouvements déjà classés ne changent pas.')) return false;
  DB.importRules[i] = window._bankRuleTombstone(r);
  saveDB();
  if (typeof _auditLog === 'function') _auditLog('delete', 'import-rule', r.id || motif, 'suppression « ' + motif + ' »');
  // ⑦.3 — les lignes de l'import en cours se reclassent immédiatement.
  const res = _bankRuleAfterChange(null);
  showToast('🗑 Règle supprimée' + (res.reclasse ? ' · les lignes de l\'import ont été reclassées' : ''), 'ok', 3000);
  return true;
}


// ⑦.6 — `applyImportRules` (moteur de règles de l'ancien staging) est SUPPRIMé :
// il n'avait plus d'appelant depuis le retrait du staging de la page Import. Le seul
// moteur de règles est désormais `_bankApplyRules` (js/core/bank-import.js), testé.

// ══════════════════════════════════════════════════════════════
// THÈME COULEURS
// ══════════════════════════════════════════════════════════════
const THEME_DEFAULTS = {
  '--bg':   '#0d1117',
  '--sur':  '#161b22',
  '--sur2': '#1c2128',
  '--bor':  '#30363d',
  '--t1':   '#e6edf3',
  '--t2':   '#8b949e',
  '--acc':  '#388bfd',
  '--grn':  '#3fb950',
  '--red':  '#f85149',
  '--ora':  '#f0883e',
};

const THEME_LABELS = {
  '--bg':   'Fond principal',
  '--sur':  'Fond des cartes',
  '--sur2': 'Fond secondaire',
  '--bor':  'Bordures',
  '--t1':   'Texte principal',
  '--t2':   'Texte secondaire',
  '--acc':  'Accent (bleu)',
  '--grn':  'Succès (vert)',
  '--red':  'Erreur (rouge)',
  '--ora':  'Alerte (orange)',
};

function rParamsTheme() {
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem(_lsKey('immotrack_theme')) || '{}') || {}; }
  catch (e) { console.warn('[theme] valeur localStorage corrompue, ignorée', e); }  // sinon un thème corrompu casse l'onglet Réglages
  const cur   = {...THEME_DEFAULTS, ...saved};
  el('theme-pickers').innerHTML = Object.entries(THEME_LABELS).map(([k,label])=>`
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:10px">
      <input type="color" value="${cur[k]||THEME_DEFAULTS[k]}" data-var="${k}"
        onchange="previewThemeVar(this.dataset.var, this.value)"
        style="width:40px;height:32px;border:1px solid var(--bor);border-radius:4px;cursor:pointer;padding:2px;background:var(--sur)">
      <span style="font-size:13px;min-width:160px">${label}</span>
      <code style="font-size:11px;color:var(--t2)">${k}</code>
    </div>`).join('');
}

function previewThemeVar(varName, value) {
  document.documentElement.style.setProperty(varName, value);
}

function saveTheme() {
  const inputs = el('theme-pickers').querySelectorAll('input[type=color]');
  const theme = {};
  inputs.forEach(inp => theme[inp.dataset.var] = inp.value);
  localStorage.setItem(_lsKey('immotrack_theme'), JSON.stringify(theme));
  applyTheme(theme);
  showToast('Thème appliqué et sauvegardé', 'ok');
}

function resetTheme() {
  localStorage.removeItem(_lsKey('immotrack_theme'));
  Object.entries(THEME_DEFAULTS).forEach(([k,v])=>document.documentElement.style.setProperty(k,v));
  rParamsTheme();
  showToast('Thème restauré', 'ok');
}

function applyTheme(theme) {
  Object.entries(theme||{}).forEach(([k,v])=>document.documentElement.style.setProperty(k,v));
}

// ═══════════════════════════════════════════════════════════════════
//  v15.04 USER-PROFILE-FILTERS Phase 4 — Onglet Paramètres
// ═══════════════════════════════════════════════════════════════════

// Liste de modules exposés à l'utilisateur dans la matrice (override toggles).
// On expose les modules non-CORE pour éviter de masquer accidentellement biens/baux/etc.
// PC-REFONTE étape 2 — seuls les modules RÉELS (fonctionnalités livrées) restent.
// Les 9 modules « À venir Sprint 7/8 » (dashboard-lentilles, bailleurs-multi, travaux,
// pilotage-matriciel, export-fec, mandat-crg-sepa, audit-trail-ui, carnet-adresse,
// bank-integration) exposaient des cases inertes vers des features inexistantes → retirés.
const PROFILE_TOGGLEABLE_MODULES = [
  { key:'import',             label:'Import / Données',          desc:'Imports CSV/Excel, batches' },
  { key:'charges-regul',      label:'Régularisation charges',    desc:'Régul annuelle + provisions' },
  { key:'export',             label:'Export / Sauvegarde',       desc:'Backups + restore + Drive' },
  { key:'equipements',        label:'Équipements',               desc:'Suivi chaudière, DAAF, etc.' },
  { key:'candidats',          label:'Candidats / pré-baux',      desc:'Pipeline candidatures + conversion bail' },
];

function rParamsProfile() {
  const wrap = el('tp-profile');
  if (!wrap) return;
  const profile = (DB.params && DB.params.userProfile) || 'solo';
  const overrides = (DB.params && DB.params.modulesEnabled) || {};
  const label = USER_PROFILE_LABELS[profile] || profile;
  const ans = (DB.params && DB.params._profileWizardAnswers) || null;

  const ansHtml = ans ? `
    <ul class="mu sm" style="margin:4px 0 0 18px;padding:0;line-height:1.7">
      <li>Logements gérés : <strong>${ans.nbLogements||'—'}</strong></li>
      <li>Statut juridique : <strong>${ans.statut||'—'}</strong></li>
      <li>Mandataire : <strong>${ans.estMandataire ? 'Oui' : 'Non'}</strong></li>
      <li>Comptabilité : <strong>${ans.compta||'—'}</strong></li>
    </ul>` : '<div class="mu sm">Pas de réponses enregistrées (wizard passé).</div>';

  wrap.innerHTML = `
    <div style="max-width:760px">
      <div class="ct mb16">${_uiIcon('person',16)} Mon profil</div>

      <div style="border:1px solid var(--bor);border-radius:var(--r);padding:16px;margin-bottom:16px;background:var(--sur2)">
        <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:10px">
          <div>
            <div class="mu sm" style="font-size:10.5px;letter-spacing:.7px;text-transform:uppercase">Profil actuel</div>
            <div style="font-size:17px;font-weight:700;color:var(--acc)">${label}</div>
          </div>
          <div style="margin-left:auto;display:flex;gap:8px">
            <button class="btn bs bb" onclick="_profileWizardOpen()">${_uiIcon('edit',14)} Modifier mon profil</button>
          </div>
        </div>
        ${ansHtml}
      </div>

      <!-- PC-REFONTE étape 2 : identité regroupée ici (prénom + représentant), déplacée depuis « Préférences ». -->
      <div class="ct mb12" style="font-size:14px">${_uiIcon('person',15)} Identité</div>
      <div style="border:1px solid var(--bor);border-radius:var(--r);padding:16px;margin-bottom:16px">
        <div class="fg mb8">
          <label style="font-size:11px">Prénom (salutation du tableau de bord — « Bonjour Jean »)</label>
          <input class="inp" id="param-user-name" placeholder="ex : Jean" style="width:100%" value="${escHtml(DB.params.userName||'')}">
        </div>
        <div class="fg mb8">
          <label style="font-size:11px">Représentant bailleur par défaut (pré-rempli dans les EDL)</label>
          <input class="inp" id="param-gerant-defaut" placeholder="ex : Jean Dupont" style="width:100%" value="${escHtml(DB.params.gerantDefaut||'')}">
        </div>
        <button class="btn bp bb" onclick="saveGlobalParams()">${_uiIcon('save',14)} Enregistrer</button>
      </div>
      <div id="cia-profil-mount"></div>
    </div>`;
  // CONSO-IA : « Utilisation de l'IA ce mois-ci » (compte connecté au cloud seulement ; absent sinon).
  try { if (window.ConsoIa) window.ConsoIa.carteProfil(el('cia-profil-mount')); } catch(e) {}
  // PREMIERS-PAS : « Relancer la visite guidée », réaffichage de la liste, partage de la progression (D6).
  try { if (window.PremiersPas) window.PremiersPas.profil(wrap); } catch(e) {}
}

function _profileToggleModule(moduleKey, on) {
  if (!moduleKey) return;
  if (!DB.params) DB.params = {};
  if (!DB.params.modulesEnabled) DB.params.modulesEnabled = {};
  DB.params.modulesEnabled[moduleKey] = !!on;
  saveDB();
  if (typeof _renderSidebarFiltered === 'function') _renderSidebarFiltered();
  if (typeof showToast === 'function') {
    showToast((on ? '✓ Activé : ' : '✕ Désactivé : ') + moduleKey, 'ok', 2000);
  }
  // Refresh affichage badges "override actif"
  rParamsProfile();
}

function _profileResetOverrides() {
  if (!DB.params) DB.params = {};
  DB.params.modulesEnabled = {};
  saveDB();
  if (typeof _renderSidebarFiltered === 'function') _renderSidebarFiltered();
  rParamsProfile();
  if (typeof showToast === 'function') {
    showToast('Modules réinitialisés au profil par défaut', 'ok', 2500);
  }
}

// PC-REFONTE — l'onglet « Thème » (color-pickers) est retiré. Il posait des styles
// INLINE sur :root (spécificité maximale) qui écrasaient le switch sombre/clair
// (data-theme). Nettoyage unique au démarrage : on retire les variables inline
// héritées d'un thème custom déjà enregistré et on purge la clé, pour rendre la
// main au design-system sobre/dark. (Remplace l'ancien loadThemeOnStart qui les appliquait.)
(function cleanupLegacyCustomTheme() {
  try {
    const raw = localStorage.getItem(_lsKey('immotrack_theme'));
    if (!raw) return;
    const saved = JSON.parse(raw || '{}');
    Object.keys(saved || {}).forEach(k => document.documentElement.style.removeProperty(k));
    localStorage.removeItem(_lsKey('immotrack_theme'));
  } catch(e) {}
})();

// ══════════════════════════════════════════════════════════════
// SAUVEGARDE SUGGÉRÉE + JAUGE localStorage
// ══════════════════════════════════════════════════════════════
/* ═══ STOCKAGE lot 3 — « Stockage de cet appareil » (CDC-STOCKAGE §3.7) ═══
   Remplace la jauge « N KB / ~10 MB » (fausse : elle mesurait la base seule contre un plafond de 10 Mo
   qui n'existe pas). Maquette validée par Didier le 06/10 (mockups/STOCKAGE/reglages-etat-stockage.html).
   L'état de la copie hors ligne est décidé par _stockage.etatCopieAppareil (testé) ; ici, on rassemble ce
   que l'app sait (miroir du lot 4, échecs vus par saveDB, horodatage) et on l'affiche. Aucune donnée au
   cloud. Les deux mesures asynchrones (espace du navigateur, filets du lot 2) remplissent leur ligne
   ensuite. Le détail reste dans showDBDiag. */
function _renderStockageCard() {
  const card = el('stockage-card');
  if (!card) return;
  const titre = '<div class="ct"><span data-uic="appareil"></span> Stockage de cet appareil</div>'
    + '<p class="mu sm sub">Ce qui est gardé dans ce navigateur pour travailler sans réseau. Le cloud reste la référence.</p>';
  const S = window._stockage;
  if (!S || typeof S.etatCopieAppareil !== 'function') {
    card.innerHTML = titre + '<p class="mu sm">État indisponible : le module de stockage n’a pas été chargé sur cette page.</p>';
    _uiHydrateSlots(card);
    return;
  }
  let M = null, backend = null, incomplete = false;
  try { const L = window._miroirLocal; M = (L && typeof L.miroir === 'function') ? L.miroir() : null; } catch (e) { M = null; }
  try { if (M && M.pret()) backend = M.backend(); } catch (e) {}
  try { incomplete = !!(M && M.copieIncomplete()); } catch (e) {}
  let dernierOk = _miroirDernierOk;
  if (!dernierOk) { try { const t = Number(localStorage.getItem(KEY + '_ecrit_at')); if (t > 0) dernierOk = t; } catch (e) {} }
  const etat = S.etatCopieAppareil({ cloud: !!window.__immoSupabaseMode, sandbox: !!_isTestMode, backend,
    copieIncomplete: incomplete, echecDepuis: _miroirEchecDepuis, dernierOk, enLigne: _miroirModeCourant() === 'cloud-en-ligne',
    plein: _miroirEchecPlein });
  let base = 0;
  try { base = JSON.stringify(DB).length; } catch (e) {}
  const QUOTA = 5 * 1024 * 1024;   // ~5 M caractères par origine (Chromium) : l'ordre de grandeur, pas une promesse
  const ls = S.occupationStockage(() => localStorage);   // accès refusé → 0, jamais une exception
  const pct = Math.max(ls > 0 ? 1 : 0, Math.min(100, Math.round(ls / QUOTA * 100)));
  const lsTxt = S.enMo(ls) + ' sur ~5 Mo';
  const ligne = (lbl, val, extra, cls) => '<div class="row' + (cls ? ' ' + cls : '') + '"><div class="flex-b"><span class="mu">' + lbl + '</span>' + val + '</div>' + (extra || '') + '</div>';
  card.innerHTML = titre
    + ligne('Copie hors ligne', '<span class="badge ' + escHtml(etat.ton) + '"><i class="dot"></i>' + escHtml(etat.libelle) + '</span>',
        '<p class="mu sm expl">' + escHtml(etat.explication) + '</p>')
    + ligne('Taille de la base', '<b>' + escHtml(S.enMo(base)) + '</b>')
    + ligne('Stockage local du navigateur', '<b>' + escHtml(lsTxt) + '</b>',
        '<div class="bar' + (pct > 80 ? ' hot' : '') + '" role="img" aria-label="' + escHtml(lsTxt) + '"><span style="width:' + pct + '%"></span></div>')
    + ligne('Espace de l’app sur cet appareil', '<b class="r" id="stk-espace">Mesure en cours</b>')
    + ligne('Copies avant migration', '<b class="r" id="stk-filets">Mesure en cours</b>', '', 'last')
    + '<div class="foot"><button class="btn bs" onclick="showDBDiag()">Détail technique</button></div>';
  _uiHydrateSlots(card);
  const poser = (id, txt) => { const n = el(id); if (n) n.textContent = txt; };
  try {
    if (navigator.storage && typeof navigator.storage.estimate === 'function') {
      navigator.storage.estimate().then(est => poser('stk-espace', S.enMo(est && est.usage) + ' utilisés, photos comprises'),
        () => poser('stk-espace', 'Non mesurable sur ce navigateur'));
    } else poser('stk-espace', 'Non mesurable sur ce navigateur');
  } catch (e) { poser('stk-espace', 'Non mesurable sur ce navigateur'); }
  try {
    const A = (typeof _filetsIdb === 'function') ? _filetsIdb() : null;
    if (!A) poser('stk-filets', 'Aucune');
    else A.cles().then(cles => {
      const n = cles.filter(k => k.startsWith('filet:' + KEY + ':')).length;
      poser('stk-filets', n ? n + ' · retirées après 30 jours et à la déconnexion' : 'Aucune');
    }, () => poser('stk-filets', 'Non mesurable sur ce navigateur'));
  } catch (e) { poser('stk-filets', 'Non mesurable sur ce navigateur'); }
}

function suggestSave(context) {
  // v14.0 REFONTE-DRIVE : le push cloud est immédiat, plus besoin de rappeler de sauvegarder DANS l'app.
  // Sauvegarde de SÉCURITÉ (export local hors-app) : on propose un bandeau discret après une génération
  // (bail/EDL/import). Appelé au save — le PDF n'a souvent pas encore son cloudKey (upload à suivre) ;
  // _backupProposeAfterDoc est alors silencieux et c'est le hook « succès upload cloud » qui affichera
  // le bandeau. DRY : un seul chemin de proposition, deux déclencheurs.
  if (typeof _backupProposeAfterDoc === 'function') { try { _backupProposeAfterDoc(); } catch (e) {} }
}

function addPieceEDL(){const n=prompt('Nom de la pièce');if(!n)return;DB.piecesEDL[n.trim()]=[];saveDB();rParamsPieces();}
// v14.72 BUG #14 — tombstones EDL pieces (résiste au merge Drive)
function delPieceEDL(nom){
  if(!confirm2('Supprimer ?')) return;
  delete DB.piecesEDL[nom];
  if(!DB.params) DB.params = {};
  if(!DB.params._deletedPiecesEDL || typeof DB.params._deletedPiecesEDL !== 'object') DB.params._deletedPiecesEDL = {};
  DB.params._deletedPiecesEDL[nom] = new Date().toISOString();
  saveDB(); rParamsPieces();
}
function addElemEDL(nom){const e=prompt('Élément');if(!e)return;DB.piecesEDL[nom].push(e.trim());saveDB();rParamsPieces();}
function delElemEDL(nom,i){DB.piecesEDL[nom].splice(i,1);saveDB();rParamsPieces();}

// ══════════════════════════════════════════════════════════════
// AGENDA — Rendu UI
// ══════════════════════════════════════════════════════════════
let _agendaView = 'list';
let _agendaCalYear = new Date().getFullYear();
let _agendaCalMonth = new Date().getMonth(); // 0-indexed

function initAgendaFilters() {
  const sl = el('agenda-f-log');
  if(sl) {
    sl.innerHTML = '<option value="">Tous logements</option>'
      + _activeLogements().map(l=>`<option value="${escHtml(l.ref)}">${escHtml(_logLabelRef(l))}${l.locataire?' — '+escHtml(l.locataire):''}</option>`).join('');
  }
  const sc = el('agenda-f-cat');
  if(sc) {
    sc.innerHTML = '<option value="">Toutes catégories</option>'
      + Object.entries(AGENDA_CATS).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join(''); // v15.62x REFONTE-PC : libellé seul (un <select> natif n'affiche pas de SVG)
  }
}

function _agendaFilter(evts) {
  const fLog = el('agenda-f-log')?.value||'';
  const fCat = el('agenda-f-cat')?.value||'';
  const showDone = el('agenda-show-done')?.checked;
  return evts.filter(e=>{
    if(!showDone && e.done) return false;
    if(fLog && e.logement !== fLog) return false;
    if(fCat && e.cat !== fCat) return false;
    return true;
  });
}
/* Mobile : même filtre logement/catégorie mais on GARDE les terminés
   (le téléphone n'a pas la case « Afficher terminés » du desktop ;
   les terminés y vivent dans la section repliée + le point gris du calendrier). */
function _agendaFilterKeepDone(evts) {
  const fLog = el('agenda-f-log')?.value||'';
  const fCat = el('agenda-f-cat')?.value||'';
  return evts.filter(e=>{
    if(fLog && e.logement !== fLog) return false;
    if(fCat && e.cat !== fCat) return false;
    return true;
  });
}

function setAgendaView(v, btn) {
  _agendaView = v;
  document.querySelectorAll('#p-agenda .btn').forEach(b=>b.classList.remove('act'));
  if(btn) btn.classList.add('act');
  el('agenda-view-list-pane').style.display = v==='list' ? '' : 'none';
  el('agenda-view-cal-pane').style.display  = v==='cal'  ? '' : 'none';
  rAgenda();
}

function rAgenda() {
  agendaAutoSync(); // sync silencieux
  _updateAgendaBadge();
  try{ if(_isPhone()){ _ensureAgendaPhCss(); _ensureAgendaPhToolbar(); } }catch(e){}
  if(_agendaView === 'cal') { rAgendaCal(); return; }
  rAgendaList();
}

// Didier 16/10 : un rappel de RÉVISION IRL non fait dont la date est passée change de couleur (jeton d'alerte --neg).
function _agendaRevisionEnRetard(e) {
  if (!e || e.done || e._deleted || e.cat !== 'IRL' || !e.autoKey) return false;
  const today = (typeof _isoLocal === 'function') ? _isoLocal(new Date()) : new Date().toISOString().slice(0,10);
  const d = String(e.date || '').slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d) || d >= today) return false;
  // Seul le DERNIER rappel de révision passé du lot peut être en retard (les années précédentes sont closes).
  const autres = (DB.agenda || []).filter(x => x && !x._deleted && x.cat === 'IRL' && x.autoKey && x.logement === e.logement && String(x.date || '') < today);
  if (autres.some(x => String(x.date || '') > d)) return false;
  const l = (DB.logements || []).find(x => x && x.ref === e.logement);
  const bail = DB.baux && DB.baux[e.logement];
  if (!l || !bail || !bail.debut) return false;
  // Avant la première révision possible (un an après l'entrée) : rien à réviser.
  const debut = String(bail.debut).slice(0, 10), un = new Date(debut + 'T00:00:00'); un.setFullYear(un.getFullYear() + 1);
  if (d < _isoLocal(un).slice(0, 10)) return false;
  // Révision appliquée (ou programmée) pour ce cycle : à l'heure.
  const applique = String(l.irlDerniereApplication || '').slice(0, 10);
  if (applique) { const lim = new Date(d + 'T00:00:00'); lim.setDate(lim.getDate() - 45); if (applique >= _isoLocal(lim).slice(0, 10)) return false; }
  try { const rev = (typeof computeIRLRevision === 'function') ? computeIRLRevision(l) : null; if (rev && (rev.dejaApplique || rev.etat === 'rien-a-reviser')) return false; } catch (err) {}
  return true;
}
function _agendaEvtCard(e, compact=false) {
  if(_isPhone()) return _agendaEvtCardPhone(e);
  const cat = AGENDA_CATS[e.cat] || AGENDA_CATS.AUTRE;
  const today = new Date().toISOString().slice(0,10);
  const isOverdue = !e.done && e.date < today;
  const isToday   = e.date === today;
  const daysLeft  = Math.round((new Date(e.date+'T00:00:00') - new Date()) / 86400000);
  // v15.62x REFONTE-PC Agenda — statut via la CHARTE uniquement (rouge=retard, ambre=proche/aujourd'hui,
  // vert=fait, corail=action à réaliser). Plus de couleur par type : le type = son line-icon en encre.
  const badge = e.done
    ? `<span class="badge grn">${_uiIcon('check',10)} Fait</span>`
    : isOverdue
      ? `<span class="badge red">${_uiIcon('warn',10)} ${Math.abs(daysLeft)} j de retard</span>`
      : isToday
        ? `<span class="badge ora">Aujourd'hui</span>`
        : daysLeft <= 7
          ? `<span class="badge ora">J-${daysLeft}</span>`
          : `<span class="badge acc">À réaliser</span>`;

  return `<div class="agenda-card${e.done?' agenda-done':' agenda-todo'}${_agendaRevisionEnRetard(e)?' agenda-late':''}" onclick="openAgendaEvt('${_lyQ(e.id)}')">
    <div class="agenda-card-top">
      <span class="agenda-cat-badge">${_agendaIconSvg(e.cat,13)} ${cat.label}</span>
      ${badge}
      <div class="agenda-card-actions">
        ${!e.done
          ? `<button onclick="agendaMarkDone(event,'${e.id}')" title="Marquer fait" aria-label="Marquer fait" class="agenda-act agenda-act-done">${_uiIcon('check',14)} Marquer fait</button>`
          : `<button onclick="agendaMarkDone(event,'${e.id}')" title="Rouvrir" aria-label="Rouvrir" class="agenda-act">${_uiIcon('refresh',14)} Rouvrir</button>`}
        <button onclick="deleteAgendaEvt(event,'${e.id}')" title="Supprimer" aria-label="Supprimer" class="agenda-act agenda-act-del">${_uiIcon('trash',14)} Supprimer</button>
      </div>
    </div>
    <div class="agenda-card-title">${escHtml(e.titre)}</div>
    <div class="agenda-card-meta">
      <span>${_uiIcon('calendar',13)} ${fd(e.date)}${e.dateFin && e.dateFin!==e.date?' → '+fd(e.dateFin):''}</span>
      ${e.logement?`<span>${_uiIcon('home',13)} ${escHtml(_logLabel(e.logement))}</span>`:''}
      ${e.recurrence?.type!=='none'?`<span>${_uiIcon('refresh',13)} ${_recLabel(e.recurrence)}</span>`:''}
      ${e.auto?`<span style="color:var(--t3)">${_uiIcon('settings',13)} Auto</span>`:''}
    </div>
    ${e.notes?`<div style="font-size:12px;color:var(--t2);margin-top:4px;white-space:pre-wrap">${escHtml(e.notes.slice(0,120))}${e.notes.length>120?'…':''}</div>`:''}
  </div>`;
}

function _recLabel(r) {
  if(!r||r.type==='none') return '';
  const map = {daily:'jour',weekly:'semaine',monthly:'mois',yearly:'an'};
  return `tous les ${r.interval===1?'':r.interval+' '}${map[r.type]||r.type}(s)`;
}

function _agendaSection(title, evts, defaultOpen=true) {
  if(!evts.length) return '';
  const id = 'ags-'+Math.random().toString(36).slice(2);
  return `<div class="mb16">
    <div style="font-size:11px;font-weight:800;color:var(--t2);text-transform:uppercase;letter-spacing:1.2px;
      margin-bottom:8px;display:flex;align-items:center;gap:8px">
      ${title}
      <span style="background:var(--sur2);border:1px solid var(--bor);border-radius:10px;font-size:10.5px;
        padding:1px 8px;font-weight:700;color:var(--t1)">${evts.length}</span>
    </div>
    <div class="agenda-list">${evts.map(e=>_agendaEvtCard(e)).join('')}</div>
  </div>`;
}

function rAgendaList() {
  const today = new Date().toISOString().slice(0,10);
  const all = _agendaFilter(DB.agenda||[]).sort((a,b)=>a.date.localeCompare(b.date));
  const overdue  = all.filter(e=>!e.done && e.date < today);
  const soon7    = all.filter(e=>!e.done && e.date >= today && _daysFrom(e.date) <= 7);
  const soon30   = all.filter(e=>!e.done && e.date >= today && _daysFrom(e.date) > 7 && _daysFrom(e.date) <= 30);
  const rest     = all.filter(e=>!e.done && _daysFrom(e.date) > 30);
  const done     = all.filter(e=>e.done);

  // TÉLÉPHONE (≤767) : rendu mobile charte-only (Terminés bornés à 30 j). PC (≥768) = chemin ci-dessous inchangé.
  // Les Terminés (section repliée) sont TOUJOURS dispo sur mobile, indépendamment de « Afficher terminés » :
  // on recalcule depuis la base en respectant SEULEMENT les filtres logement/catégorie.
  if(_isPhone()){
    const donePh=_agendaFilterKeepDone(DB.agenda||[]).filter(e=>e.done)
                   .sort((a,b)=>b.date.localeCompare(a.date)); // plus récents d'abord
    _ensureAgendaPhCss(); _rAgendaListPhone({overdue,soon7,soon30,rest,done:donePh}); return;
  }

  el('agenda-overdue-section').innerHTML = _agendaSection(_uiIcon('warn',13) + ' En retard', overdue);
  el('agenda-soon7-section').innerHTML   = _agendaSection(_uiIcon('bell',13) + ' Cette semaine (7 jours)', soon7);
  el('agenda-soon30-section').innerHTML  = _agendaSection(_uiIcon('calendar',13) + ' Ce mois (30 jours)', soon30);
  el('agenda-rest-section').innerHTML    = _agendaSection(_uiIcon('list',13) + ' À venir', rest) + _agendaSection(_uiIcon('check',13) + ' Terminés', done, false);

  if(!all.length) {
    el('agenda-overdue-section').innerHTML = `<div class="card" style="text-align:center;padding:40px 20px;color:var(--t2)">
      <div style="margin-bottom:12px;color:var(--t3)">${_uiIcon('calendar',32)}</div>
      <div style="font-weight:600;margin-bottom:6px">Aucun événement</div>
      <div style="font-size:13px">Cliquer sur <b>+ Événement</b> pour en ajouter un, ou <b>Sync baux</b> pour générer automatiquement depuis les baux.</div>
    </div>`;
  }
}

function _daysFrom(dateStr) {
  return Math.round((new Date(dateStr+'T00:00:00') - new Date()) / 86400000);
}

/* ===== AGENDA MOBILE (≤767) — rendu téléphone additif, aligné sur la direction Agenda PC :
   type = line-icon ENCRE NEUTRE (pas de teinte par type), couleur = charte SEULE
   (corail=à réaliser via liseré, rouge=en retard, ambre=proche J-N), actions LIBELLÉES,
   « Terminés » borné aux 30 derniers jours. Le chemin PC (≥768) reste intact. ===== */
function _ensureAgendaPhCss(){
  if(document.getElementById('agph-css')) return;
  var st=document.createElement('style'); st.id='agph-css';
  st.textContent=[
    '.agph-sec{margin-bottom:16px}',
    '.agph-sec-h{display:flex;align-items:center;gap:8px;margin:0 2px 9px}',
    '.agph-sec-h .uic{width:14px;height:14px;color:var(--t3);flex:0 0 auto}',
    '.agph-sec-h b{font-family:var(--display,inherit);font-weight:700;font-size:13.5px;color:var(--t1)}',
    '.agph-sec-h.late b,.agph-sec-h.late .uic{color:var(--red)}',
    '.agph-sec-h .cnt{font-size:11px;font-weight:700;color:var(--t2);background:var(--sur2);border:1px solid var(--bor);border-radius:999px;padding:1px 8px}',
    '.agph-sec-h.late .cnt{color:var(--red);background:color-mix(in srgb,var(--red) 12%,transparent);border-color:transparent}',
    '.agph-card{background:var(--sur);border:1px solid var(--bor);border-radius:13px;padding:12px 13px;margin-bottom:9px;cursor:pointer}',
    '.agph-card.todo{box-shadow:inset 3px 0 0 var(--acc)}',
    '.agph-card.late{box-shadow:inset 3px 0 0 var(--neg);background:var(--neg-soft);background:color-mix(in srgb, var(--neg) 10%, var(--sur));border-color:var(--neg)}',
    '.agph-card.done{opacity:.62}',
    '.agph-card.done .agph-ti{text-decoration:line-through;text-decoration-color:var(--t3)}',
    '.agph-top{display:flex;gap:11px;align-items:flex-start}',
    '.agph-ico{width:36px;height:36px;border-radius:10px;flex:0 0 auto;display:grid;place-items:center;background:var(--sur2);color:var(--t2)}',
    '.agph-ti{font-weight:700;color:var(--t1);font-size:14px;line-height:1.25}',
    '.agph-meta{display:flex;align-items:center;gap:5px;flex-wrap:wrap;margin-top:4px;color:var(--t3);font-size:11.5px}',
    '.agph-meta .uic{width:12px;height:12px;flex:0 0 auto}',
    '.agph-meta .m{display:inline-flex;align-items:center;gap:3px}',
    '.agph-catlbl{font-size:10px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--t2)}',
    '.agph-dotsep{opacity:.5}',
    '.agph-badge{display:inline-flex;align-items:center;gap:3px;font-size:10px;font-weight:800;border-radius:999px;padding:2px 8px;white-space:nowrap}',
    '.agph-badge .uic{width:11px;height:11px;flex:0 0 auto}',
    '.agph-badge.late{background:color-mix(in srgb,var(--red) 12%,transparent);color:var(--red)}',
    '.agph-badge.warn{background:color-mix(in srgb,var(--ora) 14%,transparent);color:var(--ora)}',
    '.agph-acts{display:flex;gap:7px;margin-top:10px}',
    '.agph-acts button{flex:1;display:inline-flex;align-items:center;justify-content:center;gap:5px;font:inherit;font-size:12px;font-weight:700;border-radius:9px;padding:8px 0;cursor:pointer;border:1px solid var(--bor);background:var(--sur);color:var(--t2);min-height:38px}',
    '.agph-acts .uic{width:15px;height:15px;flex:0 0 auto}',
    '.agph-acts .done{color:var(--acc);border-color:color-mix(in srgb,var(--acc) 40%,var(--bor))}',
    '.agph-acts .del{color:var(--red);border-color:color-mix(in srgb,var(--red) 30%,var(--bor))}',
    '.agph-done{margin-bottom:16px}',
    '.agph-done>summary{list-style:none;display:flex;align-items:center;gap:8px;cursor:pointer;background:var(--sur2);border:1px solid var(--bor);border-radius:11px;padding:11px 13px;color:var(--t2);font-size:13px;font-weight:600}',
    '.agph-done>summary::-webkit-details-marker{display:none}',
    '.agph-done>summary .uic{width:14px;height:14px;color:var(--t3)}',
    '.agph-done>summary .cnt{margin-left:auto;font-size:11px;font-weight:700;color:var(--t2);background:var(--sur);border:1px solid var(--bor);border-radius:999px;padding:1px 8px}',
    '.agph-done[open]>summary{margin-bottom:9px}',
    '.agph-fbtn{display:none}', // masqué par défaut (PC) ; ré-affiché ≤767 ci-dessous — robuste au resize mobile→desktop
    /* calendrier téléphone : points d'urgence (corail/rouge/gris) au lieu de pastilles 7-col illisibles */
    '@media(max-width:767px){',
    '#p-agenda .agenda-cal-day{min-height:50px;padding:4px 0 4px;align-items:center;gap:3px}',
    '#p-agenda .agenda-cal-day-num{align-self:center;font-size:11px}',
    '#p-agenda .agph-dots{display:flex;gap:3px;flex-wrap:wrap;justify-content:center}',
    '#p-agenda .agph-dot{width:5px;height:5px;border-radius:50%}',
    '#p-agenda .agph-dot.todo{background:var(--acc)}',
    '#p-agenda .agph-dot.late{background:var(--red)}',
    '#p-agenda .agph-dot.done{background:var(--t3)}',
    '#p-agenda .agph-cal-legend{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:12px;color:var(--t2);font-size:11.5px}',
    '#p-agenda .agph-cal-legend span{display:inline-flex;align-items:center;gap:5px}',
    '#p-agenda .agph-cal-legend .agph-dot{width:7px;height:7px}',
    /* barre d\'outils mobile épurée (mockup validé) : segment Vue + bouton Filtrer repliable + CTA corail pleine largeur */
    '#agenda-controls{flex-direction:column;align-items:stretch;gap:10px}',
    '#agenda-controls-filters{align-items:center;gap:8px}',
    '#agenda-controls-filters #agenda-view-list,#agenda-controls-filters #agenda-view-cal{flex:1 1 0}',
    '#agenda-showdone-label{display:none!important}', // « Afficher terminés » sans objet sur mobile (section Terminés toujours dispo)
    '#agenda-f-log,#agenda-f-cat{display:none;width:100%!important;flex:1 1 100%}',
    '#agenda-controls.agph-filters-open #agenda-f-log,#agenda-controls.agph-filters-open #agenda-f-cat{display:block}',
    '.agph-fbtn{display:inline-flex;align-items:center;gap:6px;position:relative;flex:0 0 auto;font:inherit;font-size:12.5px;font-weight:600;border:1px solid var(--bor);background:var(--sur);color:var(--t2);border-radius:9px;padding:8px 12px;min-height:38px;cursor:pointer}',
    '.agph-fbtn .uic{width:15px;height:15px}',
    '#agenda-controls.agph-filters-open .agph-fbtn{color:var(--acc);border-color:color-mix(in srgb,var(--acc) 40%,var(--bor))}',
    '.agph-fbtn .cnt{background:var(--acc);color:var(--cta-text,#fff);font-size:10px;font-weight:800;border-radius:999px;min-width:16px;height:16px;display:inline-grid;place-items:center;padding:0 4px}',
    '.agph-fbtn .cnt[hidden]{display:none}',
    '#agenda-controls-actions{gap:8px;flex-wrap:wrap}',
    '#agenda-controls-actions .bp{flex:1 1 auto;min-height:44px}', // CTA corail prééminent, pleine largeur restante
    '}'
  ].join('');
  document.head.appendChild(st);
}
/* Barre d'outils mobile épurée : on RÉUTILISE les contrôles desktop (mêmes #agenda-f-log/#agenda-f-cat,
   1 seule source d'état — DRY) mais on les replie derrière un bouton « Filtrer », on masque « Afficher
   terminés » (sans objet sur mobile) et on rend le CTA « + Nouvel événement » explicite. PC intact. */
function _ensureAgendaPhToolbar(){
  const ctr=el('agenda-controls'), filters=el('agenda-controls-filters');
  if(!ctr||!filters) return;
  let fb=el('agenda-ph-filter');
  if(!fb){
    fb=document.createElement('button');
    fb.id='agenda-ph-filter'; fb.type='button'; fb.className='agph-fbtn';
    fb.setAttribute('aria-label','Filtrer les événements');
    fb.onclick=function(){ ctr.classList.toggle('agph-filters-open'); };
    fb.innerHTML=_uiIcon('filter')+'Filtrer<span class="cnt" hidden>0</span>';
    const calBtn=el('agenda-view-cal');
    if(calBtn && calBtn.parentNode===filters) calBtn.insertAdjacentElement('afterend',fb);
    else filters.appendChild(fb);
  }
  _agendaPhFilterCount();
  // On ne mute AUCUN élément partagé (libellé du CTA laissé tel quel) : tout le style mobile est en CSS ≤767,
  // pour ne rien laisser fuir sur le PC après un passage mobile→desktop.
}
function _agendaPhFilterCount(){
  const fb=el('agenda-ph-filter'); if(!fb) return;
  const n=(el('agenda-f-log')?.value?1:0)+(el('agenda-f-cat')?.value?1:0);
  const cnt=fb.querySelector('.cnt'); if(cnt){ cnt.textContent=n; cnt.hidden=!n; }
}
function _agendaEvtCardPhone(e){
  const today=new Date().toISOString().slice(0,10);
  const isOverdue=!e.done && e.date<today;
  const isToday=!e.done && e.date===today;
  // Écart en jours calculé de minuit-à-minuit (évite le -1 dû à l'heure courante dans _daysFrom).
  const daysLeft=Math.round((new Date(e.date+'T00:00:00') - new Date(today+'T00:00:00'))/86400000);
  const cat=AGENDA_CATS[e.cat]||AGENDA_CATS.AUTRE;
  let badge='';
  if(!e.done){
    if(isOverdue) badge=`<span class="agph-badge late">${_uiIcon('warn')}${Math.abs(daysLeft)} j de retard</span>`;
    else if(isToday) badge=`<span class="agph-badge warn">${_uiIcon('clock')}Aujourd'hui</span>`;
    else if(daysLeft>0 && daysLeft<=30) badge=`<span class="agph-badge warn">${_uiIcon('clock')}J-${daysLeft}</span>`;
  }
  const meta=[`<span class="agph-catlbl">${escHtml(cat.label)}</span>`,'<span class="agph-dotsep">·</span>',`<span class="m">${_uiIcon('calendar')}${fd(e.date)}</span>`];
  if(e.logement) meta.push('<span class="agph-dotsep">·</span>',`<span class="m">${_uiIcon('home')}${escHtml(_logLabel(e.logement))}</span>`);
  if(e.recurrence&&e.recurrence.type!=='none') meta.push('<span class="agph-dotsep">·</span>',`<span class="m">${_uiIcon('refresh')}${escHtml(_recLabel(e.recurrence))}</span>`);
  if(e.auto) meta.push('<span class="agph-dotsep">·</span>',`<span class="m">${_uiIcon('settings')}Auto</span>`);
  const acts=e.done
    ? `<button class="del" onclick="deleteAgendaEvt(event,'${e.id}')">${_uiIcon('trash')}Supprimer</button>`
    : `<button class="done" onclick="agendaMarkDone(event,'${e.id}')">${_uiIcon('check')}Marquer fait</button><button class="del" onclick="deleteAgendaEvt(event,'${e.id}')">${_uiIcon('trash')}Suppr.</button>`;
  return `<div class="agph-card${e.done?' done':' todo'}${_agendaRevisionEnRetard(e)?' late':''}" onclick="openAgendaEvt('${_lyQ(e.id)}')">
    <div class="agph-top"><div class="agph-ico">${_agendaIconSvg(e.cat,19)}</div>
      <div style="flex:1;min-width:0"><div class="agph-ti">${escHtml(e.titre)}</div><div class="agph-meta">${meta.join('')}${badge}</div></div></div>
    <div class="agph-acts">${acts}</div>
  </div>`;
}
function _agendaSectionPhone(icon,label,evts,late){
  if(!evts.length) return '';
  return `<div class="agph-sec"><div class="agph-sec-h${late?' late':''}">${icon}<b>${label}</b><span class="cnt">${evts.length}</span></div>${evts.map(_agendaEvtCardPhone).join('')}</div>`;
}
function _rAgendaListPhone(g){
  // Terminés = 30 derniers jours (décision Didier). Frontière NETTE minuit-à-minuit
  // (pas _daysFrom qui intègre l'heure courante → un événement à J-30 pile ne clignote pas selon l'heure).
  const cut = new Date(); cut.setHours(0,0,0,0); cut.setDate(cut.getDate()-30);
  const done30 = g.done.filter(e=>new Date(e.date+'T00:00:00') >= cut);
  el('agenda-overdue-section').innerHTML = _agendaSectionPhone(_uiIcon('warn'),'En retard',g.overdue,true);
  el('agenda-soon7-section').innerHTML   = _agendaSectionPhone(_uiIcon('bell'),'Cette semaine',g.soon7,false);
  el('agenda-soon30-section').innerHTML  = _agendaSectionPhone(_uiIcon('calendar'),'Ce mois-ci',g.soon30,false);
  let restHtml = _agendaSectionPhone(_uiIcon('list'),'À venir',g.rest,false);
  if(done30.length){
    restHtml += `<details class="agph-done"><summary>${_uiIcon('check')}Terminés · 30 derniers jours<span class="cnt">${done30.length}</span></summary>${done30.map(_agendaEvtCardPhone).join('')}</details>`;
  }
  el('agenda-rest-section').innerHTML = restHtml;
  const total=g.overdue.length+g.soon7.length+g.soon30.length+g.rest.length+done30.length;
  if(!total){
    el('agenda-overdue-section').innerHTML = `<div class="agph-card" style="cursor:default;text-align:center"><div class="agph-ti" style="margin-bottom:4px">Aucun événement</div><div style="color:var(--t3);font-size:12.5px">Ajouter un événement avec « + Nouvel événement », ou synchroniser depuis les baux.</div></div>`;
  }
}
function _agendaDayDotsPhone(dayEvts){
  const today=new Date().toISOString().slice(0,10);
  const cls=e=>e.done?'done':(e.date<today?'late':'todo');
  const dots=dayEvts.slice(0,5).map(e=>`<span class="agph-dot ${cls(e)}"></span>`).join('');
  return dots?`<span class="agph-dots">${dots}</span>`:'';
}


function rAgendaCal() {
  const titleEl = el('agenda-cal-title');
  const gridEl  = el('agenda-cal-grid');
  if(!titleEl||!gridEl) return;

  const months = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
  titleEl.textContent = months[_agendaCalMonth] + ' ' + _agendaCalYear;

  const firstDay = new Date(_agendaCalYear, _agendaCalMonth, 1).getDay();
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; // Monday first
  const daysInMonth = new Date(_agendaCalYear, _agendaCalMonth+1, 0).getDate();
  const today = new Date().toISOString().slice(0,10);
  const yrm = `${_agendaCalYear}-${String(_agendaCalMonth+1).padStart(2,'0')}`;
  // Mobile : garder les terminés (point gris) ; PC : filtre desktop inchangé (case « Afficher terminés »).
  const monthEvts = (_isPhone()?_agendaFilterKeepDone:_agendaFilter)(DB.agenda||[]).filter(e=>e.date.startsWith(yrm));

  const days = ['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];
  let html = `<div class="agenda-cal-wrap">
    <div class="agenda-cal-header">${days.map(d=>`<div>${d}</div>`).join('')}</div>
    <div class="agenda-cal-grid-days">`;

  // Empty cells before
  for(let i=0;i<startOffset;i++) html += `<div class="agenda-cal-day agenda-cal-empty"></div>`;

  for(let d=1;d<=daysInMonth;d++) {
    const ds = `${_agendaCalYear}-${String(_agendaCalMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const dayEvts = monthEvts.filter(e=>e.date===ds);
    const isToday = ds===today;
    html += `<div class="agenda-cal-day${isToday?' agenda-cal-today':''}" onclick="openDayDetail('${ds}')">
      <span class="agenda-cal-day-num${isToday?' today':''}">${d}</span>
      ${_isPhone() ? _agendaDayDotsPhone(dayEvts) : (
        dayEvts.slice(0,3).map(e=>{
          // v15.62x REFONTE-PC — pastille neutre ; couleur = charte (retard rouge, à faire corail, fait atténué)
          const cls = e.done ? 'done' : ((!e.done && e.date < today) ? 'retard' : 'todo');
          return `<div class="agenda-cal-evt ${cls}">${_agendaIconSvg(e.cat,11)}${escHtml(e.titre.slice(0,22))}</div>`;
        }).join('') + (dayEvts.length>3?`<div style="font-size:9px;color:var(--t2);padding:0 3px">+${dayEvts.length-3} autres</div>`:'')
      )}
    </div>`;
  }

  html += `</div></div>`;
  // Téléphone : légende des points d'urgence (charte : corail=à réaliser, rouge=en retard, gris=fait).
  if(_isPhone()) html += `<div class="agph-cal-legend">
    <span><i class="agph-dot todo"></i>À réaliser</span>
    <span><i class="agph-dot late"></i>En retard</span>
    <span><i class="agph-dot done"></i>Fait</span></div>`;
  gridEl.innerHTML = html;
}

function agendaCalNav(dir) {
  _agendaCalMonth += dir;
  if(_agendaCalMonth > 11) { _agendaCalMonth=0; _agendaCalYear++; }
  if(_agendaCalMonth < 0)  { _agendaCalMonth=11; _agendaCalYear--; }
  rAgendaCal();
}

function openDayDetail(ds) {
  const evts = (_isPhone()?_agendaFilterKeepDone:_agendaFilter)(DB.agenda||[]).filter(e=>e.date===ds).sort((a,b)=>a.titre.localeCompare(b.titre));
  // 0 événement → créer directement
  if(!evts.length) { openAgendaEvt(null, ds); return; }
  // 1 seul événement → ouvrir directement
  if(evts.length === 1) { openAgendaEvt(evts[0].id); return; }
  // Plusieurs événements → panneau de sélection
  const d = new Date(ds+'T00:00:00');
  el('agenda-day-title').textContent = d.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});
  el('agenda-day-list').innerHTML = evts.map(e=>{
    const cat = AGENDA_CATS[e.cat]||AGENDA_CATS.AUTRE;
    const today = new Date().toISOString().slice(0,10);
    const isOverdue = !e.done && e.date < today;
    // v15.62x REFONTE-PC — neutre + charte : liseré corail = action à réaliser ; type = line-icon encre.
    return `<div onclick="closeM('ov-agenda-day');openAgendaEvt('${_lyQ(e.id)}')"
      style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:var(--r);
             border:1px solid var(--bor);${e.done?'':'box-shadow:inset 3px 0 0 var(--acc);'}background:${e.done?'var(--sur2)':'var(--sur)'};
             cursor:pointer;transition:box-shadow .15s"
      onmouseover="this.style.boxShadow='${e.done?'var(--shadow-hover)':'inset 3px 0 0 var(--acc), var(--shadow-hover)'}'" onmouseout="this.style.boxShadow='${e.done?'':'inset 3px 0 0 var(--acc)'}'">
      <span style="flex-shrink:0;display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;border-radius:8px;background:var(--sur2);color:var(--t2)">${_agendaIconSvg(e.cat,18)}</span>
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;color:${e.done?'var(--t3)':'var(--t1)'};
                    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
                    text-decoration:${e.done?'line-through':'none'}">${escHtml(e.titre)}</div>
        <div style="font-size:11px;color:var(--t3);margin-top:2px;display:flex;gap:8px;flex-wrap:wrap;align-items:center">
          <span class="agenda-cat-badge" style="font-size:10px">${cat.label}</span>
          ${e.logement?`<span>${escHtml(_logLabel(e.logement))}</span>`:''}
        </div>
      </div>
      ${e.done?`<span class="badge grn">${_uiIcon('check',10)} Fait</span>`:
        isOverdue?`<span class="badge red">En retard</span>`:''}
      <span style="font-size:16px;color:var(--t3)">›</span>
    </div>`;
  }).join('');
  // Bouton "+ Nouvel événement ce jour"
  const addBtn = el('agenda-day-add-btn');
  if(addBtn) addBtn.onclick = ()=>{ closeM('ov-agenda-day'); openAgendaEvt(null, ds); };
  openM('ov-agenda-day');
}

function agendaMarkDone(domEvt, id) {
  domEvt.stopPropagation();
  const e = (DB.agenda||[]).find(x=>x.id===id); if(!e) return;
  e.done = !e.done;
  saveDB();
  rAgenda();
}

function deleteAgendaEvt(domEvt, id) {
  domEvt.stopPropagation();
  if(!confirm('Supprimer cet événement ?')) return;
  // Rappel automatique supprimé : sa clé est mémorisée (config synchronisée) pour qu'agendaAutoSync ne le recrée pas.
  // Une autre échéance (nouvelle clé) recrée bien un rappel.
  const _ev = (DB.agenda||[]).find(x=>x.id===id);
  if (_ev && _ev.autoKey) {
    DB.params = DB.params || {};
    const _ec = Array.isArray(DB.params.agendaAutoEcartes) ? DB.params.agendaAutoEcartes : [];
    if (_ec.indexOf(_ev.autoKey) < 0) DB.params.agendaAutoEcartes = _ec.concat([_ev.autoKey]).slice(-500);
  }
  DB.agenda = (DB.agenda||[]).filter(x=>x.id!==id);
  saveDB();
  rAgenda();
}

function agendaSyncAuto() {
  const n = agendaAutoSync();
  showToast(n ? `✓ ${n} événement(s) généré(s) depuis les baux` : '✓ Agenda à jour — rien de nouveau', 'ok', 2500);
  rAgenda();
}

// ══════════════════════════════════════════════════════════════
// ÉQUIPEMENTS — Suivi entretiens par logement
// ══════════════════════════════════════════════════════════════

function onEquipImmChange() {
  // Reset le filtre logement quand l'immeuble change (évite d'avoir une
  // sélection logement incohérente avec le nouvel immeuble)
  const logSel = el('equip-f-log');
  if(logSel) logSel.value = '';
  rEquipements();
}

function rEquipements() {
  let fImm = v('equip-f-imm');
  let fLog = v('equip-f-log');

  // v14.47 audit tombstones — base partagée
  const aliveLogs = (DB.logements||[]).filter(_isAlive);
  // v15.234 NAV-FILTRE-ENTITE-GLOBAL : cascade entité → périmètre limité à l'entité active.
  const entLogs = aliveLogs.filter(_logInEnt);

  // v14.84 BUG-EQUIP-FILTER : inclure logements vacants (équipements à suivre entre 2 locataires)
  // Remplir le filtre immeuble (TOUS logements, pas seulement occupés)
  const immSel = el('equip-f-imm');
  if(immSel) {
    const cur = immSel.value;
    const imms = [...new Set(entLogs.map(l=>l.imm))].filter(Boolean).sort();
    immSel.innerHTML = '<option value="">Tous immeubles</option>'
      + imms.map(i=>`<option value="${escHtml(i)}">${escHtml(i)}</option>`).join('');
    immSel.value = (cur && imms.includes(cur)) ? cur : '';  // Q1 reset auto
    fImm = immSel.value;
  }

  // Remplir le filtre logement (filtré par entité + immeuble si sélectionné), inclut vacants
  const logSel = el('equip-f-log');
  if(logSel) {
    const cur = logSel.value;
    const opts = entLogs.filter(l => !fImm || l.imm===fImm);
    logSel.innerHTML = '<option value="">Tous logements</option>'
      + opts.map(l=>`<option value="${escHtml(l.ref)}">${escHtml(_logLabelRef(l))} — ${escHtml((l.locataire || 'Vacant').substring(0,25))}</option>`).join('');
    logSel.value = (cur && opts.some(l=>l.ref===cur)) ? cur : '';  // Q1 reset auto
    fLog = logSel.value;
  }

  const logs = entLogs.filter(l => (!fImm || l.imm===fImm) && (!fLog || l.ref === fLog));
  const container = el('equip-list'); if(!container) return;
  if(!logs.length) { container.innerHTML = '<p class="mu">Aucun logement trouvé.</p>'; return; }

  container.innerHTML = logs.map(l => {
    const bail = DB.baux[l.ref] || {};
    // v15.232 ARCHI-DB-DOUBLONS Phase 4b — libellé chauffage depuis log (source unique).
    const _chauffLabel = (typeof _readLogForBail==='function' ? _readLogForBail(bail, l).chauff : '') || bail.chauff || '';
    const equipData = (DB.equipements||{})[l.ref] || {};
    const today = new Date();
    const todayStr = today.toISOString().slice(0,10);

    // Déterminer quelles règles s'appliquent à ce logement
    // v15.08 Sprint 9 : condFn accepte (bail, log) — log.equipements pour DAAF/VMC/ECS/Citerne/Clim été
    const applicable = (typeof EQUIP_RULES !== 'undefined' ? EQUIP_RULES : []).filter(r => r.condFn(bail, l));
    if(!applicable.length) return ''; // aucun équipement déclaré

    const rows = applicable.map(rule => {
      const entry = equipData[rule.key] || {};
      const lastDate = entry.lastDate || '';
      const lastStr = lastDate ? fd(lastDate) : '<span class="mu sm">— jamais</span>';

      // Calculer prochaine date
      let nextDate = null;
      if(lastDate) {
        nextDate = new Date(lastDate+'T00:00:00');
        if(rule.intervalMonths) nextDate.setMonth(nextDate.getMonth() + rule.intervalMonths);
        else nextDate.setFullYear(nextDate.getFullYear() + (rule.intervalYears||1));
      }
      const nextStr = nextDate ? fd(nextDate.toISOString().slice(0,10)) : '<span class="mu sm">non déf.</span>';
      const diffDays = nextDate ? Math.round((nextDate - today)/86400000) : null;
      const urgColor = diffDays===null ? 'var(--t3)' : diffDays<0 ? 'var(--red)' : diffDays<=30 ? 'var(--ora)' : 'var(--grn)';
      const urgBadge = diffDays===null ? '' : diffDays<0
        ? `<span class="badge" style="background:rgba(220,38,38,.12);color:var(--red)">⚠ ${Math.abs(diffDays)}j de retard</span>`
        : diffDays===0 ? `<span class="badge" style="background:rgba(234,88,12,.12);color:var(--ora)">Aujourd'hui</span>`
        : diffDays<=30 ? `<span class="badge" style="background:rgba(234,88,12,.1);color:var(--ora)">J-${diffDays}</span>`
        : `<span class="badge" style="background:rgba(22,163,74,.1);color:var(--grn)">J-${diffDays}</span>`;

      return `<tr data-equip-key="${escHtml(l.ref)}__${escHtml(rule.key)}">
        <td><span style="margin-right:5px;color:${(AGENDA_CATS[rule.cat]||AGENDA_CATS.AUTRE).couleur};display:inline-flex;vertical-align:-3px">${_agendaIconSvg(rule.cat,15)}</span><span style="font-size:12.5px;font-weight:500">${escHtml(rule.label)}</span><div style="font-size:10px;color:var(--t3);margin-top:1px">${escHtml(rule.base)}</div></td>
        <td>${lastStr}${entry.interv?`<div style="font-size:10px;color:var(--t3)">${escHtml(entry.interv)}</div>`:''}</td>
        <td style="color:${urgColor};font-weight:500">${nextStr}</td>
        <td>${urgBadge}</td>
        <td class="act-cell">
          <button class="btn bs bb" onclick="openEquipIntervention('${_lyQ(l.ref)}','${_lyQ(rule.key)}')" style="font-size:11px">${_uiIcon('edit',13)} Intervention</button>
        </td></tr>`;
    }).join('');

    // v15.08 Sprint 9 — Section "Configuration des équipements" (état des équipements du logement)
    const eq = l.equipements || {};
    const rEsc = _lyQ(l.ref);
    const cfgPanel = `
      <details style="margin-top:14px;background:var(--sur2);border:1px solid var(--bor);border-radius:var(--rl);padding:10px 14px">
        <summary style="cursor:pointer;font-weight:600;font-size:12.5px;user-select:none">${_uiIcon('settings',13)} Configuration des équipements du logement</summary>
        <div class="mu sm" style="margin:6px 0 10px;font-size:11.5px;line-height:1.5">
          Renseigner les équipements présents pour activer les alertes d'entretien correspondantes.
          Les équipements à charge du locataire (chaudière, ramonage, chauffe-eau, climatisation, citerne) génèrent automatiquement une fréquence d'entretien.
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px 14px;font-size:12px">
          <div>
            <label class="lbl sm">Eau chaude sanitaire (ECS)</label>
            <select class="inp" onchange="_equipSaveCfg('${rEsc}','ecsType',this.value)">
              <option value=""               ${!eq.ecsType?'selected':''}>—</option>
              <option value="electrique"     ${eq.ecsType==='electrique'?'selected':''}>Électrique</option>
              <option value="gaz"            ${eq.ecsType==='gaz'?'selected':''}>Gaz (entretien annuel)</option>
              <option value="thermodynamique" ${eq.ecsType==='thermodynamique'?'selected':''}>Thermodynamique (entretien annuel)</option>
              <option value="solaire"        ${eq.ecsType==='solaire'?'selected':''}>Solaire</option>
              <option value="collective"     ${eq.ecsType==='collective'?'selected':''}>Collective (immeuble)</option>
            </select>
          </div>
          <div>
            <label class="lbl sm">VMC (ventilation)</label>
            <select class="inp" onchange="_equipSaveCfg('${rEsc}','vmcType',this.value)">
              <option value=""              ${!eq.vmcType?'selected':''}>—</option>
              <option value="aucune"        ${eq.vmcType==='aucune'?'selected':''}>Aucune</option>
              <option value="individuelle"  ${eq.vmcType==='individuelle'?'selected':''}>Individuelle (locataire nettoie bouches)</option>
              <option value="collective"    ${eq.vmcType==='collective'?'selected':''}>Collective (bailleur immeuble)</option>
            </select>
          </div>
          <div>
            <label class="lbl sm">Climatisation été &gt; 12 kW ?</label>
            <div style="display:flex;gap:6px;align-items:center;margin-top:4px">
              <input type="checkbox" ${eq.climEte?'checked':''} onchange="_equipSaveCfg('${rEsc}','climEte',this.checked)">
              <input type="number" class="inp" min="0" max="200" step="0.5" value="${escHtml(String(eq.climEtePuissance||''))}"
                     onchange="_equipSaveCfg('${rEsc}','climEtePuissance',this.value)"
                     placeholder="kW" style="width:80px;font-size:11.5px">
              <span class="mu sm" style="font-size:10.5px">kW (si oui)</span>
            </div>
          </div>
          <div>
            <label class="lbl sm">Citerne fioul individuelle ?</label>
            <div style="display:flex;gap:6px;align-items:center;margin-top:4px">
              <input type="checkbox" ${eq.citerneFioul?'checked':''} onchange="_equipSaveCfg('${rEsc}','citerneFioul',this.checked)">
              <span class="mu sm" style="font-size:10.5px">Contrôle quinquennal</span>
            </div>
          </div>
          <div>
            <label class="lbl sm">Conduit de fumée / cheminée ?</label>
            <div style="display:flex;gap:6px;align-items:center;margin-top:4px">
              <input type="checkbox" ${eq.conduitFumee?'checked':''} onchange="_equipSaveCfg('${rEsc}','conduitFumee',this.checked)">
              <span class="mu sm" style="font-size:10.5px">Ramonage annuel locataire</span>
            </div>
          </div>
          <div style="grid-column:1/-1;padding-top:8px;margin-top:6px;border-top:1px dashed var(--bor)">
            <div style="font-weight:600;font-size:12px;margin-bottom:6px">${_uiIcon('alarm')} Détecteur de fumée (DAAF)</div>
            <div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;font-size:11.5px">
              <label style="display:flex;gap:6px;align-items:center;cursor:pointer">
                <input type="radio" name="daaf-${rEsc}" value="oui" ${eq.daafPresent===true?'checked':''} onchange="_equipSaveCfg('${rEsc}','daafPresent',true)">
                Présent
              </label>
              <label style="display:flex;gap:6px;align-items:center;cursor:pointer">
                <input type="radio" name="daaf-${rEsc}" value="non" ${eq.daafPresent===false?'checked':''} onchange="_equipSaveCfg('${rEsc}','daafPresent',false)">
                Absent (à installer)
              </label>
              <label style="display:flex;gap:6px;align-items:center;cursor:pointer">
                <input type="radio" name="daaf-${rEsc}" value="" ${eq.daafPresent==null?'checked':''} onchange="_equipSaveCfg('${rEsc}','daafPresent',null)">
                Non renseigné
              </label>
              <div style="display:flex;gap:6px;align-items:center">
                <label style="font-size:10.5px;color:var(--mut)">Installé le</label>
                <input type="date" class="inp" value="${escHtml(eq.daafDateInstallation||'')}"
                       onchange="_equipSaveCfg('${rEsc}','daafDateInstallation',this.value)"
                       style="width:140px;font-size:11px">
              </div>
            </div>
            <div class="mu sm" style="margin-top:6px;font-size:10.5px;line-height:1.5;color:var(--mut)">
              Installation à la charge du bailleur (loi 2010-238). L'entretien de la pile incombe au locataire (art. R129-13).
              La photo du détecteur sera demandée lors de l'état des lieux d'entrée comme preuve.
            </div>
          </div>
        </div>
      </details>`;

    if(!rows && !cfgPanel) return '';
    return `<div class="card mb12">
      <div class="flex-b mb12">
        <div><b style="font-size:15px">${escHtml(_logLabel(l))}</b> <span class="badge gry" style="margin-left:6px">${escHtml(l.imm||'')}</span>
          <div style="font-size:12px;color:var(--t2);margin-top:2px">${escHtml(l.locataire||'Vacant')} &mdash; ${escHtml(_chauffLabel||'N/C')}</div></div>
      </div>
      ${rows ? `<div class="tbl-wrap"><table class="tbl">
        <thead><tr><th>Équipement</th><th>Dernière intervention</th><th>Prochaine échéance</th><th>Statut</th><th></th></tr></thead>
        <tbody>${rows}</tbody>
      </table></div>` : '<p class="mu sm" style="margin:4px 0 0">Aucun équipement à entretien périodique pour ce logement — utiliser la configuration ci-dessous pour en déclarer.</p>'}
      ${cfgPanel}
    </div>`;
  }).join('') || '<p class="mu">Aucun logement trouvé.</p>';
}

/** v15.08 Sprint 9 — Save un champ de log.equipements + re-render. */
function _equipSaveCfg(ref, field, value) {
  const log = (DB.logements||[]).find(l => l && !l._deleted && l.ref === ref);
  if (!log) return;
  if (!log.equipements) log.equipements = {};
  // Conversion type selon le champ
  if (field === 'climEte' || field === 'citerneFioul' || field === 'conduitFumee') {
    log.equipements[field] = !!value;
  } else if (field === 'daafPresent') {
    log.equipements[field] = (value === null ? null : !!value);
  } else if (field === 'climEtePuissance') {
    const n = parseFloat(value);
    log.equipements[field] = Number.isFinite(n) && n >= 0 ? n : 0;
  } else {
    log.equipements[field] = String(value || '');
  }
  _stamp(log);
  saveDB();
  // Re-régénère les événements agenda (les règles applicables peuvent avoir changé)
  if (typeof agendaAutoSync === 'function') {
    try { agendaAutoSync(); } catch(e) { console.warn('[equip cfg] agenda sync', e); }
  }
  rEquipements();
  if (typeof showToast === 'function') showToast('✓ Configuration équipements enregistrée', 'ok', 1800);
}

// v15.08 Sprint 9 EQUIP-CONTROLES-PERIODIQUES — helpers purs testables
//
// _calculerProchainControle(rule, lastDateIso) — date ISO de la prochaine échéance.
//   intervalYears prend le pas sur intervalMonths si défini ; sinon défaut 12 mois.
//   Approche string-based pour éviter bug timezone setMonth (cf diagnostics.js).
function _calculerProchainControle(rule, lastDateIso) {
  if (!rule || !lastDateIso) return null;
  const m = String(lastDateIso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return null;
  let y = parseInt(m[1],10), mo = parseInt(m[2],10);
  const d = parseInt(m[3],10);
  const years = rule.intervalYears || 0;
  const months = rule.intervalMonths || (years ? 0 : 12);
  y += years;
  mo += months;
  while (mo > 12) { mo -= 12; y += 1; }
  return `${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}

// _buildClauseEntretienItems(log, bail) — version structurée pour injection dans le bail
//   (array de bullets sans la mention DAAF qui est gérée à part dans l'article 11.1 bis).
function _buildClauseEntretienItems(log, bail) {
  if (!log) return [];
  const eq = log.equipements || {};
  const items = [];
  // v15.232 ARCHI-DB-DOUBLONS Phase 4b — chauffage lu depuis log (source unique) via _readLogForBail.
  // Bail signé : fallback _lb DÉSACTIVÉ (_useLb=false) → on lit UNIQUEMENT les flags bail.X figés au
  // snapshot, sinon la clause pourrait changer rétroactivement (immutabilité légale du bail signé).
  // Bail non signé : bail.X a été purgé par la migration V4b → _useLb=true → on lit le log vivant.
  const _lb = (typeof _readLogForBail === 'function' ? _readLogForBail(bail, log) : null) || {};
  const _useLb = !_lb._bailSignedSnapshot;
  const _cGaz       = (bail && bail.chauffGaz)       || (_useLb && _lb.chauffGaz);
  const _cFioul     = (bail && bail.chauffFioul)     || (_useLb && _lb.chauffFioul);
  const _cBois      = (bail && bail.chauffBois)      || (_useLb && _lb.chauffBois);
  const _cPoeleBois = (bail && bail.chauffPoeleBois) || (_useLb && _lb.chauffPoeleBois);
  const _cPoeleGran = (bail && bail.chauffPoeleGran) || (_useLb && _lb.chauffPoeleGran);
  const _cInsert    = (bail && bail.chauffInsert)    || (_useLb && _lb.chauffInsert);
  const _cChem      = (bail && bail.chauffCheminee)  || (_useLb && _lb.chauffCheminee);
  if (_cGaz || _cFioul || _cBois || _cPoeleBois || _cPoeleGran || _cInsert) {
    items.push("Entretien annuel du système de chauffage (chaudière, poêle, insert) confié à un professionnel qualifié — décret 2009-649 et arrêtés associés. Un justificatif daté et signé sera remis au BAILLEUR.");
  }
  if (_cFioul || _cBois || _cPoeleBois || _cPoeleGran || _cInsert || _cChem || eq.conduitFumee) {
    items.push("Ramonage annuel du conduit de fumée par un professionnel qualifié (Règlement Sanitaire Départemental). Certains arrêtés préfectoraux imposent une fréquence biannuelle.");
  }
  if (eq.ecsType === 'gaz') {
    items.push("Entretien annuel du chauffe-eau gaz (décret 2009-649).");
  } else if (eq.ecsType === 'thermodynamique') {
    items.push("Entretien annuel du chauffe-eau thermodynamique (fluide frigorigène).");
  }
  if (eq.climEte && Number(eq.climEtePuissance) >= 12) {
    items.push("Inspection biennale de la climatisation > 12 kW (décret 2010-349).");
  }
  if (eq.citerneFioul) {
    items.push("Contrôle et nettoyage quinquennal de la citerne fioul individuelle (arrêté 1er juillet 2004).");
  }
  if (eq.vmcType === 'individuelle') {
    items.push("Nettoyage régulier des bouches de ventilation mécanique contrôlée (RSDD).");
  }
  return items;
}

// _clauseLocataire(log, bail) — génère le texte de la clause bail "entretien locataire".
//   Liste auto des équipements à charge locataire + mention obligatoire DAAF (loi 2010-238).
function _clauseLocataire(log, bail) {
  if (!log) return '';
  const eq = log.equipements || {};
  const items = [];
  // v15.232 ARCHI-DB-DOUBLONS Phase 4b — chauffage lu depuis log (source unique) via _readLogForBail.
  // Bail signé : fallback _lb DÉSACTIVÉ (_useLb=false) → on lit UNIQUEMENT les flags bail.X figés au
  // snapshot, sinon la clause pourrait changer rétroactivement (immutabilité légale du bail signé).
  // Bail non signé : bail.X a été purgé par la migration V4b → _useLb=true → on lit le log vivant.
  const _lb = (typeof _readLogForBail === 'function' ? _readLogForBail(bail, log) : null) || {};
  const _useLb = !_lb._bailSignedSnapshot;
  const _cGaz       = (bail && bail.chauffGaz)       || (_useLb && _lb.chauffGaz);
  const _cFioul     = (bail && bail.chauffFioul)     || (_useLb && _lb.chauffFioul);
  const _cBois      = (bail && bail.chauffBois)      || (_useLb && _lb.chauffBois);
  const _cPoeleBois = (bail && bail.chauffPoeleBois) || (_useLb && _lb.chauffPoeleBois);
  const _cPoeleGran = (bail && bail.chauffPoeleGran) || (_useLb && _lb.chauffPoeleGran);
  const _cInsert    = (bail && bail.chauffInsert)    || (_useLb && _lb.chauffInsert);
  const _cChem      = (bail && bail.chauffCheminee)  || (_useLb && _lb.chauffCheminee);
  // Chauffage à entretien annuel (gaz/fioul/bois/PAC/poêle)
  if (_cGaz || _cFioul || _cBois || _cPoeleBois || _cPoeleGran || _cInsert) {
    items.push("entretien annuel du système de chauffage (chaudière, poêle, insert) à confier à un professionnel qualifié — décret 2009-649 et arrêtés associés");
  }
  if (_cFioul || _cBois || _cPoeleBois || _cPoeleGran || _cInsert || _cChem || eq.conduitFumee) {
    items.push("ramonage annuel du conduit de fumée (Règlement Sanitaire Départemental — fréquence pouvant aller jusqu'à 2 fois par an selon arrêté préfectoral)");
  }
  if (eq.ecsType === 'gaz' || eq.ecsType === 'thermodynamique') {
    items.push("entretien annuel du chauffe-eau" + (eq.ecsType === 'gaz' ? ' gaz' : ' thermodynamique'));
  }
  if (eq.climEte && Number(eq.climEtePuissance) >= 12) {
    items.push("inspection biennale de la climatisation > 12 kW (décret 2010-349)");
  }
  if (eq.citerneFioul) {
    items.push("contrôle et nettoyage quinquennal de la citerne fioul individuelle (arrêté 1er juillet 2004)");
  }
  if (eq.vmcType === 'individuelle') {
    items.push("nettoyage régulier des bouches de ventilation mécanique contrôlée (RSDD)");
  }
  // Mention DAAF obligatoire dans tous les cas (loi 2010-238)
  const daafMention = "Conformément à l'article R129-13 du Code de la construction et de l'habitation, le locataire est tenu d'entretenir le détecteur de fumée installé dans le logement, notamment de remplacer la pile lorsque celle-ci est usagée.";
  if (!items.length) return daafMention;
  const list = items.map(it => `• ${it}`).join('\n');
  return `Le locataire est tenu d'assurer les entretiens d'usage suivants à ses frais :\n\n${list}\n\n${daafMention}`;
}

let _equipEditRef = null, _equipEditKey = null;

function openEquipIntervention(ref, key) {
  _equipEditRef = ref || null;
  _equipEditKey = key || null;

  // Remplir le select logement — v14.47 audit tombstones
  const logSel = el('ei-log');
  // R-0 : le lot loué se lit sur le BAIL. Un bien acheté occupé était absent de la liste,
  // donc impossible à rattacher à une intervention. Le NOM affiché, lui, vient du cache
  // puis du bail — afficher un nom n'est pas décider (`_nomsDuBail`).
  // Statut 06/10 : bail OUVERT — la remise en état après un départ déclaré (retenue sur le dépôt avant
  // clôture) doit pouvoir se rattacher au lot, comme avant.
  logSel.innerHTML = (DB.logements||[]).filter(_isAlive).filter(_lotBailOuvert).map(l=>{
    const _n = l.locataire || _nomsDuBail(_bienActiveBail(l.ref));
    return `<option value="${escHtml(l.ref)}">${escHtml(_logLabelRef(l))}${_n ? ' — ' + escHtml(String(_n).substring(0,25)) : ''}</option>`;
  }).join('');
  if(ref) logSel.value = ref;

  // Remplir les types d'équipements selon le logement sélectionné
  _fillEquipTypeSelect();
  logSel.onchange = function(){ _fillEquipTypeSelect(); _equipAttRefresh(); };
  el('ei-type').onchange = _equipAttRefresh;

  if(key) el('ei-type').value = key;

  const curRef = ref||logSel.value;
  const curKey = key||(el('ei-type').value);
  const entry = ((DB.equipements||{})[curRef]||{})[curKey] || {};
  el('ei-date').value = entry.lastDate || new Date().toISOString().slice(0,10);
  el('ei-interv').value = entry.interv || '';
  el('ei-notes').value  = entry.notes  || '';

  _equipAttRefresh();
  openM('ov-equip-interv');
}

// v15.158 — PJ équipement (facture/contrat/notice), scopée au couple logement + type sélectionné.
function _equipAttRefresh() {
  const c = el('ei-att-container'); if (!c) return;
  const ref = el('ei-log') ? el('ei-log').value : '';
  const key = el('ei-type') ? el('ei-type').value : '';
  if (!ref || !key) { c.innerHTML = '<div class="mu sm" style="font-size:11.5px;padding:8px;background:var(--sur2);border-radius:6px">Sélectionner logement + équipement pour attacher des documents.</div>'; return; }
  const typeLabel = (el('ei-type').selectedOptions[0] || {}).textContent || key;
  c.innerHTML = _renderAttachmentSection({ parentType:'equipement', parentId: ref + '__' + key, parentRef: ref + ' · ' + String(typeLabel).trim(), logRef: ref, category:'documents', title:'📎 Documents (facture, contrat, notice)', emptyText:'Attacher la facture d\'intervention, le contrat d\'entretien, la notice…' });
}

function _fillEquipTypeSelect() {
  const ref = el('ei-log').value;
  const bail = (ref && DB.baux[ref]) || {};
  const log = (DB.logements||[]).find(l => l.ref === ref) || {};
  const typeSel = el('ei-type');
  // v15.08 Sprint 9 : passe (bail, log) à condFn
  const applicable = (typeof EQUIP_RULES !== 'undefined' ? EQUIP_RULES : []).filter(r => r.condFn(bail, log));
  typeSel.innerHTML = applicable.length
    ? applicable.map(r=>`<option value="${r.key}">${r.icon||''} ${escHtml(r.label)}</option>`).join('')
    : '<option value="AUTRE">Autre équipement</option>';
  if(_equipEditKey) typeSel.value = _equipEditKey;
}

function saveEquipIntervention() {
  const ref  = el('ei-log').value; if(!ref) return showToast('Sélectionner un logement','err');
  const key  = el('ei-type').value; if(!key) return showToast('Sélectionner un type','err');
  const date = el('ei-date').value; if(!date) return showToast('Date requise','err');
  const interv = el('ei-interv').value.trim();
  const notes  = el('ei-notes').value.trim();

  if(!DB.equipements) DB.equipements = {};
  if(!DB.equipements[ref]) DB.equipements[ref] = {};
  DB.equipements[ref][key] = { lastDate:date, interv, notes, updatedAt:td() };
  saveDB();

  // Mettre à jour l'événement agenda correspondant (marquer fait + régénérer)
  const todayStr = new Date().toISOString().slice(0,10);
  // Marquer comme fait les événements agenda auto de ce type en retard ou proche
  (DB.agenda||[]).forEach(e => {
    if(e.auto && e.logement===ref && e.autoKey && e.autoKey.includes(`EQUIP:${ref}:${key}:`)) {
      if(e.date <= date) e.done = true;
    }
  });
  // Supprimer les futurs événements auto pour ce couple (ref+key) afin de les régénérer
  DB.agenda = (DB.agenda||[]).filter(e => !(e.auto && e.logement===ref && e.autoKey && e.autoKey.includes(`EQUIP:${ref}:${key}:`)));
  agendaAutoSync();

  closeM('ov-equip-interv');
  // v15.164 BUG-EQUIP-INTERV-FEEDBACK : reset les filtres immeuble/logement AVANT le re-render,
  // sinon l'user voit « Aucun logement trouvé » si le filtre actif ne matche pas le logement de
  // l'intervention qu'il vient de saisir → impression que le save a échoué.
  const fImm = el('equip-f-imm');
  const fLog = el('equip-f-log');
  const hadFilter = !!((fImm && fImm.value) || (fLog && fLog.value));
  if (fImm) fImm.value = '';
  if (fLog) fLog.value = '';
  rEquipements();
  // Scroll + highlight de la ligne fraîchement saisie pour confirmation visuelle
  setTimeout(() => {
    // CSS.escape pour les ref logement contenant caractères spéciaux (apostrophe, accent, etc.)
    const sel = (window.CSS && CSS.escape)
      ? `tr[data-equip-key="${CSS.escape(ref + '__' + key)}"]`
      : `tr[data-equip-key="${(ref + '__' + key).replace(/"/g,'\\"')}"]`;
    const row = document.querySelector(sel);
    if (row) {
      try { row.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch(e) {}
      row.style.transition = 'background-color 1.5s ease';
      const prevBg = row.style.backgroundColor;
      row.style.backgroundColor = 'rgba(22,163,74,.20)';
      setTimeout(() => { row.style.backgroundColor = prevBg; }, 2000);
    }
  }, 120);
  showToast('✓ Intervention enregistrée' + (hadFilter ? ' (filtres réinitialisés)' : ''), 'ok', 3500);
}

function _updateAgendaBadge() {
  const today = new Date().toISOString().slice(0,10);
  const urgents = (DB.agenda||[]).filter(e=>!e.done && (e.date<today || _daysFrom(e.date)<=7));
  const badge = el('sb-agenda-badge');
  if(badge) {
    badge.style.display = urgents.length ? '' : 'none';
    badge.textContent = urgents.length;
  }
}

// ── Modale création/édition événement ─────────────────────
let _agendaEditId = null;

function openAgendaEvt(id, prefillDate='') {
  _agendaEditId = id;
  const e = id ? (DB.agenda||[]).find(x=>x.id===id) : null;
  const today = new Date().toISOString().slice(0,10);

  el('agenda-modal-title').textContent = e ? 'Modifier l\'événement' : 'Nouvel événement';
  el('agenda-evt-titre').value   = e?.titre||'';
  el('agenda-evt-date').value    = e?.date||(prefillDate||today);
  el('agenda-evt-datefin').value = e?.dateFin||(prefillDate||today);
  el('agenda-evt-cat').value     = e?.cat||'AUTRE';
  el('agenda-evt-log').value     = e?.logement||'';
  el('agenda-evt-notes').value   = e?.notes||'';
  el('agenda-evt-rec-type').value  = e?.recurrence?.type||'none';
  el('agenda-evt-rec-int').value   = e?.recurrence?.interval||1;
  el('agenda-evt-rec-fin').value   = e?.recurrence?.fin||'';
  el('agenda-evt-rappels').value   = (e?.rappels||[30,7]).join(',');
  el('agenda-evt-done').checked    = e?.done||false;
  _toggleRecPanel();

  // Remplir select logements — v14.47 audit tombstones
  const sl = el('agenda-evt-log');
  if(sl) {
    sl.innerHTML = '<option value="">— Aucun logement —</option>'
      + (DB.logements||[]).filter(_isAlive).map(l=>`<option value="${escHtml(l.ref)}"${e?.logement===l.ref?' selected':''}>${escHtml(_logLabelRef(l))}${l.locataire?' — '+escHtml(l.locataire):''}</option>`).join('');
    if(e?.logement) sl.value = e.logement;
  }
  openM('ov-agenda-evt');
}

function _toggleRecPanel() {
  const t = el('agenda-evt-rec-type')?.value;
  const panel = el('agenda-rec-panel');
  if(panel) panel.style.display = (t&&t!=='none') ? '' : 'none';
}

function saveAgendaEvt() {
  const titre = el('agenda-evt-titre').value.trim();
  if(!titre) { showToast('Titre requis','err'); return; }
  const recType = el('agenda-evt-rec-type').value;
  const evt = {
    id:        _agendaEditId || agendaId(),
    titre,
    date:      el('agenda-evt-date').value,
    dateFin:   el('agenda-evt-datefin').value || el('agenda-evt-date').value,
    logement:  el('agenda-evt-log').value,
    immeuble:  el('agenda-evt-log').value ? ((DB.logements||[]).filter(_isAlive).find(l=>l.ref===el('agenda-evt-log').value)?.imm||'') : '',
    entite:    el('agenda-evt-log').value ? (DB.baux[el('agenda-evt-log').value]?.entity||'') : '',
    cat:       el('agenda-evt-cat').value||'AUTRE',
    couleur:   '',
    notes:     el('agenda-evt-notes').value.trim(),
    recurrence:{ type:recType, interval:parseInt(el('agenda-evt-rec-int').value)||1, fin:el('agenda-evt-rec-fin').value||'' },
    rappels:   (el('agenda-evt-rappels').value||'').split(',').map(x=>parseInt(x.trim())).filter(x=>!isNaN(x)),
    auto:      false,
    // Un rappel automatique modifié à la main GARDE sa clé (auto:false) : la synchronisation ne le recrée pas en double.
    autoKey:   (_agendaEditId && ((DB.agenda || []).find(x => x.id === _agendaEditId) || {}).autoKey) || '',
    done:      el('agenda-evt-done')?.checked||false,
    createdAt: new Date().toISOString().slice(0,10),
  };
  if(!DB.agenda) DB.agenda=[];
  _stamp(evt); // v13.18
  if(_agendaEditId) {
    const idx = DB.agenda.findIndex(x=>x.id===_agendaEditId);
    // FAMILLE « écritures destructrices » — l'événement est reconstruit puis remplace l'ancien.
    // `auto` est remis à faux par le formulaire (une édition manuelle détache l'événement de l'auto-sync : plus
    // de recalage ni de purge) ; `autoKey` est gardée pour que la synchronisation ne recrée pas le rappel. La
    // préservation rattrape le reste (tag multi-espace, tombstones, champs ajoutés ailleurs).
    if(idx>=0) _preserverChampsExistants(evt, DB.agenda[idx]);
    if(idx>=0) DB.agenda[idx]=evt; else DB.agenda.push(evt);
  } else {
    DB.agenda.push(evt);
  }
  saveDB();
  closeM('ov-agenda-evt');
  rAgenda();
  showToast('✓ Événement enregistré','ok');
}

